window.GYM_EXERCISES_PT = {"3_4_Sit-Up":["3/4 Sente-se.",["Deite-se no chão e segure os pés, suas pernas devem estar dobradas nos joelhos.","Coloque as mãos para trás ou para o lado da cabeça... e comece de costas para o chão.","Flexione os quadris e a coluna para levantar o torso em direção aos joelhos.","No topo da contração, seu torso deve ser perpendicular ao chão.","Repita para a quantidade recomendada de repetições."]],"90_90_Hamstring":["90/90 Hamstring",["Deite-se de costas, com uma perna estendida.","Com a outra perna, dobre o quadril e o joelho a 90 graus, pode segurar a perna com as mãos, se necessário.","Estenda a perna para o ar, fazendo uma pausa no topo, devolva a perna para a posição inicial.","Repita para 10-20 repetições, e depois mude para a outra perna."]],"Ab_Crunch_Machine":["Ab Crunch Machine",["Escolha uma resistência leve e sente-se na máquina de abdômen colocando seus pés sob as almofadas fornecidas e agarrando as alças de cima seus braços devem ser dobrados em um ângulo de 90 graus enquanto descansa os tríceps nas almofadas fornecidas.","Ao mesmo tempo, comece a levantar as pernas enquanto você aperta seu tronco superior... e expire enquanto faz esse movimento... e não se esqueça de usar um movimento lento e controlado... e concentre-se em usar o abdômen para mover o peso enquanto relaxa as pernas e os pés.","Depois de uma segunda pausa, lentamente volte para a posição inicial enquanto você respira.","Repita o movimento para a quantidade prescrita de repetições."]],"Ab_Roller":["Ab Roller",["Segure o Ab Roller com as duas mãos e ajoelhe-se no chão.","Agora coloque o rolo no chão à sua frente para que você esteja de joelhos e de joelhos.","Desça o mais longe que puder sem tocar o chão com o seu corpo.","Depois de uma pausa na posição esticada, comece a se puxar de volta para a posição inicial enquanto expira."]],"Adductor":["Addutor.",["Deite-se de cara para baixo com uma perna em um rolo de espuma.","Rodar a perna para que a espuma entre em contato com sua coxa interna.","Enquanto tenta relaxar os músculos se a coxa interna, rolar sobre a espuma entre o quadril e o joelho, segurando pontos de tensão por 10-30 segundos."]],"Adductor_Groin":["Adductor/Groin",["Deite-se de costas com os pés levantados em direção ao teto.","Faça seu parceiro segurar seus pés ou tornozelos, sequestre suas pernas o máximo que puder, esta será sua posição inicial.","Tente apertar as pernas por 10 ou mais segundos, enquanto seu parceiro o impede de fazer isso.","Agora, relaxe os músculos nas pernas enquanto seu parceiro afasta os pés, esticando-se tanto quanto for confortável para você, certifique-se de avisar seu parceiro quando o estiramento for adequado para evitar estiramento excessivo ou lesão."]],"Advanced_Kettlebell_Windmill":["Moinho de vento Kettlebell avançado",["Limpe e aperte uma campainha com um braço.","Mantendo a chaleira fechada o tempo todo, empurre sua bunda para fora na direção da chaleira fechada, mantenha o braço não-trabalhador atrás das costas e vire os pés para fora em um ângulo de 45 graus do braço com a chaleira.","Abaixe-se o máximo possível.","Pause por um segundo e reverta o movimento de volta para a posição inicial."]],"Air_Bike":["Air Bike.",["Deite-se no chão com a parte inferior das costas pressionada para o chão, para este exercício, você precisará colocar as mãos ao lado da cabeça, no entanto, tenha cuidado para não forçar o pescoço enquanto o executa, agora levante os ombros para a posição de esmagamento.","Coloque os joelhos onde estão perpendiculares ao chão, com as pernas baixas paralelas ao chão.","Agora, ao mesmo tempo, lentamente, passar por um pedal pedal pedalando para frente com a perna direita e trazendo o joelho da perna esquerda.","Volte para a posição inicial enquanto respira.","Crunch para o lado oposto como você ciclo suas pernas e trazer mais perto seu cotovelo esquerdo para o joelho direito e expirar.","Continue alternando desta forma até que todas as repetições recomendadas para cada lado tenham sido concluídas."]],"All_Fours_Quad_Stretch":["Todos os Quatro Quad Stretch",["Comece com as mãos e joelhos, então levante a perna do chão e segure o pé com a mão.","Use sua mão para segurar o pé ou tornozelo, mantendo o joelho totalmente flexionado, esticando o quadríceps e flexores de quadril.","Concentre-se em estender os quadris, empurrá-los para o chão."]],"Alternate_Hammer_Curl":["Alternate Hammer Curl",["Levante-se com o torso ereto e um haltere em cada mão sendo mantido ao longo dos braços, os cotovelos devem estar perto do tronco.","As palmas das mãos devem estar voltadas para o seu torso.","Enquanto segura o braço parado, enrole o peso direito para frente enquanto contrai os bíceps enquanto expira, continue o movimento até que seus bíceps estejam totalmente contraídos e os halteres estejam ao nível do ombro, mantenha a posição contraída por um segundo enquanto aperta os bíceps, só os antebraços devem se mover.","Lentamente começar a trazer os halteres de volta à posição inicial enquanto você respira.","Repita o movimento com a mão esquerda.","Continue alternando desta forma para a quantidade recomendada de repetições."]],"Alternate_Heel_Touchers":["Alternate Heel Touchers",["Deite-se no chão com os joelhos dobrados e os pés no chão a 18-24 polegadas de distância, seus braços devem ser estendidos ao seu lado, esta será a sua posição inicial.","Esfregue o tronco para frente e suba cerca de 3-4 polegadas para o lado direito e toque o calcanhar direito enquanto segura a contração por um segundo.","Agora volte devagar para a posição inicial enquanto inala.","Agora aperte o tronco para a frente e para cima cerca de 3-4 polegadas para o lado esquerdo e toque o calcanhar esquerdo enquanto segura a contração por um segundo.","Continue alternando os lados desta maneira até que todas as repetições prescritas sejam feitas."]],"Alternate_Incline_Dumbbell_Curl":["Alternate Incline halteres Curl",["Sente-se em um banco inclinado com um haltere em cada mão sendo mantido com os braços abertos.","Enquanto segura o braço parado, enrole o peso direito para a frente enquanto contrai os bíceps enquanto expira, enquanto faz isso, gire a mão para que a palma fique virada para cima, continue o movimento até que seus bíceps estejam totalmente contraídos e os halteres estejam no nível do ombro, mantenha a posição contraída por um segundo enquanto aperta os bíceps.","Lentamente começar a trazer o haltere de volta à posição inicial enquanto você respira.","Repita o movimento com a mão esquerda.","Continue alternando desta forma para a quantidade recomendada de repetições."]],"Alternate_Leg_Diagonal_Bound":["Perna alternativa Diagonal amarrada",["Assuma uma postura confortável com um pé levemente na frente do outro.","Comece empurrando com a perna dianteira, dirigindo o joelho oposto para frente e o mais alto possível antes de aterrissar.","Pode ajudar usar uma linha no chão para afastar distância de um lado para o outro.","Repita a sequência com a outra perna."]],"Alternating_Cable_Shoulder_Press":["Ombros de cabo alternando",["Mova os cabos para o fundo da torre e selecione um peso apropriado.","Segure os cabos e segure-os em altura do ombro, palmas voltadas para frente.","Mantendo sua cabeça e peito para cima, estenda através do cotovelo para pressionar um lado diretamente sobre a cabeça.","Depois de parar no topo, volte para a posição inicial e repita no lado oposto."]],"Alternating_Deltoid_Raise":["Subindo deltóide alternado",["Em pé, segure um par de halteres ao seu lado.","Mantendo seus cotovelos ligeiramente dobrados, levante os pesos diretamente na sua frente para a altura do ombro, evitando qualquer balanço ou trapacear.","Devolva os pesos para o seu lado.","Na próxima repetição, levante os pesos lateralmente, elevando-os para o seu lado para cerca de altura do ombro.","Devolva os pesos para a posição inicial e continue alternando para a frente e para o lado."]],"Alternating_Floor_Press":["Imprensa Alternativa no Piso",["Deite-se no chão com duas campainhas ao lado dos ombros.","Posicione um no seu peito e o outro, segurando as campainhas na alça com as palmas voltadas para frente.","Estenda os dois braços, para que as campainhas estejam em cima do seu peito, abaixe uma campainha, trazendo-a para o seu peito e gire o pulso na direção da chaleira trancada.","Levante a campainha e repita no lado oposto."]],"Alternating_Hang_Clean":["\"Limpo de Hang Alternante\"",["Coloque duas campainhas entre os pés, para entrar na posição inicial, empurre o traseiro para trás e olhe para frente.","Limpe uma campainha para o ombro e segure a outra em posição de suspensão, limpe a chaleira para o ombro estendendo-se pelas pernas e quadris enquanto puxa a chaleira para os ombros, gire o pulso enquanto faz isso.","Abaixe a chaleira limpa para uma posição de enforcamento e limpe a chaleira alternativa."]],"Alternating_Kettlebell_Press":["Imprensa Kettlebell alternada",["Limpe duas campainhas nos ombros, limpe as chaleiras nos ombros, estendendo-se pelas pernas e quadris, enquanto puxa as chaleiras para os ombros, gira os pulsos enquanto faz isso.","Pressione um diretamente em cima, estendendo-se através do cotovelo, girando-o para a frente da palma da mão enquanto segura o outro kettlebell parado.","Abaixe a campainha para a posição inicial e pressione imediatamente com o outro braço."]],"Alternating_Kettlebell_Row":["Alternando Kettlebell Row",["Coloque duas campainhas na frente dos pés, dobre os joelhos um pouco e empurre a bunda para fora o máximo possível, enquanto você se curva para entrar na posição inicial, agarre as duas campainhas pelos punhos.","Puxe uma campainha do chão enquanto segura a outra, retraia a omoplata do lado de trabalho, enquanto flexiona o cotovelo, desenhando a omoplata para o estômago ou a caixa torácica.","Abaixe a campainha no braço e repita com o outro braço."]],"Alternating_Renegade_Row":["Alternando Renegado Row",["Coloque duas campainhas no chão sobre a largura do ombro, coloque-se sobre os dedos dos pés e as mãos como se estivesse fazendo uma flexão, com o corpo reto e estendido, use as alças das chaleiras para apoiar sua parte superior do corpo, talvez precise posicionar seus pés para apoio.","Empurre uma chaleira para o chão e reme a outra chaleira, retraindo a omoplata do lado de trabalho enquanto você flexiona o cotovelo, puxando-o para o seu lado.","Então abaixe a chaleira para o chão e comece a chaleira na mão oposta."]],"Ankle_Circles":["Círculos de tornozelos",["Use um objeto resistente como um cabide para se segurar.","Levante a perna direita no ar (cerca de 2 polegadas do chão) e faça um movimento circular com o dedo grande, finja que está desenhando um grande círculo com ele.","Quando terminar com o pé direito, repita com a perna esquerda."]],"Ankle_On_The_Knee":["Tornozelo no joelho",["De uma posição mentirosa, dobre os joelhos e mantenha os pés no chão.","Coloque o tornozelo de um pé no joelho oposto.","Segure a coxa ou o joelho da perna inferior e puxe as duas pernas para o peito, relaxe o pescoço e os ombros, segure por 10-20 segundos e mude de lado."]],"Anterior_Tibialis-SMR":["Anterior Tibialis-SMR",["Comece sentado no chão com as pernas dobradas e os pés no chão.","Usando um rolo muscular ou um rolo, aplique pressão nos músculos do lado de fora de suas canelas, trabalhe de um pouco abaixo do joelho até o tornozelo, parando em pontos de tensão por 10-30 segundos, repita na outra perna."]],"Anti-Gravity_Press":["Imprensa anti-gravidade",["Coloque um bar no chão atrás da cabeça de um banco inclinado.","Deite-se no banco de frente para baixo, com um aperto pronado, pegue a campainha do chão, flexione os cotovelos, fazendo um movimento reverso para aproximar a barra do seu peito, esta será a sua posição inicial.","Para começar, pressione a campainha na frente da cabeça, estendendo os cotovelos, mantendo os braços paralelos ao chão durante todo o movimento.","Retorne à posição inicial e repita para completar o conjunto."]],"Arm_Circles":["Círculos de Braços",["Levantem-se e estendam os braços pelos lados, os braços devem ser paralelos ao chão e perpendiculares (ângulo de 90 graus) ao tronco.","Lentamente comece a fazer círculos de cerca de 1 pé de diâmetro com cada braço estendido.","Continue o movimento circular dos braços estendidos por cerca de dez segundos... então inverta o movimento, indo na direção oposta."]],"Arnold_Dumbbell_Press":["Arnold halteres Press",["Sente-se em um banco de exercícios com apoio nas costas e segure dois halteres na sua frente no nível superior do peito com suas palmas viradas para o corpo e seus cotovelos dobrados.","Agora, para realizar o movimento, levante os halteres enquanto gira as palmas das mãos até que estejam voltadas para frente.","Continue levantando os halteres até que seus braços se estendam acima de você em posição reta do braço.","Depois de uma segunda pausa no topo, comece a abaixar os halteres para a posição original girando as palmas das mãos em sua direção.","Repita para a quantidade recomendada de repetições."]],"Around_The_Worlds":["Ao redor dos mundos",["Deite-se em um banco plano segurando um haltere em cada mão com as palmas das mãos voltadas para o teto.","Agora mova os halteres criando um semicírculo enquanto os desloca da posição inicial para a cabeça, todo o movimento deve acontecer com os braços paralelos ao chão o tempo todo.","Inverta o movimento para devolver o peso à posição inicial enquanto expira."]],"Atlas_Stone_Trainer":["Atlas Stone Trainer",["Este treinador é eficaz para desenvolver a força da Atlas Stone para aqueles que não têm acesso a pedras, e são tipicamente feitos de pontas de bar ou cano pesado.","Comece carregando o peso desejado na barra, endireite o peso, envolvendo seus braços ao redor do implemento, dobrando os quadris.","Comece puxando o peso para cima, passando pelos joelhos, estendendo-se pelos quadris, enquanto o peso limpa os joelhos, ele pode ser colocado em suas coxas e sentado para trás, abraçando-o firmemente ao seu peito.","Termine o movimento estendendo-se através de seus quadris e joelhos para elevar o peso o mais alto possível."]],"Atlas_Stones":["Atlas Stones.",["Comece com a pedra do atlas entre seus pés, dobre-se nos quadris para envolver seus braços verticalmente ao redor da Pedra Atlas, tentando colocar seus dedos sob a pedra, muitas pedras terão uma pequena porção plana no fundo, o que tornará a pedra mais fácil de segurar.","Puxando a pedra em seu torso, dirigir através da metade de trás de seus pés para puxar a pedra do chão.","Enquanto a pedra passa pelos joelhos, laceá-la sentando-se para trás, puxando a pedra em cima de suas coxas.","Sente-se baixo, colocando a pedra no peito enquanto você muda seu aperto para alcançar sobre a pedra. Levante-se, dirigindo através com seus quadris."]],"Axle_Deadlift":["Axle Deadlift",["Aproxime-se da barra para que ela esteja centrada sobre seus pés, os pés devem ter a largura do quadril à parte, dobre-se no quadril para segurar a barra na largura do ombro, permitindo que suas omoplatas se prolonguem.","Com os pés e o aperto, respire fundo, abaixe os quadris e flexione os joelhos até que suas canelas entrem em contato com a barra, olhe para frente com a cabeça, mantenha o peito para cima e as costas arqueadas, e comece a dirigir através dos calcanhares para mover o peso para cima.","Depois que a barra passar os joelhos, puxe a barra agressivamente para trás, puxando suas omoplatas juntos enquanto você dirige seus quadris para a frente para a barra.","Abaixe a barra dobrando-se nos quadris e guiando-a até o chão."]],"Back_Flyes_-_With_Bands":["Back Flyes - Com Bandas",["Passe uma banda em torno de um poste estacionário como aquele de um rack de agachamento.","Pegue a banda pelos punhos e afaste-se para que a tensão na banda aumente.","Seus braços devem ser retos e paralelos ao chão, enquanto perpendiculares ao tronco, seus pés devem ser firmemente plantados no chão, espalhados na largura do ombro, esta será a sua posição inicial.","Enquanto você expira, mova seus braços para os lados e para trás, mantenha seus braços estendidos e paralelos ao chão, continue o movimento até que os braços sejam estendidos para os seus lados.","Depois de uma pausa, volte para a posição original enquanto inala.","Repita para a quantidade recomendada de repetições."]],"Backward_Drag":["Retroceder Drag",["Carregue um trenó com o peso desejado, prendendo uma corda ou amarras no trenó que você pode segurar.","Comece o exercício movendo-se para trás para uma determinada distância, inclinando-se para trás, estendendo-se através das pernas para passos curtos para se mover o mais rápido possível."]],"Backward_Medicine_Ball_Throw":["Bola de Medicina Retrocedente",["Este exercício é melhor feito com um parceiro, se lhe falta um parceiro, a bola pode ser jogada e recuperada ou jogada contra uma parede.","Comece a ficar de pé alguns metros na frente de seu parceiro, ambos voltados para a mesma direção.","Agache-se e inverta a direção com força, chegando a extensão total e você joga a bola sobre a cabeça para o seu parceiro.","Seu parceiro pode então rolar a bola de volta para você."]],"Balance_Board":["Equilíbrio Board",["Coloque uma tábua de balanço na sua frente.","Levante-se e tente se equilibrar.","Mantenha o equilíbrio o tempo que quiser."]],"Ball_Leg_Curl":["Perna de bola Curl",["Comece no chão deitado com os pés em cima da bola.","Posicione a bola para que quando suas pernas estiverem estendidas seus tornozelos estejam em cima da bola.","Levante os quadris do chão, mantendo seu peso nas omoplatas e pés.","Flexione os joelhos, puxe a bola o mais perto possível, contraindo os isquiotibiais.","Após uma breve pausa, volte para a posição inicial."]],"Band_Assisted_Pull-Up":["Banda assistida puxar-para cima",["Esmague a banda no centro da barra, pode usar diferentes bandas para fornecer diferentes níveis de assistência.","Puxe a ponta da banda para baixo, e coloque um joelho dobrado no loop, garantindo que ele não escorregue.","Puxe-se para cima, contraindo os lats enquanto você flexiona o cotovelo, o cotovelo deve ser conduzido para o seu lado, puxe para a frente, tentando obter o queixo sobre a barra, evite movimentos de balanço ou de bater.","Após uma breve pausa, volte para a posição inicial."]],"Band_Good_Morning":["Bom dia, banda.",["Usando uma faixa de 41 polegadas, fique em uma ponta, espalhando seus pés uma pequena quantidade, dobre-se nos quadris para tocar o fim da banda atrás do pescoço, esta será a sua posição inicial.","Mantendo as pernas retas, estenda-se pelos quadris para chegar a uma posição vertical.","Certifique-se de que não vire as costas quando voltar para a posição inicial."]],"Band_Good_Morning_Pull_Through":["Bom dia, banda.",["Coloque a banda ao redor de um poste, fique um pouco longe, toque a ponta oposta ao redor do pescoço, suas mãos podem ajudar a manter a banda em posição.","Comece dobrando os quadris, recuperando sua bunda o mais longe possível, mantenha as costas planas e incline-se para a frente até cerca de 90 graus, seus joelhos devem estar ligeiramente dobrados.","Volte para a posição de partida e dirija com os quadris para voltar a uma posição de pé."]],"Band_Hip_Adductions":["Banda Hip Adductions",["Âncora uma banda em torno de um poste sólido ou outro objeto.","Fique com o lado esquerdo para o poste, e coloque seu pé direito através da banda, colocando-o ao redor do tornozelo.","Levante-se e segure o poste, se necessário.","Mantendo o joelho reto, levante as pernas direitas para o lado o máximo que puder.","Retorne à posição inicial e repita para a contagem desejada.","Troque de lado."]],"Band_Pull_Apart":["\"Banda Puxar Para Fora\"",["Comece com os braços estendidos bem na sua frente, segurando a banda com as duas mãos.","Iniciar o movimento realizando um movimento de mosca reversa, movendo suas mãos lateralmente para os seus lados.","Mantenha os cotovelos estendidos enquanto executa o movimento, trazendo a banda para o peito, certifique-se de manter os ombros afastados durante o exercício.","Pause enquanto completa o movimento, retornando à posição inicial sob controle."]],"Band_Skull_Crusher":["Band Skull Crusher",["Coloque uma banda na base de um rack ou banco, e coloque no banco para que a banda esteja alinhada com sua cabeça.","Segure a banda, levante os cotovelos para que o braço seja perpendicular ao chão, com o cotovelo flexionado, a banda deve estar acima da sua cabeça, esta será a sua posição inicial.","Estenda o cotovelo para endireitar o braço, mantendo o braço no lugar, pare no topo do movimento e volte para a posição inicial."]],"Barbell_Ab_Rollout_-_On_Knees":["\"Barbell Ab Rollout - Sobre Joelhos\"",["Segure uma campainha olímpica carregada com 5-10 libras de cada lado e ajoelhe-se no chão.","Agora coloque a campainha no chão na sua frente para que você esteja de joelhos.","Desça o mais longe que puder sem tocar o chão com seu corpo, respire durante esta parte do movimento.","Depois de uma segunda pausa na posição esticada, comece a se puxar de volta para a posição inicial enquanto expira."]],"Barbell_Bench_Press_-_Medium_Grip":["Barbell Bench Press - Aperto médio",["Deite-se em um banco plano, usando um aperto de largura média (um aperto que cria um ângulo de 90 graus no meio do movimento entre os antebraços e os braços superiores), levante a barra do rack e segure-a diretamente sobre você com os braços bloqueados.","A partir da posição inicial, respire e comece a descer lentamente até que o bar toque seu peito médio.","Depois de uma breve pausa, empurre a barra de volta para a posição inicial enquanto expira, concentre-se em empurrar a barra usando os músculos do peito, tranque os braços e aperte o peito na posição contraída no topo do movimento, segure por um segundo e comece a descer lentamente novamente.","Repita o movimento para a quantidade prescrita de repetições.","Quando terminar, coloque o bar de volta no rack."]],"Barbell_Curl":["Barbell Curl",["Levante-se com o torso ereto enquanto segura uma campainha no ombro, a palma das mãos deve estar voltada para frente e os cotovelos devem estar perto do torso, esta será sua posição inicial.","Enquanto segura os braços parados, enrole os pesos para frente enquanto contrai os bíceps enquanto expira.","Continue o movimento até que seus bíceps estejam totalmente contraídos e a barra esteja no nível do ombro.","Lentamente começar a trazer o bar de volta à posição inicial enquanto você respira.","Repita para a quantidade recomendada de repetições."]],"Barbell_Curls_Lying_Against_An_Incline":["Barbell Curls mentindo contra uma incline",["Deite-se contra um banco inclinado, com seus braços segurando uma campainha e pendurado em uma linha horizontal.","Enquanto mantém os braços parados, enrole o peso o mais alto que puder enquanto aperta os bíceps, respire enquanto realiza esta parte do movimento, só os antebraços devem se mover, não balance os braços.","Depois de uma segunda contração, lentamente volte para a posição inicial enquanto inala.","Repita para a quantidade recomendada de repetições."]],"Barbell_Deadlift":["Barbell Deadlift.",["Fique na frente de um barbeiro carregado.","Enquanto mantém as costas o mais retas possível, dobre os joelhos, dobre para a frente e segure a barra usando um aperto médio (largura do ombro) sobre a mão. Esta será a posição inicial do exercício.","Enquanto segura a barra, comece o elevador empurrando com as pernas enquanto simultaneamente coloca seu tronco na posição vertical enquanto expira, na posição vertical, estique seu peito e contraia as costas trazendo as omoplatas de volta, pense em como os soldados do exército olham quando estão em pé na atenção.","Volte para a posição inicial, dobrando-se nos joelhos, ao mesmo tempo que inclina o tronco para a frente na cintura, mantendo as costas retas, e quando os pesos da barra tocarem o chão, você estará de volta na posição inicial e pronto para realizar outra repetição.","Execute a quantidade de repetições prescritas no programa."]],"Barbell_Glute_Bridge":["Ponte Barbell Glute",["Comece sentado no chão com uma barbela carregada sobre suas pernas usando uma barra de gordura ou tendo uma almofada na barra pode reduzir muito o desconforto causado por este exercício.","Comece o movimento dirigindo com os calcanhares, estendendo os quadris verticalmente através da barra, seu peso deve ser suportado pelas costas e os calcanhares dos pés.","Estenda o máximo possível, então reverta o movimento para voltar à posição inicial."]],"Barbell_Guillotine_Bench_Press":["Barbell Guillotine Bench Press",["Usando um aperto de largura média (um aperto que cria um ângulo de 90 graus no meio do movimento entre os antebraços e os braços superiores), levante a barra do rack e segure-a sobre o pescoço com os braços presos.","Enquanto respira, desça a barra lentamente até que esteja a cerca de 1 polegada do seu pescoço.","Depois de uma segunda pausa, traga a barra de volta para a posição inicial enquanto você expira e empurre a barra usando os músculos do peito, tranque os braços e aperte o peito na posição contraída, segure por um segundo e comece a descer lentamente novamente, deve demorar pelo menos duas vezes mais para descer do que subir.","Repita o movimento para a quantidade prescrita de repetições.","Quando terminar, coloque o bar de volta no rack."]],"Barbell_Hack_Squat":["Barbell Hack Squat",["Levante-se direito enquanto segura uma campainha atrás dos braços e seus pés na largura do ombro.","Enquanto mantém a cabeça e os olhos para cima e para trás, agache-se até que suas coxas estejam paralelas ao chão.","Pressionando principalmente com o calcanhar do pé e apertando as coxas, volte para cima enquanto expira.","Repita para a quantidade recomendada de repetições."]],"Barbell_Hip_Thrust":["Barbell Hip Thrust",["Começar sentado no chão com um banco atrás de você, ter uma barba carregada sobre as pernas, usar uma barra de gordura ou ter uma almofada na barra pode reduzir muito o desconforto causado por este exercício.","Role a barra para que esteja diretamente acima de seus quadris, e incline-se para trás contra o banco para que suas omoplatas estejam perto do topo dela.","Comece o movimento dirigindo através de seus pés, estendendo seus quadris verticalmente através da barra, seu peso deve ser suportado por suas omoplatas e seus pés, estenda o mais longe possível, então inverta o movimento para voltar à posição inicial."]],"Barbell_Incline_Bench_Press_-_Medium_Grip":["Barbell Incline Bench Press - Aperto médio",["Deite-se em um banco inclinado, usando um aperto de largura média (um aperto que cria um ângulo de 90 graus no meio do movimento entre os antebraços e os braços superiores), levante a barra do rack e segure-a diretamente sobre você com os braços trancados.","Enquanto você respira, desça devagar até sentir a barra em seu peito superior.","Depois de uma segunda pausa, traga a barra de volta para a posição inicial enquanto você expira e empurre a barra usando os músculos do peito, tranque os braços na posição contraída, aperte o peito, segure por um segundo e então comece a descer lentamente novamente.","Repita o movimento para a quantidade prescrita de repetições.","Quando terminar, coloque o bar de volta no rack."]],"Barbell_Incline_Shoulder_Raise":["\"Barbell Incline Shoulder Elevou\"",["Deite-se em um banco de inclinação, usando um aperto de largura média (um aperto ligeiramente maior que a largura do ombro), levante a barra do rack e segure-a em cima de você com os braços retos.","Enquanto mantém os braços retos, levante a barra, atrasando suas omoplatas, levantando os ombros do banco enquanto você expira.","Traga o bar de volta para a posição inicial enquanto você respira.","Repita para a quantidade recomendada de repetições."]],"Barbell_Lunge":["Barbell Lunge",["Este exercício é melhor realizado dentro de um rack de agachamento para fins de segurança, para começar, primeiro coloque a barra em um rack logo abaixo do nível do ombro, uma vez que a altura correta é escolhida e a barra é carregada, passo abaixo da barra e colocar a parte de trás de seus ombros (ligeiramente abaixo do pescoço) através dele.","Segure-se na barra usando os dois braços de cada lado e levante-a do rack empurrando com as pernas e ao mesmo tempo endireitando o tronco.","Afaste-se do rack e dê um passo à frente com sua perna direita e agache-se através de seus quadris, mantendo o tronco ereto e mantendo o equilíbrio.","Usando principalmente o calcanhar do seu pé, empurre para cima e volte para a posição inicial enquanto expira.","Repita o movimento para a quantidade recomendada de repetições e então execute com a perna esquerda."]],"Barbell_Rear_Delt_Row":["Barbell Rear Delt Row",["Levante-se direito enquanto segura uma campainha usando um aperto largo (mais alto que a largura do ombro) e overhand (palms de frente para o seu corpo).","Dobrar os joelhos ligeiramente e curvar-se enquanto você mantém o arco natural de suas costas... deixar os braços pendurados na sua frente enquanto seguram a barra... assim que seu torso estiver paralelo ao chão, abrace os cotovelos e afaste-se do seu corpo... e seu torso e seus braços devem se assemelhar à letra \"T\", agora você está pronto para começar o exercício.","Enquanto mantém os braços superiores perpendiculares ao torso, puxe a barra para cima em direção ao peito superior enquanto aperta os delts traseiros e expira.","Lentamente volte para a posição inicial enquanto respira.","Repita para a quantidade recomendada de repetições."]],"Barbell_Rollout_from_Bench":["Barbell Rollout da Bench",["Ajoelhe-se com as duas pernas no banco, e tome uma pegada média a estreita no barbelo.","Para começar, estenda os quadris para rolar lentamente a barra para frente, enquanto você se move, flexione o ombro para rolar a barra acima da cabeça, certifique-se de que seus braços permaneçam estendidos ao longo do movimento.","Quando o bar for movido o mais longe possível, volte para a posição inicial."]],"Barbell_Seated_Calf_Raise":["\"Barbell Seated Calf Crescimento\"",["Coloque um bloco cerca de 12 polegadas na frente de um banco plano.","Sente-se no banco e coloque a bola dos pés no bloco.","Peça para alguém colocar uma campainha sobre suas coxas acima de seus joelhos e segure-a lá.","Levantem os dedos o mais alto possível e apertem os bezerros e expirem.","Depois de uma segunda contração, lentamente volte para a posição inicial.","Repita para a quantidade recomendada de repetições."]],"Barbell_Shoulder_Press":["Barbell Ombros Press",["Sente-se em um banco com apoio traseiro em um rack de agachamento, posicione uma campainha em uma altura que está logo acima de sua cabeça, pegue a campainha com um aperto pronado (palmas voltadas para frente).","Uma vez que você pegar a barra com a largura de aperto correta, levante a barra sobre sua cabeça, trancando seus braços, mantenha o nível do ombro e levemente na frente da cabeça.","Abaixe a barra para os ombros devagar enquanto inala.","Levante a barra de volta para a posição inicial enquanto expira.","Repita para a quantidade recomendada de repetições."]],"Barbell_Shrug":["Barbell Shrug",["Levante-se com os pés na largura do ombro enquanto segura uma campainha com as duas mãos na sua frente usando um aperto pronado (palmas voltados para as coxas).","Levante os ombros o máximo que puder enquanto expira e segure a contração por um segundo.","Retorne lentamente à posição inicial enquanto respira.","Repita para a quantidade recomendada de repetições."]],"Barbell_Shrug_Behind_The_Back":["Barbell encolhe atrás das costas.",["Levante-se com os pés na largura do ombro enquanto segura uma campainha com as duas mãos atrás das costas usando um aperto pronado (palmas voltados para trás).","Levante os ombros o máximo que puder enquanto expira e segure a contração por um segundo.","Retorne lentamente à posição inicial enquanto respira.","Repita para a quantidade recomendada de repetições."]],"Barbell_Side_Bend":["Barbell Side Bend",["Levante-se direito enquanto segura uma campainha colocada na parte de trás dos ombros, seus pés devem estar com a largura do ombro afastada, esta será a sua posição inicial.","Enquanto mantém as costas retas e a cabeça para cima, dobra-se apenas na cintura para a direita o mais longe possível, respira enquanto se inclina para o lado, então segure por um segundo e volte à posição inicial enquanto expira.","Agora repita o movimento, mas dobre-se para a esquerda.","Repita para a quantidade recomendada de repetições."]],"Barbell_Side_Split_Squat":["Barbell Side Split Squat",["Levante-se direito enquanto segura uma campainha colocada na parte de trás dos ombros (um pouco abaixo do pescoço), seus pés devem ser colocados bem afastados com o pé da perna de chumbo inclinada para o lado.","Abaixe o corpo para o lado do pé, dobrando o joelho e o quadril da perna de chumbo e mantendo a perna oposta apenas ligeiramente dobrada.","Volte para a posição inicial, estendendo o quadril e joelho da perna principal.","Depois de executar a quantidade recomendada de representantes, repita o movimento com a perna oposta."]],"Barbell_Squat":["Barbell Squat",["Este exercício é melhor realizado dentro de um rack de agachamento para fins de segurança, para começar, primeiro coloque a barra em um rack para bem abaixo do nível do ombro, uma vez que a altura correta é escolhida e a barra é carregada, passo sob a barra e coloque a parte de trás de seus ombros (levemente abaixo do pescoço) através dele.","Segure-se na barra usando os dois braços de cada lado e levante-a do rack empurrando com as pernas e ao mesmo tempo endireitando o tronco.","Afaste-se do rack e posicione suas pernas usando uma posição média do ombro com os dedos dos pés ligeiramente apontados, mantenha sua cabeça erguida o tempo todo e também mantenha uma reta para trás, esta será sua posição inicial, para os fins desta discussão, usaremos a posição média descrita acima, que visa o desenvolvimento geral, no entanto você pode escolher qualquer uma das três posições discutidas na seção de posturas dos pés.","Comece a baixar lentamente a barra dobrando os joelhos e os quadris enquanto mantém uma postura reta com a cabeça para cima. Continue para baixo até que o ângulo entre a perna superior e os bezerros se torne ligeiramente inferior a 90 graus. Inspire enquanto você executa esta parte do movimento. Dica: Se você realizou o exercício corretamente, a frente dos joelhos deve fazer uma linha reta imaginária com os dedos perpendiculares à frente. Se seus joelhos estão além dessa linha imaginária (se eles estão além dos dedos dos pés) então você está colocando estresse excessivo no joelho e o exercício foi realizado incorretamente.","Comece a levantar a barra enquanto expira, empurrando o chão com o calcanhar do pé, enquanto endireita as pernas novamente e volta para a posição inicial.","Repita para a quantidade recomendada de repetições."]],"Barbell_Squat_To_A_Bench":["\"Barbell Squat To A Bench\"",["Este exercício é melhor realizado dentro de um rack de agachamento para fins de segurança, para começar, primeiro coloque um banco plano ou uma caixa atrás de você, o banco plano é usado para ensiná-lo a colocar seus quadris de volta e atingir profundidade.","Depois de escolher a altura correta e carregar a barra, passe por baixo da barra e coloque a parte de trás dos ombros (um pouco abaixo do pescoço) através dela.","Segure-se na barra usando os dois braços de cada lado e levante-a do rack empurrando com as pernas e ao mesmo tempo endireitando o tronco.","Afaste-se do rack e posicione suas pernas usando uma posição média de largura do ombro com os dedos dos pés ligeiramente apontados. Mantenha sua cabeça erguida o tempo todo como olhando para baixo vai deixá-lo fora de equilíbrio e também manter uma reta para trás.","Se você fizer o exercício corretamente, a frente dos joelhos deve fazer uma linha reta imaginária com os dedos perpendiculares à frente. Se seus joelhos estão além dessa linha imaginária (se eles estão além dos dedos dos pés) então você está colocando estresse excessivo no joelho e o exercício foi realizado incorretamente.","Comece a levantar a barra enquanto expira, empurrando o chão com o calcanhar do pé, enquanto endireita as pernas e estende os quadris para voltar à posição inicial.","Repita para a quantidade recomendada de repetições."]],"Barbell_Step_Ups":["Barbell sobe.",["Levante-se direito enquanto segura uma campainha colocada na parte de trás dos ombros (um pouco abaixo do pescoço) e fique de pé atrás de uma plataforma elevada (como a usada para ver atrás de um banco plano).","Coloque o pé direito na plataforma elevada, pise na plataforma estendendo o quadril e o joelho da perna direita, use o calcanhar principalmente para levantar o resto do corpo e colocar o pé da perna esquerda na plataforma também, respire enquanto executa a força necessária para subir.","Desça com a perna esquerda, flexionando o quadril e o joelho da perna direita enquanto inala, e volte para a posição de pé original, colocando o pé direito ao lado do pé esquerdo na posição inicial.","Repita com a perna direita para a quantidade recomendada de repetições e depois execute com a perna esquerda."]],"Barbell_Walking_Lunge":["Barbell Walking Lunge",["Comece a ficar de pé com os pés com a largura do ombro e uma campainha nas costas.","Avance com uma perna, flexionando os joelhos para baixar os quadris, desça até o joelho traseiro quase tocar o chão, sua postura deve permanecer ereta, e seu joelho dianteiro deve ficar acima do pé dianteiro.","Dirija pelo calcanhar do seu pé de chumbo e estenda os joelhos para se levantar.","Dê um passo à frente com o pé traseiro, repetindo o pulmão na perna oposta."]],"Battling_Ropes":["Lutando contra as Cordas",["Para este exercício, você precisará de uma corda pesada ancorada no seu centro a 15-20 pés de distância, de pé na frente da corda, tomar uma extremidade em cada mão com seus braços estendidos ao seu lado.","Iniciar o movimento elevando rapidamente um braço ao nível do ombro o mais rápido possível.","Enquanto você deixa o braço cair para a posição inicial, levante o lado oposto.","Continue alternando seus braços esquerdo e direito, chicoteando as cordas para cima e para baixo o mais rápido possível."]],"Bear_Crawl_Sled_Drags":["Bear Crawl Sled Drags",["Usando um arnês ou um cinto de peso solto, amarre a corrente na parte de trás para que você fique de frente para longe do trenó, dobre para que suas mãos estejam no chão, suas costas devem estar planas e joelhos dobrados, esta é a sua posição inicial.","Comece dirigindo com as pernas, alternando a esquerda e a direita... use as mãos para manter o equilíbrio e ajudar a puxar... tente manter as costas planas enquanto se move sobre uma determinada distância."]],"Behind_Head_Chest_Stretch":["Atrás da cabeça peito esticar",["Sente-se no chão com seu parceiro atrás de você.","Coloque as mãos atrás da mão, e empurre os cotovelos o mais longe que puder, seu parceiro deve segurar os cotovelos, esta será sua posição inicial.","Tente gentilmente puxar os cotovelos para frente com as mãos atrás da cabeça por 10 ou mais segundos, e seu parceiro deve evitar que seus cotovelos se mova.","Agora relaxe os músculos e faça com que seu parceiro puxe os cotovelos para trás, até que seja confortável para você."]],"Bench_Dips":["Mergulho de Bench.",["Para este exercício você precisará colocar um banco atrás das costas, com o banco perpendicular ao seu corpo, e enquanto olha para longe dele, segure o banco na borda com as mãos totalmente estendidas, separadas na largura do ombro, as pernas serão estendidas para frente, dobradas na cintura e perpendiculares ao seu tronco, esta será a sua posição inicial.","Abaixe lentamente o corpo enquanto inala dobrando os cotovelos até se abaixar o suficiente para um ângulo ligeiramente menor que 90 graus entre o braço e o antebraço.","Usando seu tríceps para levantar seu tronco novamente, levante-se de volta para a posição inicial.","Repita para a quantidade recomendada de repetições."]],"Bench_Jump":["Bench Jump",["Comece com uma caixa ou banco 1-2 pés na sua frente, fique com os pés afastados, esta será sua posição inicial.","Faça um pequeno agachamento em preparação para o salto, balance os braços para trás.","Rebound fora desta posição, estendendo-se através dos quadris, joelhos e tornozelos para saltar o mais alto possível.","Salte sobre o banco, pousando com os joelhos dobrados, absorvendo o impacto através das pernas.","Vire-se e vire-se para a direção oposta, e depois pule de volta sobre o banco."]],"Bench_Press_-_Powerlifting":["\"Pressão de bancada - Powerlifting\"",["Comece por deitar-se no banco, tirando a cabeça do bar, se possível, coloque os pés embaixo de você e arqueie as costas, usando a barra para ajudar a suportar o seu peso, levantar o ombro do banco e retraí-los, apertando as omoplatas juntos, use seus pés para colocar suas armadilhas no banco, mantenha essa posição firme do corpo durante todo o movimento.","Por maior que seja o seu aperto, deve cobrir o anel na barra, puxar a barra para fora do rack sem prolongar seus ombros, concentrar-se em apertar a barra e tentar desmontá-la.","A barra, o pulso e o cotovelo devem ficar em fila o tempo todo.","Pause quando a campainha tocar seu torso, e depois empurre a barra com o máximo de força possível."]],"Bench_Press_-_With_Bands":["A imprensa Bench Com Bandas",["Usando um banco plano, mantenha uma faixa sob a perna do banco que é mais próxima da sua cabeça.","Assim que a banda estiver segura, agarre-a pelos dois cabos e deite-se no banco.","Estenda seus braços para que você esteja segurando as alças da banda na sua frente com a largura do ombro.","Uma vez na largura do ombro, gire os pulsos para frente para que as palmas das mãos estejam viradas para longe de você.","Abaixe as alças lentamente até que seu cotovelo forme um ângulo de 90 graus.","Como você expirar, traga as alças para cima usando seus músculos peitorais, tranque os braços na posição contraída, aperte o peito, segure por um segundo e então comece a descer lentamente.","Repita o movimento para a quantidade prescrita de repetições do seu programa de treinamento."]],"Bench_Press_with_Chains":["Bench Press com correntes",["Ajuste a corrente líder, encurtando-a ao comprimento desejado. Coloque as correntes nas mangas da barra.","Deitado no banco, coloque a cabeça para fora da barra, se possível, coloque os pés embaixo de você e arqueie as costas, usando a barra para ajudar a suportar o seu peso, levante o ombro do banco e retraia-os, apertando as omoplatas juntos, use os pés para colocar as armadilhas no banco, mantenha esta posição firme do corpo durante todo o movimento, por maior que seja o seu aperto, ele deve cobrir o anel na barra.","Tire a barra da prateleira sem atrasar os ombros, concentre-se em apertar a barra e tentar desmontá-la, baixar a barra para o peito ou estômago, a barra, o pulso e o cotovelo devem ficar em linha o tempo todo.","Pause quando a campainha tocar seu torso, e depois empurre a barra com o máximo de força possível."]],"Bench_Sprint":["Bench Sprint",["Fique no chão com um pé descansando em um banco ou caixa com seu calcanhar perto da borda.","Empurre com o pé em cima do banco, estendendo-se através do quadril e joelho.","Aterrisse com o pé oposto em cima da caixa, devolvendo seu outro pé de volta para a posição inicial.","Continuar alternando de um pé para outro para completar o conjunto."]],"Bent-Arm_Barbell_Pullover":["Bent-Arm Barbell Pullover",["Deite-se em um banco plano com uma campainha usando uma largura de aperto de ombro.","Segure a barra sobre o peito com uma curva nos braços.","Enquanto mantém os braços na posição do braço dobrado, abaixe o peso lentamente em um arco atrás da cabeça enquanto respira até sentir um estiramento no peito.","Nesse ponto, traga a campainha de volta para a posição inicial usando o arco através do qual o peso foi reduzido e expirar enquanto você realiza esse movimento.","Mantenha o peso na posição inicial por um segundo e repita o movimento para o número prescrito de repetições."]],"Bent-Arm_Dumbbell_Pullover":["Bent-Arm halteres Pullover",["Coloque um haltere em pé em um banco plano.","Assegurando que o haltere permaneça firmemente colocado no topo do banco, fique perpendicular ao banco (torso através dele como formando uma cruz) com apenas seus ombros deitados na superfície.","Segure o haltere com as duas mãos e segure-o sobre o peito com uma curva nos braços, ambas as palmas devem estar pressionando contra o lado de baixo de um dos lados do haltere, esta será sua posição inicial, cuidado, sempre certifique-se de que o haltere usado para este exercício seja seguro, usando um haltere com placas soltas, pode resultar em um haltere caindo aos pedaços e caindo em seu rosto.","Enquanto mantém os braços presos na posição do braço dobrado, abaixe o peso lentamente em um arco atrás da cabeça enquanto respira até sentir um estiramento no peito.","Nesse ponto, traga o haltere de volta para a posição inicial usando o arco através do qual o peso foi reduzido e expirar enquanto você realiza esse movimento.","Mantenha o peso na posição inicial por um segundo e repita o movimento para o número prescrito de repetições."]],"Bent-Knee_Hip_Raise":["Levante o quadril do joelho dobrado.",["Deite-se no chão com os braços ao lado dos seus lados.","Agora dobre seus joelhos em torno de um ângulo de 75 graus e levante seus pés do chão por cerca de 2 polegadas.","Usando o abdômen inferior, traga seus joelhos em sua direção enquanto mantém o ângulo de 75 graus dobrando suas pernas, continue esse movimento até que levante seus quadris do chão, rodando sua pélvis para trás, e expire enquanto executa esta parte do movimento, e no final do movimento seus joelhos estarão sobre seu peito.","Aperte o abdômen no topo do movimento por um segundo e depois volte para a posição inicial lentamente enquanto respira.","Repita para a quantidade recomendada de repetições."]],"Bent_Over_Barbell_Row":["Bent Over Barbell Row",["Segurando uma campainha com um aperto pronado (palmas viradas para baixo), dobre os joelhos ligeiramente e leve seu tronco para frente, dobrando na cintura, mantendo as costas retas até que seja quase paralelo ao chão.","Agora, mantendo o torso parado, expire e levante a campainha para você, mantenha os cotovelos perto do corpo e apenas use os antebraços para segurar o peso, na posição superior contraída, aperte os músculos das costas e segure para uma breve pausa.","Em seguida, inale e lentamente abaixe a campainha de volta para a posição inicial.","Repita para a quantidade recomendada de repetições."]],"Bent_Over_Dumbbell_Rear_Delt_Raise_With_Head_On_Bench":["Curve-se sobre halteres Traseiro Delt levantar com cabeça em Bench",["Levante-se direito enquanto segura um haltere em cada mão e com um banco inclinado na sua frente.","Ao manter as costas retas e manter o arco natural das costas, incline-se para frente até que sua testa toque o banco na sua frente, deixe os braços pendurados na sua frente perpendiculares ao chão, as palmas das mãos devem estar voltadas uma para a outra e seu tronco deve ser paralelo ao chão, esta será a sua posição inicial.","Mantendo seu torso para frente e parado, e os braços retos com uma leve curva nos cotovelos, levante os halteres direto para o lado até que ambos os braços sejam paralelos ao chão. Expire enquanto você levanta os pesos. Cuidado: evite balançar o torso ou trazer os braços de volta em oposição ao lado.","Após uma contração de um segundo no topo, lentamente abaixe os halteres de volta para a posição inicial.","Repita a quantidade recomendada de repetições."]],"Bent_Over_Low-Pulley_Side_Lateral":["Bent Over Low-Pulley Side Lateral",["Escolha um peso e segure o cabo da polia baixa com a mão direita.","Suas pernas devem estar ligeiramente dobradas com a mão esquerda colocada em sua coxa esquerda, seu braço direito deve estar pendurado em seu ombro na sua frente e com uma pequena dobra no cotovelo, esta será sua posição inicial.","Levante seu braço direito, cotovelo ligeiramente dobrado, para o lado até que o braço esteja paralelo ao chão e em linha com sua orelha direita.","Reduza lentamente o peso de volta para a posição inicial enquanto respira.","Repita a quantidade recomendada de repetições e repita o movimento com o outro braço."]],"Bent_Over_One-Arm_Long_Bar_Row":["Curve-se sobre uma fila de barras de um braço.",["Coloque peso em uma das extremidades de um barbell olímpico, certifique-se de colocar a outra ponta do barbell no canto de duas paredes, ou coloque um objeto pesado no chão para que o barbell não deslize para trás.","Dobre para a frente até que seu torso esteja o mais próximo possível do paralelo com o chão e mantenha seus joelhos ligeiramente dobrados.","Agora pegue a barra com um braço atrás das placas do lado onde o peso foi colocado e coloque sua outra mão no joelho.","Puxe a barra para cima com o cotovelo para dentro (para maximizar a estimulação das costas) até que as placas toquem seu peito inferior. Aperte os músculos das costas enquanto levanta o peso e segure por um segundo no topo do movimento. Respire enquanto levanta o peso.","Dica: não deixe as placas tocarem o chão para garantir a melhor amplitude de movimento, eu recomendo usar placas pequenas (25-lbs) ao invés de placas maiores (como 35-45lbs).","Repita para a quantidade recomendada de repetições e mude de braços."]],"Bent_Over_Two-Arm_Long_Bar_Row":["Curve-se sobre a fila de bar de dois braços.",["Coloque peso em uma das extremidades de um barbell olímpico, certifique-se de colocar a outra ponta do barbell no canto de duas paredes, ou coloque um objeto pesado no chão para que o barbell não deslize para trás.","Dobre para a frente até que seu torso esteja o mais próximo possível do paralelo com o chão e mantenha seus joelhos ligeiramente dobrados.","Agora pegue a barra com os dois braços atrás das placas do lado onde o peso foi colocado e coloque sua outra mão em seu joelho.","Puxe a barra para cima com os cotovelos para dentro (para maximizar a estimulação das costas) até que as placas toquem seu peito inferior. Aperte os músculos das costas enquanto levanta o peso e segure por um segundo no topo do movimento.","Dica: não deixe as placas tocarem o chão para garantir a melhor amplitude de movimento, eu recomendo usar placas pequenas (25-lbs) ao invés de placas maiores (como 35-45lbs).","Repita para a quantidade recomendada de repetições."]],"Bent_Over_Two-Dumbbell_Row":["Curve-se sobre a fila de dois idiotas.",["Com um haltere em cada mão (palmas voltados para o torso), dobre os joelhos ligeiramente e leve o torso para frente, dobrando na cintura, enquanto você se dobra, mantenha as costas retas até que seja quase paralelo ao chão.","Enquanto mantém o tronco parado, levante os halteres para o lado (como você expira), mantendo os cotovelos perto do corpo (não exercer qualquer força com o antebraço além de segurar os pesos). Na posição contraída superior, aperte os músculos das costas e segure por um segundo.","Devagar, reduza o peso novamente para a posição inicial enquanto inala.","Repita para a quantidade recomendada de repetições."]],"Bent_Over_Two-Dumbbell_Row_With_Palms_In":["Dobre-se sobre a fila de dois idiotas com palmas.",["Com um haltere em cada mão (palmas viradas uma para a outra), dobre os joelhos ligeiramente e leve o tronco para frente, dobrando na cintura, mantendo as costas retas até que seja quase paralelo ao chão. Dica: certifique-se de manter a cabeça erguida.","Enquanto mantém o tronco parado, levante os halteres para o seu lado enquanto expira, apertando suas omoplatas juntos, na posição contraída, aperta os músculos das costas e segura por um segundo.","Devagar, reduza o peso novamente para a posição inicial enquanto inala.","Repita para a quantidade recomendada de repetições."]],"Bent_Press":["Bent Press.",["Limpe uma chaleira no ombro, limpe a chaleira nos ombros, estendendo-se pelas pernas e quadris, enquanto levanta a chaleira para o ombro, o pulso deve girar enquanto faz isso, esta será a sua posição inicial.","Comece a me inclinar para o lado oposto da chaleira, continuando até que você possa tocar o chão com sua mão livre, mantendo seus olhos na chaleira, enquanto você faz isso, pressione o peso verticalmente se estendendo através do cotovelo, mantendo seu braço perpendicular ao chão.","Volte para a posição vertical, com a campainha acima da cabeça, devolva a campainha ao ombro e repita para o número desejado de repetições."]],"Bicycling":["Bicicleta.",["Para começar, sente-se na moto e ajuste o assento à sua altura."]],"Bicycling_Stationary":["Bicicleta, estacionária.",["Para começar, sente-se na moto e ajuste o assento à sua altura.","Você pode começar a pedalar para ligá-lo, usar a configuração manual, ou selecionar um programa para usar, normalmente, você pode inserir sua idade e peso para estimar a quantidade de calorias queimadas durante o exercício, o nível de resistência pode ser alterado durante todo o treino, os cabos podem ser usados para monitorar sua frequência cardíaca para ajudá-lo a ficar em uma intensidade apropriada."]],"Board_Press":["Imprensa do Tabuleiro",["Comece deitado no banco, tirando sua cabeça do bar, se possível, uma a cinco tábuas, feitas de 2x6, podem ser ferradas juntas e mantidas no lugar por um parceiro de treinamento, bandas, ou apenas enfiadas sob sua camisa.","Coloque os pés embaixo de você e arqueie as costas usando a barra para ajudar a suportar seu peso, levante seu ombro do banco e retraia-os, apertando as omoplatas juntos, use seus pés para levar suas armadilhas para o banco, mantenha esta posição firme do corpo durante todo o movimento.","Você pode pegar um aperto de banco padrão, ou largura do ombro para focar no tríceps, puxar a barra para fora do rack sem prolongar seus ombros, a barra, pulso e cotovelo devem ficar em linha o tempo todo, focar em apertar o bar e tentar desmontá-lo.","Abaixe a barra até as tábuas, e depois empurre a barra com o máximo de força possível."]],"Body-Up":["Corpo-para cima",["Assuma uma posição de prancha no chão, você deve apoiar seu peso corporal nos dedos dos pés e antebraços, mantendo seu torso reto, seus antebraços devem estar longe do ombro, esta será sua posição inicial.","Pressionando suas palmas firmemente no chão, estendendo-se através dos cotovelos para levantar seu corpo do chão.","Abaixem lentamente os antebraços para o chão, permitindo que os cotovelos flexionem.","Repito."]],"Body_Tricep_Press":["Corpo Tríceps Press",["Posicione uma barra em uma prateleira na altura do peito.","Em pé, segure o ombro na barra e pise um ou dois metros para trás, pés juntos e braços estendidos para que você esteja encostado na barra.","Comece flexionando o cotovelo, baixando-se em direção à barra.","Pause, e então inverta o movimento estendendo os cotovelos.","Progresso do peso corporal adicionando correntes sobre seus ombros."]],"Bodyweight_Flyes":["Peso corporal Flyes",["Posicione duas barras EZ igualmente carregadas no chão ao lado uma da outra.","Assuma uma posição de flexão sobre as barras, sustentando seu peso em seus dedos e mãos com seus braços estendidos e corpo reto.","Coloque as mãos nas barras, esta será sua posição inicial.","Usando um movimento lento e controlado, afaste as mãos da linha média do seu corpo, revirando as barras.","Depois de mover as barras o mais longe possível, volte para a posição inicial puxando-as de volta."]],"Bodyweight_Mid_Row":["Peso corporal na fileira média",["Comece pegando um aparelho de apoio médio a largo com suas palmas viradas para longe de você, de uma posição pendurada, coloque seus joelhos no peito, incline-se para trás e coloque suas pernas sobre o lado do aparelho de apoio, esta será sua posição inicial.","Começando com os braços retos, flexione os cotovelos e retraia as omoplatas para levantar seu corpo até que suas pernas entrem em contato com o aparelho de tração.","Após uma breve pausa, volte para a posição inicial."]],"Bodyweight_Squat":["Peso Corporal Agachado",["Fique com os pés afastados, coloque as mãos atrás da cabeça, esta será sua posição inicial.","Comece o movimento flexionando seus joelhos e quadris, sentando-se com seus quadris.","Continue até a profundidade máxima, se for capaz, e rapidamente reverta o movimento até voltar à posição inicial, enquanto se agacha, mantenha a cabeça e o peito para cima e empurre os joelhos para fora."]],"Bodyweight_Walking_Lunge":["Peso Corporal Lunge",["Comece a ficar de pé com os pés com a largura do ombro e as mãos nos quadris.","Avance com uma perna, flexionando os joelhos para baixar os quadris, desça até o joelho traseiro quase tocar o chão, sua postura deve permanecer ereta, e seu joelho dianteiro deve ficar acima do pé dianteiro.","Dirija pelo calcanhar do seu pé de chumbo e estenda os joelhos para se levantar.","Dê um passo à frente com o pé traseiro, repetindo o pulmão na perna oposta."]],"Bosu_Ball_Cable_Crunch_With_Side_Bends":["Bosu bola cabo crunch com dobras laterais",["Conecte uma alça padrão a cada braço de uma máquina de cabo, e posicioná-los na posição mais para baixo.","Pegue uma bola de Bosu e posicione-a na frente e no centro da máquina de cabo.","Deite-se no Bosu Ball com a pequena de suas costas arqueada ao redor da bola.","Com as duas mãos, pegue o cabo e segure o cabo.","Com os pés posicionados em uma posição larga, estenda os braços bem na sua frente e entre os joelhos, suas mãos devem estar ao nível do joelho.","Mantenha os braços retos e alinhados com o ângulo para cima do cabo, eleve o tronco em um movimento de esmagamento sem cair ou dobrar os braços.","Mantenha a posição rígida com os braços, desça lentamente para a posição inicial com as costas arqueadas ao redor da Bola de Bosu e seus abdominais alongados.","Repita a mesma série de movimentos ao fracasso.","Uma vez que você chegar ao fracasso, mantenha seu abdômen apertado e levante seu torso na posição da prancha para que suas costas estejam elevadas da bola de Bosu.","Abaixe os braços para o lado, mantenha-os retos, comece a fazer curvas laterais alternadas, alcance seus calcanhares, este movimento final vai se concentrar em seus oblíquos."]],"Bottoms-Up_Clean_From_The_Hang_Position":["\"Batoms-Up Limpo da posição de enforcamento\"",["Iniciar o exercício em pé com uma campainha em uma mão.","Esmague a chaleira o mais forte possível e levante a chaleira para o ombro."]],"Bottoms_Up":["Botas para cima.",["Comece deitado no chão, suas pernas devem estar retas e seus braços ao seu lado, esta será sua posição inicial.","Para realizar o movimento, coloque os joelhos em direção ao peito, flexionando os quadris e joelhos, e depois estenda as pernas diretamente acima de você para que fiquem perpendiculares ao chão, gire e levante a pélvis para levantar os glúteos do chão.","Após uma breve pausa, volte para a posição inicial."]],"Box_Jump_Multiple_Response":["Salto de Caixa (Resposta Múltipla)",["Assumir uma postura relaxada de frente para a caixa ou plataforma aproximadamente um braço de comprimento de distância.","Usando os braços para ajudar na explosão inicial, pule para cima e para frente, pousando com os pés simultaneamente em cima da caixa ou plataforma.","Imediatamente cair ou saltar de volta para o local original de partida, em seguida, repetir a sequência."]],"Box_Skip":["Box Skip.",["Você precisará de várias caixas alinhadas a cerca de 8 pés de distância.","Comece a encarar a primeira caixa com uma perna ligeiramente atrás da outra.","Saia da perna de trás, tentando ganhar o máximo de altura possível com os quadris.","Imediatamente ao pousar na caixa, dirija a outra perna para frente e para cima para ganhar altura e distância, saltando da caixa.","Então, vá para a próxima caixa e repita."]],"Box_Squat_with_Bands":["Agachamento de Caixa com Bandas",["Comece em um rack de energia com uma caixa na altura apropriada atrás de você. Configure as faixas nas mangas, fixadas em pinos de banda, no rack, ou halteres para que haja tensão apropriada. Se halteres forem usados, proteja-os para que eles não se movam. Além disso, certifique-se de que os halteres que você está usando sejam pesados o suficiente para as bandas que você está usando. Placas adicionais podem ser usadas para segurar os halteres para baixo. Se mais tensão for necessária, você pode ampliar a base no chão ou sufocar as bandas. Normalmente, você apontaria para uma altura de caixa que o leve a um agachaço paralelo, mas você pode treinar mais ou menos, se desejar.","Comece pisando debaixo da barra e colocando-a na parte de trás dos ombros, aperte suas omoplatas juntas e gire seus cotovelos para frente, tentando dobrar a barra pelos ombros, remova a barra do rack, crie um arco apertado nas costas, e volte para a posição, coloque seus pés mais largos para mais ênfase nas costas, glúteos, adutores e isquiotibiais, ou mais próximos para mais desenvolvimento quádruplo, mantenha sua cabeça voltada para frente.","Com as costas, os ombros e o núcleo apertados, empurre os joelhos e bumbum para fora e comece sua descida, sente-se com os quadris até que esteja sentado na caixa, idealmente, suas canelas devem ser perpendiculares ao chão, pare quando chegar na caixa e relaxe os flexores do quadril, nunca salte de uma caixa.","Mantendo o peso em seus calcanhares e empurrando seus pés e joelhos para fora, dirigir para cima da caixa enquanto você lidera o movimento com sua cabeça. Continue para cima, mantendo a cabeça firme para os pés."]],"Box_Squat_with_Chains":["Caixa Agachada com Correntes",["Comece em um suporte de energia com uma caixa na altura apropriada atrás de você, normalmente, você apontaria para uma caixa de altura que te leva a um agachamento paralelo, mas você pode treinar mais ou menos se desejar.","Para montar as correntes, comece por enrolar a corrente líder sobre as mangas da barra, a corrente pesada deve ser fixada usando um gancho de encaixe, ajustar o comprimento da corrente de chumbo para que alguns elos ainda estejam no chão no topo do movimento.","Comece pisando debaixo da barra e colocando-a na parte de trás dos ombros, aperte suas omoplatas juntas e gire seus cotovelos para frente, tentando dobrar a barra pelos ombros, remova a barra do rack, crie um arco apertado nas costas, e volte para a posição, coloque seus pés mais largos para mais ênfase nas costas, glúteos, adutores e isquiotibiais, ou mais próximos para mais desenvolvimento quádruplo, mantenha sua cabeça voltada para frente.","Com as costas, os ombros e o núcleo apertados, empurre os joelhos e bumbum para fora e comece sua descida, sente-se com os quadris até que esteja sentado na caixa, idealmente, suas canelas devem ser perpendiculares ao chão, pare quando chegar na caixa e relaxe os flexores do quadril, nunca salte de uma caixa.","Mantendo o peso em seus calcanhares e empurrando seus pés e joelhos para fora, dirigir para cima da caixa enquanto você lidera o movimento com sua cabeça."]],"Brachialis-SMR":["Brachialis-SMR",["Deite-se de lado, com o braço contra o rolo de espuma, o braço deve estar mais ou menos alinhado com o corpo, com o lado de fora do bíceps pressionado contra o rolo de espuma.","Levante os quadris do chão, apoiando seu peso no braço e nos pés, segure por 10-30 segundos e mude de lado."]],"Bradford_Rocky_Presses":["Bradford/Rocky Press",["Sua aderência deve ser maior que a largura do ombro e deve criar um ângulo de 90 graus entre o antebraço e o braço superior enquanto o barbante desce.","Assim que pegar a campainha com o aperto correto, levante a barra sobre a cabeça, trancando os braços.","Agora abaixe a barra até a parte de trás da cabeça lentamente enquanto inala.","Levante a barra de volta para a posição inicial enquanto expira.","Abaixe a barra para a posição inicial lentamente enquanto inala.","Alternar desta forma até completar a quantidade recomendada de repetições."]],"Butt-Ups":["Butt-Ups",["Comece uma posição de flexão, mas com os cotovelos no chão e descansando em seus antebraços, seus braços devem ser dobrados em um ângulo de 90 graus.","Arqueie as costas um pouco, em vez de ficar completamente reta.","Levantem os glúteos até o teto, apertando bem o abdômen para fechar a distância entre as costelas e os quadris, o resultado final será que vocês vão acabar em uma posição de ponte alta, expirem enquanto realizam esta parte do movimento.","Não deixe suas costas caírem para baixo.","Repita para a quantidade recomendada de repetições."]],"Butt_Lift_Bridge":["Levante o traseiro (Bridge)",["Deite-se no chão com as mãos ao lado e os joelhos dobrados, seus pés devem ser colocados em volta da largura do ombro, esta será sua posição inicial.","Empurrando principalmente com os calcanhares, levante os quadris do chão, mantendo as costas retas, respire enquanto faz esta parte do movimento e segure no topo por um segundo.","Lentamente, volte para a posição inicial enquanto respira."]],"Butterfly":["Borboleta",["Sente-se na máquina com as costas planas na almofada.","Seus braços devem ser posicionados paralelos ao chão, ajustar a máquina de acordo.","Aperte as alças lentamente enquanto aperta o peito no meio, respire durante esta parte do movimento e segure a contração por um segundo.","Volte para a posição inicial lentamente enquanto inala até que seus músculos do peito estejam totalmente esticados.","Repita para a quantidade recomendada de repetições."]],"Cable_Chest_Press":["Pressão do tórax do cabo",["Ajuste o peso para uma quantidade adequada e sente-se, agarrando as alças, seus braços devem estar a 45 graus no corpo, com sua cabeça e peito para cima, os cotovelos devem ser dobrados para cerca de 90 graus, esta será a sua posição inicial.","Comece se estendendo pelo cotovelo, pressionando as alças bem na sua frente, e mantenha suas omoplatas retraídas enquanto executa o movimento.","Depois de pausar na extensão total, retorne à posição inicial, mantendo tensão nos cabos.","Você também pode executar este movimento com as costas fora do bloco, em um incline ou declínio, ou mãos alternativas."]],"Cable_Crunch":["\"Cable Crunch\"",["Ajoelhe-se abaixo de uma polia alta que contém uma ligação de corda.","Segure a corda e abaixe a corda até que suas mãos sejam colocadas ao lado do seu rosto.","Flexione os quadris um pouco e deixe o peso aumentar a parte inferior das costas.","Com os quadris estacionados, flexione a cintura enquanto contrai o abdômen para que os cotovelos viajem para o meio das coxas, expire enquanto realiza esta parte do movimento e segure a contração por um segundo.","E não escolha um peso tão pesado que a parte inferior das costas segure o peso do trabalho.","Repita para a quantidade recomendada de repetições."]],"Cable_Deadlifts":["Cable Deadlifts",["Mova os cabos para o fundo das torres e selecione um peso apropriado.","Para começar, agache-se e flexione seus quadris e joelhos até que você possa alcançar as alças.","Depois de agarrá-los, comece sua ascensão, dirigindo pelos calcanhares, estenda seus quadris e joelhos, mantendo suas mãos penduradas ao seu lado, mantenha sua cabeça e peito para cima durante todo o movimento.","Depois de atingir uma posição de pé, volte para a posição inicial e repita."]],"Cable_Hammer_Curls_-_Rope_Attachment":["Cabo Hammer Curls - Anexo de corda",["Anexar uma corda a uma polia baixa e ficar de frente para a máquina a cerca de 12 polegadas de distância dela.","Segure a corda com um punho neutro (palms-in) e fique em pé mantendo o arco natural das costas e seu tronco parado.","Coloque os cotovelos ao seu lado e mantenha-os parados durante todo o movimento.","Use seus bíceps, puxe seus braços enquanto expira até que seus bíceps toquem seus antebraços.","Depois de uma contração de 1 segundo onde você aperta seus bíceps, lentamente começa a trazer o peso de volta para a posição original.","Repita para a quantidade recomendada de repetições."]],"Cable_Hip_Adduction":["Cabo Hip Adduction",["Fique na frente de uma roldana baixa virada para frente com uma perna ao lado da roldana e a outra longe.","Coloque o punho do tornozelo no cabo e também no tornozelo da perna que está ao lado da polia.","Agora saia e saia da pilha com uma postura ampla e agarre a barra do sistema de polia.","Fique no pé que não tem o punho do tornozelo (o pé mais distante) e permita que a perna com o punho seja puxada em direção à polia baixa.","Agora faça o movimento movendo a perna com o punho do tornozelo na frente da perna distante usando as coxas internas para sequestrar o quadril.","Retorne lentamente à posição inicial enquanto respira.","Repita para a quantidade recomendada de repetições e então repita o mesmo movimento com a perna oposta."]],"Cable_Incline_Pushdown":["Incineração por cabo",["Deite-se sobre incline um banco virado para longe de uma máquina de polia alta que tem um anexo de barras retas sobre ele.","Segure a barra reta em cima com uma largura de ombro pronada (extrema, palmas para baixo) e estenda os braços na sua frente.","Mantenha os braços parados, levante os braços de volta em semicírculo até que a barra fique reta sobre sua cabeça.","Devagar, volte para a posição inicial usando seus lats e segure a contração assim que chegar à posição inicial.","Repita para a quantidade recomendada de repetições."]],"Cable_Incline_Triceps_Extension":["Extensão de Tríceps Incline Cabo",["Deite-se sobre incline um banco virado para longe de uma máquina de polia alta que tem um anexo de barras retas sobre ele.","Segure a barra reta acima com uma alça estreita (menos do que a largura do ombro) e mantenha seus cotovelos dobrados para os lados.","Mantenha os braços parados, estenda os braços enquanto você flexiona o tríceps, respire durante esta parte do movimento e segure a contração por um segundo.","Lentamente, volte para a posição inicial.","Repita para a quantidade recomendada de repetições."]],"Cable_Internal_Rotation":["Rotação interna do cabo",["Sente-se ao lado de uma polia baixa de lado (com as pernas esticadas na sua frente ou cruzadas) e segure o cabo de mão única com o braço mais próximo do cabo.","Posicione o cotovelo contra o seu lado com o cotovelo dobrado a 90° e o braço apontando para a polia.","O antebraço deve estar perpendicular ao seu tronco o tempo todo.","Lentamente, volte para a posição inicial.","Repita para a quantidade recomendada de repetições e então repita o movimento com o próximo braço."]],"Cable_Iron_Cross":["Cruz de Ferro de Cabo",["Comece movendo as polias para a posição alta, selecione a resistência a ser usada, e pegue uma alça em cada mão.","Fique entre as duas polias com os braços estendidos para os lados, sua cabeça e peito devem estar levantados enquanto seus braços formam um \"T\".","Mantendo os cotovelos estendidos, puxe os braços para os lados.","Retorne os braços para a posição inicial após uma pausa na contração máxima.","Continue o movimento para o número prescrito de repetições."]],"Cable_Judo_Flip":["Cabo Judo Flip",["Ligue uma corda a uma torre, e mova o cabo para a posição mais baixa da polia.","Torça o corpo para longe da polia enquanto você traz a corda sobre o ombro como se estivesse fazendo um salto de judô.","Troque seu peso entre os pés enquanto torce e aperta para frente, puxando o cabo para baixo.","Volte para a posição inicial e repita até o fracasso.","Então, reposicione e repita a mesma série de movimentos no lado oposto."]],"Cable_Lying_Triceps_Extension":["Extensão de Tríceps por Cabo",["A maneira mais fácil de fazer isso é ter alguém te dando a barra enquanto você se deita.","Com os braços estendidos, posicione a barra sobre o tronco, seus braços e tronco devem criar um ângulo de 90 graus, esta será sua posição inicial.","Abaixe a barra dobrando o cotovelo mantendo os braços parados e os cotovelos parados.","Flexione o tríceps ao levantar a barra de volta para sua posição inicial, expire enquanto executa esta parte do movimento.","Espere um segundo na posição contratada e repita a quantidade recomendada de repetições."]],"Cable_One_Arm_Tricep_Extension":["Cabo Um Braço Tríceps Extension",["Com sua mão direita, segure um único punho preso à polia de cabo alto usando um aperto supinado (debaixo da mão, palmas viradas para cima) Você deve estar em pé diretamente na frente da pilha de peso.","Agora puxe o cabo para baixo para que seu braço e cotovelo estejam presos ao lado de seu corpo, seu braço e antebraço devem formar um ângulo agudo (menos de 90 graus), você pode manter o outro braço pela cintura e você pode ter uma perna na sua frente e a outra para um melhor equilíbrio.","Enquanto contrai o tríceps, mova o único punho para o seu lado até que seu braço esteja reto, expire enquanto faz esse movimento, só os antebraços devem se mover, seus braços devem permanecer parados o tempo todo.","Aperte o tríceps e segure por um segundo nesta posição contratada.","Lentamente devolva o cabo para a posição inicial.","Repita para a quantidade recomendada de repetições e então faça o mesmo movimento com o outro braço."]],"Cable_Preacher_Curl":["O Pastor de Cabo Curl.",["Coloque um banco de pregadores cerca de 2 pés na frente de uma máquina de polias.","Coloque uma barra reta na polia baixa.","Sente-se no banco do pastor com o cotovelo e os braços firmes em cima do banco e peça para alguém lhe dar a barra da roldana baixa.","Pegue a barra e estenda os braços em cima do banco do padre.","Agora comece a rebocar o peso em direção aos ombros e aperte os bíceps com força no topo do movimento.","Agora reduza lentamente o peso para a posição inicial.","Repita para a quantidade recomendada de repetições."]],"Cable_Reverse_Crunch":["Cabo Reverse Crunch",["Conecte uma alça de tornozelo a um cabo de polia baixa e coloque um tapete no chão na frente dele.","Sente-se com os pés em direção à polia e coloque o cabo nos tornozelos.","Deite-se, levante as pernas e dobre os joelhos num ângulo de 90 graus, suas pernas e o cabo devem estar alinhados, se não, ajuste a polia para cima ou para baixo até que estejam.","Com as mãos atrás da cabeça, traga os joelhos para dentro do tronco e levante os quadris do chão.","Pause por um momento e de forma lenta e controlada, solte seus quadris e traga suas pernas de volta ao ângulo inicial de 90 graus.","Repita o mesmo movimento para o fracasso."]],"Cable_Rope_Overhead_Triceps_Extension":["Tríceps da corda de cabo na frente",["Coloque uma corda na polia inferior da máquina de polia.","Agarrando a corda com as duas mãos, estendendo os braços com as mãos diretamente acima da cabeça usando um punho neutro (palmas viradas uma para a outra), seus cotovelos devem estar perto da cabeça e os braços devem ser perpendiculares ao chão com as juntas voltadas para o teto.","Abaixe lentamente a corda atrás da cabeça enquanto segura os braços parados, inale enquanto faz esse movimento e pause quando seus tríceps estão totalmente esticados.","Volte para a posição inicial, flexionando seus tríceps enquanto expira.","Repita para a quantidade recomendada de repetições."]],"Cable_Rope_Rear-Delt_Rows":["Corda de cabo Rear-Delt Rows",["Sente-se na mesma posição em uma estação de roldana baixa como você faria se você estivesse fazendo filas de cabo sentados para trás.","Coloque uma corda na polia e segure-a com um aperto de mão, seus braços devem ser estendidos e paralelos ao chão com os cotovelos arregaçados.","Mantenha as costas eretas e deslize seus quadris para trás para que seus joelhos estejam ligeiramente dobrados.","Mantenha os braços horizontais, perpendiculares ao tronco e paralelos ao chão durante todo o movimento.","Volte para a posição inicial onde os braços são estendidos e os ombros esticados para frente.","Repita para a quantidade recomendada de repetições."]],"Cable_Russian_Twists":["Twists russos por cabo",["Conecte uma fixação padrão, e posicione o cabo para uma posição de polia média.","Deite-se em uma bola de estabilidade perpendicular ao cabo e agarre o cabo com uma mão.","Segure o cabo com as duas mãos e estenda os braços acima do peito, as mãos devem estar diretamente alinhadas com a polia, se não, ajuste a polia para cima ou para baixo até que estejam.","Mantenha os quadris elevados e os abdominais ligados, gire o tronco para longe da polia para uma rotação completa, seu corpo deve estar plano da cabeça aos joelhos.","Pause por um momento e de forma lenta e controlada, volte para a posição inicial, ainda deve ter tensão lateral no cabo na posição de repouso.","Repita o mesmo movimento para o fracasso.","Então, reposicione e repita a mesma série de movimentos no lado oposto."]],"Cable_Seated_Crunch":["\"Cable Seated Crunch\"",["Sente-se em um banco plano com as costas viradas para uma polia alta.","Segure o cabo com as duas mãos, com as palmas das mãos voltadas uma para a outra, e coloque suas mãos firmemente sobre os dois ombros.","Com os quadris parados, flexione a cintura para que os cotovelos viajem em direção aos quadris.","Ao inalar, volte para a posição inicial lentamente.","Repita para a quantidade recomendada de repetições."]],"Cable_Seated_Lateral_Raise":["Subida lateral sentada por cabo.",["Fique no meio de duas polias baixas que são opostas uma à outra e coloque um banco plano bem atrás de você (de forma perpendicular a você; a borda estreita do banco deve ser a que está atrás de você).","Agora sente-se na beira do banco plano atrás de você com seus pés colocados na frente de seus joelhos.","Incline-se para a frente, mantendo as costas planas e descanse o tronco nas coxas.","Pegue a polia esquerda com a mão direita e a polia direita com a esquerda depois de selecionar seu peso as polias devem correr sob seus joelhos e seus braços serão estendidos com palmas voltadas uma para a outra e uma leve curva nos cotovelos esta será a posição inicial.","Enquanto mantém os braços parados, levante os braços para os lados até que estejam paralelos ao chão e à altura do ombro, expire durante a execução deste movimento e segure a contração por um segundo.","Abaixe lentamente os braços para a posição inicial enquanto inala.","Mantenha os braços perpendiculares ao torso e uma posição fixa do cotovelo (10 graus a 30 graus) durante o exercício."]],"Cable_Shoulder_Press":["Ombro de Cabo Press",["Mova os cabos para o fundo das torres e selecione um peso apropriado.","Segure os cabos e segure-os na altura do ombro, palmas voltadas para frente, esta será sua posição inicial.","Mantendo sua cabeça e peito para cima, estenda através do cotovelo para pressionar as alças diretamente sobre a cabeça.","Depois de parar no topo, volte para a posição inicial e repita."]],"Cable_Shrugs":["Cable Shrugs",["Segure uma barra de cabo que está presa a uma polia baixa com uma largura de ombro ou um pouco mais larga sobremão (palmas viradas para baixo) aderência.","Fique ereto perto da polia com os braços estendidos na sua frente segurando a barra.","Levante a barra elevando os ombros o mais alto possível, segure a contração na parte superior por um segundo, os braços devem permanecer estendidos o tempo todo, refreie-se de usar os bíceps para ajudar a levantar a barra, só os ombros devem estar se movendo para cima e para baixo.","Abaixe a barra de volta para a posição original.","Repita para a quantidade recomendada de repetições."]],"Cable_Wrist_Curl":["Curva do Pulso de Cabo",["Comece colocando um banco na frente de um cabo de polia que tem uma barra reta.","Use os braços para agarrar a barra de cabo com um aperto estreito a ombro supinado (palmas para cima) e trazê-los para cima para que seus antebraços estão descansando contra o topo de suas coxas.","Comece enrolando o pulso para cima e expirando.","Abaixem lentamente os pulsos para a posição inicial enquanto inalam.","Seus antebraços devem estar parados, pois seu pulso é o único movimento necessário para realizar esse exercício.","Repita para a quantidade recomendada de repetições."]],"Calf-Machine_Shoulder_Shrug":["Ombros de bezerro e máquina",["Coloque-se na máquina do bezerro para que as ombreiras estejam acima dos ombros, seu torso deve estar reto com os braços estendidos normalmente ao seu lado, esta será sua posição inicial.","Levante os ombros em direção aos ouvidos enquanto expira e segure a contração por um segundo.","Retorne lentamente à posição inicial enquanto inala.","Repita para a quantidade recomendada de repetições."]],"Calf_Press":["Press de Calf",["Ajuste o assento para que suas pernas estejam ligeiramente dobradas na posição inicial, as bolas dos seus pés devem estar firmemente na plataforma.","Escolha um peso apropriado, e segure as alças.","Endireite as pernas estendendo os joelhos, mal levantando o peso da pilha, seu tornozelo deve estar totalmente flexionado, os dedos dos pés apontando para cima, execute o movimento pressionando para baixo através das bolas dos seus pés, tanto quanto possível.","Após uma breve pausa, inverta o movimento e repita."]],"Calf_Press_On_The_Leg_Press_Machine":["A máquina de imprensa da perna.",["Usando uma máquina de prensar a perna, sente-se na máquina e coloque suas pernas na plataforma diretamente na sua frente em uma posição média (largura do ombro) pé.","Abaixe as barras de segurança segurando a plataforma ponderada no lugar e pressione a plataforma até que suas pernas estejam totalmente estendidas na sua frente sem trancar seus joelhos. (Nota: em algumas unidades de pressão de perna você pode deixar as barras de segurança para aumentar a segurança. Se sua unidade de pressão de perna permite isso, então este é o método preferido para realizar o exercício.) Seu torso e as pernas devem fazer ângulo perfeito de 90 graus. Agora coloque cuidadosamente seus dedos e bolas de seus pés na parte inferior da plataforma com os calcanhares estendidos.","Pressione a plataforma levantando os calcanhares enquanto expira, estendendo os tornozelos o mais alto possível e flexionando a panturrilha, garantindo que o joelho fique parado o tempo todo, não deve haver flexão a qualquer momento, mantenha a posição contraída por um segundo antes de começar a descer.","Volte lentamente para a posição inicial enquanto você respira baixando os calcanhares enquanto dobra os tornozelos até as panturrilhas ficarem esticadas.","Repita para a quantidade recomendada de repetições."]],"Calf_Raise_On_A_Dumbbell":["Calf levantar em um haltere",["Segure-se em um objeto robusto para equilibrar e fique em um cabo de haltere, de preferência um com placas redondas para que ele role como desta forma você tem que trabalhar mais duro para se estabilizar, aumentando assim a eficácia do exercício.","Agora role o pé um pouco para a frente para que você possa pegar uma boa parte do bezerro.","Levante a panturrilha enquanto você enrola o pé sobre o topo da alça para que você obtenha uma extensão completa. Expire durante a execução deste movimento. Contraia a panturrilha duramente no topo e segure por um segundo.","Agora inale enquanto você enrola o haltere um pouco para a frente enquanto você vem para baixo para obter um alongamento melhor.","Repita para a quantidade recomendada de repetições."]],"Calf_Raises_-_With_Bands":["Calf levanta - com faixas",["Pegue uma faixa de exercício e fique com os dedos dos pés, certificando-se que o comprimento da faixa entre o pé e os braços é o mesmo para ambos os lados.","Enquanto segurava as alças da banda, levantava os braços para o lado da cabeça como se estivesse se preparando para fazer uma pressão no ombro, as palmas das mãos deveriam estar voltadas para frente com os cotovelos dobrados e para os lados, esse movimento criaria tensão na banda, esta será a sua posição inicial.","Mantendo as mãos no ombro, levante-se sobre os pés enquanto expira e contraia os bezerros com força no topo do movimento.","Após uma contração de um segundo, lentamente volte para a posição inicial.","Repita para a quantidade recomendada de repetições."]],"Calf_Stretch_Elbows_Against_Wall":["Calf esticar cotovelos contra a parede",["Fique de frente para uma parede a alguns metros de distância.","Incline-se contra a parede, colocando seu peso em seus antebraços.","Tente manter seus calcanhares no chão, segure por 10-20 segundos, você pode mover-se mais ou mais perto da parede, tornando-a mais ou menos difícil, respectivamente."]],"Calf_Stretch_Hands_Against_Wall":["Calf estique as mãos contra a parede",["Fique de frente para uma parede a vários metros de distância, agite sua postura, colocando um pé para frente.","Incline-se para frente e coloque as mãos na parede, mantendo seu calcanhar, quadril e cabeça em linha reta.","Tente manter o calcanhar no chão, espere 10-20 segundos e depois mude de lado."]],"Calves-SMR":["Calves-SMR",["Comece a sentar no chão, coloque um rolo de espuma sob sua perna inferior, sua outra perna pode ser cruzada ou colocada no chão, apoiando um pouco do seu peso, esta será a sua posição inicial.","Coloque as mãos para o lado ou apenas atrás de você, e pressione para baixo para levantar os quadris do chão, colocando muito do seu peso contra o músculo da panturrilha, rolar de baixo do joelho para cima do tornozelo, parando em pontos de tensão por 10-30 segundos."]],"Car_Deadlift":["Carro Deadlift",["Este aparelho de eventos normalmente tem alças neutras, no entanto alguns têm uma barra reta que você pode se aproximar como um elevador normal.","Se você é um ocupante forte, ou para trás alguns centímetros se você é um deadlifter forte, seus pés devem ser cerca de largura do quadril de distância, dobre-se no quadril para segurar os cabos, com seus pés e apertos, respire fundo e depois abaixe os quadris e flexione os joelhos.","Olhe para a frente com a cabeça, mantenha o peito para cima e as costas arqueadas, e comece a dirigir através dos calcanhares para mover o peso para cima.","Abaixe o peso dobrando os quadris e guiando-os até o chão."]],"Car_Drivers":["Motoristas de carros",["Enquanto estão de pé, segurem uma placa em ambas as mãos nas 3 e 9 posições, suas palmas devem estar viradas uma para a outra e seus braços devem ser estendidos diretamente para fora da frente de vocês.","Iniciar o movimento girando a placa o mais longe possível para um lado, use o mesmo tipo de movimento que usaria para girar o volante para um lado.","Inverter o movimento, virá-lo todo o caminho para o lado oposto.","Repita para a quantidade recomendada de repetições."]],"Carioca_Quick_Step":["Carioca Passo Rápido",["Comece com seus pés separados e seu braço esquerdo em uma posição relaxada e atlética.","Com o seu pé direito, rápido dê um passo atrás e puxe o joelho para cima.","Incendeie os braços quando puxar o joelho direito, tendo certeza de que o joelho vai direto para cima e para baixo, evite virar os pés enquanto se move e continue olhando para frente enquanto se move para o lado."]],"Cat_Stretch":["Esticamento de Gatos",["Coloque-se no chão de joelhos.","Puxe a barriga e rode a coluna, as costas, os ombros e o pescoço, deixando a cabeça cair.","Espere por 15 segundos."]],"Catch_and_Overhead_Throw":["Pegar e atirar de cabeça.",["Comece a ficar de pé enquanto enfrenta uma parede ou um parceiro.","Usando as duas mãos, posicione a bola atrás da cabeça, esticando o máximo possível, e jogue a bola para frente.","Se estiver jogando contra a parede, certifique-se de ficar perto o suficiente da parede para receber o rebote, e mire um pouco mais alto do que com um parceiro."]],"Chain_Handle_Extension":["Extensão do cabo de corrente",["Você vai precisar de dois cabos de fixação e um banco plano, bem como correntes, para este exercício.","Comece estendendo pelo cotovelo, mantendo o braço parado, com os pulsos pronados.","Pausa no bloqueio, e inverta o movimento para voltar à posição inicial."]],"Chain_Press":["Pressionar a corrente",["Coloque-se no banco plano na mesma posição de um haltere, seus pulsos devem ser pronados e os braços perpendiculares ao chão, esta será sua posição inicial.","Abaixe as correntes flexionando os cotovelos, descarregando parte da corrente no chão.","Continue até que seu cotovelo forme um ângulo de 90 graus, e então reverta o movimento estendendo-se através do cotovelo até o bloqueio."]],"Chair_Leg_Extended_Stretch":["Cadeira Perna Estendida",["Sente-se em uma cadeira e segure o banco dos lados.","Levante uma perna, estenda o joelho, flexione o tornozelo enquanto faz isso.","Mova lentamente a perna para fora o mais longe possível, e depois volte para o centro e para baixo.","Repita para sua outra perna."]],"Chair_Lower_Back_Stretch":["Cadeira, estique as costas.",["Sente-se em uma cadeira.","Dobre-se para um lado com o braço sobre a cabeça, pode segurar a cadeira com a mão livre.","Espere 10 segundos e repita para o outro lado."]],"Chair_Squat":["Cadeira Agachada",["Para começar, ajuste a barra para uma posição que melhor corresponda à sua altura, assim que a barra estiver carregada, passe por baixo dela e posicione-a na parte de trás dos ombros.","Pegue o bar com as mãos voltadas para a frente, destranque-o e levante-o da prateleira estendendo suas pernas.","Mova os pés para frente cerca de 18 polegadas na frente da barra, posicione suas pernas usando uma posição de largura do ombro com os dedos ligeiramente apontados, olhe para frente o tempo todo e mantenha uma coluna neutra ou ligeiramente arqueada, esta será a sua posição inicial.","Abaixe lentamente a barra dobrando os joelhos, mantendo uma postura reta, com a cabeça para cima, e continue até que o ângulo entre a perna superior e inferior quebre 90 graus.","Comece a levantar a barra enquanto expira, empurrando o chão com os calcanhares dos pés, estendendo os joelhos e voltando para a posição inicial.","Repita para a quantidade recomendada de repetições."]],"Chair_Upper_Body_Stretch":["Cadeira Corpo Superior Esticamento",["Sente-se na borda de uma cadeira, segurando a parte de trás dela.","Endireite os braços, mantenha as costas retas, e puxe a parte superior do corpo para a frente para sentir um estiramento."]],"Chest_And_Front_Of_Shoulder_Stretch":["Peito e frente do ombro esticar",["Comece com as pernas juntas, segurando uma barra ou uma vassoura.","Pegue um pouco mais do que a largura do ombro, segure-o na sua frente com as palmas viradas para baixo.","Cuidado com o poste para cima e para trás da cabeça."]],"Chest_Push_from_3_point_stance":["Empurre o peito de 3 pontos de posição.",["Comece em uma posição de três pontos, agachado com suas costas planas e uma mão no chão.","Para começar, dê o seu primeiro passo enquanto puxa a bola para o peito, posicionando as duas mãos para se preparar para o lançamento.","Quando executar o segundo passo, solte a bola o mais forte possível."]],"Chest_Push_multiple_response":["Pressão no peito (reação múltipla)",["Comece em uma posição de joelhos de frente para uma parede ou use um parceiro.","Execute o passe explodindo para frente e para fora com os quadris enquanto empurra a bola o mais forte possível.","Siga em frente, pegue-se com as mãos.","Repete para o número desejado de repetições."]],"Chest_Push_single_response":["Chest Push (resposta única)",["Comece em uma posição ajoelhada segurando a bola medicinal com as duas mãos firmemente no peito.","Execute o passe explodindo para frente e para fora com os quadris enquanto empurra a bola o máximo possível.","Siga em frente, pegue-se com as mãos."]],"Chest_Push_with_Run_Release":["Empurra no peito com liberação de corrida.",["Comece em uma posição atlética com os joelhos dobrados, quadris para trás, e as costas planas.","Ao dar seu primeiro passo, puxe a bola medicinal para seu peito.","Enquanto você dá o segundo passo, empurra a bola explosivamente para frente, correndo imediatamente para 10 jardas após o lançamento."]],"Chest_Stretch_on_Stability_Ball":["Esticamento do peito na bola de estabilidade",["Fique de joelhos perto de uma bola de exercício.","Coloque seus cotovelos em cima da bola, mantendo seu braço para o lado.","Abaixe o tronco em direção ao chão, mantendo o cotovelo em cima da bola, segure o estiramento por 20-30 segundos e repita com o outro braço."]],"Chin_To_Chest_Stretch":["Queixo ao peito esticado",["Sente-se no chão.","Coloque as duas mãos na parte de trás da cabeça, dedos entrelaçados, polegares apontando para baixo e cotovelos apontando para a frente, lentamente puxe a cabeça para o peito, segure por 20-30 segundos."]],"Circus_Bell":["Circus Bell.",["O sino do circo é um haltere gigante com um cabo grosso, comece com o haltere entre os pés, e segure o punho com as duas mãos.","Limpe o haltere estendendo-se através de seus quadris e joelhos para entregar o implemento para o ombro desejado, deixando ir com a mão extra.","Assegure-se de ter uma cabeça de haltere atrás do ombro para não ser jogada fora do equilíbrio, para elevá-la acima, mergulhar flexionando os joelhos, e a movimentação para cima enquanto você estende o haltere acima, inclinando-se ligeiramente para longe dele enquanto você faz isso.","Guie cuidadosamente o sino de volta ao chão, mantendo-o sob controle o máximo possível, é melhor realizar este evento em um tapete de borracha grosso para evitar danos no chão."]],"Clean_Deadlift":["\"Limpeza Deadlift\"",["Comece a ficar de pé com uma barra perto das canelas, seus pés devem estar diretamente sob seus quadris com os pés ligeiramente virados, segure a barra com um aperto de mão dupla ou gancho, sobre a largura do ombro à parte, desça até a barra, sua coluna deve estar em extensão total, com um ângulo de costas que coloca seus ombros na frente da barra e suas costas o mais vertical possível.","Comece dirigindo através do chão através da frente dos seus calcanhares, enquanto a barra sobe, mantenha um ângulo constante nas costas, acenda seus joelhos para o lado para ajudá-los a não se meterem no caminho da barra.","Depois que a barra cruzar os joelhos, complete o elevador dirigindo os quadris para a barra até que seus quadris e joelhos sejam estendidos."]],"Clean_Pull":["\"Puxe Limpo\"",["Com uma barba no chão perto das canelas, pegue uma mão ou gancho de mão fora das pernas, abaixe os quadris com o peso focado nos calcanhares, para trás reta, cabeça virada para a frente, peito para cima, com os ombros bem na frente do bar, esta será a sua posição inicial.","Comece a puxar os calcanhares, estenda os joelhos, o ângulo das costas deve permanecer o mesmo, e os braços devem permanecer retos e cotovelos para fora, mova o peso com o controle enquanto você continua acima dos joelhos.","Em seguida, vem o segundo impulso, a principal fonte de aceleração para o limpo, à medida que a barra se aproxima da posição média da coxa, começar a estender-se através dos quadris, em um movimento de salto, acelerar estendendo os quadris, joelhos e tornozelos, usando velocidade para mover a barra para cima, não deve haver necessidade de puxar ativamente através dos braços para acelerar o peso, no final da segunda tração, o corpo deve ser totalmente estendido, inclinando-se ligeiramente para trás, com os braços ainda estendidos, a extensão total deve ser violenta e abrupta, e garantir que você não prolongue a extensão por mais tempo do que o necessário."]],"Clean_Shrug":["Enxofre limpo.",["Comece com uma largura de ombro, duas mãos ou gancho, com a barra pendurada na posição média da coxa, e suas costas devem estar retas e inclinadas ligeiramente para frente.","Encolher os ombros em direção aos ouvidos, enquanto este exercício pode ser carregado com peso mais pesado do que limpo, evite sobrecarregar ao ponto que a execução diminua."]],"Clean_and_Jerk":["Limpo e idiota.",["Com uma barba no chão perto das canelas, pegue uma mão ou gancho de mão fora das pernas, abaixe os quadris com o peso focado nos calcanhares, para trás reta, cabeça virada para a frente, peito para cima, com os ombros bem na frente do bar, esta será a sua posição inicial.","Comece o primeiro pulo dirigindo pelos calcanhares, estendendo os joelhos, seu ângulo de costas deve permanecer o mesmo, e seus braços devem permanecer retos, mova o peso com controle enquanto você continua acima dos joelhos.","Em seguida, vem o segundo puxão, a principal fonte de aceleração para o limpo, à medida que a barra se aproxima da posição média da coxa, começa a estender-se através dos quadris, em um movimento de salto, acelerando estendendo os quadris, joelhos e tornozelos, usando velocidade para mover a barra para cima, não deve haver necessidade de puxar ativamente através dos braços para acelerar o peso, no final do segundo puxão, o corpo deve ser totalmente estendido, inclinando-se ligeiramente para trás, com os braços ainda estendidos.","Enquanto a extensão completa é alcançada, a transição para o terceiro puxando agressivamente e flexionando os braços com os cotovelos para cima e para fora. Na extensão do pico, agressivamente puxe-se para baixo, girando seus cotovelos sob a barra enquanto você faz isso. Receba a barra em uma posição de agachamento frontal, cuja profundidade é dependente da altura da barra no final do terceiro puxamento.","Recupere-se imediatamente dirigindo através dos saltos, mantendo o tronco ereto e cotovelos para cima.","A segunda fase é o empurrão, que levanta o peso acima, de pé com o peso racked na frente dos ombros, começar com o mergulho, com os pés diretamente sob seus quadris, flexionar os joelhos sem mover os quadris para trás, descer apenas ligeiramente, e reverter a direção o mais poderosa possível.","Dirija através dos saltos criar tanta velocidade e força quanto possível, e certifique-se de mover sua cabeça para fora do caminho como o bar deixa os ombros.","No momento em que os pés saem do chão, os pés devem ser colocados na posição de recepção o mais rápido possível."]],"Clean_from_Blocks":["Limpo de Blocos.",["Com uma barra em caixas ou suportes da altura desejada, pegue um overhand ou gancho aperto fora das pernas, abaixe os quadris com o peso focado nos calcanhares, para trás reta, cabeça voltada para a frente, peito para cima, com os ombros bem na frente do bar.","Comece o primeiro pulo dirigindo pelos calcanhares, estendendo os joelhos, seu ângulo de costas deve permanecer o mesmo, e seus braços devem permanecer retos com os cotovelos apontados.","Enquanto a extensão completa é alcançada, a transição para a posição de recepção é agressivamente encolhendo e flexionando os braços com os cotovelos para cima e para fora. Agressivamente puxe-se para baixo, girando seus cotovelos sob a barra enquanto você faz isso. Receba a barra em uma posição de agachamento frontal, cuja profundidade é dependente da altura da barra no final da terceira puxar.","Recupere-se imediatamente dirigindo através dos saltos, mantendo o tronco ereto e cotovelos para cima."]],"Clock_Push-Up":["Clock Push-Up",["Mova-se para uma posição propensa no chão, apoiando seu peso em suas mãos e dedos dos pés.","Seus braços devem ser estendidos com as mãos ao redor da largura do ombro, mantenha seu corpo reto durante todo o movimento, esta será sua posição inicial.","Desça flexionando o cotovelo, baixando o peito em direção ao chão.","Na parte de baixo, inverta o movimento empurrando-se através da extensão do cotovelo o mais rápido possível até que você seja suportado pelo ar.","Ao acelerar, afaste seu pé externo da direção de viagem, deixando o chão, deslocando seu corpo cerca de 30 graus para a próxima repetição.","Volte para a posição inicial e repita o exercício, trabalhando todo o caminho até que você esteja de volta onde você começou."]],"Close-Grip_Barbell_Bench_Press":["Close-Grip Barbell Bench Press",["Deite-se em um banco plano, usando um aperto próximo, levante a barra do rack e segure-a em cima de você com os braços trancados, esta será a sua posição inicial.","Quando respirar, desça lentamente até sentir a barra no peito médio, e certifique-se de que, ao invés de uma pressão normal no banco, mantenha os cotovelos perto do tronco o tempo todo para maximizar o envolvimento do tríceps.","Depois de uma segunda pausa, traga a barra de volta para a posição inicial enquanto expira e empurre a barra usando os músculos do tríceps, tranque os braços na posição contraída, segure por um segundo e comece a descer lentamente novamente.","Repita o movimento para a quantidade prescrita de repetições.","Quando terminar, coloque o bar de volta no rack."]],"Close-Grip_Dumbbell_Press":["Press halteres de perto.",["Coloque um haltere em pé em um banco plano.","Assegurando que o haltere permaneça firmemente colocado no topo do banco, fique perpendicular ao banco com apenas seus ombros deitados na superfície, quadris devem estar abaixo do banco e suas pernas dobradas com os pés firmemente no chão.","Segure o haltere com as duas mãos e segure-o sobre o peito ao comprimento do braço, ambas as palmas devem estar pressionando contra o lado inferior do haltere.","Iniciar o movimento baixando o haltere para o peito.","Volte para a posição inicial estendendo os cotovelos."]],"Close-Grip_EZ-Bar_Curl_with_Band":["Close-Grip EZ-Bar Curl com Banda",["Coloque uma faixa em cada extremidade da barra, pegue a barra, coloque um pé no meio da banda, fique em pé com uma estreita e supinada aderência na barra EZ, os cotovelos devem estar perto do tronco, esta será a sua posição inicial.","Enquanto mantém os braços no lugar, flexione os cotovelos para executar o cacho, expire enquanto o peso é levantado.","Continue o movimento até que seus bíceps estejam totalmente contraídos e a barra esteja no nível do ombro.","Lentamente começar a trazer o bar de volta à posição inicial enquanto você respira.","Repita para a quantidade recomendada de repetições."]],"Close-Grip_EZ-Bar_Press":["EZ-Bar Press",["Deite-se em um banco plano com uma barra EZ carregada a um peso adequado.","Usando um aperto estreito levante a barra e segure-a sobre o tronco com os cotovelos, os braços devem ser perpendiculares ao chão, esta será a sua posição inicial.","Agora abaixe a barra até o peito enquanto respira, e mantenha os cotovelos dentro enquanto faz esse movimento.","Usando o tríceps para empurrar a barra de volta para cima, pressione-a de volta para a posição inicial, estendendo os cotovelos enquanto você expira.","Repito."]],"Close-Grip_EZ_Bar_Curl":["Close-Grip EZ Bar Curl",["Levante-se com o torso ereto enquanto segura uma barra de curva E-Z no punho interno mais próximo, a palma das mãos deve estar voltada para a frente e devem ser ligeiramente inclinadas para dentro devido à forma da barra, os cotovelos devem estar perto do tronco, esta será a sua posição inicial.","Enquanto segura os braços parados, enrole os pesos para frente enquanto contrai os bíceps enquanto expira.","Continue o movimento até que seus bíceps estejam totalmente contraídos e a barra esteja no nível do ombro.","Lentamente começar a trazer o bar de volta à posição inicial enquanto você respira.","Repita para a quantidade recomendada de repetições."]],"Close-Grip_Front_Lat_Pulldown":["Lat Trashdown dianteiro.",["Sente-se em uma máquina de puxar para baixo com uma barra larga presa na polia superior, certifique-se de ajustar a joelheira da máquina para ajustar sua altura, essas almofadas impedirão que seu corpo seja levantado pela resistência ligada à barra.","Pegue a barra com as palmas voltadas para a frente usando o aperto prescrito.","Como você tem os dois braços estendidos na sua frente - enquanto segurando a barra na largura de aderência escolhida - trazer o seu tronco de volta em torno de 30 graus ou assim, enquanto criar uma curvatura em suas costas inferiores e colocar o peito para fora.","Quando expirar, abaixe a barra até que toque o peito superior, puxando os ombros e os braços para baixo e para trás. Dica: Concentre-se em apertar os músculos das costas uma vez que você atinja a posição contraída total.","Depois de um segundo na posição contraída, enquanto apertam suas omoplatas juntas, lentamente levantem a barra de volta para a posição inicial quando seus braços estiverem totalmente estendidos e os lats estiverem totalmente esticados.","Repita esta moção pela quantidade prescrita de repetições."]],"Close-Grip_Push-Up_off_of_a_Dumbbell":["Close-Grip Push-Up de um halteres",["Deite-se no chão e coloque as mãos em um haltere ereto, apoiando seu peso nos dedos dos pés e mãos, mantendo seu tronco rígido e seus cotovelos em seus braços retos, esta será sua posição inicial.","Abaixe seu corpo, permitindo que os cotovelos flexionem enquanto inala, mantenha seu corpo reto, não permitindo que seus quadris se levantem ou caiam.","Recomponha-se para a posição inicial, estendendo os cotovelos.","Após uma pausa na posição contraída, repita o movimento para a quantidade prescrita de repetições."]],"Close-Grip_Standing_Barbell_Curl":["Close-Grip Standing Barbell Curl",["Segure uma campainha com as duas mãos, palmas para cima e alguns centímetros de distância.","Mantenha o tronco reto e a cabeça para cima, os pés devem ter a largura do ombro e os cotovelos perto do tronco, esta será sua posição inicial, e manterá seus braços e cotovelos parados durante todo o movimento.","Esvazie a barra em um movimento semicircular até que os antebraços toquem seus bíceps, expire enquanto faz esta parte do movimento e contraia seus bíceps com força por um segundo no topo.","Lentamente volte para a posição inicial enquanto inala.","Repita para a quantidade recomendada de repetições."]],"Cocoons":["Cocoons.",["Comece deitado de costas no chão, suas pernas devem estar retas e seus braços estendidos atrás da cabeça, esta será sua posição inicial.","Para realizar o movimento, coloque os joelhos em direção ao peito, girando sua pélvis para levantar seus glúteos do chão.","Após uma breve pausa, volte para a posição inicial."]],"Conans_Wheel":["Roda de Conan.",["Com o peso carregado, segure na ponta do implemento, coloque a barra no cotovelo e segure o pulso, tente manter o peso fora dos antebraços.","Comece levantando o peso do chão, mantenha uma postura firme e ereta enquanto caminha, dando passos curtos e rápidos, olhe para cima e para longe enquanto vira em círculo, não sustenha a respiração durante o evento, continue andando até completar uma ou mais voltas completas."]],"Concentration_Curls":["Curls de concentração",["Sente-se em um banco plano com um haltere na sua frente entre as pernas, suas pernas devem ser estendidas com os joelhos dobrados e os pés no chão.","Use o braço direito para levantar o haltere, coloque a parte de trás do braço direito na parte superior da coxa direita, gire a palma da mão até que esteja virada para a frente, longe da coxa, e o braço deve ser estendido e o haltere deve estar acima do chão, esta será a sua posição inicial.","Enquanto segura o braço parado, enrole os pesos para frente enquanto contrai os bíceps enquanto expira, apenas os antebraços devem se mover, continue o movimento até que seus bíceps estejam totalmente contraídos e os halteres estejam no nível do ombro.","Devagar, comecem a trazer os halteres de volta à posição inicial enquanto respiram.","Repita as repetições recomendadas e repita o movimento com o braço esquerdo."]],"Cross-Body_Crunch":["Crunch Cross-Body",["Deite-se de costas e dobre os joelhos cerca de 60 graus.","Mantenha os pés no chão e coloque as mãos atrás da cabeça.","Agora enrole-se e traga seu cotovelo direito e ombro através de seu corpo enquanto leva seu joelho esquerdo em direção ao seu ombro esquerdo ao mesmo tempo. Alcance com seu cotovelo e tente tocar seu joelho. Expire enquanto você faz esse movimento.","Agora volte para a posição inicial enquanto inala e repita com o cotovelo esquerdo e o joelho direito.","Continue alternando desta forma até que todas as repetições prescritas sejam feitas."]],"Cross_Body_Hammer_Curl":["Curva de Martelo Cruzado",["Levante-se com um haltere em cada mão, suas mãos devem estar ao seu lado com as mãos viradas para dentro.","Enquanto mantém suas palmas viradas para dentro e sem torcer o braço, enrole o haltere do braço direito para cima em direção ao ombro esquerdo enquanto você expira.","Abaixe lentamente o haltere pelo mesmo caminho que inala e repita o mesmo movimento para o braço esquerdo.","Continue alternando desta forma até que a quantidade recomendada de repetições seja realizada para cada braço."]],"Cross_Over_-_With_Bands":["Atravessem - Com faixas",["Proteja uma faixa de exercício em torno de um poste estacionário.","Ao olhar para longe do post, agarre as alças em ambas as extremidades da banda e dê um passo à frente o suficiente para criar tensão na banda.","Levante os braços para os lados, paralelos ao chão, perpendiculares ao tronco (o tronco e os braços devem se assemelhar à letra \"T\") e com as palmas voltadas para a frente.","Enquanto mantém os braços retos, traga-os para o peito em um movimento semicircular para a frente enquanto expira e flexiona os peitorais.","Retorne lentamente à posição inicial enquanto inala.","Atue para a quantidade recomendada de repetições."]],"Crossover_Reverse_Lunge":["Atravessamento Inverse Lunge",["Esta será sua posição inicial.","Faça uma pulga traseira para trás com um pé e flexione os quadris e o joelho dianteiro, enquanto faz isso, gire o tronco através da perna dianteira.","Após uma breve pausa, volte para a posição inicial e repita do outro lado, continuando de forma alternada."]],"Crucifix":["Crucifixo",["No crucifixo, você estaticamente segura pesos para fora para o tempo, enquanto o evento pode ser praticado usando halteres, é melhor praticar com um dos vários implementos usados, como machados e martelos, como se sente diferente.","Seus braços devem ser paralelos ao chão, em competição, juízes ou sensores são usados para dizer quando você quebra o paralelo, segure o máximo que puder, normalmente, os pesos devem ser pesados o suficiente para que você falhe em 30-60 segundos."]],"Crunch_-_Hands_Overhead":["Crunch - Mãos Overhead",["Deite-se no chão com as costas planas e os joelhos dobrados com um ângulo de 60 graus entre os isquiotibiais e os bezerros.","Mantenha os pés no chão e estique os braços com as palmas cruzadas.","Enrole seu corpo para frente e tire suas omoplatas do chão o tempo todo, mantenha seus braços alinhados com sua cabeça, pescoço e ombro, não mova-os para frente dessa posição, expire enquanto realiza esta parte do movimento e segure a contração por um segundo.","Desça lentamente até a posição inicial enquanto inala.","Repita para a quantidade recomendada de repetições."]],"Crunch_-_Legs_On_Exercise_Ball":["Crunch - Pernas na bola de exercício",["Deite-se de costas com os pés descansando em uma bola de exercício e seus joelhos dobrados em um ângulo de 90 graus.","Coloque seus pés a 3 ou 4 polegadas de distância e aponte seus dedos para dentro para que eles toquem.","Coloque as mãos levemente em cada lado da cabeça, mantendo os cotovelos dentro.","Empurre as costas para o chão para isolar melhor os músculos abdominais.","Comece a rolar seus ombros para fora do chão e continue a empurrar para baixo o mais forte que puder com suas costas inferiores. Seus ombros devem subir do chão apenas cerca de quatro polegadas, e suas costas inferiores devem permanecer no chão.","Lentamente volte para a posição inicial enquanto inala.","Repita para a quantidade recomendada de repetições."]],"Cuban_Press":["Imprensa Cubana",["Pegue um haltere em cada mão com um aperto pronado em uma posição de pé, levante os braços para que fiquem paralelos ao chão, permitindo que seus braços inferiores pendurem na posição de \"escarro\".","Para iniciar o movimento, gire externamente os ombros para mover o braço superior 180 graus. Mantenha os braços superiores no lugar, girando os braços superiores até que os pulsos estejam diretamente acima dos cotovelos, os antebraços perpendiculares ao chão.","Agora aperte os halteres estendendo-se aos cotovelos, endireitando seus braços acima.","Volte para a posição inicial enquanto você respira invertendo os passos.","Repita para a quantidade recomendada de repetições."]],"Dancers_Stretch":["Dancer's Stretch",["Sente-se no chão.","Cruze a perna direita por cima da esquerda, mantendo o joelho dobrado.","Coloque seu braço esquerdo na perna direita e sua mão direita no chão.","Rode a parte superior do corpo para a direita, e segure por 10-20 segundos."]],"Deadlift_with_Bands":["Deadlift com bandas",["Para fazer um lifting com bandas curtas, simplesmente rode-as sobre o bar antes de começar, e pise neles para configurar, para bandas longas, eles terão que ser ancorados em uma base segura, como halteres pesados ou uma prateleira.","Com os pés e o aperto, respire fundo, abaixe os quadris e dobre os joelhos até que suas canelas entrem em contato com a barra, olhe para frente com a cabeça, mantenha o peito para cima e as costas arqueadas, e comece a dirigir através dos calcanhares para mover o peso para cima.","Abaixe a barra dobrando-se nos quadris e guiando-a até o chão."]],"Deadlift_with_Chains":["Deadlift com correntes",["Você pode prender as correntes nas mangas da barra, ou apenas colocar o meio sobre a barra para que haja um aumento de peso maior à medida que você levanta.","Aproxime-se da barra para que ela seja centrada sobre seus pés. Os pés devem ser sobre a largura do quadril separados. Dobre-se no quadril para segurar a barra na largura do ombro, permitindo que suas omoplatas prostrar. Normalmente, você usaria um aperto sobre a mão ou um sobre / sob aperto em conjuntos mais pesados. Com seus pés, e seu conjunto de aperto, tomar uma respiração grande e, em seguida, baixar os quadris e dobrar os joelhos até que suas canelas entrar em contato com a barra.","Olhe para a frente com a cabeça, mantenha o peito para cima e as costas arqueadas, e comece a dirigir através dos calcanhares para mover o peso para cima.","Abaixe a barra dobrando-se nos quadris e guiando-a até o chão."]],"Decline_Barbell_Bench_Press":["Decline Barbell Bench Press",["Segure suas pernas no final do banco de declínio e lentamente deite-se no banco.","Usando um aperto de largura média (um aperto que cria um ângulo de 90 graus no meio do movimento entre os antebraços e os braços superiores), levante a barra do rack e segure-a diretamente sobre você com os braços trancados. Os braços devem ser perpendiculares ao chão. Esta será a sua posição inicial. Dica: A fim de proteger seu manguito rotador, é melhor se você tiver um observador ajudá-lo a levantar a barra do rack.","Enquanto você respira, desça devagar até sentir a barra em seu peito inferior.","Depois de uma segunda pausa, traga a barra de volta para a posição inicial enquanto você expira e empurre a barra usando os músculos do peito, tranque os braços e aperte o peito na posição contraída, segure por um segundo e comece a descer lentamente novamente.","Repita o movimento para a quantidade prescrita de repetições.","Quando terminar, coloque o bar de volta no rack."]],"Decline_Close-Grip_Bench_To_Skull_Crusher":["Decline Close-Grip Bench Para Skull Crusher",["Segure suas pernas no final do banco de declínio e lentamente deite-se no banco.","Para proteger o seu manguito rotador, é melhor se você tiver um observador que o ajude a levantar a campainha do rack.","Agora abaixe a barra até o peito enquanto respira, e mantenha os cotovelos dentro enquanto faz esse movimento.","Usando o tríceps para empurrar o bar de volta, pressione-o de volta para a posição inicial enquanto você expira.","Enquanto você respira e mantém os braços superiores parados, desça a barra lentamente movendo seus antebraços em um movimento semicircular em sua direção até sentir a barra tocar ligeiramente sua testa.","Levante a barra de volta para a posição inicial contraindo o tríceps e expirando.","Repita os passos 3-6 até a quantidade recomendada de repetições ser realizada."]],"Decline_Crunch":["Decline Crunch",["Segure suas pernas no final do banco de declínio e deite-se.","Agora coloque as mãos levemente em cada lado da cabeça mantendo os cotovelos dentro.","Enquanto empurra as costas para baixo no banco para isolar melhor seus músculos abdominais, começar a rolar seus ombros para fora dele.","Continue a empurrar o mais forte que puder com as costas baixas enquanto contrai seus abdominais e expira, seus ombros devem subir do banco apenas cerca de quatro polegadas, e suas costas inferiores devem permanecer no banco, no topo do movimento, contrair seus abdominais com força e manter a contração por um segundo.","Após a contração de um segundo, comece a descer lentamente para a posição inicial enquanto inala.","Repita para a quantidade recomendada de repetições."]],"Decline_Dumbbell_Bench_Press":["Decline halteres Bench Press",["Segure suas pernas no final do banco de declínio e deite-se com um haltere em cada mão em cima de suas coxas.","Assim que estiver deitado, mova os halteres na sua frente com a largura do ombro.","Uma vez na largura do ombro, gire os pulsos para frente para que as palmas das mãos estejam viradas para longe de você.","Mantenha o controle total dos halteres o tempo todo.","Quando expirar, empurre os halteres usando os músculos peitorais, tranque os braços na posição contraída, aperte o peito, segure por um segundo e comece a descer devagar.","Repita o movimento para a quantidade prescrita de repetições do seu programa de treinamento."]],"Decline_Dumbbell_Flyes":["Decline halteres Flyes",["Segure suas pernas no final do banco de declínio e deite-se com um haltere em cada mão em cima de suas coxas.","Quando estiver deitado, mova os halteres na sua frente, com a largura do ombro, as palmas das mãos devem estar voltadas uma para a outra e os braços devem ser perpendiculares ao chão e totalmente estendidos.","Com uma leve dobra nos cotovelos para evitar o estresse no tendão do bíceps, abaixe os braços em ambos os lados em um arco largo até sentir um estiramento no peito, respire enquanto realiza esta parte do movimento, lembre-se que durante todo o movimento, os braços devem permanecer estacionários, o movimento só deve ocorrer na articulação do ombro.","Retorne os braços para a posição inicial enquanto aperta os músculos do peito e expira.","Segure por um segundo na posição contratada e repita o movimento para a quantidade prescrita de repetições."]],"Decline_Dumbbell_Triceps_Extension":["Decline halteres Tríceps Extension",["Segure suas pernas no final do banco de declínio e deite-se com um haltere em cada mão em cima de suas coxas.","Quando estiver deitado, mova os halteres na sua frente, com a largura do ombro, as palmas das mãos devem estar voltadas uma para a outra e os braços devem ser perpendiculares ao chão e totalmente estendidos.","Enquanto você respira e mantém os braços parados (e cotovelos dentro), traga os halteres para baixo lentamente movendo seus antebraços em um movimento semicircular em sua direção até que seus polegares estejam ao lado de seus ouvidos.","Levante os halteres de volta para a posição inicial contraindo o tríceps e expirando.","Repita para a quantidade recomendada de repetições."]],"Decline_EZ_Bar_Triceps_Extension":["Decline EZ Bar Triceps Extension",["Segure suas pernas no final do banco de declínio e lentamente deite-se no banco.","Usando um aperto próximo (um aperto ligeiramente menor que a largura do ombro), levante a barra de EZ do rack e segure-a em cima de você com os braços fechados e cotovelos dentro. Os braços devem ser perpendiculares ao chão. Esta será a sua posição inicial. Dica: Para proteger seu punho rotador, é melhor se você tiver um observador ajudá-lo a levantar a campainha do rack.","Enquanto você respira e mantém os braços superiores parados, desça a barra lentamente movendo seus antebraços em um movimento semicircular em sua direção até sentir a barra tocar ligeiramente sua testa.","Levante a barra de volta para a posição inicial contraindo o tríceps e expirando.","Repita até que a quantidade recomendada de repetições seja realizada."]],"Decline_Oblique_Crunch":["Decline Oblique Crunch",["Segure suas pernas no final do banco de declínio e lentamente deite-se no banco.","Levante a parte superior do corpo do banco até que seu torso esteja entre 35 e 45 graus se medido a partir do chão.","Coloque uma mão ao lado da cabeça e a outra na coxa.","Levante a parte superior do corpo lentamente da posição inicial enquanto vira o tronco para a esquerda, continue a bater enquanto expira até que seu cotovelo direito toque seu joelho esquerdo, mantenha esta posição contraída por um segundo, e mantenha o abdômen apertado e mantenha o movimento lento e controlado.","Abaixe seu corpo lentamente para a posição inicial enquanto inala.","Depois de completar um conjunto à direita para a quantidade recomendada de repetições, mude para o lado esquerdo."]],"Decline_Push-Up":["Decline Push-up",["Deite-se no chão de frente para baixo e coloque suas mãos a cerca de 36 polegadas de distância enquanto segura seu tronco com os braços para cima.","Em seguida, abaixe-se para baixo até que seu peito quase toque o chão enquanto você inala.","Agora expire e pressione sua parte superior do corpo de volta para a posição inicial enquanto aperta seu peito.","Depois de uma breve pausa na posição contratada, você pode começar a se abaixar novamente para quantas repetições forem necessárias."]],"Decline_Reverse_Crunch":["Decline Reverse Crunch",["Deite-se de costas em um banco de declínio e segure-se no topo do banco com as duas mãos.","Mantenha as pernas paralelas ao chão, usando o abdômen para segurá-las enquanto mantém os joelhos e pés juntos.","Enquanto expira, mova suas pernas para o torso enquanto você gira sua pélvis para trás e levanta seus quadris do banco.","Segure a contração por um segundo e mova suas pernas de volta para a posição inicial enquanto inala.","Repita para a quantidade recomendada de repetições."]],"Decline_Smith_Press":["Decline Smith Press",["Coloque um banco de declive embaixo da máquina Smith, agora coloque a campainha em uma altura que você pode alcançar quando se deitar e seus braços estão quase totalmente estendidos, usando um aperto pronado que é maior que a largura do ombro, destrave a barra do rack e segure-a diretamente sobre você com os braços estendidos, esta será sua posição inicial.","Enquanto você inala, abaixe a barra sob controle, permitindo que os cotovelos flexionem, entrando levemente em contato com o tronco.","Após uma breve pausa, traga a barra de volta para a posição inicial, estendendo os cotovelos, expirando como você faz.","Repita o movimento para a quantidade prescrita de repetições.","Quando o conjunto estiver completo, tranque a barra de volta no rack."]],"Depth_Jump_Leap":["Salto da Profundidade",["Para esta broca você precisará de duas caixas ou bancos, uma de 12 a 16 polegadas de altura e a outra de 22 a 26 polegadas de altura.","Coloque a outra caixa com cerca de dois ou três pés na frente e de frente para o artista.","Comece deixando a caixa inicial, pousando e decolando simultaneamente com os dois pés.","Rebound, dirigindo para cima e para fora o mais intensamente possível, usando os braços e extensão total do corpo para saltar para a caixa superior."]],"Dip_Machine":["Máquina de mergulho",["Sente-se firmemente em uma máquina de mergulho, selecione o peso e segure firmemente as alças.","Mantenha os cotovelos de lado para dar ênfase ao tríceps, os cotovelos devem ser dobrados em um ângulo de 90 graus.","Enquanto contrai o tríceps, estenda os braços para baixo enquanto expira.","Agora lentamente deixe seus braços voltarem para a posição inicial enquanto você inala.","Repita para a quantidade recomendada de repetições."]],"Dips_-_Chest_Version":["Dips - Versão do peito",["Para este exercício, você precisará de acesso a barras paralelas... para entrar na posição inicial, mantenha seu corpo com os braços abertos... acima das barras.","Enquanto respirava, abaixe-se lentamente com o torso inclinando-se para a frente em torno de 30 graus ou mais e seus cotovelos irromperam ligeiramente até sentir um leve estiramento no peito.","Quando sentir o estiramento, use seu peito para trazer seu corpo de volta à posição inicial enquanto expira.","Repita o movimento para a quantidade prescrita de repetições."]],"Dips_-_Triceps_Version":["Dips - Versão Triceps",["Para entrar na posição inicial, segure seu corpo ao longo do braço com os braços quase trancados acima das barras.","Agora, inale e abaixe-se lentamente para baixo, seu tronco deve permanecer ereto e seus cotovelos devem ficar perto de seu corpo, isso ajuda a focar melhor no envolvimento do tríceps, abaixe-se até que haja um ângulo de 90 graus formado entre o braço e o antebraço.","Então, expire e empurre seu torso para cima usando seus tríceps para trazer seu corpo de volta para a posição inicial.","Repita o movimento para a quantidade prescrita de repetições."]],"Donkey_Calf_Raises":["Burro de bois levanta",["Para este exercício, você precisará de acesso a uma máquina de elevação de bezerro de burro, comece posicionando suas costas e quadris abaixo da alavanca almofadada fornecida, e a área do cóccix deve ser a que fará contato com o bloco.","Coloque os dois braços nas alças laterais e coloque as bolas dos pés no bloco do bezerro com os calcanhares estendidos, alinhando os dedos dos pés para frente, para dentro ou para fora, dependendo da área que você deseja mirar, e endireite os joelhos sem trancá-los.","Levante os calcanhares enquanto expira, estendendo os tornozelos o mais alto possível e flexionando a panturrilha, certifique-se de que o joelho fique parado o tempo todo, não deve haver flexão a qualquer momento, mantenha a posição contraída por um segundo antes de começar a voltar para baixo.","Volte lentamente para a posição inicial enquanto você respira baixando os calcanhares enquanto dobra os tornozelos até as panturrilhas ficarem esticadas.","Repita para a quantidade recomendada de repetições."]],"Double_Kettlebell_Alternating_Hang_Clean":["Dupla Kettlebell Alternando Penduragem Limpa",["Coloque duas campainhas entre os pés, para entrar na posição inicial, empurre o traseiro para trás e olhe para frente.","Limpe uma campainha no ombro e segure a outra.","Com um movimento fluido, abaixe a chaleira superior enquanto dirige a chaleira inferior para cima."]],"Double_Kettlebell_Jerk":["Double Kettlebell Jerk",["Segure uma campainha perto do cabo em cada mão.","Limpe as campainhas para os ombros, estendendo-se pelas pernas e quadris enquanto puxa as campainhas para os ombros, girando os pulsos enquanto faz isso, para que as palmas da mão fiquem viradas para a frente, esta será a sua posição inicial.","Mergulhe o corpo dobrando os joelhos, mantendo o tronco ereto.","Imediatamente inverta a direção, dirigindo através dos saltos, em essência pulando para criar impulso.","Enquanto você faz isso, pressione as campainhas acima para bloquear estendendo os braços, usando o impulso do seu corpo para mover os pesos.","Retorne seus pés ao chão de uma forma dividida, com um pé para frente e um pé para trás.","Mantendo os pesos em cima, volte para uma posição de pé, unindo seus pés."]],"Double_Kettlebell_Push_Press":["Dupla Kettlebell Press",["Limpe duas campainhas nos seus ombros.","Agache-se alguns centímetros e inverta o movimento rapidamente.","Assim que as campainhas estiverem trancadas, abaixe as campainhas para seus ombros e repita."]],"Double_Kettlebell_Snatch":["Dupla Cettlebell",["Coloque dois sinos atrás dos pés, dobre os joelhos e sente-se para pegar os sinos.","Balance as campainhas entre as pernas com força e inverta a direção.","Dirija com seus quadris e tranque as campainhas em um movimento ininterrupto."]],"Double_Kettlebell_Windmill":["Moinho de vento duplo Kettlebell",["Coloque uma chaleira na frente do pé da frente e limpe e pressione uma chaleira acima com o braço oposto, limpe a chaleira no ombro estendendo-se pelas pernas e quadris enquanto puxa a chaleira para os ombros, gire o pulso enquanto o faz, para que a palma da mão se estenda para frente.","Mantendo a chaleira fechada o tempo todo, empurre sua bunda para fora na direção da chaleira fechada, vire os pés para fora em um ângulo de 45 graus do braço com a chaleira trancada.","Dobrando o quadril para um lado, enfiando sua bunda para fora, lentamente inclinando-se até que você possa recuperar a chaleira do chão, mantenha os olhos na chaleira que você segura sobre a cabeça o tempo todo.","Pause por um segundo depois de recuperar a chaleira do chão e reverter o movimento de volta para a posição inicial."]],"Double_Leg_Butt_Kick":["Golpe duplo na perna.",["Comece com os joelhos ligeiramente dobrados.","Agache-se rapidamente a uma curta distância, flexionando os quadris e joelhos, e imediatamente se estenda para saltar para a altura vertical máxima.","Quando subir, aperte os calcanhares, flexionando os joelhos, tentando tocar as nádegas.","Termine o movimento pousando com os joelhos apenas parcialmente dobrados, usando suas pernas para absorver o impacto."]],"Downward_Facing_Balance":["Equilíbrio De frente para baixo",["Deite-se em cima de uma bola de exercício.","Enquanto descansa sobre o estômago na bola, andem com as mãos para a frente ao longo do chão e levantem as pernas, estendendo os cotovelos e joelhos."]],"Drag_Curl":["Drag Curl",["Pegue uma campainha com um aperto supinado (palmas voltadas para frente) e coloque seus cotovelos perto do torso e para trás.","Enquanto você expira, enrole a barra enquanto mantém os cotovelos para trás enquanto você \"arrasta\" a barra mantendo-a em contato com seu torso.","Lentamente volte para a posição inicial enquanto mantém a barra em contato com o torso o tempo todo.","Repita para a quantidade recomendada de repetições."]],"Drop_Push":["Soltem, empurrem.",["Posicione caixas baixas ou outras plataformas a 2-3 pés de distância.","Mova-se para uma posição de flexão entre eles, apoiando-se colocando as mãos nas caixas.","Com boa postura, desça das plataformas pressionando e movendo suas mãos para a largura do ombro, amortecendo seu pouso absorvendo o impacto através do braço."]],"Dumbbell_Alternate_Bicep_Curl":["halteres Alternate Bicep Curl",["Os cotovelos devem estar perto do torso e as palmas da mão devem estar viradas para as coxas.","Enquanto segura o braço parado, enrole o peso direito enquanto gira a palma das mãos até que estejam voltadas para frente, e continue contraindo os bíceps enquanto expira até que seus bíceps estejam totalmente contraídos e os halteres estejam no nível do ombro, mantenha a posição contraída por um segundo enquanto aperta os bíceps.","Lembre-se de torcer as palmas das mãos de volta para a posição inicial (de frente para as coxas) enquanto desce.","Repita o movimento com a mão esquerda.","Continue alternando desta forma para a quantidade recomendada de repetições."]],"Dumbbell_Bench_Press":["halteres Bench Press",["Deite-se em um banco plano com um haltere em cada mão descansando em cima de suas coxas as palmas de suas mãos estarão se encarando.","Então, usando suas coxas para ajudar a levantar os halteres, levante os halteres um de cada vez para que você possa segurá-los na sua frente com a largura do ombro.","Uma vez na largura do ombro, gire os pulsos para a frente para que as palmas das mãos fiquem longe de você, os halteres devem estar apenas nos lados do peito, com o braço e o antebraço criando um ângulo de 90 graus, e mantenha o controle total dos halteres o tempo todo.","Então, enquanto você expira, use seu peito para empurrar os halteres para cima.","Repita o movimento para a quantidade prescrita de repetições do seu programa de treinamento."]],"Dumbbell_Bench_Press_with_Neutral_Grip":["halteres Bench Press com aperto neutro",["Pegue um haltere em cada mão e deite-se em um banco plano, seus pés devem estar no chão e suas omoplatas retraídas.","Mantendo uma aderência neutra, palmas viradas uma para a outra, comecem com os braços estendidos diretamente acima de você, perpendiculares ao chão.","Comece o movimento, flexionando o cotovelo, baixando os braços para o lado, desça até os halteres chegarem ao seu tronco.","Pausa, então estenda o cotovelo e volte para a posição inicial."]],"Dumbbell_Bicep_Curl":["halteres Bicep Curl",["Mantenha os cotovelos perto do torso e gire as palmas das mãos até que estejam voltadas para a frente.","Mantenha os braços parados, expire e enrole os pesos enquanto contrai seus bíceps, continue a levantar os pesos até que seus bíceps estejam totalmente contraídos e os halteres estejam no nível do ombro, mantenha a posição contraída para uma breve pausa enquanto aperta seus bíceps.","Então, inalar e lentamente começar a baixar os halteres de volta para a posição inicial.","Repita para a quantidade recomendada de repetições."]],"Dumbbell_Clean":["Dumblebell Limpo",["Comecem com um haltere em cada mão com os pés afastados.","Abaixe os pesos para o chão, flexionando os quadris e joelhos, empurrando seus quadris para trás até que os halteres cheguem ao chão.","Para iniciar o movimento, pule violentamente para cima, estendendo os quadris, joelhos e tornozelos para acclerar os pesos para cima.","Após a extensão completa, redobre os quadris e joelhos para receber o peso em uma posição de agachamento.","Ao receber o peso na posição de agachamento, estenda os quadris e joelhos para terminar em pé com os pesos em seus ombros."]],"Dumbbell_Flyes":["halteres Flyes.",["Deite-se em um banco plano com um haltere em cada mão descansando em cima de suas coxas as palmas de suas mãos estarão se encarando.","Então, usando suas coxas para ajudar a levantar os halteres, levante os halteres um de cada vez para que você possa segurá-los na sua frente com as palmas das mãos viradas um para o outro, levante os halteres como se estivesse pressionando-os, mas pare e segure bem antes de fechar.","Com uma leve dobra nos cotovelos para evitar o estresse no tendão do bíceps, abaixe os braços em ambos os lados em um arco largo até sentir um estiramento no peito, respire enquanto realiza esta parte do movimento, lembre-se que durante todo o movimento, os braços devem permanecer estacionários, o movimento só deve ocorrer na articulação do ombro.","Retorne os braços para a posição inicial enquanto aperta os músculos do peito e expira.","Segure por um segundo na posição contratada e repita o movimento para a quantidade prescrita de repetições."]],"Dumbbell_Incline_Row":["Fila de Incline halteres",["Usando um aperto neutro, incline-se em um banco inclinado.","Pegue um haltere em cada mão com um aperto neutro, começando com os braços retos.","Retraia os ombros e flexione os cotovelos para remar os halteres para o seu lado.","Pause no topo da moção, e depois volte para a posição inicial."]],"Dumbbell_Incline_Shoulder_Raise":["Ombros em Inclinação de halteres",["Sente-se em um banco Incline enquanto segura um haltere em cada mão em cima de suas coxas.","Levantem as pernas para chutar os pesos para os ombros e inclinem-se para trás, posicionem os halteres acima dos ombros com os braços estendidos, os braços devem ser perpendiculares ao chão com as palmas voltadas para frente e os dedos apontando para o teto, esta será a sua posição inicial.","Enquanto mantém os braços retos e trancados, levante os halteres levantando os ombros do banco enquanto você expira.","Traga os halteres de volta para a posição inicial enquanto você respira.","Repita para a quantidade recomendada de repetições."]],"Dumbbell_Lunges":["Dumbell Lunges.",["Fique com o torso ereto segurando dois halteres em suas mãos ao lado, esta será sua posição inicial.","Dê um passo para frente com a perna direita cerca de 2 pés do pé sendo deixado parado para trás e abaixe o corpo, mantendo o tronco ereto e mantendo o equilíbrio.","Usando principalmente o calcanhar do seu pé, empurre para cima e volte para a posição inicial enquanto expira.","Repita o movimento para a quantidade recomendada de repetições e então execute com a perna esquerda."]],"Dumbbell_Lying_One-Arm_Rear_Lateral_Raise":["Dumblebell deitado com um braço, levante lateral traseiro.",["Enquanto segura um haltere em uma mão, deite-se com o peito para baixo em um banco ajustável levemente inclinado (cerca de 15 graus quando medido a partir do chão), a outra mão pode ser usada para segurar a perna do banco para a estabilidade.","Posicione a palma da mão que está segurando o haltere de forma neutra (palmas voltadas para seu torso) enquanto mantém o braço estendido com o cotovelo ligeiramente dobrado.","Agora levante o braço com o haltere para o lado até que seu cotovelo esteja na altura do ombro e seu braço seja aproximadamente paralelo ao chão enquanto você expira.","Abaixe lentamente o haltere para a posição inicial enquanto inala.","Repita para a quantidade recomendada de repetições."]],"Dumbbell_Lying_Pronation":["Pronação do Dumblebell",["Deite-se em um banco plano com um braço segurando um haltere e a outra mão em cima do banco dobrado para que você possa descansar sua cabeça sobre ele.","Dobre os cotovelos do braço segurando o haltere para que ele crie um ângulo de 90 graus entre o braço superior e o antebraço.","Agora levante o braço superior para que o antebraço seja perpendicular ao chão e o braço superior perpendicular ao seu tronco.","Enquanto você expira, gire externamente o antebraço para que o haltere seja levantado para frente enquanto você mantém o ângulo de 90 graus entre os braços superiores e o antebraço, você continuará esta rotação externa até que o antebraço seja paralelo ao chão.","Enquanto você respira, lentamente volte para a posição inicial.","Repita para a quantidade recomendada de repetições."]],"Dumbbell_Lying_Rear_Lateral_Raise":["Dumblebell deitado traseiro lateral levantar",["Enquanto segura um haltere em cada mão, deite-se com o peito para baixo em um banco ajustável (em torno de 15 graus quando medido a partir do chão).","Posicione as palmas das mãos de forma neutra, enquanto mantém os braços estendidos com os cotovelos ligeiramente dobrados.","Agora levante os braços para o lado até que seus cotovelos estejam na altura do ombro e seus braços sejam aproximadamente paralelos ao chão enquanto você expira.","Abaixe lentamente os halteres para a posição inicial enquanto inala.","Repita a quantidade recomendada de repetições e mude para o outro braço."]],"Dumbbell_Lying_Supination":["halteres mentindo Supinação",["Deite-se de lado em um banco plano com um braço segurando um haltere e a outra mão em cima do banco dobrado para que você possa descansar sua cabeça sobre ele.","Dobre os cotovelos do braço segurando o haltere para que ele crie um ângulo de 90 graus entre o braço superior e o antebraço.","Agora levante o braço para que o antebraço seja paralelo ao chão e perpendicular ao seu tronco (Dica: então o antebraço estará diretamente na sua frente) e o antebraço ficará parado pelo seu tronco e deve ser paralelo ao chão (alinhado com o seu tronco em todos os momentos), esta será a sua posição inicial.","Enquanto você expira, gire externamente o antebraço para que o haltere seja levantado em um movimento semicírculo enquanto você mantém o ângulo de 90 graus entre os braços e o antebraço. você continuará esta rotação externa até que o antebraço seja perpendicular ao chão e o tronco apontando para o teto.","Enquanto você respira, lentamente volte para a posição inicial.","Repita a quantidade recomendada de repetições e mude para o outro braço."]],"Dumbbell_One-Arm_Shoulder_Press":["halteres One-Arm Shoulder Press",["Pegue um haltere e sente-se em um banco de imprensa militar ou em um banco de utilidades que tem um apoio traseiro enquanto você coloca os halteres em cima de suas coxas ou fica em pé.","Limpe o haltere para chegar à altura do ombro, a outra mão pode ser mantida totalmente estendida para o lado, pela cintura ou segurando uma superfície fixa.","Rodar o pulso para que a palma da sua mão esteja voltada para frente.","Enquanto você expira, empurre o haltere para cima até que seu braço esteja totalmente estendido.","Depois de uma segunda pausa, lentamente volte para a posição inicial enquanto você inala.","Repita para a quantidade recomendada de repetições e depois troque de braço."]],"Dumbbell_One-Arm_Triceps_Extension":["halteres One-Arm Triceps Extension",["Pegue um haltere e sente-se em um banco de imprensa militar ou em um banco de utilidades que tem um apoio traseiro enquanto você coloca os halteres em cima de suas coxas ou fica em pé.","Limpe o haltere para levá-lo à altura do ombro e então estenda o braço sobre a cabeça para que todo o braço seja perpendicular ao chão e próximo à sua cabeça.","Rodar o pulso para que a palma da sua mão esteja voltada para frente e o mindinho esteja de frente para o teto.","Abaixe lentamente o haltere atrás da cabeça enquanto segura o braço parado, inspire enquanto faz esse movimento e pause quando seu tríceps está totalmente esticado.","É imperativo que apenas o antebraço se mova, o braço deve permanecer parado ao lado da cabeça.","Repita para a quantidade recomendada de repetições e mude de braços."]],"Dumbbell_One-Arm_Upright_Row":["Dumblebell One-Arm Upright Row",["Pegue um haltere e fique em pé com o braço estendido na sua frente com uma leve curva nos cotovelos e nas costas retas.","Mantenha a outra mão totalmente estendida para o lado, pela cintura ou agarrando uma superfície fixa.","Use seus ombros laterais para levantar o haltere enquanto expira, o haltere deve estar perto do corpo enquanto você o move, continue a levantá-lo até que o haltere esteja quase em linha com seu queixo, dica, seus cotovelos devem dirigir o movimento, enquanto você levanta o haltere, seu cotovelo deve estar sempre mais alto do que seu antebraço, e também, mantenha seu tronco parado e pause por um segundo no topo do movimento.","Abaixe o haltere lentamente para a posição inicial, inale enquanto executa esta parte do movimento.","Repita para a quantidade recomendada de repetições e mude de braços."]],"Dumbbell_Prone_Incline_Curl":["halteres Prone Incline Curl",["Pegue um haltere em cada mão e deite-se de costas em um banco inclinado com seus ombros perto do topo da inclinação seus joelhos podem descansar no assento ou suas pernas podem ser inclinadas para os lados (meu modo preferido).","Deixe seus braços estenderem-se e pendurarem-se naturalmente na sua frente para que fiquem perpendiculares ao chão.","Mantenha os cotovelos ao lado e vire as palmas para frente.","Levantem os halteres contraindo os bíceps até que seus braços estejam totalmente flexionados, expirem enquanto realizam esta parte do movimento e assegurem que apenas os antebraços se movam, os braços superiores devem permanecer parados o tempo todo.","Abaixe os halteres até que seus braços estejam totalmente estendidos.","Repita para a quantidade recomendada de vezes."]],"Dumbbell_Raise":["Levantar o Dumblebell",["Pegue um haltere em cada braço e levante-se com os braços estendidos pelos lados com uma leve curva nos cotovelos e nas costas retas.","Use seus ombros laterais para levantar os halteres enquanto você expira, os halteres devem estar ao lado do corpo enquanto você os move para cima, continue a levantá-los até que os halteres estejam quase alinhados com seu queixo, e seus cotovelos devem dirigir o movimento, enquanto você levanta o haltere, seu cotovelo deve estar sempre mais alto do que seu antebraço, e também, mantenha seu tronco parado e pause por um segundo no topo do movimento.","Abaixe os halteres lentamente para a posição inicial, inspire enquanto executa esta parte do movimento.","Repita para a quantidade recomendada de repetições."]],"Dumbbell_Seated_Box_Jump":["Bando de Dumblebell Seated Box Jump",["Coloque uma caixa a alguns metros do lado de um banco... segure um haltere no peito com as duas mãos e sente-se no banco de frente para a caixa.","Coloque seus pés firmemente no chão enquanto se inclina para frente, estendendo-se através dos quadris e joelhos para saltar para cima e para frente.","Pouse na caixa com os dois pés, absorvendo o impacto, permitindo que os quadris e joelhos se dobrem.","Desça e volte para a posição inicial."]],"Dumbbell_Seated_One-Leg_Calf_Raise":["Dumblebell assentou uma perna Calf levantar",["Coloque uma quadra no chão a cerca de 12 polegadas de um banco plano.","Sente-se em um banco plano e coloque um haltere em sua coxa superior esquerda cerca de 3 polegadas acima de seu joelho.","Agora coloque a bola do pé esquerdo no bloco.","Levante os dedos o mais alto possível e contraia o músculo da panturrilha.","Retorne lentamente à posição inicial, estendendo-se o mais longe possível.","Repita para o número prescrito de repetições e depois repita com a perna direita."]],"Dumbbell_Shoulder_Press":["halteres Shoulder Press",["Enquanto segura um haltere em cada mão, sente-se em um banco de imprensa militar ou banco de utilidades que tem apoio nas costas.","Agora levante os halteres para a altura do ombro um de cada vez usando suas coxas para ajudá-los a colocá-los em posição.","Certifique-se de girar seus pulsos para que as palmas de suas mãos estejam voltadas para frente.","Agora, expire e empurre os halteres para cima até que toquem no topo.","Então, após uma breve pausa na posição superior contraída, lentamente baixar os pesos de volta para a posição inicial enquanto inala.","Repita para a quantidade recomendada de repetições."]],"Dumbbell_Shrug":["halteres Shrug",["Fique ereto com um haltere em cada mão (palmas voltados para seu tronco), braços estendidos nos lados.","Levante os halteres elevando os ombros o mais alto possível enquanto expira, segure a contração no topo por um segundo, e os braços devem permanecer estendidos o tempo todo, refreie-se de usar os bíceps para ajudar a levantar os halteres, só que os ombros devem se mover para cima e para baixo.","Abaixe os halteres de volta para a posição original.","Repita para a quantidade recomendada de repetições."]],"Dumbbell_Squat":["Agachamento de halteres",["Levante-se direito enquanto segura um haltere em cada mão (palmas viradas para o lado das pernas).","Mantenha a cabeça erguida o tempo todo, pois olhar para baixo vai te desequilibrar e também manter uma parte traseira reta.","Se você fez o exercício corretamente, a frente dos joelhos deve fazer uma linha reta imaginária com os dedos perpendiculares à frente.","Comece a levantar o torso enquanto expira, empurrando o chão com o calcanhar do pé, principalmente enquanto endireita as pernas novamente e volta para a posição inicial.","Repita para a quantidade recomendada de repetições."]],"Dumbbell_Squat_To_A_Bench":["Agacha-te a um banco",["Levante-se com um banco plano atrás de você enquanto segura um haltere em cada mão (palmas viradas para o lado de suas pernas).","Mantenha a cabeça erguida o tempo todo, pois olhar para baixo vai te desequilibrar e também manter uma parte traseira reta.","Se você fez o exercício corretamente, a frente dos joelhos deve fazer uma linha reta imaginária com os dedos perpendiculares à frente. Se seus joelhos estão além dessa linha imaginária (se eles estão além dos dedos dos pés) então você está colocando estresse excessivo no joelho e o exercício foi realizado incorretamente.","Comece a levantar a barra enquanto expira, empurrando o chão com o calcanhar do pé, principalmente enquanto endireita as pernas novamente e volta para a posição inicial.","Repita para a quantidade recomendada de repetições."]],"Dumbbell_Step_Ups":["Dumblebell sobe.",["Levante-se direito enquanto segura um haltere em cada mão (palmas viradas para o lado das pernas).","Coloque o pé direito na plataforma elevada, pise na plataforma estendendo o quadril e o joelho da perna direita, use o calcanhar principalmente para levantar o resto do corpo e colocar o pé da perna esquerda na plataforma também, respire enquanto executa a força necessária para subir.","Desça com a perna esquerda, flexionando o quadril e o joelho da perna direita enquanto inala, e volte para a posição de pé original, colocando o pé direito ao lado do pé esquerdo na posição inicial.","Repita com a perna direita para a quantidade recomendada de repetições e depois execute com a perna esquerda."]],"Dumbbell_Tricep_Extension_-Pronated_Grip":["halteres Tríceps Extensionação Pronated Grip",["Deite-se em um banco plano segurando dois halteres diretamente sobre seus ombros, seus braços devem ser estendidos e formar um ângulo de 90 graus do seu tronco e do chão.","As palmas das suas mãos devem estar voltadas para frente, e seus cotovelos devem ser dobrados.","Agora, inale e abaixe lentamente os halteres até que estejam perto de suas orelhas.","Então, expire e use seu tríceps para devolver o peso para a posição inicial."]],"Dynamic_Back_Stretch":["Esticamento dinâmico das costas.",["Esta será sua posição inicial.","Mantendo seus braços eretos, balance-os para a sua frente 5-10 vezes, aumentando a amplitude de movimento de cada vez até que seus braços estejam acima de sua cabeça."]],"Dynamic_Chest_Stretch":["Esticamento dinâmico do peito",["Fiquem com as mãos juntas, braços estendidos diretamente na sua frente.","Mantenha os braços retos, mova os braços o mais rápido possível e volte de novo, semelhante a um movimento exagerado de palmas."]],"EZ-Bar_Curl":["EZ-Bar Curl",["As palmas das mãos devem estar voltadas para a frente e ligeiramente inclinadas para dentro devido à forma da barra.","Agora, mantendo seus braços parados, expire e enrole os pesos para frente enquanto contrai os bíceps.","Continue a aumentar o peso até que seus bíceps estejam totalmente contraídos e a barra esteja no nível do ombro.","Então inale e lentamente abaixe a barra de volta para a posição inicial.","Repita para a quantidade recomendada de repetições."]],"EZ-Bar_Skullcrusher":["EZ-Bar Skullcrusher",["Usando um aperto de perto, levante a barra EZ e segure-a com os cotovelos enquanto você se deita no banco, seus braços devem ser perpendiculares ao chão, esta será sua posição inicial.","Mantendo os braços parados, baixando a barra, permitindo que os cotovelos flexionem, inale enquanto você faz esta parte do movimento, pare uma vez que a barra esteja diretamente acima da testa.","Levante a barra de volta para a posição inicial, estendendo o cotovelo e expirando.","Repito."]],"Elbow_Circles":["Círculos de cotovelos",["Sente-se ou fique com os pés um pouco separados.","Coloque as mãos nos ombros com os cotovelos no nível do ombro e aponte para fora.","Faça um círculo lentamente com os cotovelos, expire enquanto começa o círculo e respire enquanto completa o círculo."]],"Elbow_to_Knee":["Cotovelo para Joelho",["Deite-se no chão, cruzando sua perna direita através de seu joelho esquerdo dobrado, aperte as mãos atrás da cabeça, começando com suas omoplatas no chão, esta será sua posição inicial.","Faça o movimento flexionando a coluna vertebral e girando seu tronco para trazer o cotovelo esquerdo para o joelho direito.","Volte para a posição inicial e repita o movimento para o número desejado de repetições antes de mudar de lado."]],"Elbows_Back":["Cotovelos para trás",["Levante-se direito.","Coloque as duas mãos nas costas, dedos apontando para baixo e cotovelos para fora.","Então puxe seus cotovelos suavemente para trás com o objetivo de tocá-los juntos."]],"Elevated_Back_Lunge":["Lunge de costas elevada.",["Posicione uma barra em um rack na altura do ombro carregado para um peso apropriado.","Enfie a barra na parte superior das costas, mantendo as costas arqueadas e apertadas, entre na plataforma levantada com os dois pés, esta será sua posição inicial.","Comece andando para trás com uma perna, descendo, flexionando seus quadris e joelhos até o joelho tocar o chão.","Pause, e estenda-se através dos quadris e joelhos para se levantar, retornando até a posição inicial antes de alternar."]],"Elevated_Cable_Rows":["Linhas de Cabo Elevadas",["Obter uma plataforma de algum tipo (pode ser uma plataforma de aeróbica ou elevação de bezerro) que tem cerca de 4-6 polegadas de altura.","Coloque no assento da máquina de linha de cabo.","Sente-se na máquina e coloque seus pés na plataforma dianteira ou barra transversal desde que seus joelhos estejam ligeiramente dobrados e não trancados.","Incline-se enquanto mantém o alinhamento natural das costas e agarre os cabos da barra V.","Com os braços estendidos, puxe para trás até que seu torso esteja em um ângulo de 90 graus de suas pernas, suas costas devem estar ligeiramente arqueadas e seu peito deve ficar para fora, você deve estar se sentindo bem esticado enquanto segura a barra na sua frente, esta é a posição inicial do exercício.","Mantendo o torso parado, puxe as alças para trás em direção ao torso, mantendo os braços perto dele até que você toque os abdominais, respire enquanto você faz esse movimento, nesse ponto você deve apertar os músculos das costas com força, segure a contração por um segundo e lentamente volte para a posição original enquanto respira.","Repita para a quantidade recomendada de repetições."]],"Elliptical_Trainer":["Treinador Elíptico",["Para começar, entre na elíptica e selecione a opção desejada no menu, a maioria das elípticas tem uma configuração manual, ou você pode selecionar um programa para rodar, normalmente, você pode inserir sua idade e peso para estimar a quantidade de calorias queimadas durante o exercício, a elevação pode ser ajustada para alterar a intensidade do treino.","As alças podem ser usadas para monitorar seu batimento cardíaco para ajudá-lo a ficar em uma intensidade apropriada."]],"Exercise_Ball_Crunch":["Exercise Ball Crunch",["Deite-se em uma bola de exercício com sua curvatura lombar pressionada contra a superfície esférica da bola. Seus pés devem ser dobrados no joelho e pressionados firmemente contra o chão. O torso superior deve ser pendurado na parte superior da bola. Os braços devem ser mantidos ao lado do corpo ou cruzados em cima do peito, uma vez que essas posições evitam tensões no pescoço (ao contrário das mãos atrás da posição da cabeça).","Abaixe o torso em uma posição de estiramento mantendo o pescoço parado o tempo todo.","Com os quadris parados, flexione a cintura contraindo os abdominais e enrole os ombros e o tronco para cima até sentir uma boa contração em seus abdominais, os braços devem simplesmente deslizar para o lado de suas pernas se você os tiver ao lado ou apenas ficar em cima de seu peito se você os tiver cruzado, as costas inferiores devem sempre ficar em contato com a bola, expire enquanto você faz esse movimento e segure a contração por um segundo.","Ao inalar, volte para a posição inicial.","Repita para a quantidade recomendada de repetições."]],"Exercise_Ball_Pull-In":["Exercise Ball Pull-In",["Coloque uma bola de exercício perto e deite-se no chão na frente dela com as mãos no chão com a largura do ombro afastada em uma posição de flexão.","Agora coloque suas canelas inferiores em cima de uma bola de exercício.","Enquanto mantém as costas completamente retas e a parte superior do corpo parada, puxe os joelhos para o peito enquanto expira, permitindo que a bola role para frente sob os tornozelos.","Agora endireite as pernas lentamente, rodando a bola de volta para a posição inicial enquanto você inala.","Repita para a quantidade recomendada de repetições."]],"Extended_Range_One-Arm_Kettlebell_Floor_Press":["Gama estendida 1 braço Kettlebell Floor Press",["Deite-se no chão e coloque uma campainha para um braço pressionar, a chaleira deve ser segurada pelo cabo, a perna do mesmo lado que você está pressionando deve ser dobrada, com o joelho atravessando a linha média do corpo.","Aperte a campainha, estendendo o cotovelo e seduzindo o braço, pressionando-o acima do corpo."]],"External_Rotation":["Rotação externa.",["Deite-se de lado em um banco plano com um braço segurando um haltere e a outra mão em cima do banco dobrado para que você possa descansar sua cabeça sobre ele.","Dobre os cotovelos do braço segurando o haltere para criar um ângulo de 90 graus entre a parte superior do braço e o antebraço.","Agora dobre o cotovelo mantendo o braço parado, desta forma, o antebraço será paralelo ao chão e perpendicular ao seu tronco (Dica, então o antebraço estará diretamente na sua frente).","Enquanto você expira, gire externamente o antebraço para que o haltere seja levantado em um movimento semicírculo enquanto você mantém o ângulo de 90 graus entre os braços e o antebraço. você continuará esta rotação externa até que o antebraço seja perpendicular ao chão e o tronco apontando para o teto.","Enquanto você respira, lentamente volte para a posição inicial.","Repita a quantidade recomendada de repetições e mude para o outro braço."]],"External_Rotation_with_Band":["Rotação externa com Banda",["A banda deve estar na mesma altura do seu cotovelo, com seu lado esquerdo na banda, a alguns metros de distância.","Segure o fim da banda com a mão direita, e mantenha o cotovelo pressionado firmemente para o lado.","Com seu braço em posição, seu cotovelo deve ser flexionado a 90 graus com sua mão estendendo-se pela frente do tronco.","Execute o movimento girando seu braço em movimento de costas, mantendo seu cotovelo no lugar.","Continue o máximo que puder, pause e depois volte para a posição inicial."]],"External_Rotation_with_Cable":["Rotação externa com cabo",["Ajustar o cabo para a mesma altura do cotovelo, ficar com o lado esquerdo para a banda a alguns metros de distância.","Segure o cabo com a mão direita, e mantenha o cotovelo pressionado firmemente para o lado.","Com seu braço em posição, seu cotovelo deve ser flexionado a 90 graus com sua mão estendendo-se pela frente do tronco.","Execute o movimento girando seu braço em movimento de costas, mantendo seu cotovelo no lugar."]],"Farmers_Walk":["Caminhada do Fazendeiro",["Há vários implementos que podem ser usados para a caminhada dos agricultores, que também podem ser realizados com halteres pesados ou barras curtas se esses implementos não estiverem disponíveis.","Depois de segurar as alças, levante-as dirigindo através de seus calcanhares, mantendo suas costas retas e sua cabeça erguida.","Caminhe rápido e rápido, e não se esqueça de respirar, mova-se para uma determinada distância, normalmente 50-100 pés, o mais rápido possível."]],"Fast_Skipping":["Saltando rápido.",["Comece em uma posição relaxada com uma perna um pouco para frente.","Pule executando um padrão de passo-a-passo direito-direito-passo para esquerda-esquerda-passo, e assim por diante, alternando para trás e para frente.","Faça saltos rápidos mantendo contato próximo com o solo e reduza o tempo de ar, movendo-se o mais rápido possível."]],"Finger_Curls":["Dedo Curls",["Segure uma campainha com as duas mãos e as palmas viradas para cima, com as mãos espaçadas sobre a largura do ombro.","Coloque seus pés no chão, a uma distância um pouco maior do que a largura do ombro.","Abaixe a barra o mais longe possível estendendo os dedos, permitindo que a barra role para baixo as mãos, pegar a barra com a junta final nos dedos.","Agora enrole a barra o mais alto possível fechando as mãos enquanto expira."]],"Flat_Bench_Cable_Flyes":["Cabo de Bench Flat Flyes",["Posicione um banco plano entre duas roldanas baixas para que quando estiver deitado, seu peito esteja alinhado com as roldanas.","Deite-se no banco e mantenha os pés no chão.","Se alguém lhe der as alças de cada mão, você vai agarrar cada pega com as palmas para cima.","Estenda os braços ao seu lado com uma pequena curva nos cotovelos, mantenha esta curva constante durante todo o movimento, seus braços devem ser paralelos ao chão, esta é a sua posição inicial.","Agora comece a levantar os braços em um movimento semi-círculo diretamente na sua frente, puxando os cabos juntos até que ambas as mãos se encontrem no topo do movimento. Aperte seu peito enquanto você executa este movimento e expirar durante este movimento.","Lentamente volte para a posição inicial.","Repita para a quantidade recomendada de repetições."]],"Flat_Bench_Leg_Pull-In":["Perna de Bench Flat Pull-In",["Deite-se em um tapete de exercício ou um banco plano com as pernas fora da ponta.","Coloque as mãos sob os glúteos com as palmas para baixo ou pelos lados segurando o banco (ou com as palmas para baixo ao lado de um tapete de exercício).","Dobre os joelhos e puxe as coxas para o meio enquanto expira, continue o movimento até que seus joelhos estejam perto do peito, mantenha a posição contraída por um segundo.","Enquanto você respira, lentamente volte para a posição inicial.","Repita para a quantidade recomendada de repetições."]],"Flat_Bench_Lying_Leg_Raise":["Bench plano, perna deitada, levante.",["Deite-se com as costas planas em um banco e suas pernas estendidas na sua frente fora do final.","Coloque as mãos sob os glúteos com as palmas para baixo ou pelos lados segurando o banco.","Enquanto mantém as pernas estendidas, retas, com os joelhos ligeiramente dobrados, mas trancadas, levante as pernas até que façam um ângulo de 90 graus com o chão, expire enquanto executa esta parte do movimento e segure a contração na parte superior por um segundo.","Agora, enquanto inala, abaixe as pernas lentamente para a posição inicial."]],"Flexor_Incline_Dumbbell_Curls":["Flexor Incline halteres Curls",["Segure o haltere para o lado mais longe de você para que você tenha mais peso no lado mais próximo de você.","Sente-se em um banco inclinado que é angulado a 45 graus enquanto segura um haltere em cada mão.","Deixe seus braços pendurados em seus lados, com os cotovelos dentro, e vire as palmas das mãos para frente com os polegares apontando para longe do corpo.","Curve os dois halteres ao mesmo tempo até que seus bíceps estejam completamente contraídos e expirem.","Enquanto você inala, lentamente volte para a posição inicial.","Repita para a quantidade recomendada de repetições."]],"Floor_Glute-Ham_Raise":["Piso Glute-Ham levantar",["Você pode usar um parceiro para este exercício ou manter seus pés sob algo estável.","Comece de joelhos com as pernas e o torso ereto, se usar um parceiro, eles segurarão seus pés para mantê-lo em posição.","Abaixe-se estendendo-se no joelho, tomando cuidado para não flexionar os quadris enquanto avança.","Coloque as mãos na sua frente quando chegar ao chão, este movimento é muito difícil e você pode ser incapaz de fazê-lo sem ajuda, use seus braços para empurrar levemente do chão para ajudar seu retorno à posição inicial."]],"Floor_Press":["Floor Press",["Ajustar os ganchos para que estejam na altura apropriada para ralar a barra, começar a deitar no chão com a cabeça perto da ponta de um suporte de energia, manter suas omoplatas puxadas juntas, puxar a barra dos ganchos.","Abaixe a barra em direção ao fundo do peito ou estômago superior, apertando a barra e tentando desmontá-la enquanto faz isso, certifique-se de colocar os cotovelos durante todo o movimento, abaixe a barra até que seu braço entre em contato com o chão e pause, evitando qualquer batida ou saltitação do peso.","Aperte a barra o mais rápido que puder, mantendo a barra, seus pulsos e cotovelos na linha."]],"Floor_Press_with_Chains":["Floor Press com correntes",["Ajustar os ganchos para que estejam na altura apropriada para ralar a barra, para este exercício, colocar as correntes diretamente sobre a extremidade da barra, tentando manter as extremidades longe das placas.","Começar deitado no chão com a cabeça perto da ponta de um suporte de energia, mantendo suas omoplatas juntas, puxando a barra dos ganchos.","Abaixe a barra em direção ao fundo do peito ou estômago superior, apertando a barra e tentando desmontá-la enquanto faz isso, certifique-se de colocar os cotovelos durante todo o movimento, abaixe a barra até que seu braço entre em contato com o chão e pause, evitando qualquer batida ou saltitação do peso.","Aperte a barra o mais rápido que puder, mantendo a barra, seus pulsos e cotovelos na linha."]],"Foot-SMR":["Foot-SMR",["Este exercício estende a fáscia dos músculos nos pés, começa sentado com os sapatos removidos, usando um rolo de pé ou um objeto semelhante, como uma pequena seção de tubo de PVC, coloque seu pé contra o rolo através do arco do seu pé, esta será sua posição inicial.","Pressione firme, rolando pelo arco do seu pé, segure por 10-30 segundos, e depois troque de pé."]],"Forward_Drag_with_Press":["Arraste com a imprensa.",["Coloque uma corrente ou corda dupla no trenó, você deve estar de frente para longe do trenó, segurando uma alça em cada mão.","Comece o movimento avançando por um passo, inclinando-se para frente, estendendo-se através das pernas e quadris para se mover, pausando com cada passo para se estender através dos cotovelos, pressionando suas mãos para frente, até que você volte para a posição inicial preparada para pressionar."]],"Frankenstein_Squat":["Frankenstein Squat",["Essa broca te ensina o posicionamento adequado da barra e do seu corpo durante o agachamento limpo e frontal.","Coloque a barba na frente dos ombros, soltando seu aperto e estendendo seus braços para frente, os ombros devem ser empurrados para a frente para criar uma prateleira, e a barra deve estar em contato com a garganta, certifique-se de que você só mova suas omoplatas para frente, não rode a coluna torácica.","Mantenha o tronco ereto, os braços para cima, os ombros para frente, e a barra deve ficar no lugar, vá para o fundo do agachamento, até que seus isquiotibiais entrem em contato com seus bezerros.","Volte para a posição vertical dirigindo pela frente do calcanhar e estendendo os joelhos e quadris."]],"Freehand_Jump_Squat":["Pule à mão livre.",["Cruze os braços sobre o peito.","Com a cabeça para cima e as costas retas, posicione os pés na largura do ombro.","Mantendo as costas retas e o peito para cima, agache-se enquanto inala até que suas coxas sejam paralelas, ou inferiores, para o chão.","Agora pressionando principalmente com a bola de seus pés, pule para cima o mais alto possível, usando as coxas como molas, expire durante esta parte do movimento.","Quando tocar no chão de novo, agache-se imediatamente e pule novamente.","Repita para a quantidade recomendada de repetições."]],"Frog_Hops":["Frog Hops.",["Fique com as mãos atrás da cabeça, e agache-se mantendo o torso ereto e a cabeça erguida.","Salte para a frente vários pés, evitando saltar desnecessariamente alto, enquanto seus pés entram em contato com o chão, absorvem o impacto através de suas pernas e saltam novamente, repitam esta ação 5-10 vezes."]],"Frog_Sit-Ups":["Sapo Sit-Ups",["Deite-se com as costas planas no chão (ou tapete de exercício) e suas pernas estendidas na sua frente.","Agora, dobrem-se nos joelhos e coloquem suas coxas externas no chão (ou tapete) enquanto fazem as solas de seus pés se tocarem.","Agora tente empurrar ambas as solas e trazê-las o mais perto possível enquanto você mantém as coxas externas no chão (ou pelo menos quase tocando-a) Dica: Nessa posição suas pernas devem criar uma forma de diamante.","Agora, cruze os braços na sua frente tocando os ombros opostos.","Isso será como fazer o primeiro movimento de 1/4 de um assento para cima.","Enquanto você inala, lentamente volte para a posição inicial.","Repita para a quantidade recomendada de repetições."]],"Front_Barbell_Squat":["Agachamento de Barbell na frente",["Para começar, coloque a barra em um rack que melhor corresponda à sua altura, assim que a altura correta for escolhida e a barra estiver carregada, coloque seus braços sob a barra, mantendo os cotovelos altos e o braço acima um pouco acima paralelo ao chão, coloque a barra em cima dos deltoides e atravesse os braços enquanto segura a barra para o controle total.","Levante a barra da prateleira primeiro empurrando com as pernas e ao mesmo tempo endireitando o tronco.","Afaste-se do rack e posicione suas pernas usando uma posição média do ombro com os dedos dos pés ligeiramente apontados.","Comece a baixar lentamente a barra dobrando os joelhos enquanto mantém uma postura reta com a cabeça para cima. Continue até que o ângulo entre a perna superior e os bezerros se torne ligeiramente inferior a 90 graus (que é o ponto em que as pernas superiores estão abaixo paralelas ao chão). Inspire enquanto você executa esta parte do movimento. Dica: Se você realizou o exercício corretamente, a frente dos joelhos deve fazer uma linha reta imaginária com os dedos perpendiculares à frente. Se seus joelhos estão além dessa linha imaginária (se eles estão além dos dedos dos pés) então você está colocando estresse excessivo no joelho e o exercício foi realizado incorretamente.","Comece a levantar a barra enquanto expira, empurrando o chão principalmente com o meio do pé, enquanto endireita as pernas novamente e volta para a posição inicial.","Repita para a quantidade recomendada de repetições."]],"Front_Barbell_Squat_To_A_Bench":["O Barbell da frente Agacha-se a um banco",["Este exercício é melhor realizado dentro de um rack de agachamento para fins de segurança, para começar, coloque um banco plano atrás de você e coloque a barra em um rack que melhor corresponda à sua altura, uma vez que a altura correta é escolhida e a barra é carregada, coloque seus braços sob a barra, mantendo os cotovelos altos e o braço superior ligeiramente acima, paralelo ao chão, descanse a barra em cima dos deltóides e cruze seus braços enquanto agarra a barra para controle total.","Levante a barra da prateleira primeiro empurrando com as pernas e ao mesmo tempo endireitando o tronco.","Afaste-se do rack e posicione suas pernas usando uma posição média do ombro com os dedos dos pés ligeiramente apontados.","Se você fez o exercício corretamente, a frente dos joelhos deve fazer uma linha reta imaginária com os dedos perpendiculares à frente. Se seus joelhos estão além dessa linha imaginária (se eles estão além dos dedos dos pés) então você está colocando estresse excessivo no joelho e o exercício foi realizado incorretamente.","Começar a levantar a barra enquanto você expira empurrando o chão principalmente com o calcanhar de seu pé como você endireitar as pernas novamente e voltar para a posição inicial.","Repita para a quantidade recomendada de repetições."]],"Front_Box_Jump":["Salto da Caixa da Frente",["Comece com uma caixa com uma altura adequada de 1-2 pés na sua frente, fique com os pés afastados, esta será a sua posição inicial.","Faça um pequeno agachamento em preparação para pular, balançando seus braços atrás de você.","Rebound fora desta posição, estendendo-se através dos quadris, joelhos e tornozelos para saltar o mais alto possível.","Pouse na caixa com os joelhos dobrados, absorvendo o impacto através das pernas, você pode pular da caixa de volta ao chão, ou, de preferência, descer uma perna de cada vez."]],"Front_Cable_Raise":["O cabo dianteiro sobe.",["Selecione o peso em uma máquina de polia baixa e agarre o cabo de mão única que está preso à polia baixa com sua mão esquerda.","Vire-se para longe da polia e coloque o braço para baixo com o cabo de mão preso na frente das coxas com as palmas da mão viradas para as coxas.","Enquanto mantém o torso parado (sem balanço), levante o braço esquerdo para a frente com uma ligeira curva no cotovelo e as palmas da mão sempre se deparam para baixo. Continue a subir até que o braço esteja ligeiramente acima paralelo ao chão. Expire enquanto executa esta parte do movimento e pause por um segundo no topo.","Agora, enquanto você inala, abaixe o braço lentamente para a posição inicial.","Uma vez que todas as repetições recomendadas tenham sido realizadas para este braço, mude de braço e faça o exercício com o direito."]],"Front_Cone_Hops_or_hurdle_hops":["Hops Cone Frontais (ou hops de obstáculos)",["Montar uma fileira de cones ou outras pequenas barreiras, colocando-os a poucos metros de distância.","Esta será a sua posição inicial.","Comece pulando com os dois pés sobre o primeiro cone, balançando os dois braços enquanto você pula.","Absorva o impacto da aterrissagem dobrando os joelhos, recuperando-se do primeiro salto pulando sobre o próximo cone.","Continue até que tenha saltado sobre todos os cones."]],"Front_Dumbbell_Raise":["Levantar o Dumbblebell",["Escolha dois halteres e fique com um torso reto e os halteres na frente de suas coxas ao longo dos braços com as palmas da mão voltadas para suas coxas.","Enquanto mantém o tronco parado (sem balanço), levante o haltere esquerdo para a frente com uma ligeira curva no cotovelo e as palmas das mãos sempre viradas para baixo. Continue a subir até que o braço esteja ligeiramente acima do paralelo ao chão. Expire enquanto executa esta parte do movimento e pause por um segundo no topo. Inspire após a segunda pausa.","Agora abaixe o haltere lentamente para a posição inicial enquanto você levanta o haltere direito.","Continue alternando desta forma até que todas as repetições recomendadas tenham sido realizadas para cada braço."]],"Front_Incline_Dumbbell_Raise":["Incentivo à frente. Levantar halteres.",["Você pode mudar o ângulo para atingir o músculo um pouco diferente de cada vez.","Estenda os braços na sua frente e tenha as palmas viradas para baixo com os halteres levantados cerca de 1 polegada acima de suas coxas.","Devagar, levante os halteres para cima até que estejam ligeiramente acima dos ombros, mantendo os cotovelos fechados, aperte no topo por um segundo e certifique-se de expirar durante esta parte do movimento.","Abaixe os braços para a posição inicial enquanto inala.","Repita para a quantidade recomendada de repetições."]],"Front_Leg_Raises":["Perna dianteira sobe.",["Fique ao lado de uma cadeira ou outro suporte, segurando com uma mão.","Mexa a perna para frente, mantendo a perna reta, continue com um balanço para baixo, trazendo a perna para trás o quanto sua flexibilidade permitir, repita 5-10 vezes, e depois mude as pernas."]],"Front_Plate_Raise":["Prato da frente, levante.",["As palmas das mãos devem estar viradas umas para as outras e os braços devem ser estendidos e trancados com uma pequena curva nos cotovelos e a placa deve estar perto da cintura na sua frente o máximo que puder.","Levante a placa lentamente enquanto expira até que esteja um pouco acima do nível do ombro, segure a contração por um segundo, dica, certifique-se de não balançar o peso ou dobrar os cotovelos, seu tronco deve permanecer parado durante todo o movimento.","Enquanto você inala, lentamente abaixe a placa de volta para a posição inicial.","Repita para a quantidade recomendada de repetições."]],"Front_Raise_And_Pullover":["Levantem a frente e pullover.",["Deite-se em um banco plano enquanto segura uma campainha usando uma mão para baixo que está a 15 polegadas de distância.","Coloque a barra em suas coxas, estenda seus braços e tranque-os mantendo uma leve curva nos cotovelos.","Agora levante o peso usando um movimento semicircular e mantendo seus braços retos enquanto inala, continue o mesmo movimento até que a barra esteja do outro lado acima de sua cabeça.","Agora devolva a campainha para a posição inicial revertendo o movimento enquanto você expira.","Repita para a quantidade recomendada de repetições."]],"Front_Squat_Clean_Grip":["Agachamento frontal (Limpo)",["Para começar, coloque a barra em um rack um pouco abaixo do nível do ombro, coloque a barra em cima dos deltoides, empurrando para as clavículas, e levemente tocando a garganta, suas mãos devem estar em um aperto limpo, tocando a barra apenas com os dedos para ajudá-la a mantê-la em posição.","Levante a barra do rack primeiro empurrando com as pernas e, ao mesmo tempo, endireitando o torso, afaste-se do rack e posicione as pernas usando uma posição média do ombro com os dedos apontados ligeiramente, mantenha a cabeça e os cotovelos para cima o tempo todo, esta será a sua posição inicial.","Ajoelhe-se, sente-se entre as pernas, continue até que seus isquiotibiais estejam em seus bezerros, mantenha seus joelhos alinhados com seus pés, usando conscientemente seus abdutores para empurrar seus joelhos para fora enquanto se agacha.","Comece a levantar a barra enquanto expira, empurrando o chão principalmente com o calcanhar ou o meio do pé, enquanto endireita as pernas novamente e volta para a posição inicial."]],"Front_Squats_With_Two_Kettlebells":["Agachamentos frontais com duas campainhas",["Limpe duas campainhas nos ombros, limpe as chaleiras nos ombros, estendendo-se pelas pernas e quadris, enquanto puxa as chaleiras para os ombros, gira os pulsos enquanto faz isso.","Olhando para frente o tempo todo, agachando-se o mais baixo possível e pausando no fundo, enquanto se agacha, empurra os joelhos para fora, deve agachar-se entre as pernas, mantendo um tronco ereto, com a cabeça e o peito para cima.","Levante-se dirigindo pelos seus calcanhares e repita."]],"Front_Two-Dumbbell_Raise":["Frente Dois-halteres levantar",["Escolha dois halteres e fique com um torso reto e os halteres na frente de suas coxas ao longo dos braços com as palmas da mão voltadas para suas coxas.","Enquanto mantém o tronco parado (sem balanço), levante os halteres para a frente com uma ligeira curva no cotovelo e as palmas das mãos sempre viradas para baixo. Continue a subir até que os braços estejam ligeiramente acima paralelos ao chão. Expire enquanto executa esta parte do movimento e pause por um segundo no topo.","Enquanto você inala, abaixe os halteres lentamente para a posição inicial.","Repita para a quantidade recomendada de repetições."]],"Full_Range-Of-Motion_Lat_Pulldown":["\"Lát-Of-Motion Pulldown\"",["Em pé ou sentado em um banco alto, agarre dois cabos de estribo que estão presos às polias altas.","Mantendo o peito para cima e mantendo um pequeno arco em suas costas inferiores, puxe as alças para baixo como se estivesse fazendo um arrancamento regular."]],"Gironda_Sternum_Chins":["Gironda Sternum Chins",["Segure a barra de puxar para cima com uma largura de ombro por baixo da mão.","Agora pendure-se com os braços estendidos e estique o peito e incline-se para trás.","Comece a puxar-se para a barra com a espinha arqueada durante todo o movimento e sua cabeça inclinada para trás o mais longe possível da barra.","Continue puxando até que sua clavícula passe pela barra e seu peito inferior ou área do esterno toque-a.","Lentamente, volte para a posição inicial enquanto inala.","Repita para a quantidade recomendada de repetições."]],"Glute_Ham_Raise":["Glute Ham levantar",["Comece a ajustar o equipamento para caber seu corpo, coloque seus pés na placa entre os rolos enquanto você se deita de bruços, seus joelhos devem estar logo atrás da almofada.","Comece do fundo do movimento, mantenha suas costas arqueadas enquanto você começa o movimento, flexionando os joelhos, empurrando seus dedos para a placa do pé enquanto faz isso, mantenha seu corpo reto e continue até que seu corpo esteja ereto.","Volte para a posição inicial, mantendo sua descida sob controle."]],"Glute_Kickback":["Glute Kickback",["Ajoelhe-se no chão ou em uma esteira de exercício e dobre-se na cintura com os braços estendidos na sua frente (perpendicular para o tronco) para entrar em uma posição de flexão ajoelhada, mas com os braços espaçados na largura do ombro.","Ao expirar, levante sua perna direita até que os isquiotibiais estejam alinhados com a parte de trás, mantendo o ângulo de 90 graus, contraia os glúteos ao longo deste movimento e segure a contração no topo por um segundo.","Volte para a posição inicial enquanto inala e repita com a perna esquerda.","Continue a alternar as pernas até que todas as repetições recomendadas sejam realizadas."]],"Goblet_Squat":["Espremedor de taças",["Fique segurando uma campainha perto do peito, esta será sua posição inicial.","Agache-se entre as pernas até que seus isquiotibiais estejam em seus bezerros.","Na posição inferior, pause e use seus cotovelos para empurrar seus joelhos para fora."]],"Good_Morning_off_Pins":["Bom dia, Pins.",["Comece com uma barra em uma prateleira na mesma altura do seu estômago, dobre-se por baixo da barra e coloque a barra na parte de trás de seus ombros como se fosse um agachamento de poder, não em cima de seus ombros, na altura adequada, você deve estar próximo ao chão quando dobrado, mantenha as costas apertadas, as omoplatas juntas e os joelhos ligeiramente dobrados, mantenha as costas arqueadas e a coluna cervical em alinhamento adequado.","Comece o movimento estendendo-se através dos quadris com seus glúteos e isquiotibiais, e você está de pé com o peso."]],"Gorilla_Chin_Crunch":["Gorilla Chin/Crunch",["Pendure-se em uma barra de queixo-up usando um aperto de mão (palmas de frente para você) que é um pouco maior do que a largura do ombro.","Agora dobre os joelhos em um ângulo de 90 graus para que as panturrilhas sejam paralelas ao chão enquanto as coxas permanecem perpendiculares a ele.","Quando você expirar, levante-se enquanto aperta os joelhos ao mesmo tempo até que seus joelhos estejam ao nível do peito, você vai parar de subir assim que seu nariz estiver ao mesmo nível da barra.","Lentamente comece a inalar quando voltar à posição inicial.","Repita para a quantidade recomendada de repetições."]],"Groin_and_Back_Stretch":["Esticamento da virilha e das costas",["Sente-se no chão com os joelhos dobrados e os pés juntos.","Entrelace seus dedos atrás da cabeça.","Curvar para baixo, trazendo seus cotovelos para dentro de suas coxas, após uma breve pausa, volte para a posição inicial com a cabeça para cima e as costas retas, repita por 10-20 repetições."]],"Groiners":["Groiners.",["Comece em posição de flexão no chão, esta será sua posição inicial.","Usando as duas pernas, pule para a frente, com os pés ao lado das mãos, mantenha a cabeça erguida.","Volte para a posição inicial e repita imediatamente o movimento, continuando por 10-20 repetições."]],"Hack_Squat":["Hack Squat",["Coloque a parte de trás do torso contra a parte de trás da máquina e coloque seus ombros sob as ombreiras fornecidas.","Coloque as pernas na plataforma usando uma posição média do ombro com os dedos dos pés ligeiramente apontados.","Coloque seus braços nas alças laterais da máquina e desengace as barras de segurança (que na maioria dos projetos é feito movendo as alças laterais de uma posição frontal voltada para uma posição diagonal).","Esta será a sua posição inicial. (Nota: para os propósitos desta discussão usaremos a posição média descrita acima que visa o desenvolvimento geral, no entanto você pode escolher qualquer uma das três posições descritas na seção de posicionamento do pé).","Comece a baixar lentamente a unidade, dobrando os joelhos enquanto mantém uma postura reta com a cabeça para cima (de costas na almofada em todos os momentos). Continue a descer até que o ângulo entre a perna superior e os bezerros se torne ligeiramente inferior a 90 graus (que é o ponto em que as pernas superiores estão abaixo paralelas ao chão). Inspire enquanto você executa esta parte do movimento. Dica: Se você realizou o exercício corretamente, a frente dos joelhos deve fazer uma linha reta imaginária com os dedos perpendiculares à frente. Se os seus joelhos estão além dessa linha imaginária (se eles estão além dos dedos dos pés) então você está colocando estresse indevido no joelho e o exercício foi realizado incorretamente.","Comece a levantar a unidade enquanto expira, empurrando o chão com o calcanhar do pé, enquanto endireita as pernas novamente e volta para a posição inicial.","Repita para a quantidade recomendada de repetições."]],"Hammer_Grip_Incline_DB_Bench_Press":["Hammer Grip Incline DB Bench Press",["Deite-se em um banco inclinado com um haltere em cada mão em cima de suas coxas.","Usando suas coxas para ajudá-lo a levantar os halteres, limpar os halteres um braço de cada vez para que você possa segurá-los com a largura do ombro.","Uma vez na largura do ombro, mantenha as palmas das mãos com uma aderência neutra (palmas viradas uma para a outra), mantenha os cotovelos arregaçados com os braços em linha com os ombros (perpendiculares para o tronco) e os cotovelos dobrados criando um ângulo de 90 graus entre o braço e o antebraço.","Agora abaixe os pesos lentamente para o seu lado enquanto você respira, mantenha o controle total dos halteres o tempo todo.","Quando expirar, empurre os halteres usando seus músculos peitorais, tranque os braços na posição contraída, segure por um segundo e comece a descer lentamente.","Repita o movimento para a quantidade prescrita de repetições.","Quando terminar, coloque os halteres de volta nas coxas e no chão."]],"Hamstring-SMR":["Hamstring-SMR",["Em uma posição sentada, estenda as pernas sobre um rolo de espuma para que fique na parte de trás das pernas superiores, coloque as mãos para o lado ou para trás para ajudar a suportar seu peso, esta será sua posição inicial.","Usando suas mãos, levante seus quadris do chão e mude seu peso no rolo de espuma para uma perna.","Role a espuma de baixo do quadril para cima da parte de trás do joelho, parando em pontos de tensão por 10-30 segundos."]],"Hamstring_Stretch":["Esticamento de Hamstring",["Deite-se de costas com uma perna estendida acima de você, com o quadril a 90 graus.","Coloque um cinto, faixa ou corda sobre a bola do seu pé.","Puxe o cinto para criar tensão nos bezerros e isquiotibiais."]],"Handstand_Push-Ups":["\"Push-Ups\"",["Com as costas para a parede, dobre-se na cintura e coloque as duas mãos no chão com a largura do ombro.","Se fizer isso pela primeira vez, peça a um observador para ajudá-lo, e também, certifique-se de ficar de frente para a parede com a cabeça, em vez de olhar para baixo.","É de extrema importância que desça devagar para evitar ferimentos na cabeça.","Levante-se devagar enquanto expira até que seus cotovelos estejam quase fechados.","Repita para a quantidade recomendada de repetições."]],"Hang_Clean":["Pendure Limpo",["Comece com uma largura de ombro, duas mãos ou gancho, com a barra pendurada na posição média da coxa, e suas costas devem estar retas e inclinadas ligeiramente para frente.","Comece por se estender agressivamente pelos quadris, joelhos e tornozelos, levando o peso para cima, enquanto faz isso, encoste os ombros em direção às orelhas.","Recupere-se imediatamente dirigindo através dos saltos, mantendo o tronco ereto e cotovelos para cima."]],"Hang_Clean_-_Below_the_Knees":["Enforquem-se, debaixo dos joelhos.",["Comece com uma largura de ombro, duas mãos ou gancho, com a barra pendurada logo abaixo dos joelhos, suas costas devem estar retas e inclinadas ligeiramente para frente.","Começar por se estender agressivamente através dos quadris, joelhos e tornozelos, levando o peso para cima, enquanto você faz isso, encoste os ombros em direção às orelhas, à medida que a extensão total é alcançada, a transição para o terceiro puxar, encolhendo agressivamente e flexionando os braços com os cotovelos para cima e para fora.","Na extensão do pico, puxe-se agressivamente para baixo, girando seus cotovelos sob a barra enquanto você faz isso, receba a barra em uma posição de agachamento frontal, cuja profundidade é dependente da altura da barra no final da terceira puxada, a barra deve ser cracked sobre os ombros prolongados, levemente tocando a garganta com as mãos relaxadas, continue a descer para a posição de agachamento inferior, que ajudará na recuperação.","Recupere-se imediatamente dirigindo através dos saltos, mantendo o tronco ereto e cotovelos para cima."]],"Hang_Snatch":["Pendurar o Snatch",["Os pés devem estar diretamente abaixo dos quadris com os pés virados para fora, seus joelhos devem estar ligeiramente dobrados, e o torso inclinado para frente, a espinha deve ser totalmente estendida e a cabeça virada para frente, a barra deve estar nos quadris, esta será a sua posição inicial.","Agressivamente, estenda-se através das pernas e quadris, na extensão máxima, encoste os ombros e permita que os cotovelos se flexionem para o lado.","Enquanto você move seus pés para a posição de recepção, forçosamente puxe-se abaixo da barra enquanto você eleva a barra acima.","Retorne para uma posição de pé com o peso sobre a cabeça e retorne o peso ao chão sob controle."]],"Hang_Snatch_-_Below_Knees":["Pendurem-se abaixo dos joelhos",["Os pés devem estar diretamente abaixo dos quadris com os pés virados para fora, seus joelhos devem estar ligeiramente dobrados, e o torso inclinado para frente, a coluna vertebral deve ser totalmente estendida e a cabeça voltada para frente, a barra deve estar logo abaixo dos joelhos, esta será a sua posição inicial.","Agressivamente, estenda-se através das pernas e quadris, na extensão máxima, encoste os ombros e permita que os cotovelos se flexionem para o lado.","Enquanto você move seus pés para a posição de recepção, forçosamente puxe-se abaixo da barra enquanto você eleva a barra acima.","Volte para uma posição em pé com o peso acima, e então devolva o peso para o chão sob controle."]],"Hanging_Bar_Good_Morning":["Bom dia.",["Comece com uma barra em uma prateleira na mesma altura do seu estômago, suspenda a barra usando correntes ou tiras de suspensão.","Dobrar-se por baixo da barra e colocar a barra na parte de trás dos ombros como você faria um agachamento de poder, não em cima de suas armadilhas, na altura adequada, você deve estar próximo ao chão quando curvado, manter as costas apertadas, ombros apertados juntos, e seus joelhos ligeiramente dobrados, manter suas costas arqueadas e sua coluna cervical em alinhamento adequado.","Comece o movimento estendendo-se pelos quadris com seus glúteos e isquiotibiais, e você está de pé com o peso.","Reduza lentamente o peso de volta para a posição inicial, onde é suportado pelas correntes."]],"Hanging_Leg_Raise":["Levantem a perna.",["Pendure-se em uma barra com os dois braços estendidos em cima de você usando um aperto largo ou um aperto médio as pernas devem ser retas para baixo com a pélvis rolada ligeiramente para trás.","Levante as pernas até que o torso faça um ângulo de 90 graus com as pernas.","Volte devagar para a posição inicial enquanto respira.","Repita para a quantidade recomendada de repetições."]],"Hanging_Pike":["Pendurando Pike",["Pendure-se em uma barra com as pernas e os pés juntos usando um aperto overhand (palms de frente para longe de você) que é ligeiramente maior do que a largura do ombro.","Agora dobre seus joelhos em um ângulo de 90 graus e traga as pernas superiores para frente para que os bezerros sejam perpendiculares ao chão enquanto as coxas permanecem paralelas a ele.","Puxe as pernas para cima enquanto expira até quase tocar as canelas com a barra acima de você.","Abaixe as pernas o mais devagar possível até chegar à posição inicial.","Repita para a quantidade recomendada de repetições."]],"Heaving_Snatch_Balance":["Equilíbrio de golpes",["Esta broca ajuda a aprender o golpe, comece segurando um peso leve na parte de trás dos ombros, seus pés devem ser um pouco mais largos que a largura do quadril, com os pés virados para fora, a mesma posição com que você faria um agachamento.","Comece mergulhando levemente com os joelhos, e aparecendo de volta para descarregar brevemente a barra, e dirija-se para baixo da barra, elevando-a para cima enquanto desce para um agachamento completo.","Retorne a uma posição em pé."]],"Heavy_Bag_Thrust":["\"Trust de Saco Pesado\"",["Use uma bolsa pesada para este exercício, assuma uma postura ereta ao lado da bolsa, com os pés espalmados, bem afastados, coloque sua mão na bolsa em altura do peito, esta será sua posição inicial.","Comece torcendo a cintura, empurrando o saco o mais forte possível.","Receba a bolsa quando ela voltar revertendo estes passos."]],"High_Cable_Curls":["Curls de cabo alto",["Fique entre um par de polias altas e segure uma alça em cada braço, posicione seus braços de uma forma que eles sejam paralelos ao chão com as palmas de suas mãos voltadas para você, esta será sua posição inicial.","Curve as alças em sua direção até que estejam ao lado de suas orelhas, certifique-se de que, assim que fizer, flexione seus bíceps e expire, os braços devem permanecer parados e apenas os antebraços devem se mover, segure por um segundo na posição contraída enquanto aperta os bíceps.","Lentamente traga os braços de volta para a posição inicial.","Repita para a quantidade recomendada de repetições."]],"Hip_Circles_prone":["Círculos de Hip (prontidão)",["Coloque-se de joelhos no chão, mantendo uma boa postura, levante um joelho dobrado do chão, esta será sua posição inicial.","Mantendo o joelho dobrado, girando o fêmur em um arco, tentando fazer um grande círculo com o joelho.","Faça isso lentamente para várias repetições, e repita do outro lado."]],"Hip_Extension_with_Bands":["Hip Extension com Bandas",["Proteja uma extremidade da banda na parte inferior de um poste e prenda a outra em um tornozelo.","Enfrentando o ponto de ligação da banda, segure a coluna para se estabilizar.","Mantendo a cabeça e o peito para cima, mova a perna o mais que puder enquanto mantém o joelho reto.","Devolva a perna para a posição inicial."]],"Hip_Flexion_with_Band":["Hip Flexion com Banda",["Proteja uma extremidade da banda na parte inferior de um poste e prenda a outra em um tornozelo.","Afaste-se do ponto de ligação da banda.","Mantendo a cabeça e o peito para cima, levante o joelho até 90 graus e pause.","Devolva a perna para a posição inicial."]],"Hip_Lift_with_Band":["Hip Lift com banda",["Depois de escolher uma banda adequada, deite-se no meio do rack, depois de segurar a banda de ambos os lados.","Ajuste sua posição para que a banda esteja diretamente sobre seus quadris, dobre seus joelhos e coloque seus pés no chão, suas mãos podem estar no chão ou segurando a banda em posição.","Mantendo seus ombros no chão, dirigindo através de seus calcanhares para levantar os quadris, empurrando para a banda o mais alto que puder.","Pause no topo da moção, e volte para a posição inicial."]],"Hug_A_Ball":["Abrace uma bola.",["Sente-se no chão.","Endireite uma bola de exercício entre as duas pernas e abaixe seus quadris para baixo em direção ao chão.","Abrace os braços ao redor da bola para apoiar seu corpo, ajuste as pernas para que seus pés fiquem achatados no chão e seus joelhos se alinhem sobre seus tornozelos, mantenha uma boa aderência na bola para que ela não se afaste de você e te mande de volta para suas nádegas."]],"Hug_Knees_To_Chest":["Joelhos de abraço para o peito",["Deite-se de costas e puxe os joelhos até o peito.","Segure os braços sob os joelhos, não por cima (que colocaria muita pressão nas articulações do joelho).","Puxe lentamente os joelhos em direção aos ombros, isso também estica os músculos das nádegas."]],"Hurdle_Hops":["Hurdle Hop",["Montar uma fileira de obstáculos ou outras pequenas barreiras, colocando-os a poucos metros de distância.","Esta será a sua posição inicial.","Comece pulando com os dois pés sobre o primeiro obstáculo, balançando os dois braços enquanto você pula.","Absorva o impacto da aterrissagem dobrando os joelhos, recuperando-se do primeiro salto pulando sobre o próximo obstáculo."]],"Hyperextensions_Back_Extensions":["Hiperextensão (extensões)",["Deite-se de bruços em um banco de hiperextensão, colocando seus tornozelos bem debaixo dos pés.","Ajuste a almofada superior, se possível, para que suas coxas fiquem planas na almofada larga, deixando espaço suficiente para você dobrar na cintura sem qualquer restrição.","Com seu corpo reto, cruze seus braços na sua frente ou atrás de sua cabeça, esta será sua posição inicial, também pode segurar uma placa de peso para resistência extra na sua frente sob seus braços cruzados.","Inspire enquanto faz esse movimento, continue se movendo para frente até sentir um bom estiramento nos isquiotibiais e não pode mais continuar sem um arredondamento nas costas.","Evitar a tentação de arquear as costas depois de uma linha reta, e também não balançar o tronco a qualquer momento para proteger as costas de ferimentos.","Repita para a quantidade recomendada de repetições."]],"Hyperextensions_With_No_Hyperextension_Bench":["Hiperextensão Sem Banco de Hiperextensão",["Com alguém segurando suas pernas, deslize até a borda um banco plano até que seus quadris pendurem na extremidade do banco.","Com seu corpo reto, cruze seus braços na sua frente ou atrás de sua cabeça, esta será sua posição inicial, também pode segurar uma placa de peso para resistência extra na sua frente sob seus braços cruzados.","Comece a curvar-se para a frente o mais longe que puder enquanto mantém as costas planas, inspire enquanto faz esse movimento, continue se movendo para frente até quase tocar o chão ou sentir um bom estiramento nos isquiotibiais.","Evitar a tentação de arquear as costas depois de uma linha reta, e também não balançar o tronco a qualquer momento para proteger as costas de lesões.","Repita para a quantidade recomendada de repetições."]],"IT_Band_and_Glute_Stretch":["Banda de TI e Esticamento de Glute",["Aperte um cinto, corda ou faixa ao redor de um de seus pés, e balance a perna através do seu corpo para o lado oposto, mantendo a perna estendida enquanto você se deita no chão.","Mantenha o pé fora do chão, puxe o cinto, usando a tensão para puxar os dedos dos pés."]],"Iliotibial_Tract-SMR":["Trato Iliotibial-SMR",["Deite-se de lado, com a perna de baixo colocada em um rolo de espuma entre o quadril e o joelho, a outra perna pode ser cruzada na sua frente.","Coloque tanto seu peso quanto é tolerável em sua perna inferior, não há necessidade de manter sua perna inferior em contato com o chão.","Role a perna sobre a espuma do quadril até o joelho, parando por 10-30 segundos em pontos de tensão."]],"Inchworm":["Lombriga.",["Mantenha as pernas retas, estique-se e coloque as mãos no chão diretamente na sua frente.","Comece andando lentamente para frente, alternando sua esquerda e sua direita... enquanto faz isso, dobre apenas no quadril, mantendo suas pernas retas.","Continue até que seu corpo esteja paralelo ao chão em posição de flexão.","Agora, mantenha as mãos no lugar e lentamente dê passos curtos com os pés, movendo-se apenas alguns centímetros de cada vez.","Continue andando até que seus pés estejam por horas, mantendo suas pernas retas como você faz."]],"Incline_Barbell_Triceps_Extension":["Incline a extensão do tríceps da Barbell.",["Segure uma campainha com um aperto de mão que é um pouco mais perto do que a largura do ombro.","Deite-se em um banco inclinado definido em qualquer ângulo entre 45-75 graus.","Traga a barra para cima com os braços estendidos e os cotovelos para dentro, os braços devem estar alinhados com o tronco acima da cabeça, esta será sua posição inicial.","Agora abaixe a barra em um movimento semicircular atrás da cabeça até que seus antebraços toquem seus bíceps.","Volte para a posição inicial enquanto expira e contrai o tríceps.","Repita para a quantidade recomendada de repetições."]],"Incline_Bench_Pull":["Incline Bench Pull",["Pegue um haltere em cada mão e deite-se de cara para baixo em um banco inclinado que é ajustado para uma inclinação que é de aproximadamente 30 graus.","Deixe que os braços pendurem em seus lados completamente estendidos quando apontarem para o chão.","Vire os pulsos até que suas mãos tenham um aperto pronunciado.","Agora abra os cotovelos, esta será sua posição inicial.","Enquanto você expira, comece a puxar os halteres para cima como se estivesse fazendo um supino reverso. Você vai fazer isso dobrando os cotovelos e trazendo os braços para cima enquanto você deixa os antebraços para cima. Continue este movimento até que os braços superiores estejam no mesmo nível que suas costas. Dica: os cotovelos sairão para o lado e seus braços e troncos devem fazer a letra \"T\" no topo do movimento. Mantenha a contração no topo por um segundo.","Devagar, volte para a posição inicial enquanto respira.","Repita para a quantidade recomendada de repetições."]],"Incline_Cable_Chest_Press":["Pressiona o tórax do cabo em inclinação.",["Ajuste o peso para uma quantidade adequada e sente-se, agarrando as alças, seus braços devem estar a 45 graus no corpo, com sua cabeça e peito para cima, os cotovelos devem ser dobrados para cerca de 90 graus, esta será a sua posição inicial.","Comece se estendendo pelo cotovelo, pressionando as alças bem na sua frente, e mantenha suas omoplatas retraídas enquanto executa o movimento.","Depois de pausar na extensão total, volte para a posição inicial, mantendo tensão nos cabos."]],"Incline_Cable_Flye":["Incline Cabo Flye",["Para entrar na posição inicial, defina as polias no nível do chão (o nível mais baixo possível na máquina que está abaixo do seu torso).","Coloque um banco inclinado (estabelecida a 45 graus) entre as polias, selecione um peso em cada um e pegue uma polia em cada mão.","Com um punho em cada mão, deite-se no banco inclino e junte suas mãos ao longo dos braços na frente do seu rosto.","Com uma pequena curva de seus cotovelos (para evitar estresse no tendão do bíceps), abaixe os braços em ambos os lados em um arco largo até sentir um estiramento no peito.","Retorne os braços à posição inicial enquanto aperta os músculos do peito e expira, mantenha a posição contraída por um segundo.","Repita o movimento para a quantidade prescrita de repetições."]],"Incline_Dumbbell_Bench_With_Palms_Facing_In":["Incline halteres Bench com palmas encarando",["Deite-se em um banco inclinado com um haltere em cada mão em cima de suas coxas.","Usando suas coxas para ajudá-lo a levantar os halteres, limpar os halteres um braço de cada vez para que você possa segurá-los com a largura do ombro.","Uma vez na largura do ombro, mantenha as palmas das mãos com uma aderência neutra (palmas viradas uma para a outra), mantenha os cotovelos arregaçados com os braços em linha com os ombros (perpendiculares para o tronco) e os cotovelos dobrados criando um ângulo de 90 graus entre o braço e o antebraço.","Agora abaixe os pesos lentamente para o seu lado enquanto você respira, mantenha o controle total dos halteres o tempo todo.","Quando expirar, empurre os halteres usando seus músculos peitorais, tranque os braços na posição contraída, segure por um segundo e comece a descer lentamente.","Repita o movimento para a quantidade prescrita de repetições.","Quando terminar, coloque os halteres de volta nas coxas e no chão."]],"Incline_Dumbbell_Curl":["Incline halteres Curl",["Sente-se em um banco inclinado com um haltere em cada mão segurada com os braços abertos, mantenha os cotovelos perto do tronco e gire as palmas das mãos até que estejam voltadas para frente, esta será sua posição inicial.","Enquanto segura o braço parado, enrole os pesos enquanto contrai os bíceps enquanto expira, apenas os antebraços devem se mover, continue o movimento até que seus bíceps estejam totalmente contraídos e os halteres estejam no nível do ombro, mantenha a posição contraída por um segundo.","Lentamente começar a trazer os halteres de volta à posição inicial enquanto você respira.","Repita para a quantidade recomendada de repetições."]],"Incline_Dumbbell_Flyes":["Incline halteres Flyes",["Segure um haltere em cada mão e deite-se em um banco inclinado que é definido para um ângulo inclinado de não mais de 30 graus.","Estenda os braços acima de você com uma pequena curva nos cotovelos.","Agora gire os pulsos para que as palmas de suas mãos estejam voltadas para você.","Enquanto você respira, comece a abaixar lentamente os braços para o lado mantendo os braços estendidos e enquanto gira os pulsos até que as palmas da mão estejam voltadas uma para a outra.","Quando você expirar, comece a trazer os halteres de volta para a posição inicial revertendo o movimento e girando as mãos para que os dedos mindinhos estejam próximos um do outro novamente.","Repita para a quantidade recomendada de repetições."]],"Incline_Dumbbell_Flyes_-_With_A_Twist":["Incline Dumbell Flyes com uma reviravolta.",["Segure um haltere em cada mão e deite-se em um banco inclinado que é definido para um ângulo inclinado de não mais de 30 graus.","Estenda os braços acima de você com uma pequena curva nos cotovelos.","Agora gire os pulsos para que as palmas de suas mãos estejam voltadas para você.","Enquanto você respira, comece a abaixar lentamente os braços para o lado mantendo os braços estendidos e enquanto gira os pulsos até que as palmas da mão estejam voltadas uma para a outra.","Quando você expirar, comece a trazer os halteres de volta para a posição inicial revertendo o movimento e girando as mãos para que os dedos mindinhos estejam próximos um do outro novamente.","Repita para a quantidade recomendada de repetições."]],"Incline_Dumbbell_Press":["Incline halteres Press",["Deite-se em um banco inclinado com um haltere em cada mão em suas coxas, as palmas de suas mãos estarão viradas uma para a outra.","Então, usando suas coxas para ajudar a empurrar os halteres para cima, levante os halteres um de cada vez para que você possa segurá-los na largura do ombro.","Uma vez que você tenha os halteres levantados para a largura do ombro, gire seus pulsos para frente para que as palmas das mãos estejam viradas para longe de você.","Mantenha o controle total dos halteres o tempo todo, então expire e empurre os halteres com o peito.","Bloqueie os braços no topo, segure por um segundo e comece a baixar lentamente o peso.","Repita o movimento para a quantidade prescrita de repetições.","Quando terminar, coloque os halteres de volta nas coxas e no chão."]],"Incline_Hammer_Curls":["Incline Hammer Curls",["Sente-se em um banco inclinado com um haltere em cada mão, você deve pressionar firmemente contra ele de volta com seus pés juntos, deixe os halteres pendurarem-se ao seu lado, segurando-os com um aperto neutro, esta será a sua posição inicial.","Iniciar o movimento flexionando o cotovelo, tentando manter o braço parado.","Continue até o topo do movimento e pause, então lentamente volte para a posição inicial."]],"Incline_Inner_Biceps_Curl":["Incline o Curl Bíceps Interior",["Segure um haltere em cada mão e deite-se em um banco inclinado.","Os halteres devem estar no braço pendurados ao seu lado e suas palmas devem estar viradas para fora.","Agora, enquanto você expira, enrole o peso para fora e para cima, mantendo seus antebraços em linha com seus deltoides laterais, continue o enrolo até que os halteres estejam na altura do ombro e para os lados de seus deltóides.","Após uma segunda contração no topo do movimento, começar a inalar e lentamente baixar os pesos de volta para a posição inicial usando o mesmo caminho usado para trazê-los para cima.","Repita para a quantidade recomendada de repetições."]],"Incline_Push-Up":["Incline o empurrão-up",["Coloque as mãos na borda do banco ou da plataforma, ligeiramente mais larga do que a largura do ombro.","Os braços devem ser perpendiculares ao corpo, mantendo o corpo reto, inferior ao peito da caixa ou plataforma, dobrando os braços.","Empurre o corpo até os braços se estenderem."]],"Incline_Push-Up_Close-Grip":["Incline a força de perto.",["Fique de frente para uma barra de máquinas Smith ou plataforma robusta elevada em uma altura apropriada.","Coloquem as mãos um ao lado do outro no bar.","Posicione seus pés para trás da barra com braços e corpo retos.","Mantendo seu corpo reto, abaixe seu peito até a barra dobrando os braços.","Volte para a posição inicial estendendo os cotovelos, pressionando-se de volta."]],"Incline_Push-Up_Depth_Jump":["Incline o salto de profundidade.",["Para esta broca você precisará de uma caixa de cerca de 12 polegadas de altura, e duas esteiras grossas ou passos de aeróbica.","Coloque os passos do lado de fora dos ombros, e coloque os pés em cima da caixa para que você esteja em uma posição de flexão inclinada, suas mãos dentro dos degraus, esta será sua posição inicial.","Comece dobrando os cotovelos para baixar o corpo, rapidamente invertendo a posição para empurrar o corpo para fora do chão, enquanto você sai do chão, mova as mãos para os degraus, dobrando os cotovelos para absorver o impacto.","Repita a moção para voltar à posição inicial."]],"Incline_Push-Up_Medium":["Incline o meio de elevação.",["Fique de frente para uma barra de máquinas Smith ou plataforma robusta elevada em uma altura apropriada.","Coloque as mãos na barra, com as mãos sobre a largura do ombro.","Posicione seus pés para trás da barra com braços e corpo retos.","Mantendo seu corpo reto, abaixe seu peito até a barra dobrando os braços.","Volte para a posição inicial estendendo os cotovelos, pressionando-se de volta."]],"Incline_Push-Up_Reverse_Grip":["Incline o aperto reverso.",["Fique de frente para uma barra de máquinas Smith ou plataforma robusta elevada em uma altura apropriada.","Coloque as mãos na barra palmas para cima, com as mãos sobre a largura do ombro.","Posicione seus pés para trás da barra com braços e corpo retos.","Mantendo seu corpo reto, abaixe seu peito até a barra dobrando os braços.","Volte para a posição inicial estendendo os cotovelos, pressionando-se de volta."]],"Incline_Push-Up_Wide":["Incline a força larga.",["Fique de frente para uma barra de máquinas Smith ou plataforma robusta elevada em uma altura apropriada.","Coloque as mãos na barra, com as mãos mais largas que a largura do ombro.","Posicione os pés para trás da barra com braços e corpo retos, seus braços devem ser perpendiculares ao corpo, esta será sua posição inicial.","Mantendo seu corpo reto, abaixe seu peito até a barra dobrando os braços.","Volte para a posição inicial estendendo os cotovelos, pressionando-se de volta."]],"Intermediate_Groin_Stretch":["Esticamento Intermediário da virilha",["Deite-se de costas com as pernas estendidas, coloque um cinto, uma corda ou uma faixa ao redor de um dos pés, e balance a perna o mais longe possível.","Puxe suavemente o cinto para criar tensão nos músculos da virilha e isquiotibial."]],"Intermediate_Hip_Flexor_and_Quad_Stretch":["Intermediário Hip Flexor e Quad Stretch",["Deite-se de cara no chão, com uma corda, um cinto ou uma faixa enrolada em torno de um pé.","Flexione o joelho e estenda o quadril da perna para ser esticado, usando as duas mãos para puxar o cinto, seu joelho e seu quadril devem sair do chão, criando tensão nos flexores e quadríceps do quadril, segure o estiramento por 10-20 segundos e repita na outra perna."]],"Internal_Rotation_with_Band":["Rotação Interna com Banda",["A banda deve estar na mesma altura do seu cotovelo, fique do lado direito da banda a alguns metros de distância.","Segure o fim da banda com a mão direita, e mantenha o cotovelo pressionado firmemente para o lado.","Com seu braço em posição, seu cotovelo deve ser flexionado a 90 graus com sua mão se afastando do torso.","Execute o movimento girando seu braço em movimento frontal, mantendo seu cotovelo no lugar.","Continue o máximo que puder, pause e depois volte para a posição inicial."]],"Inverted_Row":["Fila Invertida",["Posicione uma barra em um rack até a altura da cintura, você também pode usar uma máquina de ferreiro.","Pegue uma largura maior que o ombro, segure a barra e coloque-se debaixo da barra, seu corpo deve estar reto com os calcanhares no chão com os braços estendidos, esta será a sua posição inicial.","Comece flexionando o cotovelo, puxando o peito para a barra, retraindo as omoplatas enquanto faz o movimento.","Pause no topo da moção, e volte para a posição inicial.","Repita para o número desejado de repetições."]],"Inverted_Row_with_Straps":["Fila Invertida com alças",["Pendure uma corda ou suspense amarras de um rack ou outro objeto estável, segure as extremidades e posicione-se em uma posição supina pendurada nas cordas, seu corpo deve ser reto com os calcanhares no chão com os braços estendidos, esta será a sua posição inicial.","Comece flexionando o cotovelo, puxando o peito para as mãos, retraindo as omoplatas enquanto faz o movimento.","Pause no topo da moção, e volte para a posição inicial.","Repita para o número desejado de repetições."]],"Iron_Crosses_stretch":["Cruzes de Ferro",["Deite-se de cara no chão, com os braços estendidos para o lado, mãos pressionadas para o chão.","Para começar, flexione um joelho e traga essa perna através da parte de trás do seu corpo, tentando tocá-la no chão perto da mão oposta.","Retorne rapidamente a perna para a posição inicial, e repita rapidamente com a outra perna."]],"Isometric_Chest_Squeezes":["Squeezes de peito isométrico",["As mãos devem estar abertas com as palmas juntas e os dedos voltados para a frente (perpendicular para o tronco).","Empurrem as duas mãos uma contra a outra enquanto contraem o peito, comecem com tensão lenta e aumentem lentamente, continuem respirando normalmente enquanto executam essa contração.","Espere pelo número de segundos recomendado.","Agora solte a tensão lentamente.","Descanse pelo tempo recomendado e repita."]],"Isometric_Neck_Exercise_-_Front_And_Back":["Exercício Isométrico do Pescoço - Frente e costas",["Com a cabeça e o pescoço em posição neutra (posição normal com a cabeça ereta voltada para frente), coloque as duas mãos no lado da frente da cabeça.","Agora, levemente empurre para frente enquanto contrai os músculos do pescoço, mas resistindo a qualquer movimento da cabeça, comece com tensão lenta e aumente lentamente, continue respirando normalmente enquanto executa esta contração.","Espere pelo número de segundos recomendado.","Agora solte a tensão lentamente.","Descanse pelo tempo recomendado e repita com as mãos colocadas no lado de trás da cabeça."]],"Isometric_Neck_Exercise_-_Sides":["Exercício isométrico do pescoço - Lados",["Com a cabeça e o pescoço em posição neutra (posição normal com a cabeça ereta voltada para frente), coloque a mão esquerda no lado esquerdo da cabeça.","Agora empurre suavemente para a esquerda enquanto contrai os músculos do pescoço esquerdo, mas resistindo a qualquer movimento da cabeça, comece com tensão lenta e aumente lentamente, continue respirando normalmente enquanto executa esta contração.","Espere pelo número de segundos recomendado.","Agora solte a tensão lentamente.","Descanse pelo tempo recomendado e repita com a mão direita colocada no lado direito da cabeça."]],"Jackknife_Sit-Up":["Jackknife Sit-up",["Deite-se no chão (ou tapete de exercício) de costas com os braços estendidos para trás atrás da cabeça e as pernas estendidas também.","Ao expirar, dobre-se na cintura ao mesmo tempo que levanta as pernas e braços para se encontrar em uma posição de canivete.","Enquanto inala, abaixe os braços e as pernas para a posição inicial.","Repita para a quantidade recomendada de repetições."]],"Janda_Sit-Up":["Janda Sit-Up",["Posicione seu corpo no chão na posição básica, joelhos a um ângulo de 90o com os pés esticados no chão e braços cruzados sobre o peito ou para os lados.","Como você aperta fortemente seus glúteos e isquiotibiais, encher seus pulmões com ar e em uma lenta (três a seis segundos de contagem) subida, lentamente expirar. Dica: É importante apertar os glúteos e isquiotibiais, pois isso fará com que os flexores do quadril sejam inativados em um processo chamado inibição recíproca, o que basicamente significa que músculos opostos aos contraídos irão relaxar.","Enquanto você inala, lentamente volte de forma controlada para a posição inicial.","Repita para a quantidade recomendada de repetições."]],"Jefferson_Squats":["Jefferson Squats",["Coloque uma campainha no chão.","Fique no meio da barra de comprimento sábio.","Dobrando os joelhos e mantendo as costas retas e segurando a frente da barra com a mão direita.","Segure a parte traseira da barra com a mão esquerda. A palma da sua mão deve estar em alinhamento de aderência neutra (palmas voltados para o lado direito). Dica: Certifique-se de que seu aperto está mesmo na barra. Seu tronco deve ser posicionado bem no meio da barra e a distância entre seu tronco e sua mão direita (que deve ser na frente) deve ser a mesma que a distância entre seu tronco e sua mão esquerda (que deve ser para as costas).","Seus pés devem ter largura de ombro e seus dedos apontados.","Mantenha as costas o mais vertical possível com o chão e a cabeça para cima e lembre-se de não deixar os joelhos passarem pelos dedos dos pés.","Agora dirija-se de volta para a posição inicial empurrando com os pés Dica: mantenha a barra pendurada no comprimento do braço e seus cotovelos travados com uma leve curva."]],"Jerk_Balance":["Equilíbrio idiota.",["Essa broca ajuda você a aprender a se abaixar o suficiente durante o empurrão e corrige aqueles que se movem para trás durante o movimento.","Iniciar o movimento como você faria um idiota normal, mergulhando nos joelhos enquanto mantém seu tronco vertical, e dirigindo de volta com força, usando impulso e não seus braços para elevar o peso.","Mantenha o pé de trás no lugar, usando-o para levar seu corpo para a frente em uma divisão completa enquanto você bate o peso."]],"Jerk_Dip_Squat":["\"Agacha-te, idiota\"",["Este movimento fortalece a parte de mergulho do idiota, começa com a barra racked na posição de empurrão, com os ombros para a frente para criar uma prateleira e a barra levemente em contato com a garganta, os pés devem estar diretamente sob os quadris, com os pés virados para fora como é confortável.","Mantendo o tronco vertical, mergulhando flexionando os joelhos, permitindo que eles viajem para frente e sem mover os quadris para trás."]],"Jogging_Treadmill":["Correndo, Treadmill",["Para começar, pise na esteira e selecione a opção desejada no menu, a maioria das esteiras tem uma configuração manual, ou você pode selecionar um programa para executar, normalmente, você pode entrar em sua idade e peso para estimar a quantidade de calorias queimadas durante o exercício, a elevação pode ser ajustada para alterar a intensidade do treino.","As esteiras oferecem conveniência, benefícios cardiovasculares, e geralmente têm menos impacto do que correr lá fora, uma pessoa de 150 quilos queimará quase 250 calorias correndo por 30 minutos, em comparação com mais de 450 calorias correndo, mantendo a postura adequada enquanto você corre, e só manterá as alças quando necessário, como quando desmontar ou verificar sua frequência cardíaca."]],"Keg_Load":["Keg Load",["Para carregar barris, coloque o número desejado a uma distância da plataforma de carga, tipicamente 30-50 pés.","Comece agarrando a alça do primeiro barril, inclinando-o para o lado para agarrar a borda oposta do fundo do barril.","Quanto mais alto você puder colocar o barril, mais rápido você deve ser capaz de mover para a plataforma.","Volte para a posição inicial para recuperar o próximo barril, e repita até que o evento esteja concluído."]],"Kettlebell_Arnold_Press":["Kettlebell Arnold Press",["Limpe uma chaleira no ombro, limpe a chaleira no ombro, estendendo-se pelas pernas e quadris enquanto levanta a chaleira para o ombro, e a palma da mão deve estar voltada para dentro.","Olhando para frente, pressione a campainha para fora e para cima, girando seu pulso de modo que sua palma da mão olhe para frente no topo do movimento.","Devolva a campainha para a posição inicial, com a palma da mão virada para dentro."]],"Kettlebell_Dead_Clean":["Kettlebell está limpo.",["Coloque a chaleira entre os pés, para entrar na posição inicial, empurre seu traseiro para trás e olhe para frente.","Limpe a chaleira para o ombro, limpe a chaleira para os ombros estendendo-se pelas pernas e quadris enquanto levanta a chaleira para o ombro, o pulso deve girar enquanto faz isso.","Abaixe a chaleira, mantendo os isquiotibiais carregados mantendo suas costas retas e sua bunda para fora."]],"Kettlebell_Figure_8":["Kettlebell Figura 8",["Coloque uma campainha entre as pernas e tome uma posição mais larga que a largura do ombro, dobre-se empurrando sua bunda para fora e mantendo suas costas planas.","Pegue uma campainha e passe-a para a outra mão entre as pernas, a mão receptora deve chegar por trás das pernas, vá e volte para várias repetições."]],"Kettlebell_Halo":["Kettlebell Halo",["Segure uma campainha de cabeça para baixo pelos chifres, com o sino acima das mãos e perto do peito, segure seus abdominais e aperte seus glúteos para que sua caixa torácica fique para baixo.","Mantendo seus cotovelos perto da cabeça, mova a chaleira para cima depois de uma orelha e em torno atrás de sua cabeça.","Continue o círculo depois da orelha oposta e volte para a posição inicial na frente do seu peito, deixando o sino passar perto do seu corpo.","Complete o número de círculos prescritos em uma direção, então repita o mesmo número na direção oposta.","Mexa-se devagar e mantenha a cabeça, os quadris e as costas paradas, se seus arcos inferiores ou o sino se afastarem da cabeça, use um peso mais leve."]],"Kettlebell_Halo_With_Overhead_Extension":["Kettlebell Halo com extensão Overhead",["Segure uma campainha de cabeça para baixo pelos chifres, com o sino acima das mãos e perto do peito, segure seus abdominais e aperte seus glúteos para que sua caixa torácica fique para baixo.","Mantendo seus cotovelos perto da cabeça, mova o sino para cima depois de uma orelha e em volta até que ele fique atrás da sua cabeça.","A partir desta posição, estenda os cotovelos para pressionar a campainha até que seus braços estejam retos, mantendo seus braços ao lado da cabeça.","Dobre os cotovelos para baixar a chaleira de volta para a posição de pausa atrás da cabeça, sob controle.","Continue o círculo depois da orelha oposta e volte para a posição inicial na frente do seu peito para completar uma repetição.","Alterne a direção do círculo em cada repetição, mantenha a cabeça, os quadris e as costas para baixo ainda por toda parte, se seus arcos inferiores ou você não pode alcançar a posição superior sem se inclinar para trás, use um peso mais leve ou realize a auréola e a extensão como exercícios separados."]],"Kettlebell_Hang_Clean":["Kettlebell Hang Clean",["Coloque a chaleira entre os pés, para entrar na posição inicial, empurre seu traseiro para trás e olhe para frente.","Limpe a chaleira para o ombro, limpe a chaleira para os ombros estendendo-se pelas pernas e quadris enquanto levanta a chaleira para o ombro, o pulso deve girar enquanto faz isso.","Abaixe a chaleira para uma posição entre as pernas mantendo os isquiotibiais carregados."]],"Kettlebell_Overhead_Triceps_Extension":["Kettlebell Overhead Triceps Extension",["Mantenha os pés afastados, segurando uma campainha pelos chifres com as duas mãos, pressione-a até que seus braços se estendam, com a campainha pendurada atrás das mãos.","Segure seus abdominais e mantenha seus braços verticais e perto da cabeça.","Dobre os cotovelos para abaixar a chaleira atrás da cabeça, indo tão longe quanto a mobilidade do ombro permite sem seus cotovelos ardendo para fora.","Estenda os cotovelos para pressionar a chaleira de volta para a posição inicial, mantendo seus braços parados.","Mantenha suas costelas para baixo e evite arquear suas costas enquanto se estende."]],"Kettlebell_Pass_Between_The_Legs":["Passo Kettlebell Entre as Pernas",["Coloque uma campainha entre as pernas e tome uma postura confortável, dobre-se empurrando seu traseiro para fora e mantendo suas costas planas.","Pegue uma chaleira e passe-a para a outra mão entre as pernas, da forma de um \"W\"."]],"Kettlebell_Pirate_Ships":["Navios Piratas Kettlebell",["Com uma postura ampla, segure uma campainha com as duas mãos, deixe-a pendurada no nível da cintura com os braços estendidos, esta será a sua posição inicial.","Iniciar o movimento girando para um lado, balançando a campainha para a altura da cabeça.","Permita que o sino caia enquanto você gira para o lado oposto, novamente elevando a chaleira para a altura da cabeça.","Repita para a quantidade desejada de repetições."]],"Kettlebell_Pistol_Squat":["Kettlebell Pistol Squat",["Pegue uma chaleira com as duas mãos e segure-a pelos chifres, segure uma perna do chão e agache-se na outra.","Agache-se flexionando o joelho e sentando-se com os quadris, segurando a campainha na sua frente.","Mantenha a posição inferior por um segundo e depois reverta o movimento, dirigindo através do calcanhar e mantendo sua cabeça e peito para cima.","Abaixe-se novamente e repita."]],"Kettlebell_Seated_Press":["Kettlebell Seatted Press",["Sente-se no chão e abra as pernas confortavelmente.","Limpe uma campainha no seu ombro.","Aperte a campainha até que esteja trancada."]],"Kettlebell_Seesaw_Press":["Kettlebell Seesaw Press",["Limpe duas campainhas dois seus ombros.","Aperte uma campainha.","Abaixe a chaleira e pressione imediatamente a outra chaleira."]],"Kettlebell_Sumo_High_Pull":["\"Kettlebell Sumo High Pull\"",["Coloque uma campainha no chão entre os pés, posicione os pés em uma posição larga e segure a chaleira com as duas mãos, coloque os quadris para trás o máximo possível, com os joelhos dobrados, mantenha o peito e a cabeça para cima, esta será a sua posição inicial.","Comece estendendo os quadris e joelhos, puxando simultaneamente a chaleira para os ombros, levantando os cotovelos enquanto faz isso."]],"Kettlebell_Thruster":["Kettlebell Thruster",["Limpe duas campainhas nos seus ombros, limpe as campainhas nos seus ombros, estendendo-se pelas pernas e quadris, enquanto puxa as campainhas para os ombros, gira os pulsos como faz, esta será a sua posição inicial.","Comecem a agachar-se, flexionando seus quadris e joelhos, baixando seus quadris entre as pernas, mantendo-se eretos, retos para trás, o mais baixo possível.","Na parte inferior, inverta a direção e agache-se estendendo os joelhos e quadris, dirigindo através dos seus calcanhares, enquanto você faz isso, pressione ambas as campainhas acima, estendendo os braços para cima, usando o impulso do agachamento para ajudar a dirigir os pesos para cima.","Quando começar a próxima repetição, devolva os pesos aos ombros."]],"Kettlebell_Turkish_Get-Up_Lunge_style":["Kettlebell Turkish Get-Up (estilo de contração)",["Deite-se de costas no chão e pressione uma campainha para a posição de cima, estendendo o cotovelo.","Mantendo a chaleira fechada o tempo todo, pisque-se para o lado oposto e use seu braço não-funcionante para ajudá-lo a dirigir para a frente para a posição do pulmão, usando sua mão livre, empurre-se para uma posição sentada, então progredindo para um joelho.","Ao olhar para cima, levante-se lentamente, inverta o movimento de volta para a posição inicial e repita."]],"Kettlebell_Turkish_Get-Up_Squat_style":["Kettlebell Turkish Get-Up (estilo Squat)",["Deite-se de costas no chão e pressione uma campainha para a posição de cima, estendendo o cotovelo.","Mantendo a chaleira fechada o tempo todo, pilote para o lado oposto e use seu braço não-funcionante para ajudá-lo a dirigir para frente para a posição do pulmão.","Usando sua mão livre, empurre-se para uma posição sentada, então progredindo para os pés, enquanto olha para a chaleira, lentamente se levante, reverta o movimento para a posição inicial e repita."]],"Kettlebell_Windmill":["Moinho de vento Kettlebell",["Coloque uma chaleira na frente do seu pé de chumbo e limpe e pressione-a com o braço oposto, limpe a chaleira no ombro estendendo-a pelas pernas e quadris enquanto puxa a chaleira para os ombros, gire o pulso enquanto faz isso, para que a palma da mão se estenda para frente, pressione-a estendendo o cotovelo.","Mantendo a chaleira fechada o tempo todo, empurre seu traseiro para fora na direção da chaleira trancada. Vire seus pés para fora em um ângulo de 45 graus do braço com a chaleira trancada para fora. Dobrando o quadril para um lado, colocando seu traseiro para fora, lentamente inclinando-se até que você possa tocar o chão com sua mão livre. Mantenha seus olhos na chaleira que você segura sobre a cabeça o tempo todo.","Pausa por um segundo depois de chegar ao chão e reverter o movimento de volta para a posição inicial."]],"Kipping_Muscle_Up":["\"Kipping Muscle Up\"",["Segure os anéis usando uma pega falsa, com a base de suas palmas em cima dos anéis.","Comece com um movimento balançando as pernas ligeiramente para trás.","Enfrentar esse movimento balançando as pernas para frente e para cima, balançando o queixo e o peito para trás, puxando-se para cima com os dois braços enquanto você faz isso, enquanto você alcança a posição de cima do puxa-para cima, puxe os anéis para suas axilas enquanto você levanta seus ombros para frente, permitindo que seus cotovelos se mova para trás, para a posição correta para continuar na parte de mergulho do movimento.","Mantendo controle e estabilidade, estenda-se através do cotovelo para completar o movimento.","Use cuidado ao se abaixar no chão."]],"Knee_Across_The_Body":["Joelho através do corpo",["Deite-se no chão com a perna direita reta, dobre a perna esquerda e abaixe-a pelo corpo, segurando o joelho em direção ao chão com a mão direita.","Coloque seu braço esquerdo confortavelmente ao seu lado e vire sua cabeça para a esquerda imagine que você tem um peso amarrado ao seu cóccix deixe seu cóccix cair de volta para o chão enquanto seu peito chega na direção oposta para esticar suas costas inferiores."]],"Knee_Circles":["Círculos de Joelho",["Fique com as pernas juntas e as mãos na cintura.","Agora mova os joelhos em movimento circular enquanto respira normalmente.","Repita para a quantidade recomendada de repetições."]],"Knee_Hip_Raise_On_Parallel_Bars":["Joelho/Aumento do Hip em barras paralelas",["Posicione seu corpo na perna vertical levantar o banco para que seus antebraços estejam descansando nas almofadas ao lado do tronco e segurando as alças.","O torso deve ser reto com a parte inferior pressionada contra a almofada da máquina e as pernas estendidas apontando para o chão.","Agora, enquanto você expira, levante as pernas enquanto as mantém estendidas, continue esse movimento até que suas pernas sejam aproximadamente paralelas ao chão e então segure a contração por um segundo.","Lentamente, volte para a posição inicial enquanto respira.","Repita para a quantidade recomendada de repetições."]],"Knee_Tuck_Jump":["\"Joe Tuck Jump\"",["Comece em uma posição confortável, com os joelhos ligeiramente dobrados, segure as mãos na sua frente, palmas para baixo com os dedos juntos na altura do peito, esta será sua posição inicial.","Mergulhe rapidamente em um quarto de agachamento e imediatamente exploda para cima... conduza os joelhos em direção ao peito, tentando tocá-los nas palmas das mãos.","Salte o mais alto que puder, levante os joelhos, e então garanta que uma boa terra esteja re-extender suas pernas, absorvendo o impacto através de permitir que os joelhos rebender."]],"Kneeling_Arm_Drill":["Perfuração de braços de joelhos",["Esta broca ajuda a aumentar a eficiência do braço durante a corrida, começar a ajoelhar, pé esquerdo na frente, joelho direito para baixo, aplicar pressão através do calcanhar dianteiro para manter seus glúteos e isquiotibiais ativados.","Comece bloqueando os braços em longos, pêndulos como balanços, feche o ângulo do braço, bloqueando com os braços como você faria quando corresse, progredindo para uma corrida e finalmente um sprint.","Assim que suas mãos passarem o quadril, acelere-os durante o movimento de correr para movê-los o mais rápido possível.","Troque de joelhos e repita."]],"Kneeling_Cable_Crunch_With_Alternating_Oblique_Twists":["Ajoelhando-se cabo crunch com alternando torções oblíquas",["Conecte uma corda a um cabo de polia alta e coloque um tapete no chão na frente dele.","Pegue a corda com as duas mãos e ajoelhe-se aproximadamente dois pés de volta da torre.","Coloque a corda atrás da cabeça com as mãos nas orelhas.","Mantenha as mãos no mesmo lugar, contraia seus abdominais e puxe para baixo na corda em um movimento de esmagamento até que seus cotovelos cheguem aos joelhos.","Pause brevemente no fundo e levante-se de forma lenta e controlada até chegar à posição inicial.","Repita o mesmo movimento para baixo até que você esteja na metade do caminho, quando você começar a girar um de seus cotovelos para o joelho oposto.","Mais uma vez, pare brevemente no fundo e levante-se de forma lenta e controlada até chegar à posição inicial.","Repita o mesmo movimento de antes, mas mude o outro cotovelo para o joelho oposto.","Continue esta série de movimentos para o fracasso."]],"Kneeling_Cable_Triceps_Extension":["Ajoelhe-se Cabo Tríceps Extensão",["Coloque um banco de lado na frente de uma máquina de polia alta.","Segure uma barra reta acima da cabeça com as mãos a 6 polegadas de distância com as palmas viradas para baixo.","Vire-se para longe da máquina e ajoelhe-se.","Coloque sua cabeça e a parte de trás dos braços no banco, seus cotovelos devem estar dobrados com os antebraços apontando para a polia alta, esta será sua posição inicial.","Enquanto mantém os braços superiores perto da cabeça o tempo todo com os cotovelos dentro, pressione a barra para fora em um movimento semicircular até que os cotovelos estejam trancados e seus braços estejam paralelos ao chão.","Retorne lentamente à posição inicial enquanto respira.","Repita para a quantidade recomendada de repetições."]],"Kneeling_Forearm_Stretch":["Ajoelhe-se antebraço esticar",["Comece ajoelhando-se em um tapete com as palmas planas e os dedos apontando para os joelhos.","Incline-se lentamente para trás, mantendo as palmas no chão até sentir um estiramento nos pulsos e antebraços."]],"Kneeling_High_Pulley_Row":["Ajoelhando-se High Pulley Row",["Escolha o peso apropriado usando uma polia que está acima de sua cabeça, coloque uma corda no cabo e ajoelhe-se a alguns metros de distância, segurando a corda na sua frente com os dois braços estendidos.","Iniciar o movimento, flexionando os cotovelos e retraindo completamente seus ombros, puxando a corda para o peito superior com os cotovelos para fora.","Depois de pausar brevemente, lentamente retorne à posição inicial."]],"Kneeling_Hip_Flexor":["Ajoelhe-se, Hip Flexor.",["Ajoelhe-se em um tapete e traga seu joelho direito para cima para que o fundo de seu pé esteja no chão e estenda sua perna esquerda para fora atrás de você para que o topo de seu pé esteja no chão.","Segure por 15 segundos, e repita para o outro lado."]],"Kneeling_Jump_Squat":["Ajoelhe-se, pule.",["Comece a ajoelhar-se no chão com uma campainha amassada na parte de trás dos ombros, ou pode usar seu peso corporal para esse exercício.","Sente-se com os quadris até os glúteos tocarem os pés, mantendo a cabeça e o peito para cima.","Exploda com os quadris, gerando energia suficiente para pousar com os pés no chão.","Continue com o agachamento dirigindo através de seus calcanhares e estendendo os joelhos para chegar a uma posição de pé."]],"Kneeling_Single-Arm_High_Pulley_Row":["Ajoelhando fila de polia de braço único.",["Coloque um único punho em uma polia alta e faça sua seleção de peso.","Ajoelhe-se na frente da torre de cabo, pegando o cabo com uma mão com o braço estendido.","Começando com a palma da mão voltada para a frente, puxe o peso para baixo até o tronco, flexionando o cotovelo e retraindo a omoplata.","Após uma breve pausa, volte para a posição inicial."]],"Kneeling_Squat":["Ajoelhe-se.",["Ajoelhe-se atrás da barra, pode ser benéfico colocar um tapete para colocar os joelhos, deslizar por baixo da barra, arrastá-la na parte de trás dos ombros, suas omoplatas devem ser retraídas e a barra apertada em suas costas, desembaraçar o peso.","Com sua cabeça olhando para a frente, sente-se com sua bunda até tocar suas panturrilhas.","Reverta o movimento, devolvendo o torso para uma posição vertical."]],"Landmine_180s":["Mina 180's",["Posicione uma barra em uma mina terrestre ou tranque-a em um canto e carregue a barra em um peso apropriado.","Levante a barra do chão, levando-a para a altura do ombro com as duas mãos com os braços estendidos na sua frente.","Faça o movimento girando o tronco e os quadris enquanto balança o peso até um lado, mantenha os braços estendidos durante o exercício.","Reverta o movimento para balançar o peso até o lado oposto.","Continue alternando o movimento até que o conjunto esteja completo."]],"Landmine_Linear_Jammer":["Jammer Linear de Minas Terrestres",["Posicione uma barra em uma mina terrestre ou, sem uma, ancora-a firmemente em um canto, carregue a barra para um peso adequado e posicione o cabo de fixação na barra.","Levante a barra do chão, levando as alças para seus ombros.","Em uma postura atlética, agache-se flexionando seus quadris e colocando seus quadris de volta, mantendo seus braços flexionados.","Reverta o movimento, estendendo-se poderosamente através dos quadris, joelhos e tornozelos, enquanto também estendendo os cotovelos para endireitar os braços.","Voltem para a posição inicial."]],"Lateral_Bound":["Lateral Bound",["Assuma uma posição de meia agachada, a 90 graus da sua direção de viagem.","Permita que sua perna de chumbo faça um contra-movimento para dentro enquanto muda seu peso para a perna externa.","Empurrar imediatamente e estender, tentando amarrar para o lado, tanto quanto possível.","Ao aterrissar, empurre imediatamente na direção oposta, retornando à sua posição inicial.","Continue indo e voltando para várias repetições."]],"Lateral_Box_Jump":["Pular de Caixa Lateral",["Assuma uma posição confortável em pé, com uma caixa curta posicionada ao seu lado.","Mergulhe rapidamente em um quarto de agachamento para iniciar o reflexo de estiramento, e imediatamente inverta a direção para saltar para cima e para o lado.","Ajoelhe-se o suficiente para garantir que seus pés tenham uma boa folga sobre a caixa.","Pouse no centro da caixa, usando suas pernas para absorver o impacto.","Pule cuidadosamente para o outro lado da caixa, e continue indo e voltando para várias repetições."]],"Lateral_Cone_Hops":["Lateral Cone Hops",["Posicione vários cones em uma fileira a vários metros de distância.","Esta será a sua posição inicial.","Comece o salto mergulhando com os joelhos para iniciar um reflexo de estiramento, e imediatamente inverta a direção para empurrar para fora do chão, pulando para cima e de lado sobre o cone.","Use suas pernas para absorver o impacto no pouso, e rebote para o próximo salto, continuando na linha de cones."]],"Lateral_Raise_-_With_Bands":["Levantamento Lateral com Bandas",["Para começar, coloque-se em uma faixa de exercício para que a tensão comece com o comprimento do braço. Segure os punhos usando uma alça pronada (palmas voltadas para suas coxas) que seja ligeiramente menor do que a largura do ombro. Os punhos devem estar descansando nos lados de suas coxas. Seus braços devem ser estendidos com uma pequena curva nos cotovelos e suas costas devem ser retas. Esta será sua posição inicial.","Continue a levantar as alças até que estejam ligeiramente acima do paralelo.","Abaixe as alças lentamente para a posição inicial, inale enquanto executa esta parte do movimento.","Repita para a quantidade recomendada de repetições."]],"Latissimus_Dorsi-SMR":["Latissimus Dorsi-SMR",["Enquanto estiver deitado no chão, coloque um rolo de espuma sob suas costas e para um lado, logo atrás de seu braço.","Mantenha o braço do lado sendo esticado para trás e para o lado de você enquanto você coloca seu peso em seus lats, mantendo seu corpo superior fora do chão."]],"Leg-Over_Floor_Press":["Perna-por cima do piso",["Deite-se no chão com uma campainha no seu peito, segurando-a pelo cabo, estenda a perna ao lado da perna, sem trabalhar, seu braço livre pode ser estendido para o seu lado para apoio.","Pressione o kettlebll em uma posição fechada.","Abaixe o peso até o cotovelo tocar o chão, mantendo a chaleira acima do cotovelo."]],"Leg-Up_Hamstring_Stretch":["Esticamento de pernas para cima.",["Deite-se de costas, dobre um joelho, e coloque o pé no chão para estabilizar sua coluna.","Estenda a outra perna no ar, se estiver apertado, não conseguirá endireitá-la.","Lentamente estique as pernas o máximo possível e então puxe a perna em direção ao nariz."]],"Leg_Extensions":["Extensões de Pernas",["Para este exercício, terá de usar uma máquina de extensão da perna. Escolha primeiro o seu peso e sente- se na máquina com as pernas sob a almofada (pés apontados para a frente) e as mãos que seguram as barras laterais. Esta será a sua posição inicial. Dica: Terá de ajustar a almofada de modo a que ela caia sobre a sua perna inferior (apenas acima dos pés). Certifique- se também de que as suas pernas formam um ângulo de 90 graus entre a perna inferior e superior. Se o ângulo for inferior a 90 graus, então isso significa que o joelho está sobre os dedos dos pés, o que por sua vez cria um stress indevido na articulação do joelho. Se a máquina for concebida dessa forma, procure por outra máquina ou apenas certifique- se de que, quando começar a executar o exercício, irá parar de descer assim que atingir o ângulo de 90 graus.","Usando seu quadríceps, estenda as pernas ao máximo enquanto expira, certifique-se de que o resto do corpo permaneça parado no banco, pare um segundo na posição contraída.","Reduza lentamente o peso de volta para a posição original enquanto inala, garantindo que não passe do limite de ângulo de 90 graus.","Repita para a quantidade recomendada de vezes."]],"Leg_Lift":["Levantem a perna.",["Ao ficar em pé, com os dois pés ao lado um do outro, ao redor da largura do ombro, pegue uma superfície resistente, como os lados de um rack de agachamento ou a parte superior de uma cadeira para se preparar e manter o equilíbrio.","Com ou sem um peso no tornozelo, levante uma perna atrás de você, como se fizesse uma curva na perna, mas de pé, mantendo a outra perna reta.","Lentamente traga a perna levantada de volta ao chão enquanto você respira.","Repita para a quantidade recomendada de repetições.","Repita o movimento com a perna oposta."]],"Leg_Pull-In":["Perna puxada.",["Deite-se em um tapete de exercício com as pernas estendidas e suas mãos voltadas para baixo ao seu lado ou sob seus glúteos.","Continue o movimento até que seus joelhos estejam ao nível do peito, contraia seus abdominais enquanto executa este movimento e segure por um segundo na parte superior.","Volte para a posição inicial enquanto inala.","Repita para a quantidade recomendada de repetições."]],"Leverage_Chest_Press":["Pressão no peito da alavanca.",["Coloque um peso apropriado nos pinos e ajuste o assento para sua altura.","Seu peito e cabeça devem estar levantados e suas omoplatas retraídas.","Pressione as alças para frente estendendo-se através do cotovelo.","Após uma breve pausa no topo, devolva o peso logo acima da posição inicial, mantendo tensão nos músculos, não retornando o peso às paradas até que o conjunto esteja completo."]],"Leverage_Deadlift":["Lever Deadlift",["Coloque os pinos em um peso apropriado, posicione-se diretamente entre as pegas, segure as pegas de baixo com um aperto confortável, e então abaixe os quadris enquanto respira, olhe para frente com a cabeça e mantenha o peito para cima, esta será sua posição inicial.","Retorne o peso para a posição inicial."]],"Leverage_Decline_Chest_Press":["Pressão do peito em declive",["Coloque um peso adequado nos pinos e ajuste o assento para sua altura, as alças devem estar perto do fundo dos peitorais no início do movimento, seu peito e cabeça devem estar para cima e suas omoplatas retraídas, esta será sua posição inicial.","Pressione as alças para frente estendendo-se através do cotovelo.","Após uma breve pausa no topo, devolva o peso logo acima da posição inicial, mantendo tensão nos músculos, não retornando o peso às paradas até que o conjunto esteja completo."]],"Leverage_High_Row":["Linha Alta de Vantagem",["Coloque um peso apropriado nos pinos e ajuste a altura do assento para que você possa alcançar as alças acima de você. Ajuste a joelheira para ajudá-lo a se abaixar.","Puxe as alças em direção ao seu torso, retraindo suas omoplatas enquanto flexiona o cotovelo.","Pausar no fundo do movimento, e então lentamente retornar as alças para a posição inicial.","Para múltiplas repetições, evite retornar completamente o peso às paradas para manter a tensão nos músculos sendo trabalhados."]],"Leverage_Incline_Chest_Press":["Inclinação de alavanca de pressão no peito",["Coloque um peso apropriado nos pinos e ajuste o assento para sua altura, as alças devem estar perto do topo dos peitorais no início do movimento, seu peito e cabeça devem estar para cima e suas omoplatas retraídas, esta será sua posição inicial.","Pressione as alças para frente estendendo-se através do cotovelo.","Após uma breve pausa no topo, devolva o peso logo acima da posição inicial, mantendo tensão nos músculos, não retornando o peso às paradas até que o conjunto esteja completo."]],"Leverage_Iso_Row":["Leverage Iso Row",["Coloque um peso apropriado nos pinos e ajuste a altura do assento para que as alças estejam ao nível do peito, segure as alças com uma aderência neutra ou pronada, esta será a sua posição inicial.","Puxe as alças em direção ao seu torso, retraindo suas omoplatas enquanto flexiona o cotovelo.","Pausar no fundo do movimento, e então lentamente retornar as alças para a posição inicial."]],"Leverage_Shoulder_Press":["Ombro de alavanca Press",["Coloque um peso apropriado nos pinos e ajuste o assento para a sua altura, as pegas devem estar perto do topo dos ombros no início do movimento, seu peito e cabeça devem estar levantados e segurar com uma pega pronada, esta será a sua posição inicial.","Pressione as alças para cima, estendendo-se através do cotovelo.","Após uma breve pausa no topo, devolva o peso para pouco acima da posição inicial, mantendo tensão sobre os músculos, não retornando o peso às paradas até que o conjunto esteja completo."]],"Leverage_Shrug":["Leverage Shrug",["Coloque os pinos em um peso apropriado, posicione-se diretamente entre as alças.","Segure as alças de cima com um aperto confortável, e abaixe os quadris enquanto respira, olhe para a frente com a cabeça e mantenha o peito para cima.","Dirija pelo chão com os calcanhares, estendendo seus quadris e joelhos, enquanto se eleva a uma posição de pé, mantenha os braços retos ao longo do movimento, terminando com os ombros para trás, esta será a sua posição inicial.","Levante o peso encolhendo os ombros em direção às orelhas, movendo-se para cima e para baixo.","Pausa no topo do movimento, e então retorne o peso para a posição inicial."]],"Linear_3-Part_Start_Technique":["Técnica Linear de 3 partes",["Este exercício ajuda você a acelerar o mais rápido possível em um sprint de um ponto morto, ajuda a usar uma linha para começar, começa com dois pés na linha, coloca o pé esquerdo com o dedo do pé ao lado do tornozelo direito, coloca o pé direito 4-6 polegadas atrás do esquerdo.","Coloque sua mão direita na linha, e algo traga seu nariz perto do joelho esquerdo.","Agache-se enquanto se inclina para frente, sua cabeça está mais baixa que seus quadris e seu peso carregado na perna esquerda.","Pegue sua mão esquerda para cima para que seja paralela ao chão, apontando atrás de você, e exploda quando estiver pronta."]],"Linear_Acceleration_Wall_Drill":["Broca de parede de aceleração linear.",["Seus pés devem estar juntos, glúteos contraídos.","Comece levantando o joelho direito rapidamente, pausando, e depois dirigindo direto para o chão.","Troque as pernas, levante o joelho oposto, e depois ataque o chão direto para baixo.","Repita mais uma vez com a perna direita, e assim que o pé direito bater o chão martelá-los rapidamente, alternando esquerda e direita o mais rápido que puder."]],"Linear_Depth_Jump":["Salto Linear de Profundidade",["Você vai precisar de duas caixas ou bancos espaçados a poucos metros de distância um do outro.","Para iniciar o movimento, gentilmente cair no chão entre suas plataformas, permitindo que os joelhos e quadris flexionem.","Reverta o movimento explodindo, estendendo-se através dos quadris, joelhos e tornozelos para saltar para a outra plataforma.","Terra suavemente, absorvendo o impacto através das pernas."]],"Log_Lift":["Levantar o tronco",["Comece com o tronco na sua frente, segure os punhos, e comece a limpar o tronco, enquanto você está dobrado para começar o limpo, tente obter o tronco o mais alto possível, puxando-o para o peito, estenda através dos quadris e joelhos para trazê-lo para completar o limpo.","Empurrar a cabeça para trás e olhar para cima, criando uma prateleira no peito para descansar o tronco. Começar a imprensa mergulhando, flexionando ligeiramente através dos joelhos e invertendo o movimento.","Tente controlar a descida do tronco assim que voltar ao chão."]],"London_Bridges":["Pontes de Londres",["Coloque uma corda de escalada em um raio alto ou um membro cruzado, abaixo dele, certifique-se de que a barra da máquina do ferreiro esteja trancada no lugar com as seguranças e não possa se mover, em alternativa, uma caixa segura também pode ser usada.","Esta será a sua posição inicial.","Mantendo seu corpo reto, incline-se para trás e abaixe seu corpo lentamente indo mão sobre a mão com a corda.","Mantendo seu corpo reto, invertendo o movimento, indo de mãos dadas para a posição inicial."]],"Looking_At_Ceiling":["Olhando para o teto",["Ajoelhe-se no chão, segurando seus calcanhares com as duas mãos.","Levante suas nádegas para cima e para frente, enquanto leva sua cabeça de volta para olhar para o teto, para dar um arco em suas costas."]],"Low_Cable_Crossover":["Atravessamento de Cabo Baixo",["Para se mover para a posição inicial, coloque as polias na posição baixa, selecione a resistência a ser usada e segure uma alça em cada mão.","Suas palmas devem estar voltadas para frente, mãos abaixo da cintura, e seus braços retos.","Com uma leve curva nos braços, levante as mãos para cima e para a linha média do seu corpo, suas mãos devem se unir em frente ao peito, com as palmas viradas para cima.","Devolva seus braços para a posição inicial após uma breve pausa."]],"Low_Cable_Triceps_Extension":["Extensão de Tríceps de Cabo Baixo",["Escolha o peso desejado e deite-se de frente no banco de uma máquina de fila sentada que tem uma corda presa a ela.","Agarrem o lado de fora da corda, com as palmas viradas uma para a outra.","Posicione seus cotovelos para que eles estejam dobrados em um ângulo de 90 graus e seus braços sejam perpendiculares (ângulo de 90 graus) ao seu torso.","Enquanto você expira, estenda seus braços inferiores até que estejam retos e verticais, os braços e cotovelos ficam parados durante todo o movimento, só os antebraços devem se mover, contrair o tríceps com força por um segundo.","Enquanto você respira lentamente, volte para a posição inicial.","Repita para a quantidade recomendada de repetições."]],"Low_Pulley_Row_To_Neck":["Fila de polia baixa para o pescoço",["Sente-se em uma máquina de roldana baixa com uma corda presa.","Pegue as extremidades da corda usando um aperto de palmas para baixo e sente-se com as costas retas e os joelhos ligeiramente dobrados.","Enquanto mantém o tronco parado, levante os cotovelos e comece a dobrá-los enquanto puxa a corda para o pescoço enquanto expira. Durante todo o movimento, seus braços devem permanecer paralelos ao chão.","Depois de segurar por um segundo na posição contraída, volte lentamente para a posição inicial enquanto inala.","Repita para a quantidade recomendada de repetições."]],"Lower_Back-SMR":["Regresso inferior-SMR",["Em uma posição sentada, coloque um rolo de espuma sob suas costas, cruze os braços na sua frente e prolongue os ombros, esta será sua posição inicial.","Levante os quadris do chão e incline-se para trás, mantendo o peso nas costas, agora mude o peso ligeiramente para um lado, mantendo o peso fora da coluna vertebral e nos músculos para o lado dela, role as costas, segurando pontos de tensão por 10-30 segundos, repita do outro lado."]],"Lower_Back_Curl":["Curva inferior das costas",["Deite-se de barriga para baixo, com os braços para os lados.","Não use os braços para se levantar, mantenha a cabeça erguida durante o movimento, repita por 10-20 repetições."]],"Lunge_Pass_Through":["Lunge Pass Through",["Fique com o torso ereto segurando uma campainha na mão direita.","Aproxime-se com o pé esquerdo e abaixe a parte superior do corpo, flexionando o quadril e o joelho, mantendo o torso ereto.","Enquanto você joga, passe a chaleira debaixo da perna da frente para a mão oposta.","Pressionando o calcanhar do pé, volte para a posição inicial.","Repita o movimento para a quantidade recomendada de repetições, alternando as pernas."]],"Lunge_Sprint":["Lunge Sprint",["Ajuste uma barra em uma máquina Smith para uma altura apropriada, coloque-se sob a barra, colocando-a na parte de trás dos ombros, desprendindo a barra, e então divida os pés, movendo-se um pé para frente e um pé para trás.","Abaixe o joelho para o chão, flexionando os joelhos e baixando os quadris enquanto faz isso.","Na parte inferior da descida, imediatamente inverta a direção, dirija pelo calcanhar do pé dianteiro com pressão leve do pé de trás, salte para cima e inverta a posição das pernas.","Repita para a quantidade recomendada de repetições."]],"Lying_Bent_Leg_Groin":["Deitado com a ponta da perna.",["Deite-se de costas com os joelhos dobrados e as solas dos pés juntas.","Tente apertar os joelhos juntos, enquanto seu parceiro impede qualquer movimento de ocorrer.","Depois de 10-20 segundos, relaxe os músculos enquanto seu parceiro gentilmente empurra seus joelhos para o chão."]],"Lying_Cable_Curl":["Curva de Cabo Mentindo",["Pegue uma barra reta ou fixação de barra E-Z que está presa à polia baixa com ambas as mãos, usando um aperto de mão (palmas viradas para cima) ombro-largura.","Deite-se de costas em cima de um tapete de exercício na frente da pilha de peso com seus pés em pé contra a estrutura da máquina de polia e suas pernas retas.","Com os braços estendidos e os cotovelos perto do corpo ligeiramente dobrem os braços.","Enquanto mantém os braços parados e os cotovelos perto do corpo, enrole a barra lentamente em direção ao peito enquanto expira e aperta os bíceps.","Depois de um segundo aperto no topo do movimento, lentamente voltar à posição inicial.","Repita para a quantidade recomendada de repetições."]],"Lying_Cambered_Barbell_Row":["Deitado Cambered Barbell Row",["Coloque uma barra em baixo de um banco de exercícios.","Deite-se de frente no banco de exercícios e agarre a barra usando uma palma da mão para baixo que é maior que a largura do ombro.","Enquanto você exala reme a barra para cima enquanto você mantém os cotovelos perto do seu corpo para o seu peito, a fim de atingir a parte superior média das costas, ou para o seu estômago se o alvo os lats é o seu objetivo.","Depois de um segundo segure no topo, abaixe para baixo para a posição inicial lentamente enquanto você inala."]],"Lying_Close-Grip_Bar_Curl_On_High_Pulley":["Caindo de perto, Bar Curl em High Pulley.",["Coloque um banco na frente de uma máquina de polia alta ou lat.","Segure o anexo da barra reta usando um aperto de baixo da mão (palmas para cima) que é sobre a largura do ombro.","Deite-se de costas com a cabeça sobre o banco.","Agora estenda os braços acima dos ombros, seu tronco e os braços devem fazer um ângulo de 90 graus e os cotovelos devem estar dentro, esta será sua posição inicial.","Enquanto você expira, enrole a barra em um movimento semicircular até que toque seu queixo, aperte os bíceps por um segundo na posição superior contraída.","Retorne à posição inicial lentamente.","Repita para a quantidade recomendada de repetições."]],"Lying_Close-Grip_Barbell_Triceps_Extension_Behind_The_Head":["Deitado perto de Barbell Tríceps.",["Enquanto segura uma barbela ou uma barra EZ Curl com uma pegada pronada (palmas voltadas para a frente), deite-se de costas em um banco plano com a cabeça perto da ponta do banco. Dica: Se você está segurando uma barbela agarre-a usando uma pegada de largura do ombro e se você estiver usando uma barra E-Z agarre-a nas alças internas.","Estenda seus braços na sua frente e lentamente traga a barra de volta em um movimento semi-circular (enquanto mantém os braços estendidos) para uma posição sobre sua cabeça.","Enquanto você inala, abaixe a barra dobrando os cotovelos e mantendo o braço parado, e continue baixando a barra até que seus antebraços estejam perpendiculares ao chão.","Quando você expirar, traga a barra de volta para a posição inicial empurrando a barra para cima em um movimento semi-circular até que os braços inferiores também sejam paralelos ao chão. Contraia o tríceps com força no topo do movimento por um segundo.","Repita para a quantidade recomendada de repetições."]],"Lying_Close-Grip_Barbell_Triceps_Press_To_Chin":["Deitado de perto, Barbell Tríceps Press To Chin",["Enquanto segura um barbell ou um bar EZ Curl com um aperto pronado (palmas voltadas para a frente), deite-se de costas em um banco plano com a cabeça fora da extremidade do banco. Dica: Se você está segurando um barbell agarre-o usando um aperto ombro-largura e se você está usando um bar E-Z agarre-o nas alças internas.","Estenda os braços à sua frente enquanto segura a barba sobre o peito, os braços devem ser perpendiculares ao seu tronco, esta será a sua posição inicial.","Enquanto inala, abaixe a barra em um movimento semicircular, dobrando os cotovelos e mantendo o braço parado e os cotovelos parados.","Quando você expirar, traga a barra de volta para a posição inicial, empurrando a barra para cima em um movimento semicircular, contraia o tríceps com força no topo do movimento por um segundo, novamente, apenas os antebraços devem se mover, os braços superiores devem permanecer parados o tempo todo.","Repita para a quantidade recomendada de repetições."]],"Lying_Crossover":["Deitado Crossover",["Deite-se de costas com as pernas estendidas.","Cruze uma perna sobre seu corpo com o joelho dobrado, tentando tocar o joelho no chão, seu parceiro deve se ajoelhar ao seu lado, segurando seu ombro para baixo com uma mão e controlando a perna cruzada com a outra.","Tentar levantar o joelho dobrado do chão, já que seu parceiro impede qualquer movimento real.","Depois de 10-20 segundos, relaxe a perna enquanto seu parceiro pressiona suavemente o joelho em direção ao chão."]],"Lying_Dumbbell_Tricep_Extension":["Prolongamento do tríceps do halteres mentiroso",["Deite-se em um banco plano enquanto segura dois halteres diretamente na sua frente, seus braços devem ser estendidos a 90 graus do seu tronco e do chão, as palmas devem estar viradas para dentro e os cotovelos devem ser dobrados, esta é a posição inicial.","Enquanto você respira e mantém os braços parados com os cotovelos dentro, lentamente abaixe o peso até que os halteres estejam perto de suas orelhas.","Nesse ponto, enquanto mantém os cotovelos dentro e os braços superiores parados, use o tríceps para trazer o peso de volta para a posição inicial enquanto você expira.","Repita para a quantidade recomendada de repetições."]],"Lying_Face_Down_Plate_Neck_Resistance":["Resistindo de cabeça para baixo.",["Deite-se com o corpo todo em um banco plano, segurando uma placa de peso atrás da cabeça.","Enquanto mantém a placa segura na parte de trás da cabeça lentamente abaixe a cabeça (como em dizer \"sim\") enquanto você respira.","Levante a cabeça para a posição inicial em um movimento semicircular enquanto expira.","Repita para a quantidade recomendada de repetições."]],"Lying_Face_Up_Plate_Neck_Resistance":["Resistindo de cabeça para cima",["Você precisa se posicionar para que seus ombros estejam ligeiramente acima da extremidade de um banco plano, para que as armadilhas, pescoço e cabeça fiquem fora do banco.","Enquanto mantém o prato seguro na testa lentamente abaixe a cabeça de volta em um movimento semi-circular enquanto você respira.","Levante a cabeça para a posição inicial em um movimento semicircular enquanto expira.","Repita para a quantidade recomendada de repetições."]],"Lying_Glute":["Glute mentiroso",["Deite-se de costas com seu parceiro ajoelhado ao seu lado.","Torça o quadril de uma perna, levante-o do chão, gire a perna para que o pé esteja sobre o quadril oposto, a perna inferior perpendicular ao seu corpo, seu parceiro deve segurar o joelho e tornozelo no lugar, esta será a sua posição inicial.","Tente empurrar sua perna para o seu parceiro, que deve estar impedindo qualquer movimento real da perna.","Depois de 10-20 segundos, relaxe completamente enquanto seu parceiro empurra gentilmente o tornozelo e o joelho em direção ao seu peito."]],"Lying_Hamstring":["Deitado, Hamstring",["Deite-se de costas com as pernas estendidas, seu parceiro deve estar ajoelhado ao seu lado, levante uma perna até o teto e faça seu parceiro segurar o tornozelo, seu parceiro pode usar o ombro para segurar sua perna se necessário, esta será sua posição inicial.","Com seu parceiro segurando sua perna no lugar, tentando flexionar o joelho, contraindo os isquiotibiais por 10-20 segundos.","Então relaxe a perna, permitindo que seu parceiro empurre gentilmente a perna em direção à cabeça, e informe seu ajudante quando o estiramento for adequado para evitar lesões ou estiramento excessivo."]],"Lying_High_Bench_Barbell_Curl":["\"Lieing High Bench Barbell Curl\"",["Deite-se de frente em um banco plano alto enquanto segura uma campainha com um aperto supinado (palmas viradas para cima). Dica: Se você está segurando uma campainha agarre-a usando um aperto de ombro-largura e se você estiver usando uma barra E-Z agarre-a nas alças internas. Seu corpo superior deve ser posicionado de uma forma que o peito superior esteja sobre a extremidade do banco e a campainha está pendurada na sua frente com os braços estendidos e perpendiculares ao chão. Esta será a sua posição inicial.","Enquanto mantém os cotovelos e os braços parados, enrole o peso em um movimento semicircular enquanto contrai os bíceps e expira.","Mantenha o controle total do peso o tempo todo e evite qualquer oscilação. lembre-se, apenas os antebraços devem se mover ao longo do movimento.","Repita para a quantidade recomendada de repetições."]],"Lying_Leg_Curls":["Curls de Perna Mentida",["Ajustar a alavanca da máquina para caber sua altura e deitar de cara para baixo na máquina de enrolar a perna com a almofada da alavanca na parte de trás das pernas (apenas alguns centímetros abaixo das pernas).","Mantendo o torso plano no banco, certifique-se de que suas pernas estejam totalmente esticadas e segure as pegas laterais da máquina.","Quando você expirar, enrole as pernas o máximo possível sem levantar as pernas superiores da almofada, assim que atingir a posição contraída, segure-a por um segundo.","Ao inalar, traga as pernas de volta à posição inicial, repita a quantidade recomendada de repetições."]],"Lying_Machine_Squat":["\"Máquina De mentira Agachada\"",["Ajuste a máquina da perna a uma altura que lhe permitirá entrar nela com os joelhos dobrados e as coxas ligeiramente abaixo do paralelo.","Uma vez que você selecionar o peso, posicione-se dentro da máquina de rosto para cima com os joelhos dobrados e as coxas ligeiramente abaixo paralelas à plataforma. Certifique-se de que os joelhos não passam dos dedos dos pés. O ângulo criado entre os isquiotibiais e os bezerros deve ser um que seja ligeiramente inferior a 90 graus (já que sua posição inicial requer que você comece ligeiramente abaixo do paralelo).","Coloque as mãos pelos punhos e posicione os pés ligeiramente apontando para uma posição de largura do ombro.","Enquanto pressiona com as bolas dos pés enquanto expira, faça todo o seu corpo ereto enquanto aperta os quadris, mantenha a posição contraída por um segundo, já que está começando abaixo do paralelo, pode optar por usar suas mãos para ajudá-lo pressionando suas coxas apenas na primeira repetição.","Agache-se lentamente enquanto inala, mas ao invés de ir até a posição inicial, pare quando suas coxas estiverem paralelas à plataforma, o ângulo entre seus isquiotibiais e bezerros deve ser de 90 graus.","Repita para a quantidade recomendada de repetições."]],"Lying_One-Arm_Lateral_Raise":["Levantamento lateral de um braço só",["Enquanto segura um haltere em uma mão, deite-se com o peito em um banco plano, e a outra mão pode ser usada para segurar a perna do banco para a estabilidade.","Posicione a palma da mão que está segurando o haltere de forma neutra (palmas voltadas para seu torso) enquanto mantém o braço estendido com o cotovelo ligeiramente dobrado.","Agora levante o braço com o haltere para o lado até que seu cotovelo esteja na altura do ombro e seu braço seja aproximadamente paralelo ao chão enquanto você expira.","Abaixe lentamente o haltere para a posição inicial enquanto inala.","Repita para a quantidade recomendada de repetições."]],"Lying_Prone_Quadriceps":["Quadriceps Prone mentirosos",["Coloque o rosto no chão com seu parceiro ajoelhado ao seu lado, flexione um joelho e levante a perna do chão, tentando tocar seus glúteos com o pé, seu parceiro deve segurar o joelho e o tornozelo, esta será sua posição inicial.","Tente estender o joelho enquanto seu parceiro impede qualquer movimento real.","Depois de 10-20 segundos, relaxe os músculos enquanto seu parceiro gentilmente empurra o pé em direção aos glúteos, esticando ainda mais o quadríceps e flexores de quadril.","Depois de 10-20 segundos, mude de lado."]],"Lying_Rear_Delt_Raise":["Levantar o traseiro deitado.",["Enquanto segura um haltere em cada mão, deite com o peito em um banco plano.","Posicione as palmas das mãos de forma neutra, enquanto mantém os braços estendidos com os cotovelos ligeiramente dobrados.","Agora levante os braços para o lado até que seus cotovelos estejam na altura do ombro e seus braços sejam aproximadamente paralelos ao chão enquanto você expira.","Abaixe lentamente os halteres para a posição inicial enquanto inala.","Repita a quantidade recomendada de repetições e mude para o outro braço."]],"Lying_Supine_Dumbbell_Curl":["Supine halteres Curl",["Deite-se em um banco achatado e segure um haltere em cada braço em cima das coxas.","Traga os halteres para os lados com os braços estendidos e as palmas das mãos voltadas para suas coxas (aperto neutro).","Enquanto mantém os braços perto de seu tronco e cotovelos dentro, lentamente abaixe seus braços (como você mantê-los estendidos com uma ligeira curva nos cotovelos) para baixo para o chão como você pode ir.","Enquanto você expira, lentamente começa a enrolar os pesos para cima enquanto você gira simultaneamente seus pulsos de modo que as palmas das mãos do rosto para cima. Continue enrolando o peso até que seus bíceps são totalmente contraídos e aperte com força na posição superior por um segundo. Dica: Apenas os antebraços devem se mover. Braços superiores devem permanecer parados e cotovelos devem permanecer dentro durante todo o movimento.","Volte para a posição inicial muito lentamente."]],"Lying_T-Bar_Row":["Fila de T-Bar mentindo",["Carregar a máquina da linha da barra T com o peso desejado e ajustar a altura da perna para que seu peito superior esteja no topo da almofada. Dica: Em algumas máquinas tudo o que você pode fazer é ficar no passo apropriado que permite que você esteja em uma altura que tenha o peito superior no topo da almofada.","Você pode usar uma palma para baixo, palmas para cima, ou palmas para cima, dependendo de qual parte de suas costas você quer enfatizar.","Levante a barra da prateleira e estenda os braços na sua frente.","Mantenha os braços o mais perto possível do tronco durante o movimento, a fim de melhor segurar os músculos das costas e também não levante o corpo da almofada a qualquer momento e evite usar os bíceps para levantar o peso.","Depois de uma segunda contração no topo do movimento, enquanto você inala, lentamente volte para a posição inicial.","Repita para a quantidade recomendada de repetições."]],"Lying_Triceps_Press":["Imprensa Tríceps mentindo.",["Deite-se em um banco plano com uma barra e-z (minha preferência) ou uma barra reta colocada no chão atrás de sua cabeça e seus pés no chão.","Pegue a barra atrás de você, usando um meio overhand (pronated) aperto, e levante a barra na frente de você no comprimento dos braços. Dica: os braços devem ser perpendicular ao tronco e ao chão.","Enquanto você respira, lentamente abaixe o peso até que a barra toque levemente sua testa, mantendo os braços e cotovelos parados.","Nesse ponto, use o tríceps para trazer o peso de volta para a posição inicial enquanto você expira.","Repita para a quantidade recomendada de repetições."]],"Machine_Bench_Press":["Máquina Bench Press",["Sente-se na máquina de pressão do peito e selecione o peso.","Pise na alavanca fornecida pela máquina, já que vai ajudá-lo a levar as alças para frente para que você possa agarrar as alças e estender completamente os braços.","Pegue as alças com um aperto de palmas para baixo e levante os cotovelos para que seus braços sejam paralelos ao chão para os lados do tronco.","Agora traga as alças de volta para você enquanto respira.","Mantenha a contração por um segundo antes de voltar para a posição inicial.","Repita para a quantidade recomendada de representantes.","Quando terminar, pise na alavanca de novo e leve as alças de volta para o lugar original."]],"Machine_Bicep_Curl":["Máquina Bíceps Curl",["Ajuste o assento para a altura adequada e faça sua escolha de peso, coloque os braços contra as almofadas e segure as alças, esta será sua posição inicial.","Faça o movimento, flexionando o cotovelo, puxando o braço em direção ao braço.","Pause no topo do movimento, e então lentamente retorne o peso para a posição inicial.","Evite devolver o peso até as paradas até que o conjunto esteja completo para manter a tensão nos músculos sendo trabalhados."]],"Machine_Preacher_Curls":["Curls de Pregador de Máquina",["Sente-se na máquina Curl Preacher e selecione o peso.","Coloque a parte de trás dos braços (seu tríceps) no bloco de pregadores fornecido e agarre as alças usando um aperto de mão (palmas viradas para cima). Dica: Certifique-se de que quando colocar os braços na almofada você mantenha os cotovelos dentro.","Agora levante as alças enquanto expira e contraia os bíceps no topo da posição certifique-se de segurar a contração por um segundo.","Abaixe as alças lentamente para a posição inicial enquanto inala.","Repita para a quantidade recomendada de repetições."]],"Machine_Shoulder_Military_Press":["Ombro de máquina (Militar) Imprensa",["Sente-se na máquina do ombro e selecione o peso.","Pegue as alças para os lados enquanto mantém os cotovelos dobrados e alinhados com seu torso.","Agora levante as alças enquanto expira e estenda os braços completamente no topo da posição certifique-se de segurar a contração por um segundo.","Abaixe as alças lentamente para a posição inicial enquanto inala.","Repita para a quantidade recomendada de repetições."]],"Machine_Triceps_Extension":["Extensão do tríceps da máquina.",["Ajuste o assento para a altura adequada e faça sua escolha de peso, coloque os braços contra as almofadas e segure as alças, esta será sua posição inicial.","Execute o movimento estendendo o cotovelo, puxando seu braço inferior para longe de seu braço.","Pause na conclusão do movimento, e então lentamente retorne o peso para a posição inicial.","Evite devolver o peso até as paradas até que o conjunto esteja completo para manter a tensão nos músculos sendo trabalhados."]],"Medicine_Ball_Chest_Pass":["Passagem do peito da bola de medicina",["Você vai precisar de um parceiro para este exercício, sem um, este movimento pode ser realizado contra uma parede.","Comece a enfrentar seu parceiro segurando a bola de remédio em seu torso com as duas mãos.","Puxe a bola para o peito, e reverta o movimento estendendo-se através dos cotovelos para aplicações esportivas, você pode dar um passo enquanto joga.","Seu parceiro deveria pegar a bola, e jogá-la de volta para você.","Receba o arremesso com as duas mãos na altura do peito."]],"Medicine_Ball_Full_Twist":["Remédio Bola de Torção Completa",["Para este exercício, você precisará de uma bola de remédio e um parceiro.","Segure a bola na frente do porta-malas, abra os quadris e vire os ombros ao mesmo tempo que seu parceiro.","Para rotação completa, você e seu parceiro devem girar na mesma direção, ou seja, no sentido anti-horário.","Passe a bola para o seu parceiro, e vocês dois podem agora girar na direção oposta para repetir o procedimento."]],"Medicine_Ball_Scoop_Throw":["Arremesso de Bola de Medicina",["Assuma uma postura semi-esquat com uma bola de remédio em suas mãos seus braços devem pendurar para que a bola esteja perto de seus pés.","Comece empurrando os quadris para frente enquanto você se estende através das pernas, pulando para cima.","Enquanto você faz, balançar os braços para cima e para cima da cabeça, mantendo-os estendidos, liberando a bola no pico do seu movimento."]],"Middle_Back_Shrug":["Encoste nas costas do meio.",["Deite-se em um banco inclinado, segurando um haltere em cada mão, seus braços devem ser estendidos, pendurados e apontando para o chão, as palmas das mãos devem estar voltadas uma para a outra, esta será a sua posição inicial.","Este movimento é como a ação inversa de um abraço, ou tentar fazer laterales traseiras como se não tivesse braços.","Enquanto você inala, volte para a posição inicial.","Repita para a quantidade recomendada de repetições."]],"Middle_Back_Stretch":["Esticamento das costas do meio.",["Fique de pé para que seus pés tenham largura de ombro e mãos nos quadris.","Torça na cintura até sentir um estiramento, segure por 10 a 15 segundos e depois torça para o outro lado."]],"Mixed_Grip_Chin":["Aperta o queixo.",["Usando um espaçamento que é cerca de 1 polegada maior que a largura do ombro, pegue uma barra com as palmas de uma mão voltada para frente e as palmas da outra mão voltadas para você.","Com o braço que tem as palmas voltadas para cima, concentre-se em usar os músculos das costas para realizar o movimento, o cotovelo desse braço deve permanecer perto do tronco, com o outro braço que tem as palmas voltadas para a frente, os cotovelos estarão longe, mas em linha com o tronco, você vai se concentrar em usar as travas para puxar seu corpo para cima.","Depois de uma segunda contração no topo, comece a descer lentamente enquanto inala.","Repita para a quantidade recomendada de repetições.","No set seguinte, mude as pegadas, então se você tivesse a mão direita com as palmas voltadas para você e a esquerda com as palmas voltadas para frente, no set seguinte você terá as palmas voltadas para frente para a mão direita e voltada para você para a esquerda."]],"Monster_Walk":["\"Monster Walk\"",["Coloque uma faixa ao redor dos tornozelos e outra ao redor dos joelhos.","Para começar, dê passos curtos para frente alternando seu pé esquerdo e direito.","Depois de vários passos, faça exatamente o oposto e caminhe de volta para onde você começou."]],"Moving_Claw_Series":["Série de Garra Movendo",["Este movimento ajuda a preparar sua forma de corrida para ajudá-lo a se destacar no sprint, enquanto você corre, certifique-se de flexionar o joelho, visando chutar seus glúteos enquanto o quadril se estende.","Recarregue o quadriciclo enquanto a perna se move para a frente, atacando o chão no próximo passo.","Assegure-se de que, enquanto corre, bloqueie com os braços, perfurando em um rápido movimento de 1-2."]],"Muscle_Snatch":["Músculo Snatch",["Comece com uma barbela carregada na posição média da coxa com um aperto largo, os pés devem estar diretamente abaixo dos quadris, com os pés virados conforme necessário, abaixe os quadris, com o peito para cima e a cabeça olhando para a frente, os ombros devem estar bem na frente da barra, esta será a posição inicial.","Comece a puxar dirigindo pela frente dos calcanhares, levantando a barra, passando para a segunda puxando, estendendo-se através dos quadris joelhos e tornozelos, dirigindo a barra o mais rápido possível, a barra deve estar perto do corpo.","Continue levantando a barra para a posição de cima, sem redobrar os joelhos."]],"Muscle_Up":["Músculo para cima.",["Aperte os anéis usando uma pega falsa, com a base de suas palmas em cima dos anéis, inicie uma puxada puxando os cotovelos para o lado, flexionando os cotovelos.","Quando você chegar à posição superior do puxa-para cima, puxe os anéis para suas axilas enquanto você gira seus ombros para frente, permitindo que seus cotovelos se movam para trás, o que coloca você na posição correta para continuar na parte de mergulho do movimento.","Mantendo controle e estabilidade, estenda-se através do cotovelo para completar o movimento.","Use cuidado ao se abaixar no chão."]],"Narrow_Stance_Hack_Squats":["Estreita Stance Hack Squats",["Coloque a parte de trás do torso contra a parte de trás da máquina e coloque seus ombros sob as ombreiras fornecidas.","Coloque suas pernas na plataforma usando uma posição estreita menor que a largura do ombro com os dedos dos pés ligeiramente apontados seus pés devem estar em torno de 3 polegadas ou menos separados.","Coloque seus braços nas alças laterais da máquina e desengace as barras de segurança (que na maioria dos projetos é feito movendo as alças laterais de uma posição frontal voltada para uma posição diagonal).","Agora endireite as pernas sem trancar os joelhos.","Comece a baixar lentamente a unidade dobrando os joelhos enquanto você mantém uma postura reta com a cabeça para cima (de volta na almofada em todos os momentos). Continue para baixo até que o ângulo entre a perna superior e os bezerros torna-se ligeiramente menos de 90 graus (que é o ponto em que as pernas superiores estão abaixo paralelo ao chão). Inspire enquanto você executa esta parte do movimento.","Comece a elevar a unidade enquanto expira, empurrando o chão com os calcanhares dos pés, enquanto endireita as pernas novamente e volta para a posição inicial.","Repita para a quantidade recomendada de repetições."]],"Narrow_Stance_Leg_Press":["Estreita Stance Leg Press",["Usando uma máquina de prensar as pernas, sente-se na máquina e coloque as pernas na plataforma diretamente na sua frente, com uma posição de menor largura do que o ombro, com os dedos dos pés ligeiramente apontados, seus pés devem estar em torno de 3 polegadas ou menos separados.","Abaixe as barras de segurança segurando a plataforma ponderada no lugar e pressione a plataforma até que suas pernas estejam totalmente estendidas na sua frente.","Enquanto você inala, abaixe lentamente a plataforma até que suas pernas superiores e inferiores façam um ângulo de 90 graus.","Empurrando principalmente com os calcanhares dos pés e usando o quadríceps voltar para a posição inicial enquanto você expira.","Repita para a quantidade recomendada de repetições e certifique-se de trancar os pinos de segurança corretamente assim que terminar."]],"Narrow_Stance_Squats":["Estreita Squats Stance",["Este exercício é melhor realizado dentro de um rack de agachamento para fins de segurança, para começar, primeiro coloque a barra em um rack que melhor corresponde à sua altura, uma vez que a altura correta é escolhida e a barra é carregada, passo sob a barra e colocar a parte de trás de seus ombros (ligeiramente abaixo do pescoço) através dele.","Segure-se na barra usando os dois braços de cada lado e levante-a do rack empurrando com as pernas e ao mesmo tempo endireitando o tronco.","Afaste-se do rack e posicione suas pernas usando uma posição estreita menos larga do que o ombro com os dedos dos pés ligeiramente apontados. Pés devem estar em torno de 3-6 polegadas de distância. Mantenha sua cabeça para cima em todos os momentos (olhando para baixo vai deixá-lo fora do equilíbrio) e manter uma posição reta para trás.","Comece a baixar lentamente a barra dobrando os joelhos enquanto mantém uma postura reta com a cabeça para cima. Continue até que o ângulo entre a perna superior e os bezerros se torne ligeiramente inferior a 90 graus (que é o ponto em que as pernas superiores estão abaixo paralelas ao chão). Inspire enquanto você executa esta parte do movimento. Dica: Se você realizou o exercício corretamente, a frente dos joelhos deve fazer uma linha reta imaginária com os dedos perpendiculares à frente. Se seus joelhos estão além dessa linha imaginária (se eles estão além dos dedos dos pés) então você está colocando estresse excessivo no joelho e o exercício foi realizado incorretamente.","Comece a levantar a barra enquanto expira, empurrando o chão com o calcanhar do pé, principalmente enquanto endireita as pernas novamente e volta para a posição inicial.","Repita para a quantidade recomendada de repetições."]],"Natural_Glute_Ham_Raise":["\"Crescimento Natural de Presunto de Glute\"",["Usando a almofada da perna de uma máquina de puxar lat ou um banco de pregador, posicione-se para que seus tornozelos estejam sob as almofadas, joelhos no assento, e você está de frente para longe da máquina.","Abaixe-se sob controle até que seus joelhos estejam quase completamente retos.","Permanecendo no controle, levante-se de volta à posição inicial.","Se você é incapaz de completar um representante, use uma banda, um parceiro, ou empurre de uma caixa para ajudar a completar uma repetição."]],"Neck-SMR":["Pescoço-SMR",["Usando um rolo muscular ou um rolo, coloque o rolo atrás da cabeça e contra o pescoço, certifique-se de não colocar o rolo diretamente contra a coluna vertebral, mas vire ligeiramente para que o rolo seja pressionado contra os músculos para ambos os lados da coluna vertebral.","Começando na parte superior do pescoço, lentamente rolar para baixo os músculos do pescoço, pausando em pontos de tensão por 10-30 segundos."]],"Neck_Press":["Prensa de Pescoço",["Deite-se em um banco plano, usando um aperto de largura média (um aperto que cria um ângulo de 90 graus no meio do movimento entre os antebraços e os braços superiores), levante a barra do rack e segure-a sobre o pescoço com os braços fechados.","Enquanto respira, desça devagar até sentir a barra no pescoço.","Depois de uma segunda pausa, traga a barra de volta para a posição inicial enquanto você expira e empurre a barra usando os músculos do peito, tranque os braços e aperte o peito na posição contraída, segure por um segundo e comece a descer lentamente novamente.","Repita o movimento para a quantidade prescrita de repetições.","Quando terminar, coloque o bar de volta no rack."]],"Oblique_Crunches":["Oblique Crunches",["Deite-se no chão, com a parte de baixo das costas pressionada no chão, para este exercício, você terá que colocar uma mão ao lado da cabeça e a outra para o lado contra o chão.","Certifique-se de que seus pés estão elevados e descansando em uma superfície plana.","Agora levante o ombro em que sua mão está tocando sua cabeça.","Por exemplo, se você tem sua mão direita além de sua cabeça, então você quer elevar seu corpo para cima até que seu cotovelo direito toque seu joelho esquerdo.","Depois que o joelho tocar o cotovelo, abaixe o corpo até chegar na posição inicial.","Lembre-se de respirar durante a parte excêntrica do exercício e expirar durante a parte concêntrica (para cima) do exercício.","Continue alternando desta forma até que todas as repetições recomendadas para cada lado tenham sido concluídas."]],"Oblique_Crunches_-_On_The_Floor":["Oblique Crunches - No chão",["Comecem deitados do lado direito com as pernas em cima umas das outras, certifiquem-se de que os joelhos estão dobrados.","Coloque a mão esquerda atrás da cabeça.","Uma vez que você está nessa posição, comece movendo seu cotovelo esquerdo para cima como você faria uma batida normal, exceto que desta vez a ênfase principal é em seus oblíquos.","Crunch tão alto quanto você pode, segurar a contração por um segundo e, em seguida, lentamente cair de volta para a posição inicial.","Lembre-se de respirar durante a parte excêntrica (baixando) do exercício e expirar durante a parte concêntrica (elevação) do exercício."]],"Olympic_Squat":["Agachamento olímpico",["Comece com uma campainha apoiada em cima das armadilhas, o peito deve ser levantado e a cabeça voltada para frente, adote uma posição de largura do quadril com os pés virados conforme necessário.","Isso requer que os joelhos viajem para frente, que fiquem alinhados com os pés, o objetivo é manter o tronco o mais ereto possível, continuar o caminho todo para baixo, mantendo o peso na frente do calcanhar.","No momento, as pernas superiores entram em contato com a parte inferior, revertem o movimento, levando o peso para cima."]],"On-Your-Back_Quad_Stretch":["No seu traseiro Quad Stretch",["Deite-se em um banco ou degrau, e pendure uma perna e um braço sobre o lado.","Dobre o joelho e segure a parte de cima do pé.","Puxe o umbigo para a coluna vertebral para ficar em ponto morto, pressione o pé para baixo e para a mão, para adicionar o quadril esticado, levante o quadril da perna que está segurando em direção ao teto.","Troque de lado."]],"On_Your_Side_Quad_Stretch":["No seu lado Quad Stretch",["Comece deitado do lado direito, com o joelho direito dobrado em um ângulo de 90 graus descansando no chão na sua frente (isso estabiliza o torso).","Dobre o joelho esquerdo e segure o pé esquerdo com a mão esquerda para esticar o flexor do quadril, pressione o quadril esquerdo para frente enquanto empurra o pé esquerdo para trás para a mão."]],"One-Arm_Dumbbell_Row":["Fila halteres de um braço só",["Escolha um banco plano e coloque um haltere em cada lado.","Coloque a perna direita em cima da extremidade do banco, dobre o tronco para frente da cintura até que sua parte superior do corpo seja paralela ao chão, e coloque sua mão direita na outra extremidade do banco para apoio.","Use a mão esquerda para pegar o haltere no chão e segurar o peso mantendo as costas direitas, a palma da mão deve estar virada para o tronco, esta será a sua posição inicial.","Puxe a resistência para o lado do peito, mantendo seu braço superior perto do seu lado e mantendo o tronco parado. Respire enquanto você executa este passo. Dica: Concentre-se em apertar os músculos das costas uma vez que você atinge a posição contraída total.","Abaixe a resistência para a posição inicial.","Repita o movimento para a quantidade especificada de repetições.","Troque de lado e repita novamente com o outro braço."]],"One-Arm_Flat_Bench_Dumbbell_Flye":["Um braço, um braço, um arco, um sino, um sino, um braço, um braço, um braço, um braço, um braço, um braço, um braço, um braço, um braço, um braço, um braço, um braço, um braço, um braço, um braço.",["Deite-se em um banco plano com um haltere em uma mão descansando em cima de sua coxa, a palma da sua mão com o haltere deve estar em um aperto neutro.","Usando suas coxas para ajudá-lo a levantar o haltere, limpe o haltere para que você possa segurá-lo na sua frente com seu braço levantado sendo totalmente estendido.","Seu braço com o peso deve ter uma leve dobra no cotovelo para evitar o estresse no tendão do bíceps, comece a baixar o braço com o peso dentro, em um arco largo, até sentir um estiramento no peito, respire enquanto realiza essa parte do movimento, lembre-se que durante todo o movimento, seu braço de elevação deve permanecer parado, o movimento só deve ocorrer na articulação do ombro.","Retorne o braço para a posição inicial enquanto aperta os músculos do peito e expira.","Segure por um segundo na posição contratada e repita o movimento para a quantidade prescrita de repetições.","Troque de braços e repita o exercício."]],"One-Arm_High-Pulley_Cable_Side_Bends":["Dobraduras de cabo de um braço.",["Ligue uma alça padrão a uma torre, mova o cabo para a posição mais alta da polia.","Fique de lado para o cabo, com uma mão, levante e agarre o cabo com o punho.","Puxe o cabo até que o cotovelo toque o seu lado e o cabo esteja pelo seu ombro.","Posicione os pés com largura de quadril, coloque a mão livre no quadril para ajudar a medir o ponto pivô.","Mantenha o braço em posição estática, contrate oblíqua para diminuir o peso.","Quando atingir a contração máxima, solte lentamente o peso para a posição inicial, a pilha de peso nunca deve ser descarregada em uma posição de repouso, o objetivo é tensão constante durante o conjunto.","Repita para o fracasso.","Então, reposicione e repita a mesma série de movimentos no lado oposto."]],"One-Arm_Incline_Lateral_Raise":["Levantamento lateral de um braço.",["Deite-se de lado em um supino inclinado com um haltere na mão, certifique-se de que o ombro está pressionando contra o banco inclino e o braço está deitado em seu corpo com a palma ao redor do umbigo.","Segure um haltere no braço, mantendo-o estendido na sua frente, paralelo ao chão.","Enquanto mantém o haltere paralelo ao chão o tempo todo, faça um aumento lateral, seu braço deve viajar direto até o teto, e expire enquanto você faz esse movimento, segure o haltere na posição e sinta a contração nos ombros por um segundo.","Enquanto inala o peso em seu corpo de volta para a posição inicial.","Repita o movimento para a quantidade prescrita de repetições.","Troque de braços e repita o movimento."]],"One-Arm_Kettlebell_Clean":["Um braço, Kettlebell limpo.",["Coloque uma campainha entre os pés, enquanto você se curva para pegar a chaleira, empurre seu traseiro para trás e mantenha seus olhos olhando para frente.","Limpe a chaleira até os ombros estendendo-se pelas pernas e quadris enquanto levanta a chaleira em direção ao ombro.","Retorne o peso para a posição inicial."]],"One-Arm_Kettlebell_Clean_and_Jerk":["Um braço, Kettlebell, limpo e idiota.",["Segure uma campainha perto do cabo.","Limpe a chaleira para o ombro estendendo-se através das pernas e quadris enquanto puxa a chaleira para o ombro gira o pulso enquanto faz isso, para que a palma da mão olhe para a frente.","Mergulhe o corpo dobrando os joelhos, mantendo o tronco ereto.","Imediatamente inverta a direção, dirigindo através dos saltos, em essência pulando para criar impulso, enquanto você faz isso, pressione a chaleira para cima para bloquear estendendo os braços, usando o impulso do seu corpo para mover o peso.","Receba o peso acima retornando a uma posição de agachamento abaixo do peso.","Mantendo o peso em cima, volte para uma posição de pé, abaixe o peso para o chão para realizar a próxima repetição."]],"One-Arm_Kettlebell_Floor_Press":["Um braço Kettlebell Floor Press",["Deite-se no chão segurando uma chaleira com uma mão, com o braço apoiado pelo chão.","Aperte a chaleira direto para o teto, girando seu pulso.","Abaixe a campainha de volta para a posição inicial e repita."]],"One-Arm_Kettlebell_Jerk":["Um braço, Kettlebell, idiota.",["Segure uma campainha perto do cabo, limpe a chaleira no ombro estendendo-se pelas pernas e quadris enquanto puxa a chaleira para o ombro, gire o pulso enquanto faz isso, para que a palma da mão se estenda para frente, esta será a sua posição inicial.","Mergulhe o corpo dobrando os joelhos, mantendo o tronco ereto.","Imediatamente inverta a direção, dirigindo através dos saltos, em essência pulando para criar impulso, enquanto você faz isso, pressione a chaleira acima para bloquear, estendendo os braços, usando o impulso do seu corpo para mover o peso, recebendo o peso acima, retornando para uma posição de agachamento abaixo do peso, mantendo o peso acima, retornando para uma posição de pé.","Abaixe o peso para realizar a próxima repetição."]],"One-Arm_Kettlebell_Military_Press_To_The_Side":["Um braço Kettlebell Press militar para o lado",["Limpe uma chaleira no ombro, limpe a chaleira no ombro estendendo-se pelas pernas e quadris enquanto puxa a chaleira para o ombro, gire o pulso enquanto faz isso, para que a palma da mão se estenda para dentro, esta será sua posição inicial.","Olhe para a chaleira e pressione para cima e para fora até que esteja trancada acima.","Abaixe a chaleira para o ombro, sob controle e repita, certifique-se de contrair seu traseiro e estômago com força para aumentar a estabilidade e força."]],"One-Arm_Kettlebell_Para_Press":["Um braço Kettlebell Para Press",["Limpe uma chaleira no ombro, limpe a chaleira no ombro estendendo-se pelas pernas e quadris enquanto puxa a chaleira para o ombro, gire o pulso como faz, para que a palma da mão se estenda para frente, esta será a sua posição inicial.","Segure a chaleira com o cotovelo para o lado, e pressione-a para cima e para fora até que esteja trancada acima.","Abaixe a chaleira para o ombro, sob controle e repita, certifique-se de contrair seu traseiro e estômago com força para aumentar a estabilidade e força."]],"One-Arm_Kettlebell_Push_Press":["Um braço, Kettlebell, pressione.",["Segure uma campainha perto do cabo, limpe a chaleira no ombro estendendo-se pelas pernas e quadris enquanto puxa a chaleira para o ombro, gire o pulso enquanto faz isso, para que a palma da mão se estenda para frente, esta será a sua posição inicial.","Mergulhe o corpo dobrando os joelhos, mantendo o tronco ereto.","Imediatamente inverta a direção, dirigindo através dos calcanhares, em essência pulando para criar impulso, enquanto você faz isso, pressione a chaleira acima para bloquear, estendendo os braços, usando o impulso do seu corpo para mover o peso, baixar o peso para executar a próxima repetição."]],"One-Arm_Kettlebell_Row":["Fila Kettlebell de um braço",["Coloque uma campainha na frente dos pés, dobre os joelhos um pouco e depois empurre o traseiro para fora o máximo possível para chegar na posição inicial, pegue a chaleira e puxe-a para o estômago, retraia o ombro e flexione o cotovelo, mantenha as costas retas, abaixe e repita."]],"One-Arm_Kettlebell_Snatch":["Um braço, Kettlebell Snatch.",["Coloque uma campainha entre os pés, dobre os joelhos e empurre a bunda para voltar para a posição inicial.","Olhe em frente e balance o sino de volta entre as pernas.","Imediatamente inverta a direção e dirija com seus quadris e joelhos, acelerando a chaleira para cima, enquanto a chaleira sobe ao seu ombro, gira sua mão e bate direto para cima, usando o impulso para receber o peso bloqueado para cima."]],"One-Arm_Kettlebell_Split_Jerk":["Um braço Kettlebell Split Jerk",["Segure uma campainha perto do cabo, limpe a chaleira no ombro estendendo-se pelas pernas e quadris enquanto puxa a chaleira para o ombro, gire o pulso enquanto faz isso, para que a palma da mão se estenda para frente, esta será a sua posição inicial.","Mergulhe o corpo dobrando os joelhos, mantendo o tronco ereto.","Imediatamente inverta a direção, dirigindo através dos saltos, em essência pulando para criar impulso, enquanto você faz isso, pressione a chaleira para cima para bloquear estendendo os braços, usando o impulso do seu corpo para mover o peso.","Receba o peso acima retornando a uma posição de agachamento abaixo do peso, posicionando uma perna na sua frente e uma perna atrás de você.","Mantendo o peso acima, volte para uma posição de pé e junte seus pés."]],"One-Arm_Kettlebell_Split_Snatch":["Um braço Kettlebell Split Snatch",["Segure uma campainha com uma mão pelo cabo.","Agache-se em direção ao chão, e então inverta o movimento, estendendo os quadris, joelhos e, finalmente, os tornozelos, para levantar a chaleira acima.","Depois de estender completamente o corpo, desça em uma posição de pulmão para receber os pesos acima, uma perna para frente e uma perna para trás.","Retorne a uma posição de pé, segurando o peso acima, e junte os pés, abaixe o peso para voltar à posição inicial."]],"One-Arm_Long_Bar_Row":["Fila de Barras de Um Braço",["Coloque uma barra em uma mina terrestre ou em um canto para evitar que ela se mova.","Fique ao lado do bar, e segure com uma mão perto do colarinho, usando seus quadris e pernas, levante-se para uma posição de pé.","Assuma uma posição de joelho dobrado com os quadris para trás e o peito para cima, seu braço deve ser estendido, esta será sua posição inicial.","Puxe o peso para o seu lado, retraindo o ombro e flexionando o cotovelo.","Após uma breve pausa, volte para a posição inicial."]],"One-Arm_Medicine_Ball_Slam":["Batida de um braço de medicina.",["Comece em pé com uma postura atlética e cambaleante, segure uma bola de remédio com uma mão, do mesmo lado da perna de trás.","Comece enrolando o braço, levantando a bola de remédio acima da cabeça, enquanto você faz isso, estenda-se através dos quadris, joelhos e tornozelos para carregar para a batida.","Na extensão do pico, flexione os ombros, a coluna vertebral e os quadris para jogar a bola no chão diretamente na sua frente.","Pegue a bola no salto e continue para o número desejado de repetições."]],"One-Arm_Open_Palm_Kettlebell_Clean":["Um braço aberto Palm Kettlebell limpo",["Coloque uma campainha entre os pés.","Pegue o cabo com uma mão e levante a chaleira rapidamente, deixe-a virar para que a bola da chaleira caia na palma da sua mão.","Jogue a chaleira na sua frente e pegue o cabo com uma mão.","Leve a chaleira para o chão e repita."]],"One-Arm_Overhead_Kettlebell_Squats":["Overhead Kettlebell Squats",["Limpe a chaleira com um braço, limpe o ombro estendendo-se pelas pernas e quadris enquanto puxa a chaleira para o ombro, gire o pulso enquanto faz isso, pressione o peso sobre o ombro estendendo-se pelo cotovelo, esta será a sua posição inicial.","Olhando para frente e mantendo uma chaleira trancada acima de você, flexione os joelhos e quadris e abaixe o tronco entre as pernas, mantendo a cabeça e o peito para cima.","Pausa na posição inferior por um segundo antes de voltar ao topo, dirigindo através dos calcanhares dos pés."]],"One-Arm_Side_Deadlift":["Um braço-lado Deadlift",["Dobre os joelhos e abaixe o corpo até conseguir alcançar o barbelo.","Pegue a barra como se estivesse pegando uma pasta, já que a barra está de lado, pode precisar de um envoltório de pulso se estiver usando uma quantidade significativa de peso.","Use suas pernas para ajudar a levantar o barbelo enquanto expira.","Leve a campainha lentamente para baixo enquanto inala.","Repita para a quantidade recomendada de repetições.","Troque de braços e repita o movimento."]],"One-Arm_Side_Laterals":["Laterais de um braço só",["Pegue um haltere e coloque-o em uma de suas mãos, sua mão que não levanta deve ser usada para agarrar algo estável, como uma pressão de banco inclinada, incline-se para o braço que levanta e afaste-se da mão que está segurando o banco inclinado, pois isso permitirá que você mantenha o equilíbrio.","Fique com um torso reto e tenha o haltere ao seu lado com a palma da mão virada para você.","Enquanto mantém o tronco parado (sem balanço), levante o haltere para o seu lado com uma leve curva no cotovelo e sua mão ligeiramente inclinada para a frente como se derramasse água em um copo. Continue a subir até que o braço esteja paralelo ao chão. Expire enquanto executa este movimento e pause por um segundo no topo.","Abaixe o haltere lentamente para a posição inicial enquanto inala.","Repita para a quantidade recomendada de repetições.","Troque de braços e repita o exercício."]],"One-Legged_Cable_Kickback":["Kickback de cabo de uma perna",["Coloque um punho de couro no tornozelo em uma polia de cabo baixa e coloque o punho no tornozelo.","Enfrente a pilha de peso a uma distância de cerca de dois pés, agarrando a estrutura de aço para apoio.","Enquanto mantém seus joelhos e quadris ligeiramente dobrados e seus abdominais apertados, contraia seus glúteos para lentamente \"chutar\" a perna de trabalho de volta em um arco semicircular tão alto quanto confortavelmente irá como você expirar.","Agora, lentamente, traga sua perna de trabalho para frente, resistindo à tração do cabo até chegar à posição inicial.","Repita para a quantidade recomendada de repetições.","Troque de pernas e repita o movimento para o outro lado."]],"One_Arm_Against_Wall":["Um braço contra a parede",["De uma posição em pé, coloque um braço dobrado contra uma parede ou porta.","Incline-se lentamente em direção ao braço até sentir um estiramento em seus lats."]],"One_Arm_Chin-Up":["Um braço para cima.",["Para este exercício, comece colocando uma toalha em volta de uma barra de queixo.","Pegue a barra de queixo para cima com a palma da mão virada para você, uma mão estará segurando a barra de queixo para cima e a outra estará agarrando a toalha.","Traga seu torso de volta cerca de 30 graus, enquanto cria uma curvatura na parte inferior das costas e coloca seu peito para fora.","Puxe seu torso para cima até que a barra toque seu peito superior puxando os ombros e os braços para baixo e para trás. Expire enquanto você executa esta parte do movimento. Dica: Concentre-se em apertar os músculos das costas uma vez que você atinge a posição contraída total.","Depois de um segundo na posição contraída, comece a inalar e lentamente abaixe seu torso de volta para a posição inicial quando seus braços estão totalmente estendidos e os lats estão totalmente esticados.","Repita esta moção para a quantidade prescrita de repetições.","Troque de braços e repita o movimento."]],"One_Arm_Dumbbell_Bench_Press":["Um braço halteres Bench Press",["Deite-se em um banco plano com um haltere em uma mão em cima da coxa.","Usando sua coxa para ajudá-lo a levantar o haltere, limpar o haltere para que você possa segurá-lo na sua frente com a largura do ombro, usar a mão que você não está levantando para ajudar a posicionar o haltere sobre você corretamente.","Uma vez na largura do ombro, gire o pulso para frente para que a palma da sua mão esteja virada para longe de você.","Mantenha o controle total do haltere o tempo todo.","Quando expirar, empurre os halteres usando seus músculos peitorais, tranque os braços na posição contraída, aperte o peito, segure por um segundo e comece a descer lentamente.","Repita o movimento para a quantidade prescrita de repetições do seu programa de treinamento.","Troque de braços e repita o movimento."]],"One_Arm_Dumbbell_Preacher_Curl":["Um braço halteres Preacher Curl",["Pegue um haltere com o braço direito e coloque o braço superior em cima do banco do pastor ou do banco incline.","Enquanto você respira, abaixe lentamente o haltere até que seu braço seja estendido e o bíceps esteja totalmente esticado.","Quando você expirar, use os bíceps para enrolar o peso até que seu bíceps esteja totalmente contraído e o haltere esteja na altura do ombro.","Aperte o bíceps com força por um segundo na posição contraída e repita a quantidade recomendada de repetições.","Troque de braços e repita o movimento."]],"One_Arm_Floor_Press":["Um braço, pressione o chão.",["Deite-se em uma superfície plana com as costas pressionando contra o chão ou um tapete de exercício.","Quando começar, seu braço deve estar quase totalmente estendido, similar à posição inicial de um banco de pressão, no entanto, desta vez seu aperto será neutro (palmas viradas para o tronco).","Certifique-se de que a mão que você não está usando para levantar o peso é colocado ao seu lado.","Comece o exercício baixando a campainha até que seu cotovelo toque o chão, certifique-se de respirar porque esta é a parte excêntrica do exercício.","Então comece a levantar a campainha de volta para a posição inicial, lembre-se de expirar durante a concêntrica (parte de elevação do exercício).","Repita até que tenha realizado suas repetições recomendadas.","Troque de braços e repita o movimento."]],"One_Arm_Lat_Pulldown":["Um Braço Lat puxar para baixo",["Escolha um peso adequado e ajuste a joelheira para ajudá-lo a se abaixar.","Puxe o cabo para baixo, apertando o cotovelo para o lado enquanto flexiona o cotovelo.","Pausar no fundo do movimento, e então lentamente retornar a alça para a posição inicial.","Para várias repetições, evite retornar completamente o peso para manter a tensão nos músculos sendo trabalhados."]],"One_Arm_Pronated_Dumbbell_Triceps_Extension":["Um braço pronated halteres Tríceps extensão",["Deite-se em um banco enquanto segura um haltere com os braços estendidos, seu braço deve ser perpendicular ao seu corpo, a palma da sua mão deve estar voltada para seus pés, como um aperto pronado é necessário para realizar este exercício.","Coloque sua mão no bíceps para apoio.","Lentamente comece a baixar o haltere enquanto respira.","Então, comece a levantar o haltere para cima enquanto contrai o tríceps.","Repita até que tenha feito suas repetições.","Troque de braços e repita o movimento."]],"One_Arm_Supinated_Dumbbell_Triceps_Extension":["Um braço supinado halteres Tríceps extensão",["Deite-se em um banco enquanto segura um haltere com os braços abertos, seu braço deve ser perpendicular ao seu corpo, a palma da sua mão deve estar voltada para o seu rosto, como um aperto supinado é necessário para realizar este exercício.","Coloque sua mão no bíceps para apoio.","Lentamente comece a baixar o haltere enquanto respira.","Então, comece a levantar o haltere para cima enquanto contrai o tríceps.","Repita até que tenha feito suas repetições.","Troque de braços e repita o movimento.","Troque de braços novamente e repita o movimento."]],"One_Half_Locust":["Uma Meia Locust.",["Deite de bruços no chão.","Coloque sua mão esquerda sob seu osso esquerdo para encaixotar seu quadril e osso púbico.","Dobre o joelho direito para segurar o pé na mão direita.","Levante o pé no ar e, ao mesmo tempo, levante os ombros do chão, isso também estica o flexor do quadril direito, o peito e os ombros, mude de lado, se não incomodar as costas, pode tentar com os braços e as pernas ao mesmo tempo."]],"One_Handed_Hang":["Um enforcamento de mão.",["Segure os pés no chão ou um degrau, deixe que a maioria do seu peso pendure dessa mão, mantendo os pés no chão, segure por 10-20 segundos e mude de lado."]],"One_Knee_To_Chest":["Um Joelho para o peito",["Comece deitado no chão.","Estenda uma perna e puxe o outro joelho para o peito, segure sob a articulação do joelho para proteger a rótula.","Puxe suavemente o joelho em direção ao nariz.","Isso alonga as nádegas e a parte de trás da perna dobrada e o flexor do quadril da perna reta."]],"One_Leg_Barbell_Squat":["Um Agachamento de Barbell Perna",["Comece por ficar de 2 a 3 pés na frente de um banco plano, com as costas viradas para o banco, e ter uma campainha na sua frente no chão, e seus pés devem ter a largura do ombro um do outro.","Dobre os joelhos e use um aperto pronado com as mãos mais largas do que a largura do ombro para levantar a barba até que possa descansar no peito.","Então levante a campainha sobre a cabeça e coloque-a na base do pescoço, mova um pé para trás para que seu dedo do pé esteja descansando no banco plano, seu outro pé deve ficar parado na sua frente, mantenha a cabeça erguida o tempo todo, e fique desbalanceado e mantenha as costas retas.","Enquanto você inala, abaixe lentamente a perna até que sua coxa fique paralela ao chão, nesse ponto, seu joelho deve estar sobre os dedos dos pés, seu peito deve estar diretamente acima do meio da coxa.","Liderando com o peito e quadris e contraindo o quadríceps, eleve sua perna de volta à posição inicial enquanto expira.","Repita para a quantidade recomendada de repetições.","Troque de pernas e repita o movimento."]],"Open_Palm_Kettlebell_Clean":["Abra Palm Kettlebell Limpo",["Coloque uma campainha entre os pés, limpe a chaleira estendendo-se pelas pernas e quadris enquanto levanta a chaleira em direção aos ombros.","Solte a chaleira quando ela subir, e deixe-a virar para que a bola da chaleira caia nas palmas de suas mãos.","Solte a chaleira na sua frente e pegue o cabo com as duas mãos."]],"Otis-Up":["Otis-Up",["Segure os pés e deite-se no chão, seus joelhos devem estar dobrados, segure um peso com as duas mãos no peito, esta será sua posição inicial.","Iniciar o movimento flexionando os quadris e a coluna para levantar o tronco do chão.","Enquanto você sobe, pressione o peso para cima para que esteja acima de sua cabeça no topo do movimento.","Devolva o peso ao seu peito enquanto reverte o movimento de sentar, garantindo que não desça até o chão."]],"Overhead_Cable_Curl":["Overhead Cabo Curl",["Para começar, defina um peso confortável em cada lado da máquina de polias.","Agora ajuste a altura das polias de cada lado e certifique-se de que elas estejam posicionadas em uma altura superior à dos seus ombros.","Seus braços devem ser estendidos e paralelos ao chão com os pés posicionados na largura do ombro, separados uns dos outros.","Enquanto expira, lentamente aperte os bíceps de cada lado até que seus antebraços e bíceps toquem.","Enquanto inalar, mova seus antebraços de volta para a posição inicial.","Repita para a quantidade recomendada de repetições prescritas no seu programa."]],"Overhead_Lat":["Overhead Lat",["Sente-se no chão com seu parceiro atrás de você, levante um braço para cima, e flexione o cotovelo, tentando tocar sua mão para as costas, seu parceiro deve segurar seu tríceps e pulso, esta será sua posição inicial.","Tentativa de puxar seu braço para o seu lado como seu parceiro impede que você realmente faça isso.","Depois de 10-20 segundos, relaxe o braço e permita que seu parceiro estique ainda mais a lat aplicando pressão suave no tríceps."]],"Overhead_Slam":["Overhead Slam",["Segure uma bola de medine com as duas mãos e fique com os pés na largura do ombro.","Iniciar o contra-movimento levantando a bola acima de sua cabeça e estendendo completamente seu corpo.","Reverta o movimento, batendo a bola no chão diretamente na sua frente o mais forte que puder.","Receba a bola com as duas mãos no salto e repita o movimento."]],"Overhead_Squat":["Overhead Squat",["Comece por ter uma campainha na sua frente no chão, seus pés devem ser mais largos que a largura do ombro, separados um do outro.","Dobrar os joelhos e usar um aperto pronado (palmas voltados para você) para agarrar o barbante. Suas mãos devem estar em uma largura maior do que o ombro longe um do outro antes de levantar.","Mova a campainha para trás e levemente para trás da cabeça e certifique-se de que seus braços estejam totalmente estendidos, mantenha a cabeça erguida o tempo todo e também mantenha as costas retas, retire suas omoplatas, esta é sua posição inicial.","Abaixe lentamente o peso dobrando os joelhos até que suas coxas fiquem paralelas ao chão enquanto inala.","Agora use seus pés e pernas para ajudar a trazer o peso de volta para a posição inicial enquanto expira.","Repita para a quantidade recomendada de repetições."]],"Overhead_Stretch":["Overhead Stretch",["Levantem os dedos e abram as palmas do teto, abaixem os ombros enquanto estendem os braços.","Para criar um estiramento completo do torso, puxe o cóccix para baixo e estabilize o torso enquanto faz isso, estique os músculos na frente e na parte de trás do tronco."]],"Overhead_Triceps":["Tríceps Overhead",["Sente-se no chão com seu parceiro atrás de você, levante um braço direito, e flexione o cotovelo, tentando tocar sua mão nas costas, seu parceiro deve segurar seu cotovelo e pulso, esta será sua posição inicial.","Tentar estender o braço direto para o ar enquanto seu parceiro o impede de fazer isso.","Depois de 10-20 segundos, relaxe o braço e deixe seu parceiro esticar ainda mais o tríceps aplicando pressão suave no pulso."]],"Pallof_Press":["Pallof Press",["Ligue uma alça padrão a uma torre e, se possível, coloque o cabo na altura do ombro.","Com o lado do cabo, segure o cabo com as duas mãos e afaste-se da torre, deve estar a aproximadamente um braço longe da polia, com a tensão do peso no cabo.","Com os pés posicionados com a largura do quadril afastados e joelhos ligeiramente dobrados, segure o cabo no meio do peito.","Aperte o cabo longe do peito, estendendo os dois braços.","Mantenha a repetição por vários segundos antes de voltar para a posição inicial.","Na conclusão do set, repita de frente para o outro lado."]],"Pallof_Press_With_Rotation":["Imprensa Pallof com rotação",["Ligue uma alça padrão a uma torre, e posicione o cabo à altura do ombro.","Com o lado do cabo, pegue o cabo com uma mão e afaste-se da torre, deve estar aproximadamente longe da polia, com a tensão do peso no cabo, alinhando o braço estendido com o cabo.","As duas mãos devem estar na alça neste momento.","Em frente, pressione o cabo para longe do peito.","Mantendo seus quadris retos, torça o torso longe da polia até conseguir uma rotação de quarto.","Mantenha sua postura rígida e braços retos, volte para a posição neutra de forma lenta e controlada, seus braços devem ser estendidos na sua frente.","Com a tensão lateral ainda ativando seu núcleo, traga suas mãos para seu peito e imediatamente pressione para fora para uma posição totalmente estendida.","Repita para o fracasso.","Então, reposicione e repita a mesma série de movimentos no lado oposto."]],"Palms-Down_Dumbbell_Wrist_Curl_Over_A_Bench":["\"Curva de Pulso de Mumbum de Palmas\"",["Comece colocando dois halteres em um lado de um banco plano.","Ajoelhe-se de joelhos para que seu corpo esteja virado para o banco plano.","Use seus braços para agarrar os dois halteres com um aperto pronado (palmas voltados para baixo) e trazê-los para cima para que seus antebraços estão descansando contra o banco plano.","Comece enrolando seu pulso para cima e expirando.","Abaixem lentamente os pulsos para a posição inicial enquanto inalam.","Seus antebraços devem estar parados, pois seu pulso é o único movimento necessário para realizar esse exercício.","Repita para a quantidade recomendada de repetições."]],"Palms-Down_Wrist_Curl_Over_A_Bench":["Pulso de mão para baixo Curva sobre uma bancada",["Comece colocando uma campainha em um lado de um banco plano.","Ajoelhe-se de joelhos para que seu corpo esteja virado para o banco plano.","Use os braços para agarrar a campainha com um aperto pronado (palmas para baixo) e trazê-los para cima para que seus antebraços estão descansando contra o banco plano.","Comece enrolando seu pulso para cima e expirando.","Abaixem lentamente os pulsos para a posição inicial enquanto inalam.","Seus antebraços devem estar parados, pois seu pulso é o único movimento necessário para realizar esse exercício.","Repita para a quantidade recomendada de repetições."]],"Palms-Up_Barbell_Wrist_Curl_Over_A_Bench":["Palmas para cima Barbell Wrist Curl sobre uma bancada",["Comece colocando uma campainha em um lado de um banco plano.","Ajoelhe-se de joelhos para que seu corpo esteja virado para o banco plano.","Use os braços para agarrar a barba com um aperto supinado (palmas para cima) e trazê-los para cima de modo que seus antebraços estão descansando contra o banco plano.","Comece enrolando seu pulso para cima e expirando.","Abaixem lentamente os pulsos para a posição inicial enquanto inalam.","Seus antebraços devem estar parados, pois seu pulso é o único movimento necessário para realizar esse exercício.","Repita para a quantidade recomendada de repetições."]],"Palms-Up_Dumbbell_Wrist_Curl_Over_A_Bench":["\"Curva de Pulso de Mumbum de Palmas\"",["Comece colocando dois halteres em um lado de um banco plano.","Ajoelhe-se de joelhos para que seu corpo esteja virado para o banco plano.","Use seus braços para agarrar os dois halteres com um aperto supinado (palmas para cima) e trazê-los para cima para que seus antebraços estão descansando contra o banco plano.","Comece enrolando seu pulso para cima e expirando.","Abaixe lentamente os pulsos para a posição inicial enquanto inala.","Seus antebraços devem estar parados, pois seu pulso é o único movimento necessário para realizar esse exercício.","Repita para a quantidade recomendada de repetições."]],"Parallel_Bar_Dip":["Paralelo Bar Dip",["Coloque uma mão em cada barra, e então dê um pequeno salto para ajudá-lo a entrar na posição inicial com os braços trancados.","Comece flexionando o cotovelo, baixando o corpo até os braços quebrarem 90 graus, evite balançar e mantenha uma boa postura ao longo da descida.","Reverta o movimento estendendo o cotovelo, empurrando-se de volta para a posição inicial.","Repita para o número desejado de repetições."]],"Pelvic_Tilt_Into_Bridge":["Pelvic Incline para a ponte.",["Deite-se com os pés no chão, calcanhares debaixo dos joelhos.","Levante o cóccix até o teto para esticar as costas.","Para entrar em uma ponte, levante toda a coluna, exceto o pescoço."]],"Peroneals-SMR":["Peroneals-SMR",["Deite-se de lado, apoiando seu peso no antebraço e em um rolo de espuma colocado do lado de fora de sua perna inferior, sua perna superior pode estar em cima de sua perna inferior, ou você pode atravessá-la na sua frente.","Levante os quadris do chão e comece a rolar de baixo do joelho para cima do tornozelo do lado da perna, parando em pontos de tensão por 10-30 segundos."]],"Peroneals_Stretch":["Peroneals Stretch",["Em uma posição sentada, amarre um cinto, uma corda ou uma faixa em torno de um pé.","Com a perna estendida e o calcanhar fora do chão, puxe o cinto para que o pé seja invertido, com o interior do pé sendo puxado em sua direção."]],"Physioball_Hip_Bridge":["Ponte do Hip Physioball",["Deite-se em uma bola para que sua parte superior esteja na bola com seus quadris sem apoio, ambos os pés devem estar achatados no chão, largura do quadril afastada ou maior.","Comece estendendo os quadris usando seus glúteos e isquiotibiais, elevando seus quadris para cima enquanto faz ponte.","Pause no topo da moção e volte para a posição inicial."]],"Pin_Presses":["Pin Pressiona",["As prensas removem a fase excêntrica do supino, desenvolvendo força inicial, e também permitem treinar uma amplitude de movimento desejada.","O banco deve ser colocado em um rack de energia, definir os pinos para o ponto desejado em sua amplitude de movimento, seja apenas bloqueio ou uma polegada fora de seu peito, a barra deve ser movida para os pinos e preparada para levantar.","Comece por se deitar no banco, com a barra diretamente acima do ponto de contato durante o seu banco regular, coloque os pés embaixo de você e arqueie as costas, use a barra para ajudar a suportar seu peso, levante o ombro do banco e retraia-os, apertando as omoplatas juntos, use seus pés para levar suas armadilhas para o banco, mantenha esta posição firme do corpo durante todo o movimento.","A barra, o pulso e o cotovelo devem ficar na linha o tempo todo, focar em apertar a barra e tentar separá-la.","Os cotovelos devem ser dobrados até o bloqueio.","Devolva a barra aos pinos, pausando antes de começar a próxima repetição."]],"Piriformis-SMR":["Piriformis-SMR",["Sente-se com as nádegas em cima de um rolo de espuma, dobre os joelhos e cruze uma perna para que o tornozelo fique sobre o joelho.","Passe seu peso para o lado da perna cruzada, rolando sobre as nádegas até sentir tensão no glúteo superior, você pode ajudar o estiramento usando uma mão para puxar o joelho curvado em direção ao peito, mantenha esta posição por 10-30 segundos e depois mude de lado."]],"Plate_Pinch":["Pinch de placa",["Pegue duas placas largas e junte-as com os lados lisos voltados para fora.","Use seus dedos para segurar a parte externa da placa e seu polegar para o outro lado segurando ambas as placas juntas.","Aperte a placa com os dedos e o polegar, segure esta posição o máximo que puder.","Repita para a quantidade recomendada de conjuntos prescritos no seu programa.","Troque de braços e repita os movimentos."]],"Plate_Twist":["Torção de Placas",["Deite-se no chão ou em um tapete de exercício com as pernas totalmente estendidas e sua parte superior do corpo ereto, pegue a placa pelos lados com as duas mãos na frente de seus abdominais com os braços ligeiramente dobrados.","Lentamente cruze as pernas perto dos tornozelos e levante-as do chão, seus joelhos também devem ser ligeiramente dobrados, e lembre-se, mova seu corpo para trás um pouco para ajudá-lo a se equilibrar, girando este exercício, esta é a posição inicial.","Mova a placa para o lado esquerdo e toque o chão com ela.","Volte para a posição inicial enquanto respira e repita o movimento, mas desta vez para o lado direito do corpo.","Repita para a quantidade recomendada de repetições."]],"Platform_Hamstring_Slides":["Plataforma Hamstring Slides",["Para este movimento, é necessário um piso de madeira ou similar, deite-se de costas com as pernas estendidas, coloque uma toalha de ginástica ou um peso leve sob o calcanhar, esta será a sua posição inicial.","Comece o movimento flexionando o joelho, mantendo sua outra perna reta.","Continue trazendo o calcanhar mais perto de você, deslizando-o no chão.","Em flexão total do joelho, inverta o movimento para voltar à posição inicial."]],"Plie_Dumbbell_Squat":["Plie halteres Squat",["Segure um haltere na base com as duas mãos e fique de pé, mova as pernas para que elas sejam mais largas que a largura do ombro um do outro, com os joelhos ligeiramente dobrados.","Seus dedos devem estar virados para fora, seus braços devem estar parados enquanto realizam o exercício.","Curve lentamente os joelhos e abaixe as pernas até que suas coxas estejam paralelas ao chão.","Pressione principalmente com o calcanhar do pé para trazer o corpo de volta à posição inicial enquanto expira.","Repita para a quantidade recomendada de repetições."]],"Plyo_Kettlebell_Pushups":["Plyo Kettlebell flexões",["Coloque uma chaleira no chão, coloque-se em posição de flexão, de pé com uma mão no chão e uma mão segurando a chaleira, com os cotovelos estendidos.","Comece se rebaixando o mais baixo que puder, mantendo suas costas retas.","Rápido e vigorosamente inverter a direção, empurrando-se para o outro lado da chaleira, trocando de mãos enquanto você faz isso."]],"Plyo_Push-up":["Plyo Push-up",["Mova-se para uma posição propensa no chão, apoiando seu peso em suas mãos e dedos dos pés.","Seus braços devem ser estendidos com as mãos ao redor da largura do ombro, mantenha seu corpo reto durante todo o movimento, esta será sua posição inicial.","Desça flexionando o cotovelo, baixando o peito em direção ao chão.","Na parte inferior, inverta o movimento empurrando-se através da extensão do cotovelo o mais rápido possível.","Retorne à posição inicial e repita o exercício.","Para aumentar a dificuldade, adicione palmas ao movimento enquanto você está no ar."]],"Posterior_Tibialis_Stretch":["Esticamento posterior de Tibialis",["Em uma posição sentada, amarre um cinto, uma corda ou uma faixa em torno de um pé.","Com a perna estendida e o calcanhar fora do chão, puxe o cinto para que o pé seja everted, com o lado de fora do pé sendo puxado em sua direção."]],"Power_Clean":["Poder Limpo.",["Fique com os pés um pouco mais largos do que a largura do ombro e os dedos dos pés apontando ligeiramente.","Suas mãos devem ser um pouco mais largas do que a largura do ombro dos joelhos com cotovelos estendidos.","Coloque o bar cerca de 1 polegada na frente de suas canelas e sobre as bolas de seus pés.","Suas costas devem ser planas ou ligeiramente arqueadas, seu peito levantado e para fora e suas omoplatas devem ser retraídas.","Mantenha sua cabeça em uma posição neutra (em linha com coluna vertebral e não inclinada ou girada) com seus olhos focados na frente.","Levante a barra do chão com força estendendo os quadris e os joelhos enquanto você expira. Dica: O tronco superior deve manter o mesmo ângulo. Não se dobre na cintura ainda e não deixe os quadris subir antes dos ombros (isso teria o efeito de empurrar os glúteos no ar e esticar os isquiotibiais.","Mantenha os cotovelos estendidos com a cabeça em posição neutra e os ombros sobre a barra.","Como o bar levanta mantê-lo o mais perto possível das canelas.","Quando a barra passar os joelhos, empurre seus quadris para frente e ligeiramente dobre os joelhos para evitar trancá-los.","Mantenha as costas planas ou ligeiramente arqueadas, cotovelos totalmente estendidos e sua cabeça neutra.","Inspire e então forçosamente e rapidamente estenda seus quadris e joelhos e fique em seus dedos dos pés.","Mantenha a barra o mais perto possível do seu corpo. e mantenha os ombros sobre a barra e os braços retos o máximo possível.","Quando suas juntas inferiores estiverem totalmente estendidas, encoste os ombros para cima rapidamente sem deixar os cotovelos flexionarem ainda.","Enquanto os ombros atingem a altura mais alta, flexionem seus cotovelos para começarem a puxar seu corpo para baixo da barra.","Devido à natureza explosiva desta fase, seu torso será ereto ou com um arco para trás, sua cabeça será inclinada para trás ligeiramente e seus pés podem perder contato com o chão.","Depois que o corpo inferior estiver totalmente estendido e a barra chegar perto da altura máxima, puxe seu corpo para baixo da barra e gire os braços ao redor e abaixo da barra.","Ao mesmo tempo, flexione os quadris e joelhos em uma posição de quarto de agachamento.","Uma vez que os braços estão sob a barra, inale e levante os cotovelos para posicionar os braços superiores paralelos ao chão.","Pegue o bar com um torso ereto e apertado, uma posição neutra na cabeça e pés chatos.","Levante-se estendendo os quadris e joelhos para uma posição totalmente ereta.","Abaixe a barra reduzindo gradualmente a tensão muscular dos braços para permitir uma descida controlada da barra para as coxas.","Ao mesmo tempo, flexione os quadris e joelhos para amortecer o impacto da barra nas coxas.","Agache-se com os cotovelos estendidos até a barra tocar o chão.","Comece de novo na Fase 1 e repita a quantidade recomendada de repetições."]],"Power_Clean_from_Blocks":["Energia limpa dos blocos.",["Com uma campainha nas caixas da altura desejada, segure bem fora das pernas, abaixe os quadris com o peso focado nos calcanhares, costas retas, cabeça virada para a frente, peito para cima, com os ombros bem na frente do bar, esta será a sua posição inicial.","Comece o primeiro puxão dirigindo pelos calcanhares, estendendo os joelhos, seu ângulo de costas deve permanecer o mesmo, e seus braços devem permanecer retos, à medida que a barra se aproxima da posição média da coxa, comece a se estender pelos quadris.","Em um movimento de salto, acelerar estendendo os quadris, joelhos e tornozelos, usando velocidade para mover a barra para cima, não deve haver necessidade de puxar ativamente através dos braços para acelerar o peso.","Enquanto a extensão completa é alcançada, a transição para o terceiro impulso é agressivamente encolhendo e flexionando os braços com os cotovelos para cima e para fora.","Recupere-se imediatamente dirigindo através dos saltos, mantendo o tronco ereto e cotovelos para cima."]],"Power_Jerk":["Punheteiro do Poder",["Em pé com o peso na frente dos ombros, comece com o mergulho, com seus pés diretamente sob seus quadris, flexione os joelhos sem mover os quadris para trás, desça apenas um pouco, e inverta a direção o mais poderosa possível.","Dirija através dos saltos criar tanta velocidade e força quanto possível, e certifique-se de mover sua cabeça para fora do caminho como o bar deixa os ombros.","No momento em que os pés saem do chão, os pés devem ser colocados na posição de recepção o mais rápido possível.","Receba o bar com os braços trancados.","Retorne a uma posição em pé."]],"Power_Partials":["Parciais de Poder",["Levante-se com o torso ereto e um haltere em cada mão sendo mantido ao longo dos braços os cotovelos devem estar perto do torso.","As palmas das mãos devem estar viradas para o torso, seus pés devem ter a largura do ombro separada, esta será a sua posição inicial.","Mantendo seus braços retos e o torso parado, levante os pesos para os seus lados até que estejam sobre a altura do ombro enquanto expira.","Sinta a contração por um segundo e comece a baixar os pesos de volta para a posição inicial enquanto inala.","Repita para a quantidade recomendada de repetições."]],"Power_Snatch":["\"Power Snatch\"",["Começar com uma barra carregada no chão, a barra deve estar perto ou tocando as canelas, e uma grande aderência deve ser tomada na barra, os pés devem estar diretamente abaixo dos quadris, com os pés virados conforme necessário, baixar os quadris, com o peito para cima e a cabeça olhando para frente, os ombros devem estar bem na frente da barra, esta será a posição inicial.","Comece o primeiro pulo dirigindo pela frente dos saltos, levantando a barra do chão, o ângulo de volta deve permanecer o mesmo até que a barra passe os joelhos.","Transição para o segundo puxão estendendo-se através dos quadris joelhos e tornozelos, dirigindo a barra para cima o mais rápido possível.","Enquanto você move seus pés para a posição de recepção, uma posição um pouco maior, puxe-se abaixo da barra enquanto você eleva a barra acima.","Volte para uma posição de pé com o peso sobre a cabeça."]],"Power_Snatch_from_Blocks":["Arremesso de Energia de Blocos",["Os pés devem estar diretamente abaixo dos quadris, com os pés virados para fora como necessário, abaixe os quadris, com o peito para cima e a cabeça olhando para frente, os ombros devem estar bem na frente da barra, com os cotovelos apontados.","Comece a primeira puxada dirigindo pela frente dos saltos, levantando a barra das caixas.","Transição para o segundo puxão estendendo-se através dos quadris joelhos e tornozelos, dirigindo a barra para cima o mais rápido possível.","Quando você mover seus pés para a posição de recepção, forçosamente puxe-se abaixo da barra enquanto você eleva a barra acima, os pés devem mover-se para fora dos quadris, como necessário.","Mantendo a barra alinhada na frente dos saltos, sua cabeça e peito para cima, dirigir através dos calcanhares dos pés para mover-se para uma posição de pé."]],"Power_Stairs":["Escadas de Energia",["Nas escadas de força, os implementos são movidos para cima de uma escada, para fins de treinamento, estes podem ser realizados com um pneu ou caixa.","Comece pegando o implemento com as duas mãos, coloque os pés largos, com a cabeça e o peito para cima, dirija pelo chão com os calcanhares, estendendo os joelhos e quadris para levantar o peso do chão.","Enquanto você se inclina para trás, tente balançar o peso para as escadas, que geralmente têm cerca de 16-18\" de altura.","Repita por 3-5 repetições, e continue com um peso mais pesado, movendo-se o mais rápido possível."]],"Preacher_Curl":["Pastor Curl.",["Para realizar esse movimento, você precisará de um banco de pregadores e uma barra E-Z.","Com os braços de cima posicionados contra o banco do pastor e o peito contra ele, segure a barra de Curl E-Z no comprimento do ombro.","Enquanto você respira, lentamente abaixe a barra até que seu braço seja estendido e o bíceps esteja totalmente esticado.","Enquanto você expira, use os bíceps para enrolar o peso até que seu bíceps esteja totalmente contraído e a barra esteja em altura do ombro.","Repita para a quantidade recomendada de repetições."]],"Preacher_Hammer_Dumbbell_Curl":["Pastor Hammer halteres Curl",["Coloque a parte superior de ambos os braços em cima do banco do pregador enquanto você segura um haltere em cada mão com as palmas viradas uma para a outra (aperto neutro).","Enquanto você respira, abaixe lentamente os halteres até que seu braço seja estendido e o bíceps esteja totalmente esticado.","Enquanto você expira, use os bíceps para enrolar o peso até que seus bíceps estejam totalmente contraídos e os halteres estejam na altura do ombro.","Aperte o bíceps com força por um segundo na posição contraída e repita a quantidade recomendada de repetições."]],"Press_Sit-Up":["Pressione Sit-Up",["Para começar, deite-se em um banco com uma campainha no peito, posicione suas pernas para que fiquem seguras na extensão do banco abdominal, esta é a posição inicial.","Ao inalar, aperte os abdominais e glúteos, enrole o torso ao mesmo tempo que faz quando faz um sit-up e pressione o barbell para uma posição superior enquanto expira.","Abaixe a parte superior do corpo de volta para a posição inicial enquanto leva a campainha de volta para o tronco.","Repita para a quantidade recomendada de repetições."]],"Prone_Manual_Hamstring":["Hambstring Manual Prone.",["Precisará de um parceiro para esse exercício, deite-se com as pernas retas, sua assistente colocará a mão no seu calcanhar.","Para começar, flexione o joelho para enroscar a perna, seu parceiro deve fornecer resistência, iniciar a luz e aumentar a pressão quando o movimento estiver concluído, comunique-se com seu parceiro para monitorar os níveis de resistência adequados.","Pausa no topo, retornando a perna para a posição inicial enquanto seu parceiro proporciona resistência indo para o outro lado."]],"Prowler_Sprint":["Prowler Sprint",["Coloque seu trenó em uma superfície adequada, carregado a um peso adequado, o trenó deve fornecer resistência suficiente para exigir esforço, mas não tão pesado que você seja significativamente lento.","Você pode usar os punhos retos ou baixos para este exercício.","Com boa postura, atravesse o chão com passos curtos e alternados, mova-se o mais rápido possível por uma curta distância."]],"Pull_Through":["Puxar através",["Comece a ficar de pé alguns metros na frente de uma polia baixa com uma corda ou alça presa.","Comece o movimento alcançando as pernas o mais longe possível, dobrando os quadris, mantendo os joelhos ligeiramente dobrados, mantendo os braços retos, estendendo-se pelo quadril para ficar em pé, evitando puxar para cima pelos ombros, todo o movimento deve se originar pelos quadris."]],"Push-Up_Wide":["Push-Up Wide",["Seus cotovelos devem ser estendidos e seu corpo reto.","Para começar, permita que os cotovelos flexionem, baixando seu peito para o chão enquanto você inala.","Usando seus músculos peitorais, pressione sua parte superior do corpo até a posição inicial, estendendo os cotovelos.","Depois de parar na posição contratada, repita o movimento para a quantidade prescrita de repetições."]],"Push-Ups_-_Close_Triceps_Position":["\"Push-ups\" \"Fechar a posição do tríceps\"",["Deite-se no chão de frente para baixo e coloque as mãos mais perto do que a largura do ombro para uma posição próxima da mão.","Abaixe-se até o peito quase tocar o chão enquanto inala.","Usando seus tríceps e alguns músculos peitorais, pressione sua parte superior do corpo até a posição inicial e aperte seu peito.","Após uma segunda pausa na posição contraída, repita o movimento para a quantidade prescrita de repetições."]],"Push-Ups_With_Feet_Elevated":["Push-ups com pés elevados",["Deite-se no chão de cara para baixo e coloque suas mãos a cerca de 36 polegadas de distância um do outro segurando seu tronco ao longo dos braços.","Coloque os dedos dos pés em cima de um banco plano, isso permitirá que seu corpo seja elevado, e quanto maior a elevação do banco plano, maior a resistência do exercício.","Abaixe-se até o peito quase tocar o chão enquanto inala.","Usando seus músculos peitorais, pressione sua parte superior do corpo de volta para a posição inicial e aperte seu peito.","Após uma segunda pausa na posição contraída, repita o movimento para a quantidade prescrita de repetições."]],"Push-Ups_With_Feet_On_An_Exercise_Ball":["Push-ups com pés em uma bola de exercício",["Deite-se no chão de cara para baixo e coloque suas mãos a cerca de 36 polegadas de distância um do outro segurando seu tronco ao longo dos braços.","Coloque os dedos dos pés em cima de uma bola de exercício, isso permitirá que seu corpo seja elevado.","Abaixe-se até o peito quase tocar o chão enquanto inala.","Usando seus músculos peitorais, pressione sua parte superior do corpo de volta para a posição inicial e aperte seu peito.","Após uma segunda pausa na posição contraída, repita o movimento para a quantidade prescrita de repetições."]],"Push_Press_-_Behind_the_Neck":["Empurre a pressão atrás do pescoço.",["Com os pés diretamente sob os quadris, flexione os joelhos sem mover os quadris para trás, desça apenas ligeiramente e inverta a direção o mais poderosa possível, atravesse os calcanhares, crie o máximo de velocidade e força possível, movendo a barra em um caminho vertical.","Usando o ímpeto gerado, termine de pressionar o peso acima que se estende através dos braços.","Volte para a posição inicial, usando suas pernas para absorver o impacto."]],"Push_Up_to_Side_Plank":["Empurre para a prancha lateral.",["Coloque-se em posição de flexão nos dedos dos pés com as mãos fora da largura do ombro.","Faça uma flexão permitindo que os cotovelos flexionem, enquanto desce, mantenha seu corpo reto.","Faça uma flexão e quando subir, mude seu peso do lado esquerdo do corpo, torça para o lado enquanto leva o braço direito para o teto em uma prancha lateral.","Abaixe o braço de volta para o chão para outro empurrão e depois gire para o outro lado.","Repita a série, alternando cada lado, para 10 ou mais representantes."]],"Pushups":["Flexões.",["Deite-se no chão de cara para baixo e coloque suas mãos a cerca de 36 polegadas de distância enquanto segura seu tronco ao longo dos braços.","Em seguida, abaixe-se para baixo até que seu peito quase toque o chão enquanto você inala.","Agora expire e pressione sua parte superior do corpo de volta para a posição inicial enquanto aperta seu peito.","Depois de uma breve pausa na posição contratada, você pode começar a se abaixar novamente para quantas repetições forem necessárias."]],"Pushups_Close_and_Wide_Hand_Positions":["Flexões (Posição de mão fechada e larga)",["Deite-se no chão com o rosto para baixo e o corpo reto com os dedos dos pés no chão e as mãos mais largas do que a largura do ombro para uma posição larga da mão e mais próxima do ombro para uma posição próxima da mão.","Abaixe-se até o peito quase tocar o chão enquanto inala.","Usando seus músculos peitorais, pressione sua parte superior do corpo de volta para a posição inicial e aperte seu peito.","Após uma segunda pausa na posição contraída, repita o movimento para a quantidade prescrita de repetições."]],"Pyramid":["Pirâmide",["Comece rodando seu torso para a frente na bola para que seus quadris descansem em cima da bola e se tornem o ponto mais alto do seu corpo.","Descanse as mãos e os pés no chão, seus braços e pernas podem estar ligeiramente dobrados ou retos, dependendo do tamanho da bola, sua flexibilidade, e do comprimento dos seus membros, isso também ajuda a desenvolver força estabilizadora em seu tronco e ombros."]],"Quad_Stretch":["Quad Stretch.",["Coloque um cinto, uma corda ou uma faixa ao redor do pé superior, flexione o joelho e estenda o quadril, tentando tocar seus glúteos com o pé, e segurando o cinto com as mãos, esta será a sua posição inicial.","Com o cinto sobre o ombro ou sobre a cabeça, puxe suavemente para aumentar o estiramento no quadríceps."]],"Quadriceps-SMR":["Quadriceps-SMR",["Coloque um rolo de espuma embaixo de uma perna no quadríceps, e mantenha o pé fora do chão e relaxe a perna o máximo possível.","Mudando o peso para a perna para ser esticada como é tolerável, role sobre a espuma de cima do joelho para baixo do quadril, segurando pontos de tensão por 10-30 segundos."]],"Quick_Leap":["Salto Rápido",["Você vai precisar de uma caixa para este exercício.","Comece de frente para a caixa de pé 1-2 pés de sua borda.","Usando seus quadris, pule na caixa, pousando em ambas as pernas, certifique-se de pousar com as pernas dobradas e os pés lisos.","Imediatamente após a aterrissagem, estenda-se através de todo o corpo e balance seus braços para explodir da caixa."]],"Rack_Delivery":["Entrega de Rack",["Esta broca ensina a entrega do sino para a posição do rack nos ombros, comece a segurar uma barra na posição do espantalho, com os braços superiores paralelos ao chão, e os antebraços pendurados para baixo.","Comece girando os cotovelos ao redor da barra, entregando a barra aos ombros, enquanto seus cotovelos se aproximam, relaxem, os ombros devem ser prolongados, fornecendo uma prateleira para a barra, que deve entrar levemente em contato com a garganta.","É importante que a barra fique perto do corpo o tempo todo, pois com uma carga mais pesada qualquer distância resultará em uma colisão indesejada, à medida que o movimento se torna mais suave, velocidade e carga podem ser aumentadas antes de progredir mais."]],"Rack_Pull_with_Bands":["Rack Pull com Bandas",["Os pinos devem ser colocados no ponto desejado, logo abaixo dos joelhos, logo acima, ou na posição média da coxa, amarrar as faixas na base do rack, ou prendê-las com halteres, prender a outra ponta na barra, pode precisar sufocar as bandas para fornecer tensão.","Seus pés devem estar sob seus quadris, sua largura do ombro, as costas arqueadas e os quadris de volta para acionar os isquiotibiais, já que o peso é normalmente pesado, você pode usar um aperto misto, um gancho, ou usar alças para ajudar a segurar o peso.","Com a cabeça olhando para a frente, estendendo os quadris e joelhos, puxando o peso para cima e para trás até o bloqueio, não se esqueça de puxar seus ombros para trás enquanto completa o movimento, devolver o peso aos pinos e repetir."]],"Rack_Pulls":["Rack Pulls",["Os pinos devem ser ajustados para o ponto desejado, logo abaixo dos joelhos, logo acima, ou na posição média da coxa. Posicione-se contra a barra em posição adequada de deadlifting. Seus pés devem estar sob seus quadris, sua largura do ombro de aperto, arqueado de costas, e quadris de volta para acionar os isquiotibiais. Como o peso é tipicamente pesado, você pode usar um aperto misto, um aperto de gancho, ou usar alças para ajudar a segurar o peso.","Com sua cabeça olhando para frente, estendendo-se pelos quadris e joelhos, puxando o peso para cima e para trás até o fechamento.","Devolva o peso aos pinos e repita."]],"Rear_Leg_Raises":["A perna traseira sobe.",["Coloque suas mãos de joelhos em um tapete de exercício, sua cabeça deve estar olhando para frente e a curva dos joelhos deve criar um ângulo de 90 graus entre os isquiotibiais e os bezerros.","Estenda uma perna para cima e para trás, o joelho e o quadril devem se estender, repita por 5-10 repetições e mude de lado."]],"Recumbent_Bike":["Bicicleta Recumbent",["Para começar, sente-se na moto e ajuste o assento à sua altura.","Você pode começar a pedalar para ligá-lo, usar a configuração manual, ou selecionar um programa para usar, normalmente, você pode inserir sua idade e peso para estimar a quantidade de calorias queimadas durante o exercício, o nível de resistência pode ser alterado durante todo o treino, os cabos podem ser usados para monitorar sua frequência cardíaca para ajudá-lo a ficar em uma intensidade apropriada.","Bicicletas reclinadas oferecem conveniência, benefícios cardiovasculares e têm menos impacto do que outras atividades, uma pessoa de 150 libras queimará cerca de 230 calorias ciclando a uma taxa moderada por 30 minutos, comparado com 450 calorias ou mais correndo."]],"Return_Push_from_Stance":["Retorne Empurre de Stance",["Você precisará de um parceiro para este exercício.","Comece em uma postura atlética de 2 ou 3 pontos.","Ao sinal, mova-se para uma posição para receber o passe do seu parceiro.","Pegue a bola de remédio com as duas mãos e jogue de volta para o seu parceiro.","Você pode modificar esta broca executando rotas diferentes."]],"Reverse_Band_Bench_Press":["\"Banda de Banda Invertida\"",["Posicione um banco dentro de um rack de energia, com a barra definida para a altura correta, comece por ancorar as faixas, ou para a faixa ou para o topo do rack, certifique-se de que você estará bem sob as bandas, anexe a outra ponta à campainha.","Deite-se no banco, coloque os pés embaixo de você e arqueie as costas, use a barra para ajudar a suportar seu peso, levante seu ombro do banco e retraia-os, apertando as omoplatas juntos, use seus pés para levar suas armadilhas para o banco, mantenha esta posição firme do corpo durante todo o movimento, por mais larga que seja a sua pegada, ela deve cobrir o anel na barra.","Tire a barra da prateleira sem atrasar os ombros, concentre-se em apertar a barra e tentar desmontá-la, baixar a barra para o peito ou estômago, a barra, o pulso e o cotovelo devem ficar em linha o tempo todo.","Pause quando a campainha tocar seu torso, e depois empurre a barra com o máximo de força possível."]],"Reverse_Band_Box_Squat":["Agachamento da Caixa de Banda Invertida",["Comece em um rack de energia com uma caixa na altura apropriada atrás de você, coloque as bandas em pinos de banda ou preso ao topo do rack, garantindo que eles estarão diretamente acima da barra durante o agachamento.","Comece pisando debaixo da barra e colocando-a na parte de trás dos ombros, aperte suas omoplatas juntas e gire seus cotovelos para frente, tentando dobrar a barra pelos ombros, remova a barra do rack, crie um arco apertado nas costas, e volte para a posição, coloque seus pés mais largos para mais ênfase nas costas, glúteos, adutores e isquiotibiais, ou mais próximos para mais desenvolvimento quádruplo, mantenha sua cabeça voltada para frente.","Com as costas, os ombros e o núcleo apertados, empurre os joelhos e bumbum para fora e comece sua descida, sente-se com os quadris até que esteja sentado na caixa, idealmente, suas canelas devem ser perpendiculares ao chão, pare quando chegar na caixa e relaxe os flexores do quadril, nunca salte de uma caixa.","Mantendo o peso em seus calcanhares e empurrando seus pés e joelhos para fora, dirigir para cima da caixa enquanto você lidera o movimento com sua cabeça. Continue para cima, mantendo a cabeça firme para os pés."]],"Reverse_Band_Deadlift":["Deadlift Banda Invertida",["Coloque a barra em um rack de energia, anexe as faixas no topo do rack, usando ambas as bandas ou o próprio frame, anexe a outra extremidade das bandas à barra.","Aproxime-se da barra para que ela seja centrada sobre seus pés, você deve ter cerca de largura do quadril à parte, dobre-se no quadril para segurar a barra na largura do ombro, permitindo que suas omoplatas protraiam.","Com os pés e o aperto, respire fundo, abaixe os quadris e dobre os joelhos até as canelas entrarem em contato com a barra, olhe para frente com a cabeça, mantenha o peito para cima e as costas arqueadas, e comece a dirigir pelos calcanhares para mover o peso para cima.","Depois que a barra passar os joelhos, puxe a barra agressivamente para trás, puxando suas omoplatas juntos enquanto você dirige seus quadris para a frente para a barra.","Abaixe a barra dobrando-se nos quadris e guiando-a até o chão."]],"Reverse_Band_Power_Squat":["Agachamento de Poder da Banda Invertida",["Começar em um rack de energia com os pinos e barras na altura adequada, depois de carregar a barra, anexá-las ao topo do rack, usando pinos ou o próprio frame, e anexar a outra extremidade das bandas à barra.","Comece pisando debaixo da barra e colocando-a na parte de trás dos ombros, aperte suas omoplatas juntas e gire seus cotovelos para frente, tentando dobrar a barra em seus ombros, remova a barra do rack, criando um arco apertado em suas costas e volte para a posição, coloque seus pés largos para mais ênfase nas costas, glúteos, adutores e isquiotibiais.","Mantenha a cabeça voltada para a frente, com as costas, ombros e o núcleo apertados, empurre os joelhos e a bunda para fora e comece a descer, sente-se com os quadris o máximo possível, idealmente, suas canelas devem ser perpendiculares ao chão, a posição da barra inferior requer uma maior inclinação do tronco para manter a barra sobre os calcanhares, continue até quebrar o paralelo, que é definido como a dobra do quadril em linha com o topo do joelho.","Mantendo o peso em seus calcanhares e empurrando seus pés e joelhos para fora, dirigir para cima enquanto você lidera o movimento com sua cabeça. Continue para cima, mantendo aperto cabeça aos pés, até que você tenha retornado à posição inicial."]],"Reverse_Band_Sumo_Deadlift":["Banda reversa Sumo Deadlift",["Comece com uma barra carregada no chão dentro de um rack de energia, anexe faixas no topo do rack, usando pinos ou o próprio quadro, e anexe a outra extremidade ao barbell.","Aproxime-se da barra para que a barra intersecta o meio dos pés, os pés devem ser colocados muito largos, perto dos colares, dobre-se nos quadris para segurar a barra, os braços devem estar diretamente abaixo dos ombros, dentro das pernas, e você pode usar um aperto pronado, um aperto misto, ou gancho aperto.","Respire, e depois abaixe os quadris, olhando para a frente com a cabeça para cima, dirija pelo chão, espalhe seus pés, com o peso na parte de trás dos pés, estenda-se através dos quadris e joelhos.","Quando a barra passar pelos joelhos, incline-se e dirija os quadris para a barra, puxando suas omoplatas juntas.","Retorne o peso ao chão dobrando os quadris e controlando o peso na descida."]],"Reverse_Barbell_Curl":["Curva Barbell Invertida",["Levante-se com o torso ereto enquanto segura uma barba na largura do ombro com os cotovelos perto do torso.","Enquanto segura os braços parados, enrole os pesos enquanto contrai os bíceps enquanto expira, apenas os antebraços devem se mover, continue o movimento até que seus bíceps estejam totalmente contraídos e a barra esteja no nível do ombro, mantenha a posição contraída por um segundo enquanto aperta o músculo.","Lentamente começar a trazer o bar de volta à posição inicial enquanto você respira.","Repita para a quantidade recomendada de repetições."]],"Reverse_Barbell_Preacher_Curls":["Curls Pregador de Barbell Reverso",["Pegue uma barra EZ usando uma largura de ombro e palmas para baixo (pronated) aperto.","Coloque a parte superior dos dois braços no banco do pastor e estenda os braços.","Enquanto você expira, use os bíceps para enrolar o peso até que seus bíceps estejam totalmente contraídos e o barbelo esteja na altura do ombro, aperte os bíceps com força por um segundo na posição contraída.","Enquanto você respira, abaixe lentamente o barbelo até que seus braços se estendam e o bíceps esteja totalmente esticado.","Repita para a quantidade recomendada de repetições."]],"Reverse_Cable_Curl":["Curva de Cabo Invertida",["Levante-se com o torso ereto enquanto segura uma barra presa a uma polia baixa usando uma pronada (palmas para baixo) e a largura do ombro, e mantenha os cotovelos perto do tronco.","Enquanto segura os braços parados, enrole os pesos enquanto contrai os bíceps enquanto expira, apenas os antebraços devem se mover, continue o movimento até que seus bíceps estejam totalmente contraídos e a barra esteja no nível do ombro, mantenha a posição contraída por um segundo enquanto aperta o músculo.","Lentamente começar a trazer o bar de volta à posição inicial enquanto você respira.","Repita para a quantidade recomendada de repetições."]],"Reverse_Crunch":["Crunch Reverso",["Deite-se no chão com as pernas estendidas e os braços ao lado do torso com as palmas do chão e os braços parados durante todo o exercício.","Mova as pernas para cima para que suas coxas sejam perpendiculares ao chão e os pés estejam juntos e paralelos ao chão.","Enquanto inala, mova suas pernas para o torso enquanto você enrola sua pélvis para trás e levanta seus quadris do chão.","Segure a contração por um segundo e mova suas pernas de volta para a posição inicial enquanto expira.","Repita para a quantidade recomendada de repetições."]],"Reverse_Flyes":["Vôos Inversos",["Para começar, deite-se em um banco inclinado com o peito e o estômago pressionando contra a inclinação.","Estenda os braços na sua frente para que fiquem perpendiculares ao ângulo do banco, as pernas devem ficar paradas enquanto faz pressão com a bola dos dedos dos pés.","Mantendo a pequena curva dos cotovelos, mova os pesos para fora e para longe um do outro (para o lado) em um arco de movimento enquanto expira.","Os braços devem ser elevados até ficarem paralelos ao chão.","Sinta a contração e reduza lentamente os pesos de volta para a posição inicial enquanto inala.","Repita para a quantidade recomendada de repetições."]],"Reverse_Flyes_With_External_Rotation":["Voas reversas com rotação externa.",["Para começar, deite-se em um banco inclinado, a um ângulo de 30 graus, com o peito e o estômago pressionando contra a inclinação.","Seus braços devem estar na sua frente para que eles sejam perpendiculares ao ângulo do banco. Dica: Seus cotovelos devem ter uma leve curva. As pernas devem estar paradas enquanto se faz pressão com a bola dos dedos (seus calcanhares não devem tocar no chão).","Mantendo a pequena curva dos cotovelos, mover os pesos para fora e para longe um do outro em um arco de movimento enquanto expira.","Enquanto você levanta o peso, seu pulso deve girar externamente em 90 graus para que você vá de uma palma para baixo (pronada) aderência para uma palma virada para o outro (neutro) aderência. Dica: Tente apertar suas omoplatas juntos para obter os melhores resultados deste exercício.","Os braços devem ser elevados até estarem nivelados com a cabeça.","Sinta a contração e reduza lentamente os pesos de volta para a posição inicial enquanto inala.","Repita para a quantidade recomendada de repetições."]],"Reverse_Grip_Bent-Over_Rows":["Reverse Grip Bent-Over Rows",["Fique ereto enquanto segura uma campainha com um aperto supinado (palmas viradas para cima).","Dobre os joelhos ligeiramente e leve o tronco para frente, dobrando a cintura, mantendo as costas retas até que seja quase paralelo ao chão.","Enquanto mantém o torso parado, levante a campainha enquanto expira, mantendo os cotovelos perto do corpo e não fazendo nenhuma força com o antebraço além de segurar os pesos.","Devagar, reduza o peso novamente para a posição inicial enquanto inala.","Repita para a quantidade recomendada de repetições."]],"Reverse_Grip_Triceps_Pushdown":["Aperto Reverso Tríceps Pushdown",["Comece colocando uma barra de fixação (em linha reta ou e-z) em uma máquina de polia alta.","De frente para a barra de fixação, agarre-a com as palmas viradas para cima (aperto supinado) na largura do ombro. Abaixe a barra usando seus lats até que seus braços sejam totalmente estendidos por seus lados.","Lentamente eleve a fixação da barra enquanto inala para que esteja alinhada com seu peito.","Em seguida, começar a baixar a barra de cabo de volta para a posição original olhando enquanto expirar e contraindo o tríceps duro.","Repita para a quantidade recomendada de repetições."]],"Reverse_Machine_Flyes":["Máquina Invertida Voa",["Ajustar as pegas para que estejam totalmente na parte traseira, fazer uma seleção adequada de peso e ajustar a altura do assento para que as pegas estejam ao nível do ombro, agarrar as pegas com as mãos voltadas para dentro, esta será a sua posição inicial.","Em um movimento semicircular, puxe suas mãos para o lado e para trás, contraindo seus dedos traseiros.","Mantenha os braços ligeiramente dobrados durante todo o movimento, com todo o movimento ocorrendo na articulação do ombro.","Pausa na parte de trás do movimento, e lentamente retorne o peso para a posição inicial."]],"Reverse_Plate_Curls":["Curls Prato Inverso",["Comece por ficar em pé, com uma placa pesada mantida por ambas as mãos e braços totalmente estendidos. Use uma pegada pronada (palmas viradas para baixo) e certifique-se de seus dedos agarrar o lado áspero da placa enquanto seu polegar agarra o lado liso.","Seus pés devem ter a largura do ombro um do outro e a placa deve estar perto da virilha.","Levante lentamente a placa enquanto mantém os cotovelos e os braços parados até que seus bíceps e antebraços toquem enquanto expiram.","Sinta a contração por um segundo e comece a baixar o peso de volta para a posição inicial enquanto inala","Repita para a quantidade recomendada de repetições."]],"Reverse_Triceps_Bench_Press":["Imprensa de Banco de Tríceps Reverso.",["Deite-se em um banco plano, usando um aperto próximo e supinado, levante a barra do rack e segure-a em cima de você com os braços estendidos na sua frente e perpendicular ao chão, esta será sua posição inicial.","Quando respirar, desça devagar até sentir a barra no peito médio, e certifique-se de que, ao invés de uma pressão normal, mantenha os cotovelos perto do tronco o tempo todo para maximizar o envolvimento do tríceps.","Depois de uma segunda pausa, traga a barra de volta para a posição inicial enquanto expira e empurre a barra usando os músculos do tríceps, tranque os braços na posição contraída, segure por um segundo e comece a descer lentamente novamente.","Repita o movimento para a quantidade prescrita de repetições.","Quando terminar, coloque o bar de volta no rack."]],"Rhomboids-SMR":["Rhomboids-SMR",["Deite-se de costas no chão, coloque um rolo de espuma embaixo das costas, e cruze os braços na sua frente, prolongando os ombros, esta será a sua posição inicial.","Levante os quadris do chão, coloque o peso no rolo de espuma, mude o peso para um lado de cada vez, girando sobre o meio e a parte superior das costas, pare em pontos de tensão por 10-30 segundos."]],"Rickshaw_Carry":["Rickshaw Carry.",["Posicione o quadro no ponto de partida, e carregue com o peso apropriado, de pé no centro do quadro, começando por agarrar as alças e dirigir através de seus calcanhares para levantar o quadro, certifique-se de que seu peito e cabeça estão para cima e suas costas estão retas.","Comece a andar rapidamente, com passos rápidos e controlados, mantenha o peito para cima e cabeça para frente, e certifique-se de continuar respirando, e traga o quadro para o chão depois de chegar ao ponto final."]],"Rickshaw_Deadlift":["Rickshaw Deadlift",["Coloque a armação com o peso desejado, se concentre entre as alças, os pés devem ter largura de quadril à parte, dobre-se nos quadris para segurar as alças, permitindo que suas omoplatas prolonguem.","Olhe para frente com a cabeça, mantenha o peito para cima e as costas arqueadas, e comece a dirigir através dos calcanhares para mover o peso para cima.","Abaixe o peso dobrando os quadris e guiando-os até o chão."]],"Ring_Dips":["Anel Dips",["Segure um anel em cada mão, e então dê um pequeno salto para ajudá-lo a entrar na posição inicial com os braços trancados.","Comece flexionando o cotovelo, baixando o corpo até os braços quebrarem 90 graus, evite balançar e mantenha uma boa postura ao longo da descida.","Reverta o movimento estendendo o cotovelo, empurrando-se de volta para a posição inicial.","Repita para o número desejado de repetições."]],"Rocket_Jump":["Rocket Jump.",["Comece em uma posição relaxada com os pés largura do ombro separados e mantenha seus braços perto do corpo.","Para iniciar o movimento, agache-se na metade e exploda o mais alto possível.","Estenda todo o corpo, alcançando o mais longe possível, assim que pousar, absorva seu impacto através das pernas."]],"Rocking_Standing_Calf_Raise":["Levantem-se os bezerros.",["Este exercício é melhor realizado dentro de um rack de agachamento para fins de segurança, para começar, defina a barra em um rack que melhor corresponda à sua altura, uma vez que a altura correta é escolhida e a barra é carregada, passo abaixo da barra e colocá-la na parte de trás de seus ombros (ligeiramente abaixo do pescoço).","Segure-se na barra usando os dois braços de cada lado e levante-a do rack empurrando com as pernas e ao mesmo tempo endireitando o tronco.","Afaste-se do rack e posicione suas pernas usando uma posição média de largura do ombro com os dedos dos pés ligeiramente apontados. Mantenha sua cabeça erguida o tempo todo, enquanto olhar para baixo vai te desequilibrar.","Levante os calcanhares enquanto expira, estendendo os tornozelos o mais alto possível e flexionando a panturrilha, certifique-se de que o joelho fique parado o tempo todo, não deve haver nenhuma flexão (além da pequena curva inicial que criamos durante o posicionamento) a qualquer momento, mantenha a posição contraída por um segundo antes de começar a voltar para baixo.","Volte lentamente para a posição inicial enquanto você respira baixando os calcanhares enquanto dobra os tornozelos até as panturrilhas ficarem esticadas.","Agora levante os dedos dos pés contraindo os músculos da tíbia na frente das panturrilhas enquanto expira.","Espere um segundo e traga-os de volta enquanto respira.","Repita para a quantidade recomendada de repetições."]],"Rocky_Pull-Ups_Pulldowns":["Rocky Pull-Ups/Pulldowns",["Pegue a barra com as palmas voltadas para a frente usando um aperto largo.","Como você tem os dois braços estendidos na frente de você segurando a barra na largura de aderência escolhida, traga seu torso de volta em torno de 30 graus ou assim, enquanto cria uma curvatura em suas costas inferiores e colocar seu peito para fora.","Puxe seu torso para cima até que a barra toque seu peito superior puxando os ombros e os braços para baixo e para trás. Expire enquanto você executa esta parte do movimento. Dica: Concentre-se em apertar os músculos das costas uma vez que você atinge a posição contraída total.","Depois de um segundo na posição contraída, comece a inalar e lentamente abaixe seu torso de volta para a posição inicial quando seus braços estão totalmente estendidos e os lats estão totalmente esticados.","Agora repita os mesmos movimentos descritos acima, exceto que desta vez seu torso permanecerá reto enquanto você sobe e a barra tocará a parte de trás do pescoço em vez da parte superior do peito.","Uma vez que você se rebaixou de volta para a posição inicial, repita o exercício para a quantidade prescrita de repetições em seu programa."]],"Romanian_Deadlift":["Deadlift Romeno",["DL de cima para a posição 2: https://www.youtube.com/watch?v=WtWtjViRsKo"]],"Romanian_Deadlift_from_Deficit":["Deadlift Romeno do Déficit",["Você pode ficar em uma plataforma levantada para aumentar a amplitude de movimento.","Comece flexionando os joelhos ligeiramente, e então flexione o quadril, movendo sua bunda para trás o mais longe possível, baixando o torso tanto quanto a flexibilidade permitir, as costas devem permanecer em extensão absoluta o tempo todo, e a barra deve permanecer em contato com as pernas.","Reverta o movimento para voltar à posição inicial."]],"Rope_Climb":["Corda Escalada",["Pegue a corda com as duas mãos acima da cabeça e puxe a corda enquanto dá um pequeno salto.","Enrole a corda em torno de uma perna, usando seus pés para beliscar a corda.","Solte a corda dos pés enquanto se levanta com os braços, trazendo seus joelhos para o peito.","Continue até alcançar o topo da corda.","Para se abaixar, solte o aperto dos pés na corda enquanto desliza para baixo usando um movimento mão sobre mão."]],"Rope_Crunch":["Corda Crunch",["Ajoelhe-se 1-2 pés na frente de um cabo com uma corda presa.","Depois de selecionar um peso adequado, segure a corda com as duas mãos chegando acima, seu tronco deve estar ereto na posição inicial.","Para começar, flexione a coluna vertebral, tentando trazer sua caixa torácica para as pernas enquanto puxa o cabo para baixo.","Pausa no fundo do movimento, e então lentamente voltar para a posição inicial.","Isso pode ser feito com torções ou para o lado para atingir os oblíquos."]],"Rope_Jumping":["Corda pulando",["Segure uma ponta da corda em cada mão, posicione a corda atrás de você no chão, levante os braços e vire a corda sobre sua cabeça, trazendo-a para baixo na sua frente, quando chegar ao chão, pule sobre ela, encontre um bom ritmo de giro que possa ser mantido, diferentes velocidades e técnicas podem ser usadas para introduzir variação.","O salto de corda é emocionante, desafia sua coordenação, e requer muita energia, uma pessoa de 150 libras queimará cerca de 350 calorias pulando corda por 30 minutos, comparado com mais de 450 calorias correndo."]],"Rope_Straight-Arm_Pulldown":["Corda direita-arm puxar para baixo",["Coloque uma corda em uma polia alta e faça sua seleção de peso... afaste-se da polia com os pés cambaleando e pegue a corda com as duas mãos... incline-se para a frente do quadril, mantendo as costas retas, com os braços estendidos na sua frente.","Mantendo os braços retos, estenda o ombro para puxar a corda até as coxas.","Pausa no fundo da moção, apertando seus lats.","Volte para a posição inicial sem permitir que o peso descanse totalmente na pilha."]],"Round_The_World_Shoulder_Stretch":["Ombro redondo do mundo esticar",["Levante-se com as pernas juntas, segurando uma barra ou vassoura.","Segure o poste atrás dos quadris com uma largura maior do que o ombro, suas palmas devem estar para baixo e seus polegares virados para fora.","Levante os braços devagar atrás da cabeça, não force se ficar difícil levantar mais."]],"Rowing_Stationary":["Remo, estacionário.",["Para começar, sente-se no remador, certifique-se de que seus calcanhares estão descansando confortavelmente contra a base dos pedais dos pés e que as alças estão seguras, selecione o programa que deseja usar, se for o caso, sente-se direito e dobre-se para frente nos quadris.","Há três fases de movimento ao usar um remador, a primeira fase é quando você se aproxima no remador, seus joelhos estão dobrados e contra o peito, seu corpo está ligeiramente inclinado para frente, mantendo uma boa postura, em seguida, empurre os pedais dos pés e estenda suas pernas enquanto leva suas mãos para sua área abdominal superior, apertando seus ombros para trás enquanto você faz isso, para evitar esticar suas costas, use principalmente seus músculos da perna e do quadril.","A fase de recuperação envolve simplesmente endireitar seus braços, dobrar os joelhos, e trazer seu corpo para frente novamente enquanto você volta para a primeira fase."]],"Runners_Stretch":["\"Ronner's Stretch\"",["É mais fácil entrar nesse trecho se você começar a se levantar, colocar uma perna atrás de você, e lentamente abaixar seu tronco para o chão.","Mantenha o calcanhar dianteiro no chão (se levantar, afaste a outra perna mais para trás).","Coloque as mãos em cada lado da perna da frente, para tirar mais desse trecho, empurre sua bunda até o teto, e então abaixe-a gradualmente de volta para o chão, você vai esticar o flexor do quadril da perna traseira, e o tendão e as nádegas da frente."]],"Running_Treadmill":["Correndo, Treadmill",["Para começar, pise na esteira e selecione a opção desejada no menu, a maioria das esteiras tem uma configuração manual, ou você pode selecionar um programa para executar, normalmente, você pode entrar em sua idade e peso para estimar a quantidade de calorias queimadas durante o exercício, a elevação pode ser ajustada para alterar a intensidade do treino.","As esteiras oferecem comodidade, benefícios cardiovasculares, e geralmente têm menos impacto do que correr para fora, uma pessoa de 150 lb queimará mais de 450 calorias correndo 8 milhas por hora por 30 minutos, mantendo a postura adequada enquanto corre, e só manterá as alças quando necessário, como quando desmontar ou verificar sua frequência cardíaca."]],"Russian_Twist":["Torção Russa",["Deite-se no chão colocando seus pés debaixo de algo que não vai se mover ou tendo um parceiro segurá-los.","Eleve sua parte superior do corpo para que crie uma forma imaginária de V com suas coxas, seus braços devem ser estendidos totalmente na sua frente perpendicular ao seu tronco e com as mãos fechadas.","Torça o torso para o lado direito até que seus braços estejam paralelos com o chão enquanto expira.","Segure a contração por um segundo e volte para a posição inicial enquanto expira.","Repita para a quantidade recomendada de repetições."]],"Sandbag_Load":["Carregar saco de areia",["Para carregar sacos de areia ou outros objetos, comece com os implementos colocados a uma distância da plataforma de carga, normalmente 15 metros.","Começar levantando o saco de areia, sacos de areia são extremamente estranhos, e a maneira de levantá-los pode variar dependendo do saco de areia usado, chegar o mais longe possível, estendendo-se através dos quadris e joelhos para puxá-lo para cima.","Mova-se o mais rápido possível para a plataforma, e carregue-a, estendendo-se através de seus quadris, joelhos e tornozelos para levá-la o mais alto possível.","Volte para a posição inicial para recuperar o próximo saco de areia, e repita até que o evento esteja concluído."]],"Scapular_Pull-Up":["Scapular Pull-Up",["Segure uma barra de tração.","De uma posição pendurada, levante-se alguns centímetros sem usar os braços, faça isso deprimindo sua cintura de ombros em um movimento de retrocesso.","Pause na conclusão do movimento, e então lentamente voltar para a posição inicial antes de executar mais repetições."]],"Scissor_Kick":["Chute de tesoura",["Para começar, deite-se com as costas pressionadas contra o chão ou em um tapete de exercício (opcional), seus braços devem ser estendidos totalmente para os lados com as palmas viradas para baixo.","Com uma leve curva nos joelhos, levante as pernas para que seus calcanhares estejam a cerca de 6 polegadas do chão.","Agora levante sua perna esquerda para um ângulo de 45 graus enquanto sua perna direita é baixada até que o calcanhar esteja a cerca de 2-3 polegadas do chão.","Troque os movimentos levantando a perna direita e baixando a perna esquerda.","Repita para a quantidade recomendada de repetições."]],"Scissors_Jump":["Tesoura Jump",["Assuma uma posição de apoio com um pé para frente com o joelho dobrado, e o joelho traseiro quase tocando o chão.","Certifique-se de que o joelho dianteiro esteja sobre a linha média do pé, estendendo-se através de ambas as pernas, pulando o mais alto possível, balançando os braços para ganhar elevação.","Quando você pular o mais alto que puder, mude a posição das pernas, movendo sua perna dianteira para trás e a perna traseira para a frente.","Ao pousar, absorva o impacto através das pernas, adotando a posição do pulmão, e repita."]],"Seated_Band_Hamstring_Curl":["Banda sentada Hamstring Curl",["Proteja uma banda perto do chão e coloque um banco a alguns metros dela.","Sente-se no banco e segure a banda atrás dos tornozelos, começando com as pernas retas.","Flexione os joelhos, levando os pés para o banco, talvez precise se inclinar um pouco para evitar que seus pés batam no chão.","Pause na conclusão do movimento, e então lentamente retorne à posição inicial."]],"Seated_Barbell_Military_Press":["Imprensa Militar Barbell Sentada",["Sente-se em um banco de imprensa militar com uma barra atrás da cabeça e ou tem um observador dando-lhe a barra (melhor no manguito rotador desta forma) ou pegá-lo com cuidado com um aperto pronado (palmas voltadas para a frente).","Assim que pegar a campainha com o comprimento correto, levante a barra sobre a cabeça, trancando os braços, segurando o ombro e ligeiramente na frente da cabeça, esta é sua posição inicial.","Abaixe a barra até a clavícula lentamente enquanto inala.","Levante a barra de volta para a posição inicial enquanto expira.","Repita para a quantidade recomendada de repetições."]],"Seated_Barbell_Twist":["Torção de Barbell Assada",["Comece sentando-se no final de um banco plano com uma barba colocada em cima de suas coxas, seus pés devem ter a largura do ombro um do outro.","Segure a barra com as palmas viradas para baixo e certifique-se de que suas mãos sejam mais largas do que a largura do ombro um do outro.","Agora abaixe a campainha atrás da cabeça até que esteja descansando ao longo da base do pescoço.","Enquanto mantém os pés e a cabeça parados, mova a cintura de um lado para o outro para que seus músculos oblíquos sintam a contração.","Lembre-se de expirar enquanto torce seu corpo para o lado e para dentro quando voltar para a posição inicial.","Repita para a quantidade recomendada de repetições."]],"Seated_Bent-Over_One-Arm_Dumbbell_Triceps_Extension":["Sentou-se Bent-Over One-Arm halteres Tríceps Extensão",["Sente-se no final de um banco plano com um haltere em um braço usando um aperto neutro (palmas da mão voltada para você).","Dobre levemente os joelhos e leve o torso para frente, dobrando a cintura, mantendo as costas retas até que seja quase paralelo ao chão.","O braço superior com o haltere deve estar perto do tronco e alinhado com ele (elevado até que seja paralelo ao chão enquanto os antebraços estão apontando para o chão enquanto as mãos seguram os pesos).","Mantendo o braço parado, use o tríceps para levantar o peso enquanto expira até que o antebraço fique paralelo ao chão e o braço todo seja estendido, como muitos outros exercícios de braço, apenas o antebraço se move.","Depois de uma segunda contração no topo, abaixe lentamente o haltere de volta para a posição inicial enquanto você inala.","Repita o movimento para a quantidade prescrita de repetições.","Troque de braços e repita o exercício."]],"Seated_Bent-Over_Rear_Delt_Raise":["Assento dobrado sobre o delta traseiro levantar",["Coloque alguns halteres olhando para frente em frente a um banco plano.","Sente-se no final do banco com as pernas juntas e os halteres atrás das suas panturrilhas.","Dobrem a cintura, mantendo as costas retas para pegar os halteres, as palmas das mãos devem estar se encarando enquanto escolhem.","Mantendo seu torso para frente e parado, e os braços ligeiramente dobrados nos cotovelos, levante os halteres para o lado até que ambos os braços sejam paralelos ao chão. Expire enquanto você levanta os pesos. (Nota: evite balançar o torso ou trazer os braços de volta em oposição ao lado.)","Após uma contração de um segundo no topo, lentamente abaixe os halteres de volta para a posição inicial.","Repita para a quantidade recomendada de repetições."]],"Seated_Bent-Over_Two-Arm_Dumbbell_Triceps_Extension":["Sentado Bent-Over Dumbell Tríceps Extension",["Sente-se no final de um banco plano com um haltere em ambos os braços usando um aperto neutro (palmas da mão voltada para você).","Dobre levemente os joelhos e leve o torso para frente, dobrando a cintura, mantendo as costas retas até que seja quase paralelo ao chão.","Os braços superiores com os halteres devem estar próximos do tronco e alinhados com ele (elevados até ficarem paralelos ao chão enquanto os antebraços estão apontando para o chão enquanto as mãos seguram os pesos).","Mantendo os braços parados, use o tríceps para levantar o peso enquanto você expira até que os antebraços sejam paralelos ao chão e o braço todo seja estendido.","Depois de uma segunda contração no topo, abaixe lentamente os halteres de volta para a posição inicial enquanto você inala.","Repita o movimento para a quantidade prescrita de repetições."]],"Seated_Biceps":["Bíceps Sentados",["Sente-se no chão com os joelhos dobrados e seu parceiro parado atrás de você, estenda os braços atrás de você com as palmas viradas um para o outro, seu parceiro segurará os pulsos para você, esta será a posição inicial.","Tente flexionar os cotovelos, enquanto seu parceiro evita qualquer movimento real.","Depois de 10-20 segundos, relaxe os braços enquanto seu parceiro puxa os pulsos suavemente para esticar os bíceps."]],"Seated_Cable_Rows":["Filas de cabos sentados",["Para este exercício você precisará acessar uma máquina de roldana baixa com uma barra V. Nota: a barra V permitirá que você tenha uma aderência neutra onde as palmas de suas mãos se enfrentem umas às outras.","Incline-se enquanto mantém o alinhamento natural das costas e agarre os cabos da barra V.","Com os braços estendidos, puxe para trás até que seu torso esteja em um ângulo de 90 graus de suas pernas, suas costas devem estar ligeiramente arqueadas e seu peito deve ficar para fora, você deve estar se sentindo bem esticado enquanto segura a barra na sua frente, esta é a posição inicial do exercício.","Mantendo o torso parado, puxe as alças para trás em direção ao torso, mantendo os braços perto dele até que você toque os abdominais, respire enquanto você faz esse movimento, nesse ponto você deve apertar os músculos das costas com força, segure a contração por um segundo e lentamente volte para a posição original enquanto respira.","Repita para a quantidade recomendada de repetições."]],"Seated_Cable_Shoulder_Press":["Ombro de cabo sentado",["Ajuste o peso para uma quantidade adequada e sente-se, segurando as alças, seus braços devem estar a 90 graus no corpo, com a cabeça e o peito para cima, os cotovelos também devem ser dobrados para cerca de 90 graus, esta será a sua posição inicial.","Comece estendendo pelo cotovelo, pressionando as alças acima da cabeça.","Depois de parar no topo, devolva as alças para a posição inicial, certifique-se de manter tensão nos cabos.","Você também pode executar esse movimento com as costas fora do bloco e mãos alternadas."]],"Seated_Calf_Raise":["Levantem-se os bezerros.",["Sente-se na máquina e coloque os dedos dos pés na parte inferior da plataforma com os calcanhares estendidos, escolha o posicionamento do dedo do pé de sua escolha, conforme o início deste capítulo.","Coloque suas coxas embaixo da alavanca, que precisa ser ajustada de acordo com a altura de suas coxas.","Levante a alavanca empurrando os calcanhares para cima e solte a barra de segurança.","Abaixe os calcanhares lentamente dobrando os tornozelos até que as panturrilhas estejam esticadas.","Levante os calcanhares estendendo os tornozelos o mais alto possível, contrair os bezerros e expirar.","Repita para a quantidade recomendada de repetições."]],"Seated_Calf_Stretch":["Esticamento de Calf Sentado",["Sente-se direito em um tapete de exercício.","Dobre um joelho e coloque o pé no chão para estabilizar o tronco.","Endireite a outra perna e flexione o tornozelo.","Usando uma faixa, toalha, ou sua mão se você puder alcançar, puxe os dedos para você."]],"Seated_Close-Grip_Concentration_Barbell_Curl":["Barbell Curl de Concentração de Barbell",["Sente-se em um banco plano com uma campainha ou um bar E-Z na sua frente, entre as pernas, suas pernas devem ser abertas com os joelhos dobrados e os pés no chão.","Use os braços para levantar a barba e colocar a parte de trás dos braços em cima das coxas internas (cerca de três polegadas e meio de distância da frente do joelho). Um aperto supinado mais perto do que a largura do ombro é necessário para realizar este exercício. Dica: Seu braço deve ser estendido ao comprimento dos braços e a campainha deve estar acima do chão.","Enquanto segura os braços parados, enrole os pesos para a frente enquanto contrai os bíceps enquanto expira, apenas os antebraços devem se mover, continue o movimento até que seus bíceps estejam totalmente contraídos e os halteres estejam no nível do ombro, mantenha a posição contraída por um segundo enquanto aperta os bíceps.","Lentamente comece a trazer a campainha de volta à posição inicial enquanto respira.","Repita para a quantidade recomendada de repetições."]],"Seated_Dumbbell_Curl":["Curva de halteres Sentada",["Sente-se em um banco plano com um haltere em cada mão sendo segurado ao longo dos braços, os cotovelos devem estar perto do tronco.","Rodar as palmas das mãos para que estejam de frente para o seu torso.","Enquanto segura o braço parado, enrole os pesos e comece a torcer os pulsos assim que os halteres passarem suas coxas para que as palmas das suas mãos fiquem viradas para frente no final do movimento, certifique-se de contrair os bíceps enquanto expira e certifique-se de que apenas os antebraços se movem, continue o movimento até que seus bíceps estejam totalmente contraídos e os halteres estejam no nível do ombro, mantenha a posição contraída por um segundo enquanto aperta os bíceps.","Lentamente começar a trazer os halteres de volta para a posição inicial como sua respiração e como você gira os pulsos de volta para um aperto neutro.","Repita para a quantidade recomendada de repetições."]],"Seated_Dumbbell_Inner_Biceps_Curl":["Bíceps curvos internos sentados.",["Sente-se na extremidade de um banco plano com um haltere em cada mão sendo mantido ao longo dos braços os cotovelos devem estar perto do tronco.","Rodar as palmas das mãos para que eles estejam voltados para dentro em uma posição neutra.","Enquanto segura os braços parados, enrole os halteres para fora e para cima, girando as palmas para fora enquanto você levanta e mantendo seus antebraços em linha com seus deltoides externos.","Continue o movimento até que seus bíceps estejam totalmente contraídos e os halteres estejam no nível do ombro, mantenha a posição contraída por um segundo enquanto aperta os bíceps.","Lentamente comece a trazer os halteres de volta para a posição inicial enquanto você respira, lembre-se de girar os braços enquanto você baixa os halteres para que você possa mudar de volta para um aperto neutro.","Repita para a quantidade recomendada de repetições."]],"Seated_Dumbbell_Palms-Down_Wrist_Curl":["halteres sentado Palms-Down Wrist Curl",["Comece colocando dois halteres no chão em frente a um banco plano.","Sente-se na borda do banco plano com as pernas a cerca de largura do ombro afastada.","Use seus braços para agarrar os dois halteres e trazê-los para cima para que seus antebraços estejam descansando contra suas coxas com as palmas das mãos viradas para baixo.","Comece enrolando seu pulso para cima e expirando.","Abaixe os pulsos lentamente para a posição inicial enquanto inala, certifique-se de inalar durante esta parte do exercício, seus antebraços devem estar parados, pois seu pulso é o único movimento necessário para realizar esse exercício.","Repita para a quantidade recomendada de repetições.","Quando terminar, simplesmente abaixe os halteres para o chão."]],"Seated_Dumbbell_Palms-Up_Wrist_Curl":["halteres Palms-Up Wrist Curl",["Comece colocando dois halteres no chão em frente a um banco plano.","Sente-se na borda do banco plano com as pernas a cerca de largura do ombro afastada.","Use seus braços para agarrar os dois halteres e trazê-los para cima para que seus antebraços estejam descansando contra suas coxas com as palmas das mãos viradas para cima.","Comece enrolando seu pulso para cima e expirando.","Abaixe os pulsos lentamente para a posição inicial enquanto inala, certifique-se de inalar durante esta parte do exercício, seus antebraços devem estar parados, pois seu pulso é o único movimento necessário para realizar esse exercício.","Repita para a quantidade recomendada de repetições.","Quando terminar, simplesmente abaixe os halteres para o chão."]],"Seated_Dumbbell_Press":["Imprensa de halteres Sentada",["Pegue alguns halteres e sente-se em um banco de imprensa militar ou um banco de utilidades que tem um apoio traseiro enquanto você coloca os halteres em cima das coxas.","Limpe os halteres um de cada vez usando suas coxas para elevar os halteres à altura do ombro de cada lado.","Rodar os pulsos para que as palmas de suas mãos estejam voltadas para frente.","Enquanto você expira, empurre os halteres para cima até que eles toquem no topo.","Depois de uma segunda pausa, lentamente volte para a posição inicial enquanto você inala.","Repita para a quantidade recomendada de repetições."]],"Seated_Flat_Bench_Leg_Pull-In":["A perna de Bench Plana Sentada. Puxe.",["Sente-se em um banco com as pernas esticadas na sua frente um pouco abaixo do paralelo e seus braços segurando-se para os lados do banco.","Traga os joelhos em sua direção enquanto você move seu torso para perto deles ao mesmo tempo.","Depois de uma segunda pausa, volte para a posição inicial enquanto inala.","Repita para a quantidade recomendada de repetições."]],"Seated_Floor_Hamstring_Stretch":["Esticamento de fio dental no chão.",["Sente-se em um tapete com sua perna direita estendida na sua frente e sua perna esquerda dobrada com seu pé contra sua coxa interna direita.","Incline-se para frente dos quadris e segure o tornozelo até sentir um estiramento no tendão, segure por 15 segundos e repita para o outro lado."]],"Seated_Front_Deltoid":["Deltóide Frente Sentada",["Sente-se no chão com as pernas dobradas, seu parceiro parado atrás de você, coloque os braços para fora, com as palmas viradas para o chão, tente movê-los o mais longe possível, enquanto seu assistente segura os pulsos, esta será a sua posição inicial.","Mantendo os cotovelos retos, tentando mover os braços para a frente, com o seu parceiro gentilmente restringindo você para evitar qualquer movimento real por 10-20 segundos.","Agora, relaxe os músculos e deixe seu parceiro gentilmente aumentar o estiramento nos ombros e peito."]],"Seated_Glute":["Glute Sentado",["Em uma posição sentada com os joelhos dobrados, cruze um tornozelo sobre o joelho oposto, seu parceiro ficará atrás de você, agora, incline-se para frente enquanto seu parceiro segura seus ombros com as mãos, esta será a sua posição inicial.","Tente empurrar seu torso de volta por 10-20 segundos, já que seu parceiro impede qualquer movimento real de seu torso.","Agora relaxe os músculos enquanto seu parceiro aumenta o estiramento empurrando gentilmente seu torso para frente por 10-20 segundos."]],"Seated_Good_Mornings":["Bom dia.",["Coloque uma caixa em um suporte de energia, os pinos devem ser colocados em uma altura apropriada, comece por pisar sob a barra e colocá-la na parte de trás dos ombros, não em cima de suas armadilhas, aperte suas omoplatas e gire seus cotovelos para frente, tentando dobrar a barra em seus ombros.","Tire a barra do rack, criando um arco apertado na parte inferior das costas, mantenha a cabeça voltada para frente, com as costas, ombros e o núcleo apertados, empurre os joelhos e a bunda para fora e comece sua descida, sente-se com os quadris até estar sentado na caixa, esta será a sua posição inicial.","Mantendo a barra firme, dobre-se para frente nos quadris o máximo possível, se você definir os pinos para o que seria paralelo, você não só tem uma segurança se falhar, mas sabe quando parar.","Pausa acima dos pinos e inverta o movimento até que o torso fique ereto."]],"Seated_Hamstring":["Presunto Sentado.",["Agora, incline-se para frente enquanto seu parceiro segura seus ombros com as mãos.","Tente empurrar seu torso de volta por 10-20 segundos, já que seu parceiro impede qualquer movimento real de seu torso.","Agora relaxe os músculos enquanto seu parceiro aumenta o estiramento empurrando gentilmente seu torso para frente por 10-20 segundos."]],"Seated_Hamstring_and_Calf_Stretch":["Presunto Sentado e Esticamento de Calf",["Sente-se com as duas pernas estendidas, esta será sua posição inicial.","Inclinando-se ligeiramente para a frente, puxe o cinto para puxar os dedos do pé para trás."]],"Seated_Head_Harness_Neck_Resistance":["Resistência ao pescoço da cabeça sentada.",["Coloque uma cinta no chão no final de um banco plano, depois de selecionar os pesos, sente-se no final do banco plano com os pés mais largos que a largura do ombro, separados uns dos outros.","Agora segure o peso com as duas mãos enquanto eleva o torso para trás até que esteja quase perpendicular ao chão.","Coloque as duas mãos em cima dos joelhos.","Abaixe o pescoço lentamente até o queixo tocar a parte superior do peito enquanto respira.","Enquanto expira, traga seu pescoço de volta para a posição inicial.","Repita para a quantidade recomendada de repetições."]],"Seated_Leg_Curl":["Curva de Perna Assada",["Ajuste a alavanca da máquina para caber sua altura e sentar na máquina com as costas contra a almofada de apoio.","Coloque a parte de trás da perna em cima da alavanca acolchoada (apenas alguns centímetros abaixo das panturrilhas) e segure a almofada contra suas coxas, logo acima dos joelhos. Então segure as pegas laterais na máquina enquanto aponta seus dedos dos pés retos (ou você também pode usar qualquer uma das outras duas posições) e certifique-se de que as pernas estão totalmente retas bem na sua frente.","Enquanto expira, puxe a alavanca o máximo possível para a parte de trás das coxas, flexionando os joelhos, mantendo o tronco parado o tempo todo, mantendo a posição contraída por um segundo.","Retorne lentamente à posição inicial enquanto respira.","Repita para a quantidade recomendada de repetições."]],"Seated_Leg_Tucks":["Perna Asseada",["Sente-se em um banco com as pernas esticadas na sua frente um pouco abaixo do paralelo e seus braços segurando-se para os lados do banco.","Traga os joelhos em sua direção enquanto você move seu torso para perto deles ao mesmo tempo.","Depois de uma segunda pausa, volte para a posição inicial enquanto inala.","Repita para a quantidade recomendada de repetições."]],"Seated_One-Arm_Dumbbell_Palms-Down_Wrist_Curl":["Curva de pulso sentado com um braço só, com o Mumbell Palms-Down Wrist.",["Sente-se em um banco plano com um haltere na mão direita.","Coloque seus pés no chão, a uma distância um pouco maior do que a largura do ombro.","Incline-se para a frente e coloque o antebraço direito em cima da coxa direita com a palma da mão para baixo.","Abaixe o haltere o mais longe possível, mantenha um aperto apertado no haltere.","Agora enrole o haltere o mais alto possível, contraindo os antebraços e exalando, mantenha a contração por um segundo antes de abaixar novamente, o único movimento deve acontecer no pulso.","Execute para a quantidade recomendada de repetições, mude de braços e repita o movimento."]],"Seated_One-Arm_Dumbbell_Palms-Up_Wrist_Curl":["Curva de pulso de um braço sentado.",["Sente-se em um banco plano com um haltere na mão direita.","Coloque seus pés no chão, a uma distância um pouco maior do que a largura do ombro.","Incline-se para a frente e coloque o antebraço direito em cima da coxa direita com a palma da mão para cima.","Abaixe o haltere o mais longe possível, mantenha um aperto apertado no haltere.","Agora enrole o haltere o mais alto possível, contraindo os antebraços e exalando, mantenha a contração por um segundo antes de abaixar novamente, o único movimento deve acontecer no pulso.","Execute para a quantidade recomendada de repetições, mude de braços e repita o movimento."]],"Seated_One-arm_Cable_Pulley_Rows":["Filas de polia de cabo de um braço sentado",["Para entrar na posição inicial, primeiro sente-se na máquina e coloque seus pés na plataforma da frente ou barra transversal desde que seus joelhos estejam ligeiramente dobrados e não trancados.","Incline-se enquanto mantém o alinhamento natural das costas e agarre o único punho com o braço esquerdo usando um aperto de palmas para baixo.","Com o braço estendido, puxe para trás até o torso estar em um ângulo de 90 graus das pernas, suas costas devem ser ligeiramente arqueadas e seu peito deve estar se estendendo para fora, você deve estar se sentindo bem esticado enquanto segura a barra na sua frente, o braço direito pode ser mantido pela cintura, esta é a posição inicial do exercício.","Mantendo o torso parado, puxe as alças para trás em direção ao torso enquanto mantém os braços perto dele enquanto você gira o pulso, de modo que no momento em que sua mão está por seus abdominais, ele está em uma posição neutra (palmas voltadas para o torso).","Lembre-se de girar o pulso enquanto você volta para a posição inicial para que as palmas estejam viradas para baixo novamente.","Repita para a quantidade recomendada de repetições e então faça o mesmo movimento com a mão direita."]],"Seated_Overhead_Stretch":["\"Sente-se sobre a cabeça esticada\"",["Sente-se direito em um tapete de exercício.","Toque as solas de seus pés junto com seus pés de seis a oito polegadas na frente de seus quadris.","Coloque uma mão no chão ao seu lado e sua outra mão atrás da cabeça.","Levante o cotovelo para o teto enquanto inclina o tronco para o outro lado, segure por 10 a 20 segundos e mude de lado."]],"Seated_Palm-Up_Barbell_Wrist_Curl":["Palm-Up Palmbell Barrist Currl",["Segure uma campainha com as duas mãos e as palmas viradas para cima, com as mãos espaçadas sobre a largura do ombro.","Coloque seus pés no chão, a uma distância um pouco maior do que a largura do ombro.","Incline-se para a frente e coloque seus antebraços em cima de suas coxas com as palmas para cima.","Abaixe a barra o máximo possível enquanto inala e mantém um aperto apertado.","Agora enrole a barra o mais alto possível enquanto flexiona os antebraços e exala."]],"Seated_Palms-Down_Barbell_Wrist_Curl":["\"Sentei Palms-Down Barbell Wrist Curl\"",["Segure uma campainha com as duas mãos e as palmas viradas para baixo, com as mãos espaçadas sobre a largura do ombro.","Coloque seus pés no chão, a uma distância um pouco maior do que a largura do ombro.","Incline-se para a frente e coloque seus antebraços em cima de suas coxas com as palmas para baixo.","Abaixe a barra o máximo possível enquanto inala e mantém um aperto apertado.","Agora enrole a barra o mais alto possível enquanto flexiona os antebraços e exala."]],"Seated_Side_Lateral_Raise":["Assalto lateral sentado.",["Pegue um par de halteres e sente-se no final de um banco plano com os pés firmes no chão, segure os halteres com as palmas viradas para dentro e seus braços para baixo, de braços abertos, esta será a sua posição inicial.","Enquanto mantém o tronco parado (sem balanço), levante os halteres para o seu lado com uma ligeira curva no cotovelo e as mãos ligeiramente inclinadas para a frente como se derramando água em um copo. Continue a subir até que os braços estejam paralelos ao chão. Expire enquanto executa este movimento e pause por um segundo no topo.","Abaixe os halteres lentamente para a posição inicial enquanto inala.","Repita para a quantidade recomendada de repetições."]],"Seated_Triceps_Press":["Imprensa de Tríceps Sentado",["Sente-se em um banco com apoio nas costas e segure um haltere com ambas as mãos e segure-o ao longo do braço.","Mantendo os braços superiores perto da cabeça e perpendiculares ao chão, abaixe a resistência em um movimento semicircular atrás da cabeça até que seus antebraços toquem seus bíceps.","Volte para a posição inicial usando os tríceps para levantar o haltere.","Repita para a quantidade recomendada de repetições."]],"Seated_Two-Arm_Palms-Up_Low-Pulley_Wrist_Curl":["Cão de pulso de dois braços, baixo pulso.",["Coloque um banco na frente de uma máquina de polia baixa que tenha uma barra ou EZ Curl anexado nela.","Mova o banco para longe o suficiente para que quando você levar a alça para o topo de suas coxas tensão é criada no cabo devido à pilha de peso sendo movido para cima.","Agora segure o cabo com as duas mãos, palmas para cima, usando um aperto de ombro-largura.","Afaste-se e sente-se no banco com os pés à volta da largura do ombro, firmemente no chão.","Incline-se para a frente e coloque os antebraços nas coxas com os pulsos sobre os joelhos.","Abaixe a barra o mais longe possível, enquanto inala e mantém um aperto apertado.","Agora enrole a barra o mais alto possível enquanto contrai os antebraços.","Depois de uma segunda contração no topo voltar para a posição inicial enquanto você inala.","Repita para a quantidade recomendada de repetições."]],"See-Saw_Press_Alternating_Side_Press":["See-saw Press (Pressão lateral alternada)",["Pegue um haltere com cada mão e levante-se.","Limpe os halteres para o nível peito/ombro e depois gire seus pulsos para que suas palmas estejam voltadas para você como se estivesse se preparando para executar uma Arnold Press.","Agora comece a estender seu braço esquerdo para cima enquanto roda o pulso para que a palma da sua mão se desloque para a frente enquanto sobe, seus cotovelos devem sair também quando levanta o peso, simultaneamente, você também estará dobrando do quadril para o lado oposto.","Depois, com o peso totalmente estendido e você se curvando para o lado direito, comece o movimento para o lado esquerdo.","Repita para a quantidade recomendada de repetições."]],"Shotgun_Row":["Fila de tiro.",["Coloque uma única alça em um cabo baixo.","Depois de selecionar o peso correto, fique um pouco para trás com uma posição largada, seu braço deve ser estendido e seu ombro para frente, esta será sua posição inicial.","Faça o movimento retraindo o ombro e flexionando o cotovelo, enquanto puxa, supina o pulso, girando a palma da mão para cima.","Após uma breve pausa, volte para a posição inicial."]],"Shoulder_Circles":["Círculos de ombros",["Com ombros relaxados e braços descansando frouxamente em seus lados (ou em seu colo se você estiver sentado), gentilmente enrole seus ombros para frente, para cima, para trás e para baixo.","Você pode fazer esse exercício alternando ombros ou ambos ao mesmo tempo."]],"Shoulder_Press_-_With_Bands":["Ombros com faixas",["Para começar, coloque-se em uma faixa de exercício para que a tensão comece ao comprimento do braço, segure as alças e levante-as para que as mãos estejam em altura do ombro de cada lado.","Rodar os pulsos para que as palmas das mãos estejam voltadas para frente, seus cotovelos devem ser dobrados, com os braços e antebraços na linha do tronco.","Enquanto você expira, levante as alças até que seus braços estejam totalmente estendidos."]],"Shoulder_Raise":["Levante o ombro.",["Relaxem os braços para os lados e levantem os ombros em direção às orelhas, e voltem para baixo."]],"Shoulder_Stretch":["Ombro esticar",["Alcance seu braço esquerdo através de seu corpo e segure-o direito."]],"Side-Lying_Floor_Stretch":["Esticamento do andar lateral",["Primeiro, deite-se do lado esquerdo, dobrando o joelho esquerdo na sua frente para estabilizar seu torso (use seus músculos abdominais também para segurá-lo na vertical).","Endireite a perna direita e coloque o pé direito no chão atrás da esquerda, estique o braço direito sobre a cabeça e puxe suavemente o pulso direito para esticar todo o lado direito do corpo."]],"Side_Hop-Sprint":["Lado Hop-Sprint",["Fique do lado de um cone ou obstáculo.","Comece este exercício pulando de lado sobre o obstáculo, recuperando-se de seu pouso para saltar de volta para onde você começou.","Pule por um número prescrito ou repetições o mais rápido possível, e termine este exercício correndo a uma curta distância ao pousar o último salto."]],"Side_Lateral_Raise":["Levante-se lateralmente",["Escolha dois halteres e fique com um torso reto e os halteres ao seu lado com as palmas da mão voltadas para você.","Enquanto mantém o tronco em uma posição estacionária (sem balanço), levante os halteres para o seu lado com uma ligeira curva no cotovelo e as mãos ligeiramente inclinadas para a frente como se derramando água em um copo. Continue a subir até que os braços sejam paralelos ao chão. Expire enquanto você executa este movimento e pause por um segundo no topo.","Abaixe os halteres lentamente para a posição inicial enquanto inala.","Repita para a quantidade recomendada de repetições."]],"Side_Laterals_to_Front_Raise":["Laterais laterais para a frente levantar",["Em pé, segure um par de halteres ao seu lado.","Mantendo seus cotovelos ligeiramente dobrados, levante os pesos diretamente na sua frente para a altura do ombro, evitando qualquer balanço ou trapacear.","No topo do exercício, mova os pesos na sua frente, mantendo seus braços estendidos.","Abaixe os pesos com um movimento controlado.","Na próxima repetição, levante os pesos na sua frente para a altura do ombro antes de mover os pesos lateralmente para os seus lados.","Abaixe os pesos para a posição inicial."]],"Side_Leg_Raises":["Perna lateral sobe.",["Fique ao lado de uma cadeira, que você pode segurar como apoio.","Mantendo sua perna reta, levante-a o mais longe possível, e balance-a de volta para baixo, permitindo que ela atravesse a perna oposta.","Repita este movimento oscilando 5-10 vezes, aumentando a amplitude de movimento como você faz."]],"Side_Lying_Groin_Stretch":["Esticamento da virilha deitada lateral",["Comece deitado do lado direito e dobre o joelho direito na sua frente para estabilizar o tronco.","Levante a perna esquerda para cima e segure-a na parte de trás do joelho (mais fácil) ou no pé (mais forte).","Puxe o joelho esquerdo em direção ao ombro esquerdo e, simultaneamente, pressione o pé ou joelho até o chão para intensificar este estiramento, endireitar a perna esquerda."]],"Side_Neck_Stretch":["Esticamento do pescoço lateral",["Comece com os ombros relaxados, gentilmente incline a cabeça para o ombro.","Auxiliar esticar com uma leve puxada na cabeça."]],"Side_Standing_Long_Jump":["Lado em pé salto longo",["Comecem com os pés e largura do quadril separados em uma postura atlética, sua cabeça e peito devem estar para cima, joelhos e quadris ligeiramente dobrados, esta será sua posição inicial.","Inclinando-se para a direita, estendendo-se pelos quadris, joelhos e tornozelos para pular no ar, bloqueie com os braços para liderar o movimento, pulando o mais longe possível para a direita.","Terra virada para a mesma direção com seus pés de largura do quadril separados, absorvendo o impacto através de seu corpo inferior."]],"Side_To_Side_Chins":["Lado a lado Chins",["Pegue a barra com as palmas voltadas para a frente usando um aperto largo.","Como você tem os dois braços estendidos na frente de você segurando a barra em um aperto largo, traga seu torso de volta em torno de 30 graus ou assim, enquanto cria uma curvatura em suas costas inferiores e colocar o peito para fora.","Puxe o torso para cima enquanto se inclina para o lado esquerdo até que a barra quase toque seu peito superior puxando os ombros e os braços para baixo e para trás. Expire enquanto você executa esta parte do movimento. Dica: Concentre-se em apertar os músculos das costas uma vez que você atinja a posição contraída completa. O torso superior deve permanecer parado enquanto ele se move através do espaço (sem balanço) e apenas os braços devem mover. Os antebraços não devem fazer outro trabalho além de segurar a barra.","Depois de um segundo de contração, inale enquanto volta para a posição inicial.","Agora, puxe seu torso para cima enquanto se inclina para o lado direito até que a barra quase toque seu peito superior, desenhando os ombros e os braços para baixo e para trás. Expire enquanto você executa esta parte do movimento. Dica: Concentre-se em apertar os músculos das costas uma vez que você atinja a posição contraída completa.","Depois de um segundo de contração, inale enquanto volta para a posição inicial.","Repita os passos 3-6 até que você tenha realizado a quantidade prescrita de repetições para cada lado."]],"Side_Wrist_Pull":["Pulso lateral do pulso",["Cruze o braço esquerdo sobre a linha média do seu corpo e segure o pulso esquerdo na mão direita para baixo no nível de seus quadris.","Endireite-se lentamente, puxe e levante até a altura do ombro, como imaginamos, sinta este estiramento originar-se nas costas, não nos ombros, e não puxe muito forte na articulação dos ombros."]],"Side_to_Side_Box_Shuffle":["Do lado para o lado da caixa Shuffle",["Fique em um lado da caixa com seu pé esquerdo descansando no meio dela.","Para começar, salte para cima e para o outro lado da caixa, pousando com o pé direito em cima da caixa e o pé esquerdo no chão.","Continue mexendo para frente e para trás através da caixa."]],"Single-Arm_Cable_Crossover":["Cabo de um braço cruzado.",["Comece movendo as polias para a posição alta, selecione a resistência a ser usada, e pegue uma alça em cada mão.","Aproxime-se na frente de ambas as polias com os braços estendidos na sua frente, unindo as mãos, sua cabeça e peito devem ser levantados enquanto você se inclina para frente, enquanto seus pés devem ser cambaleados.","Manter o braço esquerdo no lugar, permitir que o braço direito se estenda para o lado, mantendo uma pequena curva no cotovelo, o braço direito deve ser perpendicular ao corpo em aproximadamente nível de ombro.","Devolva seu braço para a posição inicial puxando sua mão de volta para a linha média do corpo.","Segure por um segundo na posição inicial e repita o movimento do lado oposto, continue alternando para trás e para frente para o número prescrito de repetições."]],"Single-Arm_Linear_Jammer":["Jammer Linear de braço único.",["Posicione uma barra em uma mina terrestre ou tranque-a em um canto e carregue a barra em um peso apropriado.","Levante a barra do chão, levando-a para os ombros com uma ou ambas as mãos, adote uma postura ampla, esta será a sua posição inicial.","Execute o movimento estendendo o cotovelo, pressionando o peso para cima, mova-se explosivamente, estendendo os quadris e joelhos completamente para produzir força máxima.","Voltem para a posição inicial."]],"Single-Arm_Push-Up":["Um braço para cima.",["Começar a se pronar no chão... mover-se para uma posição que sustente seu peso em seus dedos e um braço... seu braço de trabalho deve ser colocado diretamente sob o ombro, totalmente estendido... suas pernas devem ser estendidas, e para este movimento você pode precisar de uma base mais larga, colocando seus pés mais afastados do que em uma flexão normal.","Mantenha boa postura, e coloque sua mão livre atrás das costas.","Abaixe-se, permitindo que o cotovelo flexione até tocar o chão.","Desça devagar, e inverta a direção... e estenda o braço para voltar à posição inicial."]],"Single-Cone_Sprint_Drill":["Perfuração de Sprint single-cone",["Esta broca ensina ação rápida dos pés, você precisa de um único cone, comece a ficar ao lado do cone com um braço para trás e um braço para frente.","Corte os pés o mais rápido possível, bloqueando com os braços, circule o cone, mantenha os joelhos para cima, com ação violenta dos pés.","Descanse depois de três viagens ao redor do cone."]],"Single-Leg_High_Box_Squat":["Agachamento de uma só perna.",["Coloque uma caixa em um rack, coloque uma corda ou uma corda sobre a caixa.","Em pé na frente dele, pise na caixa para uma posição de pé, deixando sua outra perna ficar sem apoio.","Continue subindo e descendo na mesma perna antes de mudar para o lado oposto."]],"Single-Leg_Hop_Progression":["Progressão de Hop de uma só perna",["Organize uma linha de cones na sua frente, assuma uma posição de pé relaxada, balanceada em uma perna, levante o joelho da perna oposta, esta será a sua posição inicial.","Pule para frente, pule e pouse com a mesma perna sobre o cone.","Use um salto contra movimento para pular de cone para cone.","No final, vire-se e volte para a outra perna."]],"Single-Leg_Lateral_Hop":["Hop lateral de uma só perna.",["Para entrar na posição inicial, fique em uma perna com o joelho ligeiramente dobrado.","Para começar, execute um contra-salto para pular de lado sobre o cone.","Pouse na sua perna pulando, e imediatamente se recupere, pulando de volta para a posição inicial.","Continue pulando para trás e para frente."]],"Single-Leg_Leg_Extension":["Extensão da perna de uma perna",["Sente-se na máquina e ajuste-a para que esteja posicionada corretamente, a almofada deve estar contra a parte inferior da canela, mas não em contato com o tornozelo, ajuste o assento para que o ponto pivô esteja em linha com o joelho, selecione um peso apropriado para suas habilidades.","Mantendo boa postura, estendendo completamente uma perna, parando no topo do movimento.","Volte para a posição inicial sem deixar o peso parar, mantendo a tensão no músculo.","Repita para o número desejado de repetições."]],"Single-Leg_Stride_Jump":["Stride Jump de uma só perna",["Fique ao lado de uma caixa com seu pé dentro em cima, perto da borda.","Comece balançando os braços para cima enquanto você empurra através da perna superior, pulando para cima o mais alto possível.","Aterrisse na mesma posição que começou, usando sua perna interior para desacelerar o impacto."]],"Single_Dumbbell_Raise":["Levante-se um haltere.",["Com uma postura ampla, segure um burro com as duas mãos, agarrando a cabeça do haltere em vez do cabo, seus braços devem ser estendidos e pendurados na cintura, esta será a sua posição inicial.","Levante o peso até que esteja acima do nível do ombro, mantendo os braços estendidos, seu tronco e quadris devem permanecer parados durante todo o movimento.","Volte para a posição inicial e repita a quantidade recomendada de repetições."]],"Single_Leg_Butt_Kick":["Chute no rabo da perna única.",["Comece em pé em uma perna, com o joelho dobrado levantado.","Usando um salto contra movimento, decolar para cima, estendendo o quadril, joelho e tornozelo da perna de castigo.","Imediatamente flexione o joelho e tente tocar sua bunda com o calcanhar de sua perna pulando.","Sua perna oposta deve ficar na mesma posição durante a broca."]],"Single_Leg_Glute_Bridge":["Ponte Glute de Perna Única",["Deite-se no chão com os pés lisos e os joelhos dobrados.","Levante uma perna do chão, puxando o joelho para o peito.","Execute o movimento dirigindo pelo calcanhar, estendendo seu quadril para cima e levantando seus glúteos do chão.","Estenda o máximo possível, pause e depois volte para a posição inicial."]],"Single_Leg_Push-off":["\"Push-off da perna única\"",["Fique no chão com um pé descansando na caixa, calcanhar perto da borda.","Empurre com o pé em cima da caixa, tentando ganhar o máximo de altura possível, estendendo-se através do quadril e joelho.","Aterrisse com o mesmo pé em cima da caixa, devolvendo seu outro pé de volta à posição inicial."]],"Sit-Up":["Sente-se.",["Deite-se no chão colocando seus pés debaixo de algo que não vai se mover ou tendo um parceiro segurá-los.","Coloque as mãos atrás da cabeça e tranque-as, apertando os dedos.","Eleve sua parte superior do corpo para que ele crie uma forma V imaginária com suas coxas.","Uma vez que sentir a contração por um segundo, abaixe sua parte superior do corpo de volta para a posição inicial enquanto inala.","Repita para a quantidade recomendada de repetições."]],"Sit_Squats":["Sente-se Agachados",["Esta será sua posição inicial.","Comece o movimento flexionando seus joelhos e quadris, sentando-se com seus quadris.","Continue até que você tenha agachado uma parte do caminho para baixo, mas esteja acima do paralelo, e rapidamente reverta o movimento até que você retorne à posição inicial."]],"Skating":["Patinagem",["A patinação é uma atividade divertida que pode ser eficaz em melhorar a aptidão cardiorrespiratória e a resistência muscular, requer equilíbrio e coordenação relativamente bons, é necessário aprender o básico da patinação, incluindo girar e parar e usar equipamento protetor para evitar possíveis lesões.","Se quiser um desafio cardiológico, faça uma patinação intervalada, dois minutos de cada cinco minutos, usando os três minutos restantes para se recuperar, uma pessoa de 150 quilos normalmente queima 175 calorias em 30 minutos patinando em um ritmo confortável, semelhante a uma caminhada rápida."]],"Sled_Drag_-_Harness":["Sled Drag - Harness",["Para começar, carregue o trenó com o peso desejado e prenda a correia de tração.","Seja puxando para frente ou para trás, incline-se na direção da viagem e progresso estendendo-se através dos quadris e joelhos."]],"Sled_Overhead_Backward_Walk":["Andando de cabeça para baixo",["Anexar duas alças a um trenó conectado por uma corda ou corrente.","Vire-se para o trenó, retroceda até que haja alguma tensão na linha, segure as mãos diretamente acima da cabeça com os cotovelos estendidos, esta será a sua posição inicial.","Ande para trás, mantendo os braços levantados acima da cabeça, evite movimentos de carne seca."]],"Sled_Overhead_Triceps_Extension":["Extensão de Tríceps Deslizado",["Coloque duas alças em um trenó usando uma corrente ou corda.","De frente para o trenó, afastem-se até que haja tensão na linha, levantem as mãos acima da cabeça, mantendo-as juntas, palmas viradas uma para a outra, cotovelos apontados para cima com os cotovelos flexionados, esta será sua posição inicial.","Estenda o cotovelo para endireitar o braço, certifique-se de que o braço fique em posição para isolar o tríceps.","Após extensão total, um passo à frente para tirar a folga da linha."]],"Sled_Push":["Sled Push.",["Carregue seu trenó empurrando com o peso desejado.","Pegue uma postura atlética, inclinando-se para o trenó com os braços estendidos, agarrando as alças, empurrando o trenó o mais rápido possível, focando em estender seus quadris e joelhos para fortalecer sua cadeia posterior."]],"Sled_Reverse_Flye":["Sled Reverse Flye",["Anexar duas alças a um trenó conectado por uma corda ou corrente.","Enfrente o trenó, retroceda até que haja alguma tensão na linha, pegue as duas alças com o comprimento dos braços ao nível da cintura, dobre os joelhos ligeiramente e mantenha seu peito e cabeça para cima, esta será a sua posição inicial.","Sem flexionar o cotovelo, puxar as alças para cima e para fora, realizando uma mosca reversa com alguma rotação externa.","Volte para a posição inicial, dando alguns passos de volta para tirar a folga da linha."]],"Sled_Row":["Sled Row",["Anexar alças duplas a um trenó conectado por uma corda ou corrente, carregar o trenó a um peso apropriado, enfrentar o trenó, recuar até que haja alguma tensão na linha.","Com um punho em cada mão, dobre os joelhos ligeiramente, mantenha sua cabeça e peito para cima, e comece com os braços estendidos.","Para iniciar o movimento, flexione o cotovelo enquanto você retrai suas omoplatas, puxando o trenó em sua direção.","Dê um ou dois passos para trás para ter tensão na linha e repetir."]],"Sledgehammer_Swings":["Sledgehammer balanços",["Você vai precisar de um pneu e uma marreta para este exercício.","Se você é destro, sua mão esquerda deve estar na parte inferior do cabo, e sua mão direita deve estar sufocando mais perto da cabeça.","Quando você levanta o trenó, sua mão direita desliza em direção à cabeça, enquanto você balança para baixo, sua mão direita desliza para baixo para se juntar à sua mão esquerda, derrubá-lo o mais forte que puder contra o pneu, controlar a batida do martelo do pneu.","Repita do outro lado."]],"Smith_Incline_Shoulder_Raise":["Smith Incline Ombro Levantar",["Coloque um banco incline abaixo da máquina do ferreiro, coloque a campainha em uma altura que você pode alcançar quando estiver deitado e seus braços estiverem quase totalmente estendidos, assim que o peso que você precisa for selecionado, deite-se no banco incline e certifique-se de que seus ombros estejam alinhados bem debaixo da campainha.","Usando uma largura de ombro pronada (palmas para a frente) aperto, levantar a barra do rack e segurá-lo em cima de você com uma ligeira curva nos cotovelos.","Quando expirar, levante a barra até que seus braços estejam totalmente estendidos.","Depois de uma segunda pausa, traga a barra de volta para a posição inicial enquanto você respira.","Repita o movimento para a quantidade prescrita de repetições.","Quando terminar, coloque o bar de volta no rack."]],"Smith_Machine_Behind_the_Back_Shrug":["\"Máquina Smith Atrás do Encolhimento\"",["Com a barra no nível da coxa, carregue um peso apropriado.","Fique com a barra atrás de você, tomando uma amplitude de ombro, segurando a barra e soltando o peso, você deveria estar de pé com a cabeça e o peito para cima e os braços estendidos.","Não flexione os braços ou o pulso durante o movimento.","Depois de uma breve pausa, devolva o peso para a posição inicial.","Repita para o número desejado de repetições antes de usar os ganchos para empilhar o peso."]],"Smith_Machine_Bench_Press":["Smith Machine Bench Press",["Coloque um banco plano embaixo da máquina do ferreiro, agora coloque a campainha em uma altura que você pode alcançar quando estiver deitado e seus braços estiverem quase totalmente estendidos, assim que o peso que você precisa estiver selecionado, deite-se no banco plano, usando um aperto pronado que seja maior que a largura do ombro, destrave a barra do rack e segure-a sobre você com os braços trancados, esta será a sua posição inicial.","Enquanto respira, desça devagar até sentir a barra no peito.","Depois de uma segunda pausa, traga a barra de volta para a posição inicial enquanto expira e empurre a barra usando os músculos do peito, tranque os braços na posição contraída, segure por um segundo e comece a descer lentamente novamente.","Repita o movimento para a quantidade prescrita de repetições.","Quando terminar, tranque o bar no rack."]],"Smith_Machine_Bent_Over_Row":["Smith Machine Bent Over Row",["Coloque a campainha ligada à máquina de ferreiro em uma altura de cerca de 2 polegadas abaixo de seus joelhos.","Dobre os joelhos um pouco e traga o torso para frente, dobrando a cintura, mantendo as costas retas até que seja quase paralela ao chão.","Agora segure a campainha usando um aperto de mão (pronada) e destranque-a da prateleira da máquina do ferreiro e deixe-a pendurada diretamente na sua frente enquanto seus braços pendem perpendicularmente ao chão e ao tronco.","Enquanto mantém o torso parado, levante a campainha enquanto expira, mantendo os cotovelos perto do corpo e não fazendo nenhuma força com o antebraço além de segurar os pesos.","Devagar, reduza o peso novamente para a posição inicial enquanto inala.","Repita para a quantidade recomendada de repetições."]],"Smith_Machine_Calf_Raise":["Smith Machine Calf Levantar",["Coloque um bloco ou placa de peso abaixo da barra na máquina Smith, coloque a barra em uma posição que melhor corresponda à sua altura, assim que a altura correta for escolhida e a barra estiver carregada, pise nas placas com as bolas dos pés e coloque a barra na parte de trás dos ombros.","Pegue o bar com as duas mãos viradas para frente, gire o bar para desenrascar, esta será a sua posição inicial.","Levante os calcanhares o mais alto possível empurrando as bolas dos pés, flexionando o bezerro no topo da contração, seus joelhos devem permanecer estendidos, mantenha a posição contraída por um segundo antes de começar a descer.","Volte devagar para a posição inicial enquanto você respira enquanto baixa os calcanhares.","Repita para a quantidade recomendada de repetições."]],"Smith_Machine_Close-Grip_Bench_Press":["Smith Machine Close-Grip Bench Press",["Coloque um banco plano embaixo da máquina do ferreiro, coloque a campainha em uma altura que você pode alcançar quando estiver deitado e seus braços estiverem quase totalmente estendidos, uma vez que o peso que você precisa esteja selecionado, deite-se no banco plano, usando um aperto próximo e pronado (palmas voltadas para frente) que esteja ao redor da largura do ombro, destrave a barra do rack e segure-a diretamente sobre você com os braços trancados, esta será a sua posição inicial.","Quando respirar, desça devagar até sentir a barra no peito médio, e certifique-se de que, ao invés de uma pressão normal, mantenha os cotovelos perto do tronco o tempo todo para maximizar o envolvimento do tríceps.","Depois de uma segunda pausa, traga a barra de volta para a posição inicial enquanto expira e empurre a barra usando os músculos do tríceps, tranque os braços na posição contraída, segure por um segundo e comece a descer lentamente novamente.","Repita o movimento para a quantidade prescrita de repetições.","Quando terminar, tranque o bar no rack."]],"Smith_Machine_Decline_Press":["Smith Machine Decline Press",["Coloque um banco de declive no rack para que a barra fique acima do seu peito, carregue um peso apropriado e tome o seu lugar no banco.","Rodar a barra para desapertá-la do rack e estender completamente seus braços, suas costas devem ser ligeiramente arqueadas e suas omoplatas retraídas.","Comece o movimento, flexionando os braços, baixando a barra para o peito.","Pause brevemente, e então estenda seus braços para empurrar o peso de volta para a posição inicial.","Depois de completar o número desejado de repetições, gire a barra para empilhar o peso."]],"Smith_Machine_Hang_Power_Clean":["Smith Machine Hang Power Clean",["Posicione a barra na altura do joelho e carregue-a para um peso adequado.","Pegue a barra do lado de fora da largura do ombro e desaperte a barra da máquina, seus braços devem ser estendidos com a cabeça e o peito para cima, seus cotovelos devem ser apontados com os ombros para trás e para baixo, seus quadris devem estar de volta, carregando a tensão nos isquiotibiais, esta será a sua posição inicial.","Incentive o movimento com força estendendo os quadris e joelhos, acelerando para a barra, certifique-se de manter seus braços retos durante esta parte do movimento.","Após extensão total, redobre os quadris e joelhos para baixar sua posição de recepção.","Permita que os braços flexionem neste ponto, girando os cotovelos ao redor da barra para recebê-lo em seus ombros.","Estenda os quadris e joelhos para chegar a uma posição de pé com a barra em seus ombros para completar o movimento."]],"Smith_Machine_Hip_Raise":["\"Máquina Smith Hip Eleve\"",["Coloque um banco no rack e carregue a barra para um peso adequado, deite-se no banco, colocando o fundo dos pés contra a barra, destranque a barra e estenda as pernas, pode precisar usar as mãos para ajudá-lo, para que a estabilidade aumente, agarre os lados da Máquina Smith, esta será a sua posição inicial.","Iniciar o movimento girando sua pélvis, flexionando sua coluna para levantar os quadris do banco, mantendo uma leve curva nos joelhos ao longo do movimento.","Depois de uma breve pausa, devolva os quadris para o banco.","Repita para o número desejado de repetições."]],"Smith_Machine_Incline_Bench_Press":["Smith Machine Incline Bench Press",["Coloque um banco incline abaixo da máquina de ferreiro, coloque a campainha em uma altura que você pode alcançar quando estiver deitado e seus braços estiverem quase totalmente estendidos, assim que o peso que você precisa estiver selecionado, deite-se no banco incline e certifique-se de que seu peito superior esteja alinhado com a campainha, usando um aperto pronado (palmas voltadas para frente) que seja maior do que a largura do ombro, destrave a barra do rack e segure-a diretamente sobre você com os braços trancados, esta será a sua posição inicial.","Enquanto respira, desça devagar até sentir a barra no peito.","Depois de uma segunda pausa, traga a barra de volta para a posição inicial enquanto expira e empurre a barra usando os músculos do peito, tranque os braços na posição contraída, segure por um segundo e comece a descer lentamente novamente.","Repita o movimento para a quantidade prescrita de repetições.","Quando terminar, coloque o bar de volta no rack."]],"Smith_Machine_Leg_Press":["Smith Machine Leg Press",["Posicione uma barra de uma máquina Smith a alguns metros do chão, certifique-se de que ela esteja descansando sobre os cofres, depois de carregar a barra para um peso adequado, deite-se debaixo da barra, coloque o meio dos pés na barra, colocando os joelhos no peito, esta será a sua posição inicial.","Comece o movimento dirigindo através de seus pés para mover a barra para cima, estendendo os quadris e joelhos.","No topo da moção, pare brevemente antes de voltar para a posição inicial."]],"Smith_Machine_One-Arm_Upright_Row":["Smith Machine One-Arm Upright Row",["Com a barra no nível da coxa, carregue um peso apropriado.","Segure bem a barra e solte o peso, retirando sua mão da barra, e seu braço deve ser estendido quando estiver de cabeça e peito para cima, esta será sua posição inicial.","Comece o movimento, flexionando o cotovelo, levantando a parte superior do braço com o cotovelo apontado.","Após uma breve pausa, devolva o peso para a posição inicial.","Repita para o número desejado de repetições antes de usar os ganchos para empilhar o peso."]],"Smith_Machine_Overhead_Shoulder_Press":["Smith Machine Overhead Shoulder Press",["Para começar, coloque um banco plano (ou de preferência um com apoio de costas) sob uma máquina de ferreiro.","Quando tiver a altura correta, sente-se um pouco atrás da campainha para que haja uma linha reta imaginária da ponta do seu nariz até a campainha, seus pés devem estar parados, pegue a campainha com as palmas viradas para a frente, destrave-a e levante-a para que seus braços sejam totalmente estendidos, esta é a posição inicial.","Lentamente comece a baixar o barbelo até que esteja nivelado com seu queixo enquanto inala.","Então levante a campainha de volta para a posição inicial usando seus ombros enquanto expira.","Repita para a quantidade recomendada de repetições."]],"Smith_Machine_Pistol_Squat":["Smith Machine Pistol Squat",["Para começar, defina a barra para uma posição que melhor corresponda à sua altura.","Pegue o bar com as mãos voltadas para a frente, destranque-o e levante-o da prateleira estendendo as pernas.","Olhe para frente e mantenha uma espinha neutra ou ligeiramente arqueada, esta será sua posição inicial.","Mantendo uma boa postura, abaixe-se flexionando o joelho e o quadril, descendo tanto quanto a flexibilidade permite.","Pause brevemente na parte inferior e então volte para a posição inicial dirigindo através do calcanhar do seu pé, estendendo o joelho e quadril."]],"Smith_Machine_Reverse_Calf_Raises":["Smith Machine Reverse Calf levanta.",["Ajuste a campainha na máquina do ferreiro para caber em sua altura e alinhar uma plataforma levantada bem debaixo da barra.","Fique na plataforma com os calcanhares dos pés em cima, com as bolas dos pés estendidas, posicione os dedos dos pés para frente, com uma posição de largura de ombro.","Agora, coloque seus ombros sob a barra enquanto mantém o posicionamento do pé descrito e empurre a barra para cima estendendo seus quadris e joelhos até que seu tronco esteja ereto os joelhos devem ser mantidos com uma pequena curva, nunca trancados esta será a sua posição inicial","Levante as bolas dos pés enquanto expira, estendendo os dedos o mais alto possível e flexionando seu bezerro, certifique-se de que o joelho fique parado o tempo todo, não deve haver dobra a qualquer momento, mantenha a posição contraída por um segundo antes de começar a descer.","Lentamente volte para a posição inicial enquanto você respira baixando as bolas dos pés e dos pés.","Repita para a quantidade recomendada de repetições."]],"Smith_Machine_Squat":["\"Smith Machine Squat\"",["Para começar, primeiro coloque a barra na altura que melhor corresponde à sua altura, assim que a altura correta for escolhida e a barra estiver carregada, passe por baixo da barra e coloque a parte de trás dos ombros (um pouco abaixo do pescoço) através dela.","Segure na barra usando ambos os braços de cada lado (palmas voltadas para frente), destranque-a e levante-a da prateleira empurrando-a primeiro com as pernas e, ao mesmo tempo, endireitando o tronco.","Esta é a sua posição inicial, para os fins desta discussão, usaremos a posição média que visa o desenvolvimento geral, no entanto você pode escolher qualquer uma das três posições discutidas na seção de posturas dos pés.","Comece a baixar lentamente a barra dobrando os joelhos enquanto mantém uma postura reta com a cabeça para cima. Continue até que o ângulo entre a perna superior e os bezerros se torne ligeiramente inferior a 90 graus (que é o ponto em que as pernas superiores estão abaixo paralelas ao chão). Inspire enquanto você executa esta parte do movimento. Dica: Se você realizou o exercício corretamente, a frente dos joelhos deve fazer uma linha reta imaginária com os dedos perpendiculares à frente. Se seus joelhos estão além dessa linha imaginária (se eles estão além dos dedos dos pés) então você está colocando estresse excessivo no joelho e o exercício foi realizado incorretamente.","Comece a levantar a barra enquanto expira, empurrando o chão com o calcanhar do pé, enquanto endireita as pernas novamente e volta para a posição inicial.","Repita para a quantidade recomendada de repetições."]],"Smith_Machine_Stiff-Legged_Deadlift":["Smith Machine Stiff-Legged Deadlift",["Para começar, coloque a barra na máquina do ferreiro em uma altura que está ao redor do meio de suas coxas. Uma vez que a altura correta é escolhida e a barra é carregada, agarre a barra usando um aperto pronado (palmas para frente) que é largura do ombro à parte.","Levante a barra, estendendo os braços e mantendo as costas retas, e mantenha o torso reto e as pernas espaçadas, usando uma largura de ombro ou posição mais estreita, os joelhos devem estar ligeiramente dobrados, esta é a sua posição inicial.","Mantendo os joelhos parados, baixando a barba até o topo dos pés, dobrando na cintura, mantendo as costas retas, como se fosse pegar algo do chão até sentir um estiramento nos isquiotibiais.","Comece a levantar o torso de novo assim que sentir os isquiotibiais esticar, estendendo os quadris e a cintura até voltar à posição inicial.","Repita para a quantidade recomendada de repetições."]],"Smith_Machine_Upright_Row":["\"Máquina Smith\" \"Lá em cima\"",["Para começar, coloque a barra na máquina do ferreiro em uma altura que está ao redor do meio de suas coxas. Uma vez que a altura correta é escolhida e a barra é carregada, agarre a barra usando um aperto pronado (palmas para frente) que é largura do ombro à parte.","Levante a campainha e estenda os braços com as costas retas, deve haver uma pequena curva nos cotovelos, esta é a posição inicial.","Use seus ombros laterais para levantar a barra enquanto expira, a barra deve estar perto do corpo enquanto você o move, continue a levantá-lo até que ele quase toque seu queixo, dica, seus cotovelos devem dirigir o movimento, enquanto você levanta a barra, seus cotovelos devem ser sempre mais altos que seus antebraços, e também, mantenha seu tronco parado e pause por um segundo no topo do movimento.","Abaixe a barra lentamente para a posição inicial, inspire enquanto executa esta parte do movimento.","Repita para a quantidade recomendada de repetições."]],"Smith_Single-Leg_Split_Squat":["Smith Single-Leg Split Squat",["Para começar, coloque um banco plano 2-3 pés atrás da máquina do ferreiro e, em seguida, defina a barra na altura que melhor corresponde à sua altura, uma vez que a altura correta é escolhida e a barra é carregada, passo abaixo da barra e colocar a parte de trás de seus ombros (ligeiramente abaixo do pescoço) através dela.","Segure na barra usando ambos os braços de cada lado (palmas voltadas para frente), destranque-a e levante-a da prateleira empurrando-a primeiro com as pernas e, ao mesmo tempo, endireitando o tronco.","Posicione as pernas colocando um pé um pouco para frente sob a barra e estendendo a outra perna para trás e coloque o topo do pé no banco.","Comece a baixar lentamente a barra dobrando o joelho enquanto mantém uma postura reta com a cabeça para cima. Continue até que o ângulo entre a perna superior e a panturrilha se torne ligeiramente inferior a 90 graus (que é o ponto em que as pernas superiores são abaixo paralelas ao chão). Inspire enquanto você executa esta parte do movimento. Dica: Se você realizou o exercício corretamente, a frente do joelho deve fazer uma linha reta imaginária com os dedos perpendiculares à frente. Se seu joelho está além dessa linha imaginária (se está além dos dedos dos pés) então você está colocando estresse excessivo no joelho e o exercício foi realizado incorretamente.","Comece a levantar a barra enquanto expira, empurrando o chão com o calcanhar do pé, principalmente enquanto endireita sua perna novamente e volta para a posição inicial.","Repita para a quantidade recomendada de repetições.","Troque de pernas e repita o movimento."]],"Snatch":["Snatch.",["Coloque seus pés em uma posição de largura do ombro com a campainha descansando bem acima da conexão entre os dedos dos pés e o resto do pé.","Com as palmas viradas para baixo, dobre-se nos joelhos e mantenha a traseira plana, agarre a barra com uma largura maior do que o ombro, abaixe os quadris e certifique-se de que seu corpo caia como se fosse sentar em uma cadeira.","Comece a empurrar o chão como se fosse uma plataforma móvel com os pés e, simultaneamente, comece a levantar a campainha mantendo-a perto das pernas.","Quando a barra chegar ao meio das coxas, empurre o chão com as pernas e levante o corpo para uma extensão completa em um movimento explosivo.","Levante os ombros de volta em um movimento de encolhimento enquanto levanta a barra enquanto levanta os cotovelos para o lado e os mantém acima da barra o máximo possível.","Agora, em um movimento muito rápido, mas poderoso, você tem que colocar seu corpo sob o barbell quando ele atingiu um ponto alto o suficiente onde ele pode ser controlado e cair enquanto trava seus braços e segurando o barbell acima enquanto você assume uma posição de agachamento.","Finalizar o movimento levantando-se da posição de agachamento para terminar o elevador no final do elevador ambos os pés devem estar em linha e os braços totalmente estendidos segurando a campainha acima."]],"Snatch_Balance":["Equilíbrio de golpes",["Comece com os pés na posição de puxar, a barra racked através da parte de trás dos ombros, e as mãos colocadas em um aperto largo.","Abra o bar com um mergulho abrupto e movimentação dos joelhos, e dirigir agressivamente sob o bar, transicionando os pés para a posição de recepção.","O tronco deve permanecer vertical, baixando os quadris entre as pernas.","Continue a descer até a profundidade máxima, e volte para uma posição de pé."]],"Snatch_Deadlift":["Snatch Deadlift",["O lifting fortalece a primeira atração do lifting, começa com um aperto largo com a campainha colocada na plataforma, os pés devem estar diretamente sob os quadris, com os pés virados para fora, agachando-se até a barra, mantendo as costas em extensão absoluta com a cabeça voltada para frente.","Iniciar o movimento dirigindo pelos saltos, levantando os quadris, o ângulo de volta deve permanecer o mesmo até que a barra passe os joelhos.","Nesse ponto, dirija seus quadris através da barra enquanto se deita, devolva a barra para a plataforma revertendo o movimento."]],"Snatch_Pull":["Snatch Pull",["Com uma campainha no chão perto das canelas, pegue um aperto largo, abaixe os quadris com o peso focado nos calcanhares, costas retas, cabeça virada para a frente, peito para cima, com os ombros bem na frente do bar, esta será a sua posição inicial.","Comece o primeiro pulo dirigindo pelos calcanhares, estendendo os joelhos, seu ângulo de costas deve permanecer o mesmo, e seus braços devem permanecer retos, mova o peso com controle enquanto você continua acima dos joelhos.","A seguir vem o segundo puxão, a principal fonte de aceleração para o puxão, à medida que a barra se aproxima da posição média da coxa, começa a estender-se através dos quadris, em um movimento de salto, acelerando estendendo os quadris, joelhos e tornozelos, usando velocidade para mover a barra para cima.","Não deve haver necessidade de puxar ativamente através dos braços para acelerar o peso, no final da segunda puxada, o corpo deve ser totalmente estendido, inclinando-se ligeiramente para trás."]],"Snatch_Shrug":["Snatch Shrug",["Comece com um aperto largo, com a barra pendurada na posição média da coxa, você pode usar um gancho ou um aperto superior, suas costas devem estar retas e inclinadas ligeiramente para frente.","Encoste os ombros em direção aos ouvidos, enquanto esse exercício pode ser carregado com peso mais pesado do que um golpe, evite sobrecarregar ao ponto em que a execução diminua."]],"Snatch_from_Blocks":["Snatch from Blocks",["Os pés devem estar diretamente abaixo dos quadris, com os pés virados para fora como necessário, abaixe os quadris, com o peito para cima e a cabeça olhando para frente, os ombros devem estar bem na frente da barra, com os cotovelos apontados.","Comece a primeira puxada dirigindo pela frente dos saltos, levantando a barra das caixas.","Transição para o segundo puxão estendendo-se através dos quadris joelhos e tornozelos, dirigindo a barra para cima o mais rápido possível.","Quando você mover seus pés para a posição de recepção, forçosamente puxe-se abaixo da barra enquanto você eleva a barra acima, os pés devem mover-se para fora dos quadris, feito o necessário.","Mantendo a barra alinhada na frente dos saltos, sua cabeça e peito para cima, dirigir através dos calcanhares dos pés para mover-se para uma posição de pé."]],"Speed_Band_Overhead_Triceps":["Faixa de velocidade Overhead Tríceps",["Para este exercício, ancoramos uma banda no chão, usamos um banco incline e ancoramos a banda na base, de pé sobre o banco, e isso poderia ser feito em pé na banda.","Para começar, puxe a faixa atrás da cabeça, segurando-a com um aperto pronado e seus cotovelos para cima.","Para realizar o movimento, estenda-se através do cotovelo para endireitar seus braços, garantindo que você mantenha seu braço no lugar.","Pause, e depois volte para a posição inicial."]],"Speed_Box_Squat":["Agachamento de caixa de velocidade",["Anexar bandas ao bar que estão firmemente ancoradas perto do chão, talvez precise sufocar as bandas para obter tensão adequada.","Carregue a barra para um peso que ainda requer esforço, mas não é tão pesado que a velocidade seja comprometida.","Posicione a barra na parte superior das costas, omoplatas retraídas, arqueadas e tudo de cabeça a dedo apertado.","Sente-se com os quadris até estar sentado na caixa, garantindo que desça sob controle e não caia na superfície.","Pausar brevemente, e explodir fora da caixa, estendendo-se através dos quadris e joelhos."]],"Speed_Squats":["Agachamentos de velocidade",["Este exercício é melhor realizado dentro de um rack de agachamento para fins de segurança, para começar, primeiro coloque a barra em um rack que melhor corresponde à sua altura, uma vez que a altura correta é escolhida e a barra é carregada, passo sob a barra e colocar a parte de trás de seus ombros (ligeiramente abaixo do pescoço) através dele.","Segure-se na barra usando os dois braços de cada lado e levante-a do rack empurrando com as pernas e ao mesmo tempo endireitando o tronco.","Afaste-se do rack e posicione suas pernas usando uma posição média do ombro com os dedos dos pés ligeiramente apontados.","Comece a baixar a barra dobrando os joelhos enquanto você mantém uma postura reta com a cabeça para cima. Continue para baixo até que o ângulo entre a perna superior e os bezerros se torne ligeiramente inferior a 90 graus (que é o ponto em que as pernas superiores estão abaixo paralelas ao chão). Inspire enquanto você executa esta parte do movimento. Dica: Se você realizou o exercício corretamente, a frente dos joelhos deve fazer uma linha reta imaginária com os dedos perpendiculares à frente. Se seus joelhos estão além dessa linha imaginária (se eles estão além dos dedos dos pés) então você está colocando estresse excessivo no joelho e o exercício foi realizado incorretamente.","Comece a levantar a barra o mais rápido possível sem envolver impulso enquanto você expira empurrando o chão com o calcanhar do seu pé principalmente quando você endireitar as pernas novamente e voltar para a posição inicial.","Repita para a quantidade recomendada de repetições."]],"Spell_Caster":["Rodízio de Soletração",["Segure um haltere em cada mão com um aperto pronado, seus pés devem estar largos com seus quadris e joelhos estendidos, esta será sua posição inicial.","Comece o movimento puxando os dois halteres para um lado do quadril, girando o tronco.","Mantendo os braços retos e os halteres paralelos ao chão, girando o tronco para balançar os pesos para o lado oposto.","Continue alternando, girando de um lado para o outro até que o conjunto esteja completo."]],"Spider_Crawl":["Rastejem-se!",["Comece em uma posição propensa no chão, suporte seu peso em suas mãos e dedos dos pés, com seus pés juntos e seu corpo reto, seus braços devem estar dobrados a 90 graus, esta será sua posição inicial.","Iniciando o movimento levantando um pé do chão, externamente gire a perna e leve o joelho para o cotovelo, o mais longe possível.","Devolva esta perna para a posição inicial e repita no lado oposto."]],"Spider_Curl":["Curva de Aranha",["Comece colocando a barra na parte do banco de pregadores onde você normalmente sentaria, não deixe de alinhar a campainha corretamente, para que fique equilibrada e não caia.","Mova-se para o lado da frente do banco do pregador (a parte em que os braços geralmente estão) e posicione-se em uma inclinação de 45 graus com seu torso e estômago pressionado contra o lado da frente do banco do pregador.","Certifique-se de que seus pés (especialmente os dedos dos pés) estão bem posicionados no chão e coloque seus braços superiores em cima da almofada localizada na parte de dentro do banco do pregador.","Use os braços para agarrar a barba com um aperto supinado (palmas viradas para cima) em cerca de largura do ombro ou um pouco mais perto um do outro.","Devagar comece a levantar a campainha para cima e expire, mantenha a posição contraída por um segundo enquanto aperta os bíceps.","Lentamente comece a trazer a campainha de volta para a posição inicial enquanto você respira..","Repita para a quantidade recomendada de repetições."]],"Spinal_Stretch":["Esticamento Spinal",["Sente-se em uma cadeira para que suas costas estejam retas e seus pés plantados no chão.","Entrelace seus dedos atrás da cabeça, cotovelos para fora e seu queixo para baixo.","Torça a parte superior do corpo para um lado cerca de 3 vezes o máximo que puder, então incline-se para frente e torça o tronco para alcançar o cotovelo no chão, dentro do joelho.","Volte para a posição vertical e repita para o outro lado."]],"Split_Clean":["Separar Limpo",["Com uma campainha no chão, perto das canelas, pegue um aperto de mão fora das pernas, abaixe os quadris com o peso focado nos calcanhares, para trás reta, cabeça virada para frente, peito para cima, com os ombros bem na frente do bar, esta será a sua posição inicial.","Comece o primeiro pulo dirigindo pelos calcanhares, estendendo os joelhos, seu ângulo de costas deve permanecer o mesmo, e seus braços devem permanecer retos, mova o peso com controle enquanto você continua acima dos joelhos.","Em seguida, vem o segundo puxão, a principal fonte de aceleração para o limpo, à medida que a barra se aproxima da posição média da coxa, começa a estender-se através dos quadris, em um movimento de salto, acelerando estendendo os quadris, joelhos e tornozelos, usando velocidade para mover a barra para cima, não deve haver necessidade de puxar ativamente através dos braços para acelerar o peso, no final do segundo puxão, o corpo deve ser totalmente estendido, inclinando-se ligeiramente para trás, com os braços ainda estendidos.","Quando a extensão completa for alcançada, a transição para a terceira puxada, empurrando agressivamente os braços com os cotovelos para cima e para fora, na extensão de pico, agressivamente puxe-se para baixo, girando os cotovelos sob a barra enquanto faz isso.","Receber o bar com os pés rachados, movendo-se agressivamente um pé para frente e um pé para trás.","Recupere-se imediatamente dirigindo através dos saltos, mantendo o tronco ereto e cotovelos para cima."]],"Split_Jerk":["\"Divide o idiota\"",["Em pé com o peso na frente dos ombros, comece com o mergulho, com seus pés diretamente sob seus quadris, flexione os joelhos sem mover os quadris para trás.","Dirige através dos calcanhares, cria o máximo de velocidade e força possível, e não se esqueça de mover sua cabeça para fora do caminho quando a barra sair dos ombros, neste momento, quando os pés saírem do chão, os pés devem ser colocados na posição de recepção o mais rápido possível.","No breve momento em que os pés não estão ativamente dirigindo contra a plataforma, o esforço do atleta para empurrar a barra para cima vai levá-los para baixo.","Retornem a uma posição de pé, unindo os pés."]],"Split_Jump":["Salto Dividido",["Assuma uma posição de apoio com um pé para frente com o joelho dobrado, e o joelho traseiro quase tocando o chão.","Certifique-se de que o joelho dianteiro esteja acima da linha média do pé.","Estendendo-se pelas duas pernas, pulando o mais alto possível, balançando os braços para ganhar elevação.","Quando você pular, junte seus pés, e mova-os de volta para suas posições iniciais enquanto aterrissa.","Absorva o impacto voltando à posição inicial."]],"Split_Snatch":["Separem-se.",["Começar com uma barra carregada no chão, a barra deve estar perto ou tocando as canelas, e uma grande aderência deve ser tomada na barra, os pés devem estar diretamente abaixo dos quadris, com os pés virados conforme necessário, baixar os quadris, com o peito para cima e a cabeça olhando para frente, os ombros devem estar bem na frente da barra, esta será a posição inicial.","Comece o primeiro pulo dirigindo pela frente dos saltos, levantando a barra do chão, o ângulo de volta deve permanecer o mesmo até que a barra passe os joelhos.","Transição para o segundo puxão estendendo-se através dos quadris joelhos e tornozelos, dirigindo a barra para cima o mais rápido possível.","Quando você mover seus pés para a posição de recepção, forçosamente puxe-se abaixo da barra enquanto eleva a barra acima, os pés devem mover-se fortemente para uma posição dividida, um pé para a frente, um pé para trás, receba a barra com seu corpo o mais baixo possível e os braços totalmente estendidos para cima.","Mantendo o bar alinhado sobre a frente dos saltos, sua cabeça e peito para cima, dirigir através dos calcanhares dos pés para se mover para uma posição de pé, unindo seus pés.","Com cuidado, devolva o peso ao chão."]],"Split_Squat_with_Dumbbells":["Separem-se com halteres.",["Posicione-se em uma posição cambaleante com o pé traseiro elevado e o pé dianteiro para frente.","Segure um haltere em cada mão, deixando-os pendurados nos lados.","Comece descendo, flexionando o joelho e o quadril para abaixar o corpo, mantendo boa postura para o movimento, mantendo o joelho dianteiro em linha com o pé enquanto faz o exercício.","No fundo do movimento, dirija através do calcanhar para estender o joelho e quadril para voltar à posição inicial."]],"Split_Squats":["Agachamentos Divididos",["Estar em posição de pé, pular em uma posição de perna dividida, com uma perna para frente e uma perna para trás, flexionando os joelhos e baixando os quadris ligeiramente enquanto você faz isso.","Quando descer, imediatamente inverta a direção, fique de pé e pule, invertendo a posição das pernas."]],"Squat_Jerk":["Agacha-te, idiota.",["Com os pés diretamente sob seus quadris, flexione os joelhos sem mover os quadris para trás, desça apenas um pouco, e inverta a direção o mais poderosa possível, atravesse os calcanhares, crie o máximo de velocidade e força possível, e certifique-se de mover a cabeça para fora do caminho enquanto a barra sai dos ombros.","No momento em que os pés saem do chão, os pés devem ser colocados na posição de recepção o mais rápido possível. No breve momento em que os pés não estão ativamente dirigindo contra a plataforma, o esforço do atleta para empurrar a barra para cima irá levá-los para baixo.","Mantendo a barra alinhada sobre a frente dos saltos, sua cabeça e peito para cima, dirigir através dos calcanhares dos pés para mover-se para uma posição de pé."]],"Squat_with_Bands":["Agache-se com Bandas",["Coloque as bandas nas mangas, fixadas em pinos de banda, rack, ou halteres para que haja tensão apropriada.","Comece pisando debaixo da barra e colocando-a na parte de trás dos ombros, aperte suas omoplatas juntas e gire seus cotovelos para frente, tentando dobrar a barra em seus ombros, remova a barra do rack, criando um arco apertado em suas costas inferiores, e volte para a posição, coloque seus pés largos para mais ênfase nas costas, glúteos, adutores e isquiotibiais, mantenha sua cabeça voltada para frente.","Com as costas, os ombros e o núcleo apertados, empurre os joelhos para fora e comece a descer, sente-se com os quadris o máximo possível, idealmente, suas canelas devem ser perpendiculares ao chão, a posição da barra inferior requer uma maior inclinação do tronco para manter a barra sobre os calcanhares, continue até quebrar o paralelo, que é definido como a dobra do quadril em linha com o topo do joelho.","Mantendo o peso em seus calcanhares e empurrando seus pés e joelhos para fora, dirigir para cima enquanto você lidera o movimento com sua cabeça. Continue para cima, mantendo aperto cabeça aos pés, até que você tenha retornado à posição inicial."]],"Squat_with_Chains":["Agache-se com correntes",["Para montar as correntes, comece por enrolar a corrente líder sobre as mangas da barra, a corrente pesada deve ser fixada usando um gancho de encaixe, ajustar o comprimento da corrente de chumbo para que alguns elos ainda estejam no chão no topo do movimento.","Comece pisando debaixo da barra e colocando-a na parte de trás dos ombros, aperte suas omoplatas juntas e gire seus cotovelos para frente, tentando dobrar a barra em seus ombros, remova a barra do rack, criando um arco apertado em suas costas inferiores, e volte para a posição, coloque seus pés largos para mais ênfase nas costas, glúteos, adutores e isquiotibiais, mantenha sua cabeça voltada para frente.","Com as costas, os ombros e o núcleo apertados, empurre os joelhos para fora e comece a descer, sente-se com os quadris o máximo possível, idealmente, suas canelas devem ser perpendiculares ao chão, a posição da barra inferior requer uma maior inclinação do tronco para manter a barra sobre os calcanhares, continue até quebrar o paralelo, que é definido como a dobra do quadril em linha com o topo do joelho.","Mantendo o peso em seus calcanhares e empurrando seus pés e joelhos para fora, dirigir para cima enquanto você lidera o movimento com sua cabeça. Continue para cima, mantendo aperto cabeça aos pés, até que você tenha retornado à posição inicial."]],"Squat_with_Plate_Movers":["Agache-se com os movedores de pratos.",["Para começar, coloque a barra em um rack logo abaixo do nível do ombro, posicione uma placa de peso no chão a alguns metros de volta do rack, assim que a barra estiver carregada, pise debaixo dela e coloque a parte de trás dos ombros sobre ela.","Segure na barra com as duas mãos e tire-a da prateleira empurrando com as pernas e, ao mesmo tempo, endireite o torso.","Afaste-se do rack e adote uma postura larga com os dedos apontados ligeiramente, com um pé na placa de peso.","Comece a baixar lentamente a barra dobrando os joelhos e quadris, continue até que o ângulo entre a perna superior e as panturrilhas fique ligeiramente inferior a 90 graus.","Levante a barra enquanto expira, empurrando o chão com os calcanhares dos pés enquanto estende os quadris e joelhos.","No topo do movimento, passo lateral, unindo seus pés no lado oposto da placa.","Usando o seu pé interior, empurre a placa de peso, deslizando-a pelo chão para onde você estava parado.","Coloque o seu pé interno na placa de peso, adotando uma postura larga para a próxima repetição."]],"Squats_-_With_Bands":["Agachados - Com Bandas",["Para começar, certifique-se de que a banda de exercícios esteja em uma divisão uniforme entre o lado esquerdo e direito do corpo, para fazer isso, use suas mãos para agarrar os dois lados da banda e colocar os dois pés no meio da banda, seus pés devem ter largura de ombro entre si.","Ao segurar as bandas, elas devem ter a mesma altura de cada lado, você deve usar um aperto pronado (palmas voltados para frente) e ter as alças das bandas ao lado do seu rosto para este exercício.","Lentamente comece a dobrar os joelhos e abaixe as pernas para que suas coxas sejam paralelas ao chão enquanto expira.","Use o calcanhar dos pés para empurrar seu corpo para a posição inicial enquanto expira.","Repita para a quantidade recomendada de repetições."]],"Stairmaster":["Stairmaster.",["Para começar, entre na escadaria e selecione a opção desejada no menu, você pode escolher uma configuração manual, ou você pode selecionar um programa para executar, normalmente, você pode entrar em sua idade e peso para estimar a quantidade de calorias queimadas durante o exercício.","Coloque as pernas para cima e para baixo em um ritmo estabelecido, dirigindo os pedais para baixo, mas não até o chão.","Os Stairmasters oferecem conveniência, benefícios cardiovasculares, e geralmente têm menos impacto do que correr para fora."]],"Standing_Alternating_Dumbbell_Press":["Imprensa de halteres em pé.",["Levante os halteres para os ombros com as palmas voltadas para a frente e os cotovelos apontados.","Estenda um braço para pressionar o haltere, mantendo sua mão no lugar.","Após uma breve pausa, devolva o peso para a posição inicial.","Repita para o lado oposto, continuando alternando entre os braços."]],"Standing_Barbell_Calf_Raise":["Levantem-se.",["Este exercício é melhor realizado dentro de um rack de agachamento para fins de segurança, para começar, primeiro coloque a barra em um rack que melhor corresponda à sua altura, uma vez que a altura correta é escolhida e a barra é carregada, passo abaixo da barra e colocar a barra na parte de trás de seus ombros (um pouco abaixo do pescoço).","Segure-se na barra usando os dois braços de cada lado e levante-a do rack empurrando com as pernas e ao mesmo tempo endireitando o tronco.","Afaste-se do rack e posicione suas pernas usando uma posição média do ombro com os dedos dos pés ligeiramente apontados. Mantenha sua cabeça erguida o tempo todo, pois olhar para baixo vai te desequilibrar e também manter uma reta para trás. Os joelhos devem ser mantidos com uma leve curva; nunca trancados. Esta será sua posição inicial. Dica: Para uma melhor amplitude de movimento, você também pode colocar a bola de seus pés em um bloco de madeira, mas tenha cuidado, pois esta opção requer mais equilíbrio e um bloco resistente.","Levante os calcanhares enquanto expira, estendendo os tornozelos o mais alto possível e flexionando a panturrilha, certifique-se de que o joelho fique parado o tempo todo, não deve haver flexão a qualquer momento, mantenha a posição contraída por um segundo antes de começar a voltar para baixo.","Volte lentamente para a posição inicial enquanto você respira baixando os calcanhares enquanto dobra os tornozelos até as panturrilhas ficarem esticadas.","Repita para a quantidade recomendada de repetições."]],"Standing_Barbell_Press_Behind_Neck":["Pressão de Barbell de pé atrás do pescoço",["Este exercício é melhor realizado dentro de um rack de agachamento para facilitar a coleta do bar.","Segure-se na barra usando os dois braços de cada lado e levante-a do rack empurrando com as pernas e ao mesmo tempo endireitando o tronco.","Afaste-se do rack e posicione suas pernas usando uma posição média do ombro com os dedos dos pés ligeiramente apontados.","Eleve o barbeador em cima, estendendo completamente os braços enquanto expira.","Segure a contração por um segundo e abaixe a campainha de volta para a posição inicial inalando.","Repita para a quantidade recomendada de repetições."]],"Standing_Bent-Over_One-Arm_Dumbbell_Triceps_Extension":["Bent-Over One-Arm halteres Triceps Extension",["Com um haltere em uma mão e a palma voltada para o tronco, dobre os joelhos ligeiramente e leve o tronco para frente, dobrando a cintura, mantendo as costas retas até que seja quase paralelo ao chão.","O braço deve estar perto do tronco e paralelo ao chão enquanto o antebraço aponta para o chão enquanto a mão segura o peso.","Mantendo os braços parados, use o tríceps para levantar os pesos enquanto você expira até que os antebraços estejam paralelos ao chão e o braço todo seja estendido.","Depois de uma segunda contração no topo, abaixe lentamente o haltere de volta para a posição inicial enquanto você inala.","Repita o movimento para a quantidade prescrita de repetições.","Troque de braços e repita o exercício."]],"Standing_Bent-Over_Two-Arm_Dumbbell_Triceps_Extension":["Bent-Over Tríceps Dumblebell de dois braços",["Com um haltere em cada mão e as palmas voltadas para o tronco, dobre os joelhos ligeiramente e leve o tronco para frente, dobrando na cintura, mantendo as costas retas até que seja quase paralelo ao chão. Certifique-se de manter a cabeça erguida. Os braços superiores devem estar próximos do tronco e paralelos ao chão, enquanto os antebraços estão apontando para o chão enquanto as mãos seguram os pesos. Dica: Deve haver um ângulo de 90 graus entre os antebraços e o braço superior.","Mantendo os braços parados, use o tríceps para levantar os pesos enquanto você expira até que os antebraços sejam paralelos ao chão e os braços todos sejam estendidos.","Depois de uma segunda contração no topo, abaixe lentamente os halteres de volta à posição inicial enquanto você inala.","Repita o movimento para a quantidade prescrita de repetições."]],"Standing_Biceps_Cable_Curl":["Curva de Cabo Bíceps em pé",["Levante-se com o torso ereto enquanto segura uma barra de cabo que está presa a uma polia baixa. Segure a barra de cabo na largura do ombro e mantenha os cotovelos perto do torso.","Enquanto segura os braços parados, enrole os pesos enquanto contrai os bíceps enquanto expira, apenas os antebraços devem se mover, continue o movimento até que seus bíceps estejam totalmente contraídos e a barra esteja no nível do ombro, mantenha a posição contraída por um segundo enquanto aperta o músculo.","Lentamente começar a trazer a barra de volta para a posição inicial enquanto você respira.","Repita para a quantidade recomendada de repetições."]],"Standing_Biceps_Stretch":["Bíceps em pé esticam",["Aperte as mãos atrás das costas com as palmas juntas, endireite os braços e depois gire-as para baixo.","Levante os braços e segure até sentir um estiramento no bíceps."]],"Standing_Bradford_Press":["Bradford Press em pé",["Coloque uma barra carregada no nível do ombro em um rack com uma alça pronada na largura do ombro, comece com a barra racked na frente de seus ombros.","Iniciar o elevador estendendo os cotovelos para pressionar a barra acima, evite trancar o cotovelo enquanto move o peso atrás da cabeça.","Abaixe a barra até a parte de trás da cabeça até que seu cotovelo forme um ângulo reto.","Levante a barra sobre sua cabeça estendendo os cotovelos.","Abaixe a barra para a posição inicial.","Alternar desta forma até completar a quantidade recomendada de repetições."]],"Standing_Cable_Chest_Press":["Pressão do tórax em pé.",["Posicione polias duplas até a altura do peito e selecione um peso adequado, coloque um pé ou dois na frente dos cabos, segurando uma em cada mão, você pode cambalear sua posição para uma melhor estabilidade.","Posicione o braço em um ângulo de 90 graus com as omoplatas juntas.","Mantendo o resto do corpo parado, estenda-se através dos cotovelos para pressionar os cabos para frente, atraindo-os juntos na sua frente.","Pause no topo da moção, e volte para a posição inicial."]],"Standing_Cable_Lift":["Levantamento de cabos em pé",["Ligue uma alça padrão em uma torre, e mova o cabo para a posição mais baixa da polia.","Com o lado do cabo, pegue o cabo com uma mão e afaste-se da torre, deve estar aproximadamente longe da polia, com a tensão do peso no cabo, seu braço estendido deve estar alinhado com o cabo.","Com os pés afastados, agache-se e segure o cabo com as duas mãos.","Em um movimento, puxe o cabo para cima e para cima do corpo até que seus braços estejam em uma posição totalmente estendida acima da cabeça.","Mantenha as costas retas e os braços perto do corpo enquanto gira o pé e endireita as pernas para obter uma amplitude completa de movimento.","Retraia os braços e o corpo, volte para a posição neutra de forma lenta e controlada.","Repita para o fracasso.","Então, reposicione e repita a mesma série de movimentos no lado oposto."]],"Standing_Cable_Wood_Chop":["Palha de madeira de cabo em pé",["Conecte uma alça padrão a uma torre, e mova o cabo para a posição mais alta da polia.","Com o lado do cabo, pegue o cabo com uma mão e afaste-se da torre, deve estar aproximadamente longe da polia, com a tensão do peso no cabo, seu braço estendido deve estar alinhado com o cabo.","Com os pés posicionados, largura do ombro afastada, alcance para cima com a outra mão e agarre o cabo com as duas mãos.","Em um movimento, puxe o cabo para baixo e através de seu corpo para o joelho dianteiro enquanto gira o tronco.","Mantenha as costas e os braços retos e firmes enquanto você gira o pé de trás e dobra os joelhos para obter uma amplitude completa de movimento.","Mantenha sua posição e braços retos, volte para a posição neutra de forma lenta e controlada.","Repita para o fracasso.","Então, reposicione e repita a mesma série de movimentos no lado oposto."]],"Standing_Calf_Raises":["O bezerro de pé levanta.",["Vá para a máquina de levantar bezerros, você deve conseguir empurrar seus bezerros completamente para baixo."]],"Standing_Concentration_Curl":["Curva de Concentração",["Pegando um haltere em sua mão de trabalho, incline-se para frente, deixe seu braço de trabalho pendurada perpendicularmente ao chão com o cotovelo apontando, esta será sua posição inicial.","Flexione o cotovelo para enrolar o peso, mantendo o braço parado no topo da repetição, flexione o bíceps e pause.","Abaixe o haltere de volta para a posição inicial.","Repita o movimento para a quantidade prescrita de repetições."]],"Standing_Dumbbell_Calf_Raise":["Levantem-se.",["Coloque a bola do pé em uma tábua de madeira resistente e estável (que tem cerca de 2-3 polegadas de altura) enquanto seus calcanhares se estendem e tocam o chão.","Com os dedos dos pés apontando ou retos (para atingir todas as partes igualmente), para dentro (para ênfase na cabeça exterior) ou para fora (para ênfase na cabeça interior), levante os calcanhares do chão enquanto você expira contraindo os bezerros.","Ao inalar, volte para a posição inicial baixando lentamente os saltos.","Repita para a quantidade recomendada de vezes."]],"Standing_Dumbbell_Press":["halteres Press",["Levante os halteres para a altura da cabeça, os cotovelos para fora e cerca de 90 graus.","Mantendo a técnica rígida sem movimentação de pernas ou inclinando-se para trás, estenda-se através do cotovelo para levantar os pesos juntos diretamente acima de sua cabeça.","Pause, e lentamente retorne o peso para a posição inicial."]],"Standing_Dumbbell_Reverse_Curl":["halteres em pé Curl Reverso",["Para começar, fique em pé com um haltere em cada mão usando um aperto pronado (palmas viradas para baixo), seus braços devem ser totalmente estendidos enquanto seus pés têm largura de ombro separados um do outro.","Enquanto segura os braços parados, enrole os pesos enquanto contrai os bíceps enquanto expira, apenas os antebraços devem se mover, continue o movimento até que seus bíceps estejam totalmente contraídos e os halteres estejam no nível do ombro, mantenha a posição contraída por um segundo enquanto aperta o músculo.","Lentamente começar a trazer os halteres de volta à posição inicial enquanto você respira.","Repita para a quantidade recomendada de repetições."]],"Standing_Dumbbell_Straight-Arm_Front_Delt_Raise_Above_Head":["halteres em pé, braço direito, frente delta, levante acima da cabeça.",["Segure os halteres na frente de suas coxas, palmas de frente para suas coxas.","Mantenha os braços retos com uma pequena curva nos cotovelos, mas mantenha-os trancados.","Erguer os halteres em movimento semicircular para o comprimento do braço acima enquanto expira.","Retorne lentamente à posição inicial usando o mesmo caminho que inala.","Repita para a quantidade recomendada de repetições."]],"Standing_Dumbbell_Triceps_Extension":["halteres Tríceps em pé.",["Para começar, levante-se com um haltere de ambas as mãos, seus pés devem ter uma largura de ombro diferente um do outro, lentamente use as duas mãos para agarrar o haltere e erguê-lo sobre a cabeça até que ambos os braços estejam totalmente estendidos.","A resistência deve estar nas palmas das mãos com os polegares ao redor, a palma das mãos deve estar voltada para o teto, esta será a sua posição inicial.","Mantenha os braços superiores perto da cabeça com cotovelos e perpendiculares ao chão, abaixe a resistência em um movimento semicircular atrás da cabeça até que seus antebraços toquem seus bíceps.","Volte para a posição inicial usando os tríceps para levantar o haltere.","Repita para a quantidade recomendada de repetições."]],"Standing_Dumbbell_Upright_Row":["Em pé, halteres, em frente.",["Segure um haltere em cada mão com um aperto pronunciado (palmas para a frente) que é ligeiramente menor do que a largura do ombro os halteres devem estar descansando em cima de suas coxas seus braços devem ser estendidos com uma pequena curva nos cotovelos e suas costas devem ser retas.","Use seus ombros laterais para levantar os halteres enquanto você expira, os halteres devem estar perto do corpo enquanto você o move para cima e os cotovelos devem dirigir o movimento, continue a levantá-los até que eles quase toquem seu queixo, dica, seus cotovelos devem dirigir o movimento, enquanto você levanta os halteres, seus cotovelos devem ser sempre mais altos que seus antebraços, também, mantenha seu tronco parado e pare por um segundo no topo do movimento.","Abaixe os halteres lentamente para a posição inicial, inspire enquanto executa esta parte do movimento.","Repita para a quantidade recomendada de repetições."]],"Standing_Elevated_Quad_Stretch":["Esticamento Quad em pé.",["Comece por ficar de costas a cerca de dois a três metros de um banco ou de um passo.","Levante uma perna atrás de você e descanse o pé no degrau, ou no seu degrau ou na bola do seu pé, o que achar mais confortável.","Mantenha seu joelho de apoio ligeiramente dobrado e evite deixar que o joelho se estenda além dos dedos dos pés."]],"Standing_Front_Barbell_Raise_Over_Head":["Em pé frente Barbell levantar sobre a cabeça",["Para começar, fique em pé com uma barba nas mãos, deve segurar a barra com as palmas viradas para baixo e mais perto do que a largura do ombro, longe uma da outra.","Seus pés deveriam ter largura de ombro, longe um do outro, seus cotovelos devem estar ligeiramente dobrados, esta é a posição inicial.","Levante a campainha até que esteja diretamente sobre sua cabeça enquanto expira.","Assim que sentir a contração, comece a baixar a campainha de volta para a posição inicial enquanto inala.","Repita para a quantidade recomendada de repetições."]],"Standing_Gastrocnemius_Calf_Stretch":["Esticamento Gastrocnêmio de Calf",["Coloque o calcanhar direito em um degrau com o joelho estendido e incline-se para frente para agarrar o dedo direito com a mão direita.","Apoie seu peso na perna esquerda e coloque sua mão esquerda na coxa esquerda.","Puxe os dedos direito para o joelho até sentir um estiramento no bezerro."]],"Standing_Hamstring_and_Calf_Stretch":["Fio dental e estiramento de bezerro",["Estando com um cinto, uma faixa, ou uma corda em volta de um pé, enquanto está de pé, coloque esse pé para frente.","Agora levante os dedos do pé da frente do chão e incline-se para frente.","Usando o cinto, puxe o pé para aumentar o estiramento do bezerro, segure 10-20 segundos e repita com o outro pé."]],"Standing_Hip_Circles":["Círculos de quadril em pé",["Comece em pé em uma perna, segurando um suporte vertical.","Levante o joelho sem suporte para 90 graus.","Abra o quadril o mais longe possível, tentando fazer um grande círculo com seu joelho.","Faça este movimento lentamente para várias repetições, e repita do outro lado."]],"Standing_Hip_Flexors":["Flexores de quadril em pé.",["Levante-se direito com a coluna vertical, o pé esquerdo ligeiramente na frente da direita.","Dobrar os joelhos e levantar o calcanhar traseiro do chão enquanto pressiona o quadril direito para a frente, não consegue um estiramento profundo nesta posição, no entanto, porque é difícil relaxar o flexor do quadril e ficar sobre ele ao mesmo tempo."]],"Standing_Inner-Biceps_Curl":["Curl de Biceps Interiores",["Levantem-se com um haltere em cada mão, segurando os braços, os cotovelos devem estar perto do torso, suas pernas devem estar na largura do ombro, longe uma da outra.","Rodar as palmas das mãos para que eles estejam voltados para dentro em uma posição neutra.","Enquanto segura os braços parados, enrole os pesos enquanto contrai os bíceps enquanto expira.","Continue o movimento até que seus bíceps estejam totalmente contraídos e os halteres estejam no nível do ombro.","Mantenha a posição contraída por um segundo enquanto aperta os bíceps.","Lentamente comece a trazer os halteres de volta para a posição inicial enquanto você respira, lembre-se de girar os pulsos enquanto você baixa o peso para mudar de volta para um aperto neutro.","Repita para a quantidade recomendada de repetições."]],"Standing_Lateral_Stretch":["Esticamento lateral em pé",["Tome uma postura um pouco mais larga do que a distância do quadril com seus joelhos ligeiramente dobrados.","Coloque sua mão direita no quadril direito para apoiar a coluna vertebral.","Levante o braço esquerdo em uma linha vertical e coloque a mão esquerda atrás da cabeça.","Mantenha seu peso uniformemente distribuído entre as duas pernas (não se incline para o quadril esquerdo)."]],"Standing_Leg_Curl":["Perna em pé Curl",["Ajuste a alavanca da máquina para caber sua altura e deite-se com o tronco dobrado na cintura virada para a frente em torno de 30-45 graus (já que uma posição angular é mais favorável para recrutamento de isquiotibiais) com a almofada da alavanca na parte de trás da perna direita (apenas alguns centímetros abaixo das panturrilhas) e a frente da perna direita em cima da almofada da máquina.","Mantendo o torso dobrado para frente, certifique-se de que sua perna esteja totalmente esticada e segure as pegas laterais da máquina.","Quando expirar, enrole a perna direita o máximo possível sem levantar a parte superior da almofada, assim que atingir a posição contraída, segure-a por um segundo.","Ao inalar, traga as pernas de volta à posição inicial, repita a quantidade recomendada de repetições.","Faça o mesmo exercício agora para a perna esquerda."]],"Standing_Long_Jump":["Salto Longo em Pé",["Esta broca é melhor feita em areia ou outra superfície de pouso suave, certifique-se de que você seja capaz de medir a distância, fique em uma posição de agachamento parcial com os pés de largura do ombro separados.","Usando um grande balanço de braço e um contramovimento das pernas, pule para frente o máximo que puder.","Tente pousar com os pés na sua frente, alcançando o máximo possível com as pernas.","Meça a distância do seu ponto de aterrissagem até o ponto de partida e os resultados da pista."]],"Standing_Low-Pulley_Deltoid_Raise":["Levantar Deltoide de Baixo Pulley",["Use sua mão esquerda para cruzar o corpo e agarrar uma única alça presa à polia baixa com uma alça pronada (palmas viradas para baixo).","Certifique-se de que suas costas estão eretas e seus pés têm largura de ombros separados um do outro.","Comece a usar a mão esquerda e desloque-se para fora do corpo até que ele seja elevado à altura do ombro enquanto expira.","Sinta a contração no topo por um segundo e comece a baixar lentamente o cabo de volta para a posição inicial original enquanto inala.","Repita para a quantidade recomendada de repetições.","Troque de braços e repita o exercício."]],"Standing_Low-Pulley_One-Arm_Triceps_Extension":["Extensão de Tríceps de Baixo Pulley.",["Pegue um único punho com o braço esquerdo ao lado da máquina de polia baixa. Afaste-se da máquina mantendo o punho para o lado do seu corpo com o braço totalmente estendido. Agora use ambas as mãos para elevar o único punho diretamente acima da cabeça com a palma voltada para frente. Mantenha o braço superior completamente vertical (perpendicular para o chão) e coloque a mão direita sobre o cotovelo esquerdo para ajudar a mantê-lo estável. Esta é a posição inicial.","Mantendo os braços superiores perto da cabeça e perpendiculares ao chão, abaixe a resistência em um movimento semicircular atrás da cabeça até que seus antebraços toquem seus bíceps.","Volte para a posição inicial usando o tríceps para levantar o único punho.","Repita para a quantidade recomendada de repetições.","Troque de braços e repita o exercício."]],"Standing_Military_Press":["Imprensa Militar em pé",["Comece colocando uma campainha que é sobre peito alto em um rack de agachamento.","Dobre levemente os joelhos e coloque a campainha no osso da sua gola, levante a campainha mantendo-a deitada no peito, dê um passo para trás e posicione seus pés com a largura do ombro um do outro.","Assim que pegar a campainha com o comprimento correto, levante a barra sobre a cabeça, trancando os braços, segurando o ombro e ligeiramente na frente da cabeça, esta é sua posição inicial.","Abaixe a barra até a clavícula lentamente enquanto inala.","Levante a barra de volta para a posição inicial enquanto expira.","Repita para a quantidade recomendada de repetições."]],"Standing_Olympic_Plate_Hand_Squeeze":["Prato Olímpico em pé, aperto de mão.",["Para começar, mantenha-se em pé enquanto segura uma placa de peso ao longo do braço em cada mão usando um aperto neutro (palmas viradas para dentro) e seus pés devem ter largura de ombro separada um do outro.","Abaixe as placas até que os dedos estejam quase estendidos, mas ainda possa segurar pesos.","Agora levante as placas de volta para a posição inicial enquanto você expira fechando suas mãos.","Repita para a quantidade recomendada de repetições prescritas no seu programa."]],"Standing_One-Arm_Cable_Curl":["Curva de Cabo de Um Braço",["Comece pegando uma única alça ao lado da máquina de polia baixa, certifique-se de estar longe o suficiente da máquina para que seu braço suporte o peso.","Certifique-se de que seu braço esteja parado, perpendicular ao chão com cotovelos e palmas voltadas para a frente, seu braço não levantado deve estar agarrando sua cintura, isso permitirá que você mantenha seu equilíbrio.","Lentamente começa a enrolar o único cabo para cima mantendo o braço parado até o antebraço tocar o bíceps enquanto expira.","Mantenha a posição de contração enquanto aperta o bíceps e então abaixe o único cabo de volta para a posição inicial enquanto inala.","Repita para a quantidade recomendada de repetições.","Troque de braços enquanto faz esse exercício."]],"Standing_One-Arm_Dumbbell_Curl_Over_Incline_Bench":["halteres Curl Over Incline Bench",["Fique no lado de trás de um banco inclinado como se fosse ser um observador para alguém.","Posicione sua mão não-elevante no canto ou lado do banco inclinado, o peito deve ser pressionado contra a parte superior da inclinação e seus pés devem ser pressionados contra o chão em uma posição larga.","Enquanto segura o braço parado, enrole o haltere para cima enquanto contrai os bíceps enquanto expira, apenas os antebraços devem se mover, continue o movimento até que seus bíceps estejam totalmente contraídos e o haltere esteja no nível do ombro, mantenha a posição contraída por um segundo.","Lentamente começar a trazer os halteres de volta à posição inicial enquanto você respira.","Repita para a quantidade recomendada de repetições.","Troque de braços enquanto faz esse exercício."]],"Standing_One-Arm_Dumbbell_Triceps_Extension":["Extensão de um braço só para o Tríceps.",["Para começar, levante-se com um haltere em uma mão, seus pés devem ter uma largura de ombro entre si, agora estenda o braço com o haltere sobre sua cabeça, e o dedo pequeno de sua mão deve estar voltado para o teto, e a palma da sua mão deve estar voltada para frente, o haltere deve estar acima da sua cabeça.","Esta será a sua posição inicial.","Mantenha o braço perto da cabeça e perpendicular ao chão, abaixe a resistência em um movimento semicircular atrás da cabeça até o antebraço tocar o bíceps.","Volte para a posição inicial usando os tríceps para levantar o haltere.","Repita para a quantidade recomendada de repetições.","Troque de braços e repita o exercício."]],"Standing_Overhead_Barbell_Triceps_Extension":["Em pé, Barbell Triceps Extension.",["Para começar, levante-se segurando uma barra ou barra e-z usando um aperto pronado (palmas voltados para a frente) com as mãos mais próximas do que a largura do ombro um do outro.","Agora eleve o sino acima da cabeça até que seus braços estejam totalmente estendidos.","Mantendo os braços superiores perto da cabeça e cotovelos, perpendiculares ao chão, baixando a resistência em um movimento semicircular atrás da cabeça até que seus antebraços toquem seus bíceps.","Volte para a posição inicial usando o tríceps para levantar o barbelo.","Repita para a quantidade recomendada de repetições."]],"Standing_Palm-In_One-Arm_Dumbbell_Press":["Palm-In One-Arm halteres Press",["Comece por ter um haltere em uma mão com o braço estendido para o lado usando um aperto neutro.","Agora levante o haltere lentamente até criar um ângulo de 90 graus com o braço.","Levante lentamente o haltere até que seu braço esteja totalmente estendido.","Enquanto inala o peso para baixo até que seu braço esteja em um ângulo de 90 graus novamente.","Sinta a contração por um segundo e então levante o peso de volta para a posição inicial enquanto expira, lembre-se de segurar no banco incline e manter seus pés posicionados para manter o equilíbrio durante o exercício.","Repita para a quantidade recomendada de repetições.","Troque de braços e repita o exercício."]],"Standing_Palms-In_Dumbbell_Press":["Palmas de pé em halteres Press",["Comece por ter um haltere em cada mão com o braço totalmente estendido para o lado usando um aperto neutro, seus pés devem ter largura do ombro separados um do outro, agora lentamente levante os halteres até criar um ângulo de 90 graus com os braços, e seus antebraços devem ser perpendiculares ao chão, esta é a posição inicial.","Mantenha um aperto neutro durante todo o exercício, levante lentamente os halteres até que seus braços estejam totalmente estendidos.","Enquanto inala os pesos para baixo até que seu braço esteja em um ângulo de 90 graus novamente.","Repita para a quantidade recomendada de repetições."]],"Standing_Palms-Up_Barbell_Behind_The_Back_Wrist_Curl":["Barbell de pé atrás da curva de pulso.",["Comece por ficar em pé e segurando uma campainha atrás dos glúteos ao longo do braço enquanto usa um aperto pronado (palmas estarão de costas para longe dos glúteos) e tendo suas mãos com largura de ombro separadas umas das outras.","Você deve olhar para frente enquanto seus pés estão longe um do outro.","Enquanto exala, lentamente eleve o sino, enrolando seu pulso em um movimento semi-circular em direção ao teto.","Segure a contração por um segundo e abaixe a campainha de volta para a posição inicial enquanto inala.","Repita para a quantidade recomendada de repetições.","Quando terminar, abaixe a campainha até o rack de agachamento ou o chão dobrando os joelhos."]],"Standing_Pelvic_Tilt":["Pélvico em pé.",["Comece com os pés à distância.","Dobre um pouco os joelhos para mantê-los macios e primavera.","Você pode querer mover sua pélvis para frente e para trás e para trás algumas vezes antes de segurar o cóccix para frente neste trecho."]],"Standing_Rope_Crunch":["Crunch de corda em pé",["Coloque uma corda em uma polia alta e selecione um peso apropriado.","Fique de costas para a torre de cabos, pegue a corda com as duas mãos sobre os ombros, segurando-a em seu peito superior, esta será sua posição inicial.","Execute o movimento flexionando a coluna vertebral, apertando o peso o máximo que puder.","Mantenha o pico de contração por um momento antes de voltar para a posição inicial."]],"Standing_Soleus_And_Achilles_Stretch":["\"Soleus e Aquiles se esticam\"",["Fique com os pés à distância, um pé na frente do outro.","Dobre os joelhos, mantenha o calcanhar traseiro no chão."]],"Standing_Toe_Touches":["Toca o dedo do pé",["Fique com algum espaço na frente e atrás de você.","Dobrar a cintura, manter as pernas retas, até que possa relaxar e deixar a parte superior do corpo pendurada na sua frente, deixar seus braços e mãos penduradas naturalmente, segurar por 10 a 20 segundos."]],"Standing_Towel_Triceps_Extension":["Toalha de pé Tríceps extensão",["Para começar, levante-se com os dois braços totalmente estendidos acima da cabeça segurando uma extremidade de uma toalha com as duas mãos, seus cotovelos devem estar dentro e os braços perpendiculares ao chão com as palmas viradas para o outro enquanto seus pés devem ter largura de ombro separada uma da outra.","Agora comunique-se com seu parceiro para que ele possa segurar o outro lado da toalha para aplicar resistência mantendo seus braços superiores perto da cabeça (cotovelos dentro) e perpendicular ao chão, abaixe a resistência em um movimento semicircular atrás de sua cabeça até que seus antebraços toquem seus bíceps.","Volte para a posição inicial usando o tríceps para levantar a toalha.","Repita para a quantidade recomendada de repetições."]],"Standing_Two-Arm_Overhead_Throw":["De pé, dois braços, overhead Throw",["Para começar, alcance a bola de remédio bem atrás da cabeça enquanto dobra os joelhos ligeiramente e se inclina para trás.","Jogue a bola violentamente para frente, flexionando no quadril e usando todo o seu corpo para completar o movimento.","A bola medicinal pode ser jogada para um parceiro ou para uma parede, recebendo-a quando ela se recupera."]],"Star_Jump":["Salto das Estrelas",["Comece em uma posição relaxada com os pés largura do ombro separados e mantenha seus braços perto do corpo.","Para iniciar o movimento, agache-se na metade e exploda o mais alto possível, estenda seu corpo inteiro, estendendo suas pernas e braços para longe do corpo.","Quando pousar, traga seus membros de volta e absorva seu impacto através das pernas."]],"Step-up_with_Knee_Raise":["Avance com o aumento do joelho.",["Esta será a sua posição inicial.","Começando o movimento, colocando o pé esquerdo no topo do banco, estendendo o quadril e o joelho da perna dianteira para ficar em pé na caixa com a perna esquerda, flexionando o joelho direito e o quadril, levando o joelho o mais alto que puder.","Reverta este movimento para descer da caixa, e então repita a sequência na perna oposta."]],"Step_Mill":["Moinho Passo",["Para começar, entre na estribeira e selecione a opção desejada no menu, você pode escolher uma configuração manual, ou você pode selecionar um programa para executar, normalmente, você pode entrar em sua idade e peso para estimar a quantidade de calorias queimadas durante o exercício, tenha cuidado para que você não tropece enquanto sobe as escadas, recomenda-se que mantenha o controle sobre as alças para que você não caia.","As madrastas oferecem conveniência, benefícios cardiovasculares, e geralmente têm menos impacto do que correr para fora, oferecendo uma taxa similar de calorias queimadas, normalmente são muito mais difíceis do que outros equipamentos cardiológicos, uma pessoa de 150 lb normalmente queima mais de 300 calorias em 30 minutos, comparado com cerca de 175 calorias andando."]],"Stiff-Legged_Barbell_Deadlift":["Levantador de Deadbell de pernas firmes.",["Pegue uma barra usando um aperto de mão (palmas viradas para baixo), você pode precisar de alguns invólucros de pulso se usar uma quantidade significativa de peso.","Fique com o torso reto e as pernas espaçadas com a largura do ombro ou uma postura mais estreita, os joelhos devem estar ligeiramente dobrados, esta é a sua posição inicial.","Mantendo os joelhos parados, baixando a barba até o topo dos pés, dobrando os quadris, mantendo as costas retas, como se fosse pegar algo do chão até sentir um estiramento nos isquiotibiais.","Comece a levantar o torso de novo, estendendo os quadris até voltar à posição inicial.","Repita para a quantidade recomendada de repetições."]],"Stiff-Legged_Dumbbell_Deadlift":["Levantador de Deadbell de pernas firmes",["Pegue alguns halteres segurando-os ao seu lado com o braço.","Fique com o torso reto e as pernas espaçadas com a largura do ombro ou uma postura mais estreita, os joelhos devem estar ligeiramente dobrados, esta é a sua posição inicial.","Mantendo os joelhos parados, baixando os halteres para cima dos pés, dobrando na cintura, mantendo as costas retas, como se fosse pegar algo do chão até sentir um estiramento nos isquiotibiais.","Comece a levantar o torso, estendendo os quadris e a cintura até voltar à posição inicial.","Repita para a quantidade recomendada de repetições."]],"Stiff_Leg_Barbell_Good_Morning":["Bom dia, Barbell Perna Firme",["Este exercício é melhor realizado dentro de um rack de agachamento para fins de segurança, para começar, primeiro coloque a barra em um rack que melhor corresponde à sua altura, uma vez que a altura correta é escolhida e a barra é carregada, passo sob a barra e colocar a parte de trás de seus ombros (ligeiramente abaixo do pescoço) através dele.","Segure-se na barra usando os dois braços de cada lado e levante-a do rack empurrando com as pernas e ao mesmo tempo endireitando o tronco.","Afaste-se do rack e posicione suas pernas usando uma posição média de largura do ombro.","Mantenha as pernas paradas, mova o torso para frente, dobrando os quadris enquanto inala, abaixe o torso até ficar paralelo com o chão.","Comece a aumentar a barra enquanto expira, elevando seu torso para a posição inicial.","Repita para a quantidade recomendada de repetições."]],"Stomach_Vacuum":["Aspiração do estômago",["Para começar, fiquem em pé, com os pés longe um do outro, coloquem as mãos nos quadris, esta é a posição inicial.","Agora inale o máximo de ar possível e comece a expirar o máximo possível enquanto traz seu estômago o máximo possível e mantenha essa posição, tente visualizar seu umbigo tocando sua espinha dorsal.","Uma contração isométrica é de cerca de 20 segundos, durante a espera de 20 segundos, tente respirar normalmente, então inale e traga seu estômago de volta para a posição inicial.","Uma vez que tenha praticado este exercício, tente realizar este exercício por mais de 20 segundos.","Repita para a quantidade recomendada de conjuntos."]],"Straight-Arm_Dumbbell_Pullover":["Traidor de halteres.",["Coloque um haltere em pé em um banco plano.","Assegurando que o haltere permaneça firmemente colocado no topo do banco, fique perpendicular ao banco (torso através dele como formando uma cruz) com apenas seus ombros deitados na superfície.","Segure o haltere com as duas mãos e segure-o sobre o peito com o comprimento dos braços, ambas as palmas devem estar pressionando contra o lado de baixo um dos lados do haltere, esta será sua posição inicial, cuidado, sempre certifique-se de que o haltere usado para este exercício seja seguro, usar um haltere com placas soltas pode resultar em que o haltere caia e caia em seu rosto.","Enquanto mantém os braços retos, abaixe o peso lentamente em um arco atrás da cabeça enquanto respira até sentir um estiramento no peito.","Nesse ponto, traga o haltere de volta para a posição inicial usando o arco através do qual o peso foi reduzido e expirar enquanto você realiza esse movimento.","Mantenha o peso na posição inicial por um segundo e repita o movimento para o número prescrito de repetições."]],"Straight-Arm_Pulldown":["Puxem o braço direito.",["Você vai começar agarrando a barra larga da polia superior de uma máquina de puxar para baixo e usando uma maior do que a largura do ombro pronada (palmas para baixo) aperto.","Dobre o tronco para frente na cintura em torno de 30 graus com os braços totalmente estendidos na sua frente e uma leve curva nos cotovelos.","Enquanto mantém os braços retos, puxe a barra para baixo contraindo os lats até que suas mãos estejam ao lado das coxas.","Enquanto mantém os braços retos, volte para a posição inicial enquanto respira.","Repita para a quantidade recomendada de repetições."]],"Straight_Bar_Bench_Mid_Rows":["\"Banco direto no meio das fileiras\"",["Coloque uma campainha carregada na ponta de um banco, de pé no banco atrás do bar, pegue uma pegada média e pronada, fique com os quadris para trás e peito para cima, mantendo uma coluna neutra, esta será a sua posição inicial.","Reme a barra até o torso retraindo as omoplatas e flexionando os cotovelos.","Depois de uma breve pausa, lentamente retorne a barra para a posição inicial, garantindo ir até o fim."]],"Straight_Raises_on_Incline_Bench":["Elevações retas em Incline Bench",["Coloque um bar no chão atrás da cabeça de um banco inclinado.","Deite-se no banco de frente para baixo, com um aperto pronado, pegue a campainha do chão, mantendo seus braços retos, deixe a barra pendurada para baixo, esta será sua posição inicial.","Para começar, levante a campainha na frente da cabeça enquanto mantém os braços estendidos.","Voltem para a posição inicial."]],"Stride_Jump_Crossover":["Stride Jump Crossover",["Fique ao lado de uma caixa com seu pé dentro em cima, perto da borda.","Comece balançando os braços para cima enquanto você empurra através da perna superior, pulando para cima o mais alto possível.","Aterrisse na posição oposta que você começou, no lado oposto da caixa, o pé que estava inicialmente na caixa estará agora no chão, com o pé oposto agora na caixa.","Repita o movimento, voltando para o outro lado."]],"Sumo_Deadlift":["Sumo Deadlift",["Comece com uma barra carregada no chão, aproxime-se da barra para que a barra se cruze no meio dos pés, os pés devem ser colocados bem largos, perto dos colares, dobre-se nos quadris para segurar a barra, os braços devem estar diretamente abaixo dos ombros, dentro das pernas, e você pode usar uma pegada pronada, uma pegada mista, ou gancho, relaxe os ombros, que na verdade alonga os braços.","Respire, e depois abaixe os quadris, olhando para a frente com a cabeça para cima, dirija pelo chão, espalhe seus pés, com o peso na parte de trás dos pés, estenda-se através dos quadris e joelhos.","Quando a barra passar pelos joelhos, incline-se e dirija os quadris para a barra, puxando suas omoplatas juntas.","Retorne o peso ao chão dobrando os quadris e controlando o peso na descida."]],"Sumo_Deadlift_with_Bands":["Sumo Deadlift com Bandas",["Para levantar com faixas curtas, simplesmente rode-as sobre o bar antes de começar, e pise neles para se instalar.","Comece com uma barra carregada no chão, aproxime-se da barra para que a barra se cruze no meio dos pés, os pés devem ser colocados bem largos, perto dos colares, dobre-se nos quadris para segurar a barra, os braços devem estar diretamente abaixo dos ombros, dentro das pernas, e você pode usar uma pegada pronada, uma pegada mista ou gancho.","Respire, e depois abaixe os quadris, olhando para a frente com a cabeça para cima, dirija pelo chão, espalhe seus pés, com o peso na parte de trás dos pés, estenda-se através dos quadris e joelhos.","Quando a barra passar pelos joelhos, incline-se e dirija os quadris para a barra, puxando suas omoplatas juntas.","Retorne o peso ao chão dobrando os quadris e controlando o peso na descida."]],"Sumo_Deadlift_with_Chains":["Sumo Deadlift com correntes",["Você pode prender as correntes nas mangas da barra, ou apenas colocar o meio sobre a barra para que haja um aumento de peso maior à medida que você levanta.","Comece com uma barra carregada no chão, aproxime-se da barra para que a barra se cruze no meio dos pés, os pés devem ser colocados bem largos, perto dos colares, dobre-se nos quadris para segurar a barra, os braços devem estar diretamente abaixo dos ombros, dentro das pernas, e você pode usar uma pegada pronada, uma pegada mista, ou gancho, relaxe os ombros, que na verdade alonga os braços.","Respire, e depois abaixe os quadris, olhando para a frente com a cabeça para cima, dirija pelo chão, espalhe seus pés, com o peso na parte de trás dos pés, estenda-se através dos quadris e joelhos.","Quando a barra passar pelos joelhos, incline-se e dirija os quadris para a barra, puxando suas omoplatas juntas.","Retorne o peso ao chão dobrando os quadris e controlando o peso na descida."]],"Superman":["Super-Homem.",["Para começar, deite-se de costas no chão ou no tapete de exercício, seus braços devem estar totalmente estendidos na sua frente, esta é a posição inicial.","Erga os braços, pernas e peito do chão e segure esta contração por 2 segundos.","Lentamente comece a baixar seus braços, pernas e peito para baixo para a posição inicial enquanto inala.","Repita para a quantidade recomendada de repetições prescritas no seu programa."]],"Supine_Chest_Throw":["Arremesso Supina do Peito",["Esta broca é ótima para o peito passar quando você não tem um parceiro ou uma parede de força suficiente.","Comece com a bola no peito, segurada com as duas mãos no fundo.","Explodir, estendendo-se através do cotovelo para jogar a bola diretamente acima de você o mais alto possível.","Pegue a bola com as duas mãos enquanto desce."]],"Supine_One-Arm_Overhead_Throw":["Supinar um braço sobre a cabeça",["Deite-se de costas com os joelhos dobrados, segure a bola com uma mão, estendendo o braço completamente atrás da cabeça, esta será sua posição inicial.","Iniciar o movimento no ombro, jogando a bola diretamente para a frente de você enquanto você se senta, tentando ir para a distância máxima.","A bola pode ser jogada para um parceiro ou saltada de uma parede."]],"Supine_Two-Arm_Overhead_Throw":["Arremesso Supina de Dois Braços",["Deite no chão de costas com os joelhos dobrados.","Segure a bola com as duas mãos, estendendo os braços completamente atrás da cabeça.","Iniciar o movimento no ombro, jogando a bola diretamente para a frente de você enquanto você se senta, tentando ir para a distância máxima.","A bola pode ser jogada para um parceiro ou saltada de uma parede."]],"Suspended_Fallout":["Suspenderam as chuvas.",["Ajuste as alças para que as alças estejam em uma altura adequada, abaixo do nível da cintura.","Comecem a levantar e agarrar as alças, inclinem-se para uma posição de flexão inclinada.","Mantendo os braços retos, incline-se mais para as alças da suspensão, aproximando seu corpo do chão, permitindo que seus ombros se estendam, levantando seus braços para cima e para cima da cabeça.","Mantenha uma coluna neutra e mantenha o resto do corpo reto, seus ombros são as únicas juntas que podem se mover.","Pause durante a contração de pico, e depois volte para a posição inicial."]],"Suspended_Push-Up":["Suspensos, empurrem.",["Âncora suas alças de suspensão firmemente no topo de um rack ou outro objeto.","Inclinando-se nas alças, pegue uma alça em cada mão e mova-se para uma posição de tábua de flexão, você deve estar o mais próximo do paralelo ao chão como você pode lidar com seus braços totalmente estendido, mantendo uma boa postura.","Mantendo um torso reto e rígido, desce lentamente, permitindo que os cotovelos flexionem.","Continue até que seus cotovelos quebrem 90 graus, pausando antes de se estender para voltar à posição inicial."]],"Suspended_Reverse_Crunch":["Suspenderam o crunch reverso.",["Coloque um conjunto de alças de suspensão com as alças penduradas a cerca de um pé do chão.","Coloque os pés nas alças, mantenha uma postura reta, não deixe os quadris caírem, esta será sua posição inicial.","Comece o movimento flexionando os joelhos e os quadris, puxando os joelhos para o torso, enquanto faz isso, incline a pélvis anteriormente, permitindo que sua coluna flexione.","No topo do movimento controlado, volte para a posição inicial."]],"Suspended_Row":["Fila Suspensa",["Suspenda suas alças em torno da altura do peito, pegue um punho em cada mão e incline-se para trás, mantenha seu corpo ereto e sua cabeça e peito para cima, seus braços devem ser totalmente estendidos, esta será sua posição inicial.","Comece flexionando o cotovelo para iniciar o movimento.","Ao completar a pausa do movimento, e depois voltar para a posição inicial."]],"Suspended_Split_Squat":["Agachamento Suspenso",["Suspendam suas alças para que as alças fiquem a 18-30 polegadas do chão.","De frente para longe da instalação, coloque o pé traseiro no cabo atrás de você, mantenha a cabeça olhando para frente e o peito para cima, com o joelho ligeiramente dobrado, esta será a sua posição inicial.","Desça flexionando o joelho e os quadris, baixando-se para o chão, mantenha o peso no calcanhar do pé e mantenha sua postura durante todo o exercício.","No fundo do movimento, inverta o movimento, estendendo-se através do quadril e joelho para retornar à posição inicial."]],"Svend_Press":["Svend Press",["Comecem em posição de pé.","Aperte duas placas leves junto com as mãos, segure as placas juntas perto do peito para criar uma contração isométrica nos músculos do peito, seus dedos devem ser apontados para frente, esta é a sua posição inicial.","Aperte as placas entre as palmas e estenda os braços diretamente na sua frente em um movimento controlado.","Pausa no topo do movimento, e então lentamente voltar para a posição inicial."]],"T-Bar_Row_with_Handle":["T-Bar Row com alça",["Coloque uma barra em uma mina terrestre ou em um canto para evitar que ela se mova.","Fique sobre a barra, e posicione um cabo de linha D em volta da barra ao lado do colarinho, usando seus quadris e pernas, levante-se para uma posição de pé.","Assuma uma postura ampla com os quadris para trás e o peito para cima, seus braços devem ser estendidos, esta será sua posição inicial.","Puxe o peso para o abdômen, retraindo as omoplatas e flexionando os cotovelos.","Após uma breve pausa, volte para a posição inicial."]],"Tate_Press":["Tate Press",["Deite-se em um banco plano com um haltere em cada mão em cima de suas coxas.","Usando suas coxas para ajudá-lo a levantar os halteres, limpe os halteres um braço de cada vez para que você possa segurá-los na sua frente com a largura do ombro.","Manter os braços parados, mover lentamente os halteres para dentro e para baixo em um movimento semi circular até que eles toquem o peito superior enquanto inalam.","Enquanto você expira, mova os halteres para cima usando seus tríceps e o mesmo movimento semi-circular, mas ao contrário, tente manter os halteres juntos enquanto eles se movem para cima, tranque seus braços na posição contraída, segure por um segundo e então comece a descer lentamente novamente.","Repita o movimento para a quantidade prescrita de repetições do seu programa de treinamento."]],"The_Straddle":["O Straddle",["Comece em posição sentada, ereta, e estenda as pernas na sua frente em um V.","Com as mãos no chão, incline-se o máximo possível."]],"Thigh_Abductor":["Seqüestrador de coxas",["Para começar, sente-se na máquina do seqüestro e selecione um peso que você está confortável com. Quando suas pernas estão posicionadas corretamente, segure os cabos de cada lado.","Pressione lentamente contra a máquina com as pernas para tirá-las umas das outras enquanto expiram.","Sinta a contração por um segundo e comece a mover suas pernas de volta para a posição inicial enquanto respira.","Repita para a quantidade recomendada de repetições."]],"Thigh_Adductor":["Adutor de coxa.",["Para começar, sente-se na máquina adutora e selecione um peso que você está confortável com. Quando suas pernas estão posicionadas corretamente nas almofadas das pernas da máquina, segure as alças de cada lado.","Lentamente pressione contra a máquina com as pernas para movê-las um para o outro enquanto expiram.","Sinta a contração por um segundo e comece a mover suas pernas de volta para a posição inicial enquanto respira.","Repita para a quantidade recomendada de repetições."]],"Tire_Flip":["Pneu Flip.",["Comece apertando o fundo do pneu no piso, e posicione os pés um pouco para trás.","Para levantar o pneu, estenda-se através dos quadris, joelhos e tornozelos, dirigindo para o pneu e para cima.","Quando o pneu atingir um ângulo de 45 graus, dê um passo à frente e dirija um joelho para o pneu, assim como você ajusta seu aperto para a parte superior do pneu e empurre-o para frente o mais forte possível para completar a curva."]],"Toe_Touchers":["Toe Touchers",["Para começar, deite-se no chão ou em um tapete de exercício com as costas pressionadas contra o chão.","Suas pernas devem estar se tocando, lentamente eleve suas pernas no ar, até que estejam quase perpendiculares ao chão, com uma leve curva nos joelhos, seus pés devem ser paralelos ao chão.","Mova os braços para que sejam totalmente estendidos a um ângulo de 45 graus do chão.","Enquanto mantém sua parte inferior pressionada contra o chão, lentamente levante seu tronco e use suas mãos para tentar tocar seus dedos.","Lentamente comece a baixar o tronco e os braços para a posição inicial enquanto inala.","Repita para a quantidade recomendada de repetições."]],"Torso_Rotation":["Rotação do torso",["Fique de pé segurando uma bola de exercício com as duas mãos, estenda os braços para que a bola fique bem na sua frente, esta será a sua posição inicial.","Rode seu torso para um lado, mantendo seus olhos na bola enquanto se move, agora volte para a direção oposta, repita por 10-20 repetições."]],"Trail_Running_Walking":["Trail Running/Walking",["Correr ou caminhar em trilhas fará o sangue bombear e o coração bater quase imediatamente certifique-se de ter bons sapatos enquanto você usa os músculos de suas panturrilhas e nádegas para puxar-se para cima de uma colina, os joelhos, articulações e tornozelos absorvem a maior parte do bater voltando para baixo.","Uma pessoa de 150 lb pode queimar mais de 200 calorias por 30 minutos andando para cima, comparado a 175 em uma superfície plana."]],"Trap_Bar_Deadlift":["Trap Bar Deadlift",["Para esta carga de exercício uma barra de armadilha, também conhecida como uma barra de feitiço, para um peso adequado descansando no chão.","Abaixe os quadris, olhe para frente com a cabeça e mantenha o peito levantado.","Comece o movimento dirigindo pelos calcanhares e estenda os quadris e joelhos, evite arredondar as costas o tempo todo.","Ao completar o movimento, reduza o peso de volta ao solo sob controle."]],"Tricep_Dumbbell_Kickback":["Tríceps halteres Kickback",["Comece com um haltere em cada mão e suas palmas voltadas para o torso, mantenha as costas retas com uma leve curva nos joelhos e dobre-se para frente na cintura, seu torso deve ser quase paralelo ao chão, certifique-se de manter a cabeça erguida, seus braços devem estar perto do tronco e paralelos ao chão, seus antebraços devem ser apontados para o chão enquanto segura os pesos, deve haver um ângulo de 90 graus formado entre o antebraço e o braço superior, esta é a sua posição inicial.","Agora, mantendo seus braços parados, expire e use o tríceps para levantar os pesos até que o braço seja estendido.","Após uma breve pausa na contração superior, inale e abaixe lentamente os halteres de volta para a posição inicial.","Repita o movimento para a quantidade prescrita de repetições.","Este exercício pode ser executado também um braço de cada vez, assim como as fileiras de um braço são realizadas.","Além disso, se você gosta da variedade de um braço, você pode usar uma alça de polia baixa em vez de um haltere para melhor contração de pico."]],"Tricep_Side_Stretch":["Esticamento do Triceps.",["Traga o braço direito sobre o corpo e sobre o ombro esquerdo, segurando o cotovelo com a mão esquerda, até que sinta um estiramento no tríceps, e repita para o outro braço."]],"Triceps_Overhead_Extension_with_Rope":["Tríceps Overhead Extension com corda",["Depois de selecionar um peso adequado, agarre a corda com as duas mãos e o rosto longe do cabo.","Posicione as mãos atrás da cabeça com os cotovelos apontados para cima, seus cotovelos devem começar flexionados, e você pode cambalear sua postura e inclinar-se suavemente para longe da máquina para criar maior estabilidade.","Para realizar o movimento, estenda-se através do cotovelo mantendo o braço em posição, levantando as mãos acima da cabeça.","Aperte seu tríceps no topo do movimento, e lentamente abaixe o peso de volta para a posição inicial."]],"Triceps_Pushdown":["Tríceps empurrando para baixo",["Anexar uma barra reta ou angular a uma polia alta e agarrar com um aperto overhand (palms virados para baixo) na largura do ombro.","Em pé, com o torso reto e uma inclinação muito pequena para frente, traga os braços superiores perto do corpo e perpendicular ao chão, os antebraços devem estar apontando para a polia enquanto seguram a barra, esta é sua posição inicial.","Use o tríceps, abaixe a barra até que toque a frente das coxas e os braços sejam totalmente estendidos perpendicularmente ao chão, os braços devem permanecer parados ao lado do tronco e apenas os antebraços devem se mover.","Depois de um segundo tempo na posição contratada, leve a barra lentamente até o ponto de partida.","Repita para a quantidade recomendada de repetições."]],"Triceps_Pushdown_-_Rope_Attachment":["Tríceps Pushdown - Anexamento de corda",["Anexar uma corda a uma polia alta e agarrar com uma aderência neutra (palmas viradas uma para a outra).","Os antebraços devem estar apontando para a polia enquanto seguram a corda com as palmas viradas uma para a outra.","Ao usar o tríceps, desça a corda enquanto você traz cada lado da corda para o lado de suas coxas, no final do movimento os braços são totalmente estendidos e perpendiculares ao chão, os braços superiores devem sempre permanecer parados ao lado do seu tronco e apenas os antebraços devem se mover.","Depois de segurar por um segundo, na posição contraída, leve a corda lentamente até o ponto de partida.","Repita para a quantidade recomendada de repetições."]],"Triceps_Pushdown_-_V-Bar_Attachment":["Tríceps empurrando - V-Bar anexo",["Anexar uma barra de V a uma polia alta e agarrar com um aperto de mão (palmas viradas para baixo) na largura do ombro.","Em pé, com o torso reto e uma inclinação muito pequena para frente, traga os braços superiores perto do seu corpo e perpendicular ao chão, os antebraços devem estar apontando para a polia enquanto seguram a barra, os polegares devem ser mais altos que o dedo pequeno, esta é a sua posição inicial.","Use o tríceps, abaixe a barra até que toque a frente das coxas e os braços sejam totalmente estendidos perpendicularmente ao chão, os braços devem permanecer parados ao lado do tronco e apenas os antebraços devem se mover.","Depois de um segundo tempo na posição contratada, leve o V-Bar lentamente até o ponto de partida.","Repita para a quantidade recomendada de repetições."]],"Triceps_Stretch":["Tríceps esticar",["Segure a mão atrás da cabeça, segure o cotovelo e puxe gentilmente, segure por 10 a 20 segundos e mude de lado."]],"Tuck_Crunch":["Tuck Crunch",["Para começar, deite-se no chão ou em um tapete de exercício com as costas pressionadas contra o chão.","Suas pernas devem ser cruzadas enrolando um tornozelo ao redor do outro, lentamente eleve suas pernas para cima até que suas coxas estejam perpendiculares ao chão com uma leve curva nos joelhos, e seus joelhos e dedos dos pés devem ser paralelos ao chão, em vez das coxas.","Tire os braços do chão e cruze-os para que descansem em seu peito.","Enquanto mantém a parte inferior das costas pressionada contra o chão, lentamente levante o torso, lembre-se de expirar enquanto faz esta parte do exercício.","Lentamente comece a baixar seu torso de volta para a posição inicial enquanto inala.","Repita para a quantidade recomendada de repetições."]],"Two-Arm_Dumbbell_Preacher_Curl":["halteres Dumblebell Curl",["Pegue um haltere com cada braço e coloque os braços em cima do banco do pastor ou do banco incline.","Enquanto você respira, abaixe lentamente os halteres até que seu braço seja estendido e o bíceps esteja totalmente esticado.","Enquanto você expira, use os bíceps para enrolar os pesos até que seus bíceps estejam totalmente contraídos e os halteres estejam em altura do ombro.","Aperte o bíceps com força por um segundo na posição contraída e repita a quantidade recomendada de repetições."]],"Two-Arm_Kettlebell_Clean":["Dois braços Kettlebell Limpo",["Coloque duas campainhas entre os pés, para entrar na posição inicial, empurre o traseiro para trás e olhe para frente.","Limpe as campainhas nos ombros, estendendo-se pelas pernas e quadris, enquanto levanta as chaleiras em direção aos ombros, gira os pulsos enquanto faz isso.","Abaixe as campainhas de volta para a posição inicial e repita."]],"Two-Arm_Kettlebell_Jerk":["Dois-Arm Kettlebell Jerk",["Limpe duas campainhas para os ombros, limpe as campainhas para os ombros, estendendo-se pelas pernas e quadris enquanto você balança as campainhas para os ombros, gire os pulsos enquanto você faz isso, para que as palmas da mão fiquem para a frente, desça alguns centímetros e inverta o movimento rapidamente dirigindo ambas as chaleiras para cima, imediatamente após o empurrão inicial, agache-se novamente e fique debaixo das chaleiras, assim que as chaleiras estiverem trancadas para fora, fique de pé para completar o exercício."]],"Two-Arm_Kettlebell_Military_Press":["Imprensa militar Kettlebell de dois braços",["Limpe duas campainhas nos seus ombros, limpe as campainhas nos seus ombros, estendendo-se pelas pernas e quadris enquanto balança as campainhas nos seus ombros, gire os pulsos enquanto faz isso, para que as palmas da mão fiquem viradas para frente.","Aperte as campainhas para cima e para fora, enquanto as chaleiras passam pela sua cabeça, incline-se para os pesos, para que as chaleiras fiquem atrás da sua cabeça, certifique-se de contrair seus traseiros, traseiros e estômagos para aumentar a estabilidade."]],"Two-Arm_Kettlebell_Row":["Fila Kettlebell de dois braços",["Coloque duas campainhas na frente dos pés, dobre os joelhos ligeiramente e empurre o traseiro para fora o máximo possível para ficar na posição inicial.","Pegue as duas campainhas e puxe-as para o estômago, retraindo suas omoplatas e flexionando os cotovelos."]],"Underhand_Cable_Pulldowns":["Cabos escondidos puxados.",["Sente-se em uma máquina de puxar para baixo com uma barra larga presa na polia superior, ajuste a joelheira da máquina para caber na sua altura, essas almofadas impedirão que seu corpo seja levantado pela resistência ligada à barra.","Pegue a barra de puxar para baixo com as palmas voltadas para seu tronco (um aperto supinado) e certifique-se de que as mãos sejam colocadas mais perto que a largura do ombro.","Como você tem os dois braços estendidos na frente de você segurando a barra na largura de aderência escolhida, traga seu torso de volta em torno de 30 graus ou assim, enquanto cria uma curvatura em suas costas inferiores e colocar seu peito para fora.","Quando expirar, puxe a barra para baixo até tocar o peito superior, puxando os ombros e os braços para baixo e para trás. Dica: Concentre-se em apertar os músculos das costas uma vez que você atinja a posição totalmente contraída e mantenha os cotovelos perto do corpo.","Depois de um segundo na posição contraída, enquanto respira, lentamente traga a barra de volta para a posição inicial quando seus braços estão totalmente estendidos e os lats estão totalmente esticados.","Repita esta moção para a quantidade prescrita de repetições."]],"Upper_Back-Leg_Grab":["Pegar a parte de trás superior.",["Enquanto sentado, dobre-se para a frente para abraçar suas coxas de baixo com os dois braços.","Mantenha seus joelhos juntos e suas pernas estendidas enquanto você coloca seu peito para baixo para seus joelhos, você também pode esticar suas costas puxando suas costas para longe de seus joelhos enquanto as abraça."]],"Upper_Back_Stretch":["Esticamento superior das costas",["Aperte os dedos com os polegares apontando para baixo, rodeie os ombros enquanto você alcança as mãos para a frente."]],"Upright_Barbell_Row":["Lá em cima, Barbell Row",["Segure uma campainha com um aperto de mão levemente menor que a largura do ombro, a barra deve estar descansando na parte superior das coxas com os braços estendidos e uma leve dobra nos cotovelos, suas costas também devem estar retas, esta será a sua posição inicial.","Agora expire e use os lados dos ombros para levantar a barra, levantando os cotovelos para cima e para o lado. Mantenha a barra perto do corpo enquanto você a levanta. Continue a levantar a barra até que quase toque o queixo.","Abaixe a barra lentamente para a posição inicial, inspire enquanto executa esta parte do movimento.","Repita para a quantidade recomendada de repetições."]],"Upright_Cable_Row":["Fila de cabos em cima.",["Segure um cabo de barras retas que está preso a uma polia baixa com uma aderência pronada (palmas voltadas para suas coxas) ligeiramente menor que a largura do ombro.","Use seus ombros laterais para levantar a barra de cabo enquanto você expira, a barra deve estar perto do corpo enquanto você o move, continue a levantá-lo até que ele quase toque seu queixo, dica, seus cotovelos devem dirigir o movimento, enquanto você levanta a barra, seus cotovelos devem ser sempre mais altos do que seus antebraços, também, mantenha seu tronco parado e pause por um segundo no topo do movimento.","Abaixe a barra lentamente para a posição inicial, inspire enquanto executa esta parte do movimento.","Repita para a quantidade recomendada de repetições."]],"Upright_Row_-_With_Bands":["Fila direita com bandas.",["Para começar, coloque-se em uma faixa de exercício para que a tensão comece com o comprimento do braço. Segure as pegas usando uma alça pronada (palmas voltadas para suas coxas) que seja ligeiramente menor do que a largura do ombro. As pegas devem estar descansando em cima de suas coxas. Seus braços devem ser estendidos com uma ligeira curva nos cotovelos e suas costas devem ser retas. Esta será sua posição inicial.","Use seus ombros laterais para levantar as alças enquanto expira, as alças devem estar perto do corpo, enquanto você as move, continue a levantar as alças até que quase toquem seu queixo, e os cotovelos devem dirigir o movimento, enquanto você levanta as alças, seus cotovelos devem ser sempre mais altos que seus antebraços, e também, mantenha seu tronco parado e pause por um segundo no topo do movimento.","Abaixe as alças lentamente para a posição inicial, inale enquanto executa esta parte do movimento.","Repita para a quantidade recomendada de repetições."]],"Upward_Stretch":["Para cima, esticar.",["Estenda as duas mãos acima da cabeça, com as palmas das mãos tocando.","Devagar, empurre as mãos para cima e para trás, mantendo as costas retas."]],"V-Bar_Pulldown":["V-Bar Pulldown",["Sente-se em uma máquina de puxar para baixo com uma barra V ligada à polia superior.","Ajuste a joelheira da máquina para caber na sua altura, e evitará que seu corpo seja levantado pela resistência ligada à barra.","Pegue a barra V com as palmas viradas uma para a outra, estique o peito e incline-se ligeiramente para trás, para que melhor se atrapalhe.","Continue até que seu peito quase toque na barra V, expire enquanto executa este movimento, mantenha o tronco parado durante todo o movimento.","Depois de uma segunda espera na posição contraída, lentamente traga a barra de volta para a posição inicial enquanto você respira.","Repita para o número de repetições prescritas."]],"V-Bar_Pullup":["V-Bar Pullup",["Comece colocando o meio da barra V no meio da barra pull-up (assumindo que a estação pull-up que você está usando não tem alças neutras).","Assim que colocar a barra V, segure a barra de cada lado e pendure nela, estique o peito e incline-se um pouco para trás, a fim de melhor acionar os lats, esta será sua posição inicial.","Usando seus lats, puxe seu torso para cima enquanto inclina sua cabeça para trás ligeiramente para que você não bata em si mesmo com a barra chin-up. Continue até que seu peito quase toque a barra V. Expire enquanto executa este movimento.","Depois de um segundo de espera na posição contraída, abaixe lentamente seu corpo de volta para a posição inicial enquanto você respira.","Repita para o número de repetições prescritas."]],"Vertical_Swing":["Balanço Vertical",["Permita que o haltere pendure os braços entre as pernas, segurando-o com as duas mãos, mantenha as costas retas e a cabeça erguida.","Balance o haltere entre suas pernas, flexionando os quadris e dobrando os joelhos ligeiramente.","Reverte poderosamente o movimento estendendo-se nos quadris, joelhos e tornozelos para se impulsionar para cima, balançando o burro sobre sua cabeça.","Ao pousar, absorva o impacto através das pernas e desenhe o haltere para o tronco antes da próxima repetição."]],"Walking_Treadmill":["Andando, Treadmill",["Para começar, pise na esteira e selecione a opção desejada no menu, a maioria das esteiras tem uma configuração manual, ou você pode selecionar um programa para executar, normalmente, você pode entrar em sua idade e peso para estimar a quantidade de calorias queimadas durante o exercício, a elevação pode ser ajustada para alterar a intensidade do treino.","As esteiras oferecem comodidade, benefícios cardiovasculares, e geralmente têm menos impacto do que andar fora, quando se anda, você deve mover-se a um ritmo moderado a rápido, não de lazer, sendo uma atividade de menor intensidade, caminhar não queima tantas calorias como outras atividades, mas ainda proporciona grande benefício, uma pessoa de 150 lb queimará cerca de 175 calorias andando 4 milhas por hora por 30 minutos, comparado com 450 calorias correndo duas vezes mais rápido, mantendo uma postura adequada como você anda, e apenas manter as alças quando necessário, como ao desmontar ou verificar seu ritmo cardíaco."]],"Weighted_Ball_Hyperextension":["Hiperextensão de bola ponderada.",["Para começar, deite-se em uma bola de exercício com seu torso pressionando contra a bola e paralelo ao chão.","Levante o tronco lentamente dobrando a cintura e as costas, lembre-se de expirar durante este movimento.","Segure a contração na parte inferior das costas por um segundo e abaixe o tronco de volta para a posição inicial enquanto inala.","Repita para a quantidade recomendada de repetições prescritas no seu programa."]],"Weighted_Ball_Side_Bend":["\"Lado de bola ponderado dobre\"",["Para começar, deite-se em uma bola de exercício com seu lado esquerdo do tronco (cimeira, quadris e ombro) pressionado contra a bola.","Seus pés devem estar no chão enquanto suas pernas estão cruzadas e penduradas na bola. Segure uma placa ponderada com a mão direita diretamente para o lado direito da sua cabeça.","Coloque seu braço esquerdo no tronco para que sua palma esteja nos oblíquos, deve haver um ângulo direito entre o antebraço esquerdo e a parte superior do braço.","Levante o lado do torso, flexionando lateralmente na cintura enquanto expira.","Segure a contração por um segundo e abaixe-se lentamente de volta para a posição inicial enquanto inala.","Repita para a quantidade recomendada de repetições.","Troque de lado e repita o exercício."]],"Weighted_Bench_Dip":["Bench Mergulhado.",["Para este exercício, você precisará colocar um banco atrás das costas e outro à sua frente, com os bancos perpendiculares ao seu corpo, segure um banco na borda com as mãos próximas ao seu corpo, separados na largura do ombro, seus braços devem ser estendidos.","As pernas serão estendidas para frente em cima do outro banco, suas pernas devem ser paralelas ao chão, enquanto seu torso deve ser perpendicular ao chão, seu parceiro colocará o haltere em seu colo, este exercício é melhor realizado com um parceiro, pois colocar o peso em seu colo pode ser desafiador e causar lesões sem ajuda, esta será sua posição inicial.","Abaixe lentamente o corpo enquanto inala dobrando os cotovelos até se abaixar o suficiente para um ângulo ligeiramente menor que 90 graus entre o braço e o antebraço.","Usando o tríceps para levantar o torso novamente, levante-se de volta à posição inicial enquanto expira.","Repita para a quantidade recomendada de repetições."]],"Weighted_Crunches":["-Crunches ponderados",["Deite-se de costas com os pés no chão ou descansando em um banco com os joelhos dobrados em um ângulo de 90 graus.","Segure um peso no peito, ou pode segurá-lo esticado acima do torso.","Agora, expire e lentamente comece a rolar seus ombros para fora do chão... seus ombros devem subir do chão cerca de 4 polegadas enquanto suas costas ficam no chão.","No topo do movimento, flexione seus abdominais e segure para uma breve pausa.","Então inale e abaixe-se lentamente de volta para a posição inicial."]],"Weighted_Jump_Squat":["Salto Ponderado",["Posicione uma campainha levemente carregada na parte de trás dos ombros, e também pode usar um colete, saco de areia ou outro tipo de resistência para esse exercício.","O peso deve ser leve o suficiente para não atrasá-lo significativamente seus pés devem estar fora da largura do ombro com sua cabeça e peito para cima.","Usando um contra-movimento, agache-se parcialmente e inverta imediatamente sua direção para explodir do chão, estendendo-se através de seus quadris, joelhos e tornozelos.","Quando voltar ao chão, absorva o impacto através das pernas."]],"Weighted_Pull_Ups":["\"Puxa para cima\"",["Coloque um peso em um cinto de mergulho e segure-o ao redor da cintura, pegue a barra de puxar com as palmas das mãos voltadas para a frente, para um aperto médio, suas mãos devem ser espaçadas na largura do ombro, ambos os braços devem ser estendidos na frente de você segurando a barra na aderência escolhida.","Você vai querer trazer seu torso de volta cerca de 30 graus enquanto cria uma curvatura em suas costas inferiores e colocar seu peito para fora.","Agora, expire e puxe o torso até a cabeça estar acima das mãos, concentre-se em apertar as pás do ombro para trás e para baixo quando chegar na posição contraída.","Depois de um breve momento na posição superior contraída, inalar e lentamente baixar seu torso de volta para a posição inicial com seus braços estendidos e seus lats totalmente esticados."]],"Weighted_Sissy_Squat":["Agachamento de Sissy ponderado",["Em pé, com os pés na largura do ombro e os dedos dos pés levantados, use uma mão para segurar as vigas de um rack de agachamento e o braço oposto para segurar uma placa em cima de seu peito.","Enquanto você usa um braço para se segurar, dobrar os joelhos e lentamente baixar o tronco em direção ao chão, trazendo sua pélvis e joelhos para frente, inale enquanto desce e pare quando suas pernas superiores e inferiores quase criam um ângulo de 90 graus, mantenha a posição de estiramento por um segundo.","Depois de um segundo de espera, use os músculos da coxa para trazer seu torso de volta para a posição inicial.","Repita para a quantidade recomendada de vezes."]],"Weighted_Sit-Ups_-_With_Bands":["\"Sit-ups ponderados com faixas\"",["Comece amarrando as bandas ao redor da base do banco de declínio, coloque as alças em direção ao interior do banco de declínio, para que, quando deitar, você possa alcançar as duas.","Coloque as pernas na máquina de decaimento até que estejam seguras, agora alcance as bandas de exercício com as duas mãos, use um aperto pronado (palmas para a frente) para agarrar as alças, posicione-as perto do osso do colarinho e gire o pulso para uma aderência neutra, com as palmas viradas para o tronco, e seus braços devem permanecer parados durante todo o exercício.","Mova o tronco para cima até a parte superior do corpo estar perpendicular ao chão enquanto expira, segure a contração por um segundo e abaixe o corpo para a posição inicial enquanto inala.","Repita para a quantidade recomendada de repetições."]],"Weighted_Squat":["Agachamento Peso",["Comece por posicionar dois bancos planos de largura do ombro, além um do outro, fique em cima deles e enrole o cinto ponderado em torno de sua cintura com a quantidade de peso que você se sente confortável.","Uma vez que você está em pé com o peso pendurado entre suas pernas, posicione seus braços para que eles sejam totalmente estendidos para o lado do seu corpo.","Comece dobrando os joelhos enquanto mantém uma postura reta com a cabeça para cima. Continue para baixo até que o ângulo entre a perna superior e os bezerros se torne ligeiramente inferior a 90 graus (que é o ponto em que as pernas superiores estão abaixo paralelas ao chão). Inspire enquanto você executa esta parte do movimento. Dica: Se você realizou o exercício corretamente, a frente dos joelhos deve fazer uma linha reta imaginária com os dedos perpendiculares à frente. Se seus joelhos estão além dessa linha imaginária (se eles estão além de seus dedos dos pés) então você está colocando estresse excessivo no joelho e o exercício foi realizado incorretamente.","Comece a mover o corpo para cima empurrando o chão do banco plano com a bola do seu pé principalmente quando você endireitar as pernas novamente e voltar para a posição inicial.","Repita para a quantidade recomendada de repetições."]],"Wide-Grip_Barbell_Bench_Press":["Big Grip Barbell Bench Press",["Deite-se em um banco plano, com os pés firmes no chão, usando um punho largo, pronado, que está a cerca de 3 polegadas de distância da largura do ombro (para cada mão), levante a barra do rack e segure-a sobre você com os braços fechados, a barra será perpendicular ao tronco e ao chão, esta será a sua posição inicial.","Enquanto respira, desça devagar até sentir a barra no peito.","Depois de uma segunda pausa, traga a barra de volta para a posição inicial enquanto você expira e empurre a barra usando os músculos do peito, tranque os braços e aperte o peito na posição contraída, segure por um segundo e comece a descer lentamente novamente.","Repita o movimento para a quantidade prescrita de repetições."]],"Wide-Grip_Decline_Barbell_Bench_Press":["Big Grip Decline Barbell Bench Press",["Deite-se em um banco de declínio com os pés firmemente trancados na frente do banco, usando um aperto largo, pronado (palmas para frente) que está a cerca de 3 polegadas de distância da largura do ombro (para cada mão), levantar a barra do rack e segurá-lo diretamente sobre você com os braços trancados, a barra será perpendicular ao tronco e ao chão. Esta será a sua posição inicial.","Enquanto você respira, desça devagar até sentir a barra em seu peito inferior.","Depois de uma segunda pausa, traga a barra de volta para a posição inicial enquanto você expira e empurre a barra usando os músculos do peito, tranque os braços e aperte o peito na posição contraída, segure por um segundo e comece a descer lentamente novamente.","Repita o movimento para a quantidade prescrita de repetições."]],"Wide-Grip_Decline_Barbell_Pullover":["Pullover Barbell de Declínio de Largura.",["Deite-se em um banco de declive com as duas pernas firmemente trancadas na posição, pegue a campainha atrás da cabeça usando um aperto pronado (palmas viradas para fora), certifique-se de agarrar a campainha mais larga do que a largura do ombro para este exercício, lentamente levante a campainha para cima do chão usando os braços.","Quando posicionado corretamente, seus braços devem ser totalmente estendidos e perpendiculares ao chão.","Comece movendo a campainha de volta em um movimento semicircular como se fosse colocá-la no chão, mas em vez disso, pare quando os braços estiverem paralelos ao chão.","Agora traga o barbell enquanto expira até que você esteja de volta à posição inicial.","Repita o movimento para a quantidade prescrita de repetições do seu programa de treinamento.","Quando terminar com o seu conjunto, abaixe lentamente a campainha de volta para baixo até que esteja nivelada com sua cabeça e solte-a."]],"Wide-Grip_Lat_Pulldown":["Largura larga para baixo.",["Sente-se em uma máquina de puxar para baixo com uma barra larga presa na polia superior, certifique-se de ajustar a joelheira da máquina para ajustar sua altura, essas almofadas impedirão que seu corpo seja levantado pela resistência ligada à barra.","Pegue a barra com as palmas voltadas para a frente usando o aperto prescrito. Nota sobre pegas: Para um aperto largo, suas mãos precisam ser espaçadas a uma distância maior que a largura do ombro.","Como você tem os dois braços estendidos na frente de você segurando a barra na largura de aderência escolhida, traga seu torso de volta em torno de 30 graus ou assim, enquanto cria uma curvatura em suas costas inferiores e colocar seu peito para fora.","Quando expirar, abaixe a barra até tocar o peito superior, puxando os ombros e os braços para baixo e para trás.","Depois de um segundo na posição contraída apertando suas omoplatas juntas, lentamente levante a barra de volta para a posição inicial quando seus braços estiverem totalmente estendidos e os lats estiverem totalmente esticados.","Repita esta moção para a quantidade prescrita de repetições."]],"Wide-Grip_Pulldown_Behind_The_Neck":["Golpe largo atrás do pescoço",["Sente-se em uma máquina de puxar para baixo com uma barra larga presa na polia superior, certifique-se de ajustar a joelheira da máquina para ajustar sua altura, essas almofadas impedirão que seu corpo seja levantado pela resistência ligada à barra.","Pegue a barra com as palmas voltadas para a frente usando o aperto prescrito.","Como você tem os dois braços estendidos na frente de você segurando a barra na largura de aderência escolhida, traga seu torso e cabeça para frente.","Quando expirar, abaixe a barra até tocar a parte de trás do pescoço, puxando os ombros e os braços para baixo e para trás. Dica: Concentre-se em apertar os músculos das costas uma vez que você atinja a posição contraída total.","Depois de um segundo na posição contraída apertando suas omoplatas juntas, lentamente eleve a barra de volta para a posição inicial quando seus braços estão totalmente estendidos e os lats estão totalmente esticados.","Repita esta moção para a quantidade prescrita de repetições."]],"Wide-Grip_Rear_Pull-Up":["Retirada de trás larga.",["Pegue a barra com as palmas voltadas para a frente usando um aperto largo.","Como você tem os dois braços estendidos na frente de você segurando a barra, traga seu torso para frente e cabeça para que haja uma linha imaginária da barra puxada para a parte de trás do seu pescoço.","Para fazer isso, puxe os ombros e os braços para baixo e para trás, enquanto ligeiramente inclinando sua cabeça para frente, expire enquanto você executa esta parte do movimento, dica, concentre-se em apertar os músculos das costas uma vez que você atinja a posição contraída, o torso superior deve permanecer parado enquanto se move pelo espaço e apenas os braços devem se mover, os antebraços não devem fazer outro trabalho além de segurar a barra.","Depois de um segundo na posição contraída, comece a inalar e lentamente abaixe seu torso de volta para a posição inicial quando seus braços estão totalmente estendidos e os lats estão totalmente esticados.","Repita esta moção para a quantidade prescrita de repetições."]],"Wide-Grip_Standing_Barbell_Curl":["Barbell Curl em pé de largura",["Levante-se com o torso ereto enquanto segura uma campainha no punho exterior largo, a palma das mãos deve estar voltada para frente, os cotovelos devem estar perto do torso, esta será a sua posição inicial.","Enquanto segura os braços parados, enrole os pesos para frente enquanto contrai os bíceps enquanto expira.","Continue o movimento até que seus bíceps estejam totalmente contraídos e a barra esteja no nível do ombro.","Lentamente começar a trazer o bar de volta à posição inicial enquanto você respira.","Repita para a quantidade recomendada de repetições."]],"Wide_Stance_Barbell_Squat":["Squat Barbell Wide Stance",["Este exercício é melhor realizado dentro de um rack de agachamento para fins de segurança, para começar, primeiro coloque a barra em um rack que melhor corresponde à sua altura, uma vez que a altura correta é escolhida e a barra é carregada, passo sob a barra e colocar a parte de trás de seus ombros (ligeiramente abaixo do pescoço) através dele.","Segure-se na barra usando os dois braços de cada lado e levante-a do rack empurrando com as pernas e ao mesmo tempo endireitando o tronco.","Afaste-se do rack e posicione suas pernas usando uma postura mais ampla do que o ombro com os dedos apontados ligeiramente.","Comece a baixar lentamente a barra dobrando os joelhos enquanto mantém uma postura reta com a cabeça para cima. Continue até que o ângulo entre a perna superior e os bezerros se torne ligeiramente inferior a 90 graus (que é o ponto em que as pernas superiores estão abaixo paralelas ao chão). Inspire enquanto você executa esta parte do movimento. Dica: Se você realizou o exercício corretamente, a frente dos joelhos deve fazer uma linha reta imaginária com os dedos perpendiculares à frente. Se seus joelhos estão além dessa linha imaginária (se eles estão além dos dedos dos pés) então você está colocando estresse excessivo no joelho e o exercício foi realizado incorretamente.","Comece a levantar a barra enquanto expira, empurrando o chão com o calcanhar do pé, enquanto endireita as pernas novamente e volta para a posição inicial.","Repita para a quantidade recomendada de repetições."]],"Wide_Stance_Stiff_Legs":["Pernas grandes e fortes",["Comece com uma campainha carregada no chão, adote uma postura larga, e depois curve-se nos quadris para agarrar a barra, seus quadris devem estar o mais longe possível, e suas pernas quase retas, mantenha as costas retas, e sua cabeça e peito para cima, esta será sua posição inicial.","Comece o movimento engajando os quadris, levando-os para a frente enquanto você permite que os braços pendurem em linha reta, continue até que você esteja em pé, e então lentamente retorne o peso para a posição inicial."]],"Wind_Sprints":["Sprints de vento",["Pendure-se em uma barra com um aperto pronado, seus braços e pernas devem ser estendidos, esta será sua posição inicial.","Comece rapidamente levantando um joelho o mais alto que puder, não balance seu corpo ou suas pernas.","Reverta imediatamente o movimento, devolvendo a perna para a posição inicial e, simultaneamente, levante o joelho o mais alto possível.","Continue alternando entre as pernas até que o conjunto esteja completo."]],"Windmills":["Moinhos de vento",["Deite-se de costas com os braços estendidos para os lados e as pernas retas.","Levante uma perna e cruze-a rapidamente sobre seu corpo, tentando tocar o chão perto da mão oposta.","Retorne à posição inicial e repita com a perna oposta."]],"Worlds_Greatest_Stretch":["O maior alongamento do mundo",["Este é um estiramento de três partes, comece com o pulmão para frente, com o pé dianteiro plano no chão e nos dedos do pé de trás, com os joelhos dobrados, agache-se até o joelho quase tocar o chão, mantenha o tronco ereto e mantenha esta posição por 10-20 segundos.","Agora, coloque o braço do mesmo lado da perna dianteira no chão, com o cotovelo ao lado do pé, e sua outra mão deve ser colocada no chão, paralela à perna de chumbo, para ajudá-lo a sustentá-lo durante esta parte do trecho.","Depois de 10-20 segundos, coloque as mãos em ambos os lados do pé da frente, levante os dedos do pé da frente do chão, e endireite a perna, talvez precise reposicionar a perna traseira para fazer isso, segure por 10-20 segundos e repita toda a sequência para o outro lado."]],"Wrist_Circles":["Círculos de pulso",["Eleva seus braços para o lado de vocês até que estejam totalmente estendidos e paralelos ao chão em uma altura que esteja uniformemente alinhada com seus ombros.","Mantenha seu corpo parado, exceto pelos pulsos, e comece a girar os dois pulsos para frente em movimento circular.","Repita para a quantidade recomendada de repetições."]],"Wrist_Roller":["Rolo de pulso",["Para começar, fique de pé segurando um rolo de pulso usando um aperto pronado (palmas viradas para baixo) e seus pés devem ter largura de ombro separada.","Levante os dois braços lentamente até que estejam totalmente estendidos e paralelos ao chão na sua frente, veja se a corda não está enrolada no rolo, todo o seu corpo deve estar parado, exceto os antebraços.","Rodar um pulso de cada vez em um movimento ascendente para levar o peso até a barra, rodando a corda ao redor do rolo.","Uma vez que o peso atingiu a barra, lentamente começar a baixar o peso de volta para baixo, girando o pulso em um movimento para baixo até que o peso atinge a posição inicial.","Repita para a quantidade prescrita de repetições em seu programa."]],"Wrist_Rotations_with_Straight_Bar":["Rotações de pulso com barra reta",["Segure uma campainha com as duas mãos e as palmas viradas para baixo, com as mãos espaçadas sobre a largura do ombro.","Alternando entre cada uma de suas mãos, realize o movimento estendendo o pulso como se estivesse enrolando um jornal.","Reverta o movimento, flexionando o pulso, rodando na direção oposta, continuando o movimento alternado até a falha."]],"Yoke_Walk":["Yoke Walk",["O jugo geralmente é feito com um aparelho de jugo, mas às vezes é visto com geladeiras ou outros objetos pesados.","Começar por colocar o aparelho na parte de trás dos ombros, com a cabeça olhando para frente e para trás arqueada, levantar o jugo dirigindo através dos calcanhares.","Comece a andar o mais rápido possível, usando passos curtos e rápidos, pode segurar os postes laterais do jugo para ajudar a estacioná-lo e mantê-lo em posição, continue a distância o mais rápido possível, geralmente 75-100 pés."]],"Zercher_Squats":["Zercher Squats",["Para começar, coloque a barra em uma prateleira que combina melhor com sua altura, a altura correta deve estar em qualquer lugar acima da cintura, mas abaixo do peito, uma vez que a altura correta é escolhida e a barra é carregada, tranque suas mãos juntas e coloque a barra em cima dos braços entre o antebraço e o braço superior.","Levante a barra para que ela esteja descansando em cima dos antebraços... e se você está segurando a barra corretamente, deve parecer que você tem seus braços cruzados... mas com uma barra correndo através deles.","Afaste-se do rack e posicione suas pernas usando uma posição média de largura do ombro com os dedos dos pés ligeiramente apontados. Mantenha sua cabeça erguida o tempo todo como olhando para baixo vai deixá-lo fora de equilíbrio e também manter uma reta para trás.","Comece a baixar a barra dobrando os joelhos enquanto você mantém uma postura reta com a cabeça para cima. Continue para baixo até que o ângulo entre a perna superior e os bezerros se torne ligeiramente inferior a 90 graus (que é o ponto em que as pernas superiores estão abaixo paralelas ao chão). Inspire enquanto você executa esta parte do movimento. Dica: Se você realizou o exercício corretamente, a frente dos joelhos deve fazer uma linha reta imaginária com os dedos perpendiculares à frente. Se seus joelhos estão além dessa linha imaginária (se eles estão além dos dedos dos pés) então você está colocando estresse excessivo no joelho e o exercício foi realizado incorretamente.","Comece a levantar a barra enquanto expira, empurrando o chão com a bola do pé, principalmente quando endireita as pernas novamente e volta para a posição inicial.","Repita para a quantidade recomendada de repetições."]],"Zottman_Curl":["Zottman Curl",["Levante-se com o torso ereto e um haltere em cada mão sendo mantido ao longo dos braços, os cotovelos devem estar perto do tronco.","Certifique-se de que as palmas das mãos estão voltadas uma para a outra.","Enquanto segura o braço parado, enrole os pesos enquanto contrai os bíceps enquanto expira, apenas os antebraços devem se mover, seu pulso deve girar para que você tenha um aperto supinado, continue o movimento até que seus bíceps estejam totalmente contraídos e os halteres estejam no nível do ombro.","Mantenha a posição contraída por um segundo enquanto aperta os bíceps.","Agora, durante a posição contraída, gire o pulso até que agora tenha um punho pronado com o polegar em uma posição mais alta do que o mindinho.","Lentamente começar a trazer os halteres de volta para baixo usando o aperto pronated.","À medida que os halteres fecham as coxas, comecem a girar o pulso para que você volte para um aperto neutro (palmas viradas para o seu corpo).","Repita para a quantidade recomendada de repetições."]],"Zottman_Preacher_Curl":["Zottman Pastor Curl",["Pegue um haltere em cada mão e coloque seus braços em cima do banco do pastor ou do banco incline os halteres devem ser mantidos na altura do ombro e os cotovelos devem ser flexionados segure os halteres com as palmas das mãos viradas para baixo esta será a sua posição inicial","Enquanto você respira, abaixe lentamente os halteres mantendo as palmas para baixo até que seu braço seja estendido e seus bíceps estejam totalmente esticados.","Agora gire seus pulsos quando estiver no fundo do movimento para que as palmas das mãos estejam viradas para cima.","Enquanto você expira, use seus bíceps para enrolar os pesos até que estejam totalmente contraídos e os halteres estejam na altura do ombro.","Aperte os bíceps com força por um segundo na posição contraída e gire seus pulsos para que as palmas estejam viradas para baixo novamente.","Repita para a quantidade recomendada de repetições."]],"wger-12":["Adução de quadril sentado",["Posição inicial: sente-se na máquina com os joelhos para dentro e contra as almofadas."]],"wger-348":["Aumentos Laterais",["Este exercício funciona o músculo deltóide do ombro. O movimento começa com os braços retos, e as mãos segurando pesos nos lados ou na frente do corpo. O corpo está em uma posição leve para a frente, com quadris e joelhos dobrados um pouco. Os braços são mantidos retos ou ligeiramente dobrados, e levantados através de um arco de movimento no plano coronal que termina quando as mãos estão aproximadamente na altura do ombro. Pesos são baixados para a posição inicial, completando um rep. Ao usar uma máquina de cabo, o indivíduo fica de pé com o plano coronal em linha com a pulley, que está no ou perto do chão.[9] O exercício pode ser completado um ombro de cada vez (com a outra mão usada para estabilizar o corpo contra o peso movido), ou com ambas as mãos simultaneamente se estiverem disponíveis duas pulleys paralelas."]],"wger-365":["Perna Curls (deitando)",["Deite-se em um banco e coloque seus bezerros atrás do suporte da perna (melhor se eles estão segurando em torno dos bezerros inferiores). Segure um aperto nas barras para ter certeza de que o corpo está firmemente no lugar. Dobrar suas pernas trazendo o peso para cima, ir lentamente para trás. Durante o exercício o corpo não deve se mover, todo o trabalho é feito pelas pernas."]],"wger-465":["Pastor Curls.",["Coloque a barra de cachos EZ sobre as alças restantes na frente do banco do pastor. Incline-se sobre o banco e agarre a barra de cachos EZ com palmas para cima. Sente-se no assento do banco do pregador para que seus braços superiores descansem sobre a almofada e seu peito seja pressionado contra a almofada. Abaixe o peso até que seus cotovelos sejam estendidos e os braços estejam retos."]],"wger-512":["Remo sentado, aperto estreito.",["* Aperte os músculos","* Movimento controlado","* Movimento lento","Mantenha a parte superior do corpo ereto.","Não se incline para trás","Puxe em direção ao peito"]],"wger-567":["Ombros, halteres",["Sente-se em um banco, o descanso de trás deve ser quase vertical, pegue dois halteres e leve-os para a altura do ombro, as palmas das mãos e os cotovelos apontam durante todo o exercício para a frente, pressione os pesos para cima, no ponto mais alto eles chegam muito perto, mas não tocam, vá devagar e repita."]],"wger-584":["Um pastor de braço único Curl.",["Sente-se no banco do pastor e faça um curl bíceps com um haltere em uma mão, sua outra mão pode estar descansando, ou sob o cotovelo do seu braço."]],"wger-659":["Extensões do tríceps no cabo",["Pegue o cabo, fique de pé com os pés largos, mantenha as costas retas e incline-se um pouco para a frente, empurre a barra para baixo, certificando-se que os cotovelos não se movem durante o exercício, gire as mãos para fora no final e volte para a posição inicial sem pausa."]],"Iron_Cross":["Cruz de ferro",["Nas argolas, comece em apoio com os braços estendidos. Abra os braços lateralmente até aproximá-los da altura dos ombros. Volte ao apoio com controle."]],"One-Arm_Kettlebell_Swings":["Swing unilateral com kettlebell",["Segure o kettlebell com uma mão e leve o quadril para trás. Estenda o quadril para impulsionar o peso à frente. Deixe o peso voltar entre as pernas com controle."]],"Push_Press":["Desenvolvimento com impulso",["Comece com a barra apoiada na frente dos ombros. Flexione ligeiramente os joelhos e estenda as pernas para impulsionar a barra acima da cabeça. Baixe-a até os ombros com controle."]],"Side_Bridge":["Prancha lateral",["Apoie o antebraço no chão com o cotovelo abaixo do ombro. Eleve o quadril até alinhar o tronco e as pernas. Sustente a posição e troque de lado."]],"Side_Jackknife":["Abdominal lateral canivete",["Deite-se de lado com as pernas estendidas. Eleve o tronco e a perna de cima, aproximando o cotovelo do joelho. Retorne devagar e troque de lado."]]};
